local DecompileN = type(decompile) == "function" and decompile or nil
local VApi
local Fallback
local VState = "idle"
local VError
local LastWarning
local DecompNames = {"Valm Decompiler", "ByteFall", "LunaUX", "LuaCID", "X2125", "Native"}
local DecompNameSet = {}
for _, DecompilerName in ipairs(DecompNames) do
    DecompNameSet[DecompilerName] = true
end
local DefaultFallbacks = {"ByteFall", "LunaUX", "LuaCID", "X2125", "Native"}
local function GetDecompOrder(DecompilerSettings)
    DecompilerSettings = type(DecompilerSettings) == "table" and DecompilerSettings or {}
    local PrimaryName = "Valm Decompiler"
    local Fallbacks = DecompilerSettings.Fallbacks
    if type(Fallbacks) ~= "table" then
        Fallbacks = {}
        local SeenFallbacks = {}
        local LegacyFallback = DecompilerSettings.DecompilerFallback
        if DecompNameSet[LegacyFallback] and LegacyFallback ~= PrimaryName then
            Fallbacks[#Fallbacks + 1] = LegacyFallback
            SeenFallbacks[LegacyFallback] = true
        end
        for _, DecompilerName in ipairs(DefaultFallbacks) do
            if DecompilerName ~= PrimaryName and not SeenFallbacks[DecompilerName] then
                Fallbacks[#Fallbacks + 1] = DecompilerName
                SeenFallbacks[DecompilerName] = true
            end
        end
    end
    local Order = {PrimaryName}
    local Seen = {[PrimaryName] = true}
    if PrimaryName ~= "ByteFall" then
        Order[#Order + 1] = "ByteFall"
        Seen.ByteFall = true
    end
    for Slot = 1, #DecompNames - 1 do
        local DecompilerName = Fallbacks[Slot]
        if DecompNameSet[DecompilerName] and not Seen[DecompilerName] then
            Order[#Order + 1] = DecompilerName
            Seen[DecompilerName] = true
        end
    end
    return Order
end
local function SetStatus(Key, Value)
    local SharedEnvironment = _G
    if type(getgenv) == "function" then
        local EnvTest, EnvironmentResult = pcall(getgenv)
        if EnvTest and type(EnvironmentResult) == "table" then
            SharedEnvironment = EnvironmentResult
        end
    end
    if type(SharedEnvironment) == "table" then
        pcall(function()
            SharedEnvironment["ValmDecompiler" .. Key] = Value
        end)
    end
end
local function WarnFailure(Failure)
    local ErrorText = tostring(Failure or "unknown native error")
    SetStatus("LastNativeError", ErrorText)
    if LastWarning ~= ErrorText then
        LastWarning = ErrorText
        if type(warn) == "function" then
            pcall(warn, "[Valm Decompiler] Native reconstruction failed: " .. ErrorText .. ". The configured fallback chain will be attempted next.")
        end
    end
end
local function LoadD()
    if type(VApi) == "table" and type(VApi.Decompile) == "function" then
        return VApi
    end
    if VState == "loading" then
        if type(task) == "table" and type(task.wait) == "function" then
            local Deadline = os.clock() + 20
            while VState == "loading" and os.clock() < Deadline do
                task.wait()
            end
        end
        if type(VApi) == "table" and type(VApi.Decompile) == "function" then
            return VApi
        end
        return nil, VError or "Valm Decompiler is still loading"
    end
    VState = "loading"
    local LoadSuccess, LoadResult = pcall(function()
        local Compiler = loadstring or (type(getgenv) == "function" and getgenv().loadstring) or load
        if type(Compiler) ~= "function" then
            error("loadstring is unavailable")
        end
        local ScriptSource = game:HttpGet("https://raw.githubusercontent.com/9faces/9faces-decompiler/479f8e854c5dfcc2a9c2a7152b95f007a9a5aa92/Loader.lua")
        if type(ScriptSource) ~= "string" or ScriptSource == "" then
            error("The Valm Decompiler loader download was empty")
        end
        local OldElseMatch = 'if Name == "JUMP" and TargetIndex > InstructionIndex + 1 then'
        local NewElseMatch = 'if (Name == "JUMP" or Name == "JUMPX") and TargetIndex > InstructionIndex + 1 then'
        local JumpStart, LongJumpMatcherEnd = string.find(ScriptSource, OldElseMatch, 1, true)
        if JumpStart then
            ScriptSource = string.sub(ScriptSource, 1, JumpStart - 1) .. NewElseMatch .. string.sub(ScriptSource, LongJumpMatcherEnd + 1)
        end
        local OldElse = 'if CandidateBlock.Kind == "If" and InstructionIndex + 1 == CandidateBlock.EndIndex and TargetIndex > CandidateBlock.EndIndex then'
        local NewElse = 'if CandidateBlock.Kind == "If" and CandidateBlock.EndIndex > InstructionIndex and (TargetIndex > CandidateBlock.EndIndex or TargetIndex + 1 == CandidateBlock.EndIndex) then'
        local ElseStart, ElseCandidateEnd = string.find(ScriptSource, OldElse, 1, true)
        if ElseStart then
            ScriptSource = string.sub(ScriptSource, 1, ElseStart - 1) .. NewElse .. string.sub(ScriptSource, ElseCandidateEnd + 1)
        end
        local OldTopMatch = 'elseif Name == "JUMP" and TopBlock and TopBlock.Kind == "If" and InstructionIndex + 1 == TopBlock.EndIndex and TargetIndex > TopBlock.EndIndex then'
        local NewTopMatch = 'elseif (Name == "JUMP" or Name == "JUMPX") and TopBlock and TopBlock.Kind == "If" and TopBlock.EndIndex > InstructionIndex and (TargetIndex > TopBlock.EndIndex or TargetIndex + 1 == TopBlock.EndIndex) then'
        local TopBlockElseStart, TopBlockElseEnd = string.find(ScriptSource, OldTopMatch, 1, true)
        if TopBlockElseStart then
            ScriptSource = string.sub(ScriptSource, 1, TopBlockElseStart - 1) .. NewTopMatch .. string.sub(ScriptSource, TopBlockElseEnd + 1)
        end
        local OldForwardFail = [[elseif TargetIndex > InstructionIndex + 1 then
                return nil, "Unmatched forward jump at instruction " .. tostring(Instruction.PC)]]
        local NewForwardFail = [[elseif TargetIndex > InstructionIndex + 1 then
                if TargetIndex == InstructionIndex + 2 then
                    local StaysInsideBlocks = true
                    for BlockIndex = 1, #Blocks do
                        if TargetIndex >= Blocks[BlockIndex].EndIndex then
                            StaysInsideBlocks = false
                            break
                        end
                    end
                    if StaysInsideBlocks then
                        InstructionIndex = TargetIndex - 1
                    else
                        return nil, "Short forward jump crosses a structured block boundary at instruction " .. tostring(Instruction.PC)
                    end
                elseif TargetIndex > #Instructions then
                    local LastInstruction = Instructions[#Instructions]
                    local RawTargetPc = Name == "JUMPX" and (Instruction.PC + Instruction.E + 1) or (Instruction.PC + Instruction.D + 1)
                    local LastInstructionEndPc = LastInstruction and (LastInstruction.PC + (LastInstruction.Aux ~= nil and 2 or 1)) or 0
                    if LastInstruction and RawTargetPc >= LastInstructionEndPc then
                        InstructionIndex = #Instructions
                    else
                        return nil, "Forward jump target is not an instruction boundary at instruction " .. tostring(Instruction.PC)
                    end
                elseif TopBlock and TopBlock.Kind == "If" and (TargetIndex > TopBlock.EndIndex or TargetIndex + 1 == TopBlock.EndIndex) then
                    IndentLevel = math.max(0, IndentLevel - 1)
                    EmitLine("else")
                    IndentLevel = IndentLevel + 1
                    TopBlock.EndIndex = TargetIndex
                else
                    local BlockDetails = {}
                    for BlockIndex = 1, #Blocks do
                        local Block = Blocks[BlockIndex]
                        BlockDetails[#BlockDetails + 1] = tostring(Block.Kind) .. ":" .. tostring(Block.EndIndex)
                    end
                    local RawTargetPc = Name == "JUMPX" and (Instruction.PC + Instruction.E + 1) or (Instruction.PC + Instruction.D + 1)
                    return nil, "Unmatched forward jump at instruction " .. tostring(Instruction.PC) .. " (instruction index " .. tostring(InstructionIndex) .. ", opcode " .. tostring(Name) .. ", target index " .. tostring(TargetIndex) .. ", target pc " .. tostring(RawTargetPc) .. ", blocks " .. table.concat(BlockDetails, ",") .. ", instruction count " .. tostring(#Instructions) .. ")"
                end]]
        local FailureStart, FailureEnd = string.find(ScriptSource, OldForwardFail, 1, true)
        if FailureStart then
            ScriptSource = string.sub(ScriptSource, 1, FailureStart - 1) .. NewForwardFail .. string.sub(ScriptSource, FailureEnd + 1)
        end
        local OriginalIfExitScan = [[            if LoopBlockIndex then
                EmitLine(LoopAction)]]
        local UpdatedIfExitScan = [[            local MatchingIfExitIndex = nil
            if not LoopBlockIndex and not ElseBlockIndex and TargetIndex > InstructionIndex + 1 then
                for BlockIndex = #Blocks, 1, -1 do
                    local CandidateBlock = Blocks[BlockIndex]
                    if CandidateBlock.Kind == "If" and CandidateBlock.EndIndex == TargetIndex then
                        MatchingIfExitIndex = BlockIndex
                        break
                    end
                end
            end
            if LoopBlockIndex then
                EmitLine(LoopAction)]]
        local IfExitScanStart, IfExitScanEnd = string.find(ScriptSource, OriginalIfExitScan, 1, true)
        if IfExitScanStart then
            ScriptSource = string.sub(ScriptSource, 1, IfExitScanStart - 1) .. UpdatedIfExitScan .. string.sub(ScriptSource, IfExitScanEnd + 1)
        end
        local OldIfExit = [[elseif TopBlock and TopBlock.Kind == "If" and TargetIndex == TopBlock.EndIndex then
            elseif TargetIndex <= InstructionIndex then]]
        local UpdatedIfExitBranch = [[elseif MatchingIfExitIndex then
                while #Blocks > MatchingIfExitIndex do
                    CloseBlock(table.remove(Blocks))
                end
            elseif TargetIndex <= InstructionIndex then]]
        local IfExitBranchStart, IfExitBranchEnd = string.find(ScriptSource, OldIfExit, 1, true)
        if IfExitBranchStart then
            ScriptSource = string.sub(ScriptSource, 1, IfExitBranchStart - 1) .. UpdatedIfExitBranch .. string.sub(ScriptSource, IfExitBranchEnd + 1)
        end
        if not JumpStart or not ElseStart or not TopBlockElseStart or not FailureStart or not IfExitScanStart or not IfExitBranchStart then
            error("The native decompiler did not match the control-flow compatibility patches")
        end
        local CountA
        local CountB
        local CountC
        ScriptSource, CountA = string.gsub(ScriptSource, "local MaxBytecodeBytes = 4194304", "local MaxBytecodeBytes = 8388608", 1)
        ScriptSource, CountB = string.gsub(ScriptSource, "local MaxOutputLines = 12000", "local MaxOutputLines = 24000", 1)
        ScriptSource, CountC = string.gsub(ScriptSource, "if CurrentDepth > 64 then", "if CurrentDepth > 128 then", 1)
        local CountD
        ScriptSource, CountD = string.gsub(ScriptSource, 'Version = "0.3.0%-beta%.31"', 'Version = "0.3.0-beta.32"', 1)
        if CountA ~= 1 or CountB ~= 1 or CountC ~= 1 or CountD ~= 1 then
            error("The native decompiler did not match the capacity or version compatibility patches")
        end
        local LoaderChunk, CompileError = Compiler(ScriptSource)
        if type(LoaderChunk) ~= "function" then
            error("The Valm Decompiler loader could not be compiled: " .. tostring(CompileError or "unknown compiler error"))
        end
        return LoaderChunk()
    end)
    if not LoadSuccess then
        VError = tostring(LoadResult)
        VState = "failed"
        SetStatus("LoaderError", VError)
        WarnFailure("Loader initialization failed: " .. VError)
        return nil, VError
    end
    local SharedEnvironment = _G
    if type(getgenv) == "function" then
        local EnvTest, EnvironmentResult = pcall(getgenv)
        if EnvTest and type(EnvironmentResult) == "table" then
            SharedEnvironment = EnvironmentResult
        end
    end
    local Api = type(LoadResult) == "table" and LoadResult or (SharedEnvironment and SharedEnvironment.ValmDecompiler) or _G.ValmDecompiler
    if type(Api) ~= "table" or type(Api.Decompile) ~= "function" then
        VError = "The Valm Decompiler loader did not expose ValmDecompiler.Decompile"
        VState = "failed"
        SetStatus("LoaderError", VError)
        WarnFailure(VError)
        return nil, VError
    end
    VApi = Api
    VError = nil
    VState = "ready"
    SetStatus("LoaderError", nil)
    local StatusSuccess, Status = pcall(function()
        return type(Api.GetStatus) == "function" and Api.GetStatus() or {Name = Api.Name, Version = Api.Version}
    end)
    if StatusSuccess then
        SetStatus("Status", Status)
        SetStatus("Version", Status.Version or Api.Version)
    end
    return VApi
end
local function VDecomp(ScriptInstance)
    local Api, LoadError = LoadD()
    if not Api then
        WarnFailure("Loader unavailable: " .. tostring(LoadError))
        return nil, LoadError
    end
    if type(Fallback) == "function" and type(Api.SetBytefallFallback) == "function" then
        pcall(Api.SetBytefallFallback, Fallback)
    end
    local SharedEnvironment = _G
    if type(getgenv) == "function" then
        local EnvTest, EnvironmentResult = pcall(getgenv)
        if EnvTest and type(EnvironmentResult) == "table" then
            SharedEnvironment = EnvironmentResult
        end
    end
    local BytecodeProvider = SharedEnvironment and SharedEnvironment.getscriptbytecode or getscriptbytecode or (SharedEnvironment and SharedEnvironment.dumpstring) or dumpstring
    if type(BytecodeProvider) ~= "function" then
        local Failure = "The executor does not expose getscriptbytecode or dumpstring"
        Api.LastError = Failure
        WarnFailure(Failure)
        return nil, Failure
    end
    if type(Api.SetBytecodeProvider) == "function" then
        local ProviderSuccess, ProviderError = pcall(Api.SetBytecodeProvider, BytecodeProvider)
        if not ProviderSuccess then
            Api.LastError = tostring(ProviderError)
            WarnFailure(Api.LastError)
            return nil, Api.LastError
        end
    end
    local BytecodeSuccess, Bytecode = pcall(BytecodeProvider, ScriptInstance)
    if not BytecodeSuccess then
        Api.LastError = "Bytecode capture failed: " .. tostring(Bytecode)
        WarnFailure(Api.LastError)
        return nil, Api.LastError
    end
    if type(Bytecode) ~= "string" or Bytecode == "" then
        Api.LastError = "The executor returned empty or invalid bytecode"
        WarnFailure(Api.LastError)
        return nil, Api.LastError
    end
    local BytecodeVersion = string.byte(Bytecode, 1)
    SetStatus("LastBytecodeVersion", BytecodeVersion)
    SetStatus("LastBytecodeSize", #Bytecode)
    SetStatus("OpcodeMultiplier", nil)
    local DecompileSuccess, DecompiledSource, DecompileError = pcall(Api.Decompile, Bytecode, {PascalCase = true, SkipBytefallFallback = true})
    if Api.LastOpcodeMultiplier ~= nil then
        SetStatus("OpcodeMultiplier", Api.LastOpcodeMultiplier)
    end
    if not DecompileSuccess then
        Api.LastError = "Native reconstruction raised an error: " .. tostring(DecompiledSource)
        WarnFailure(Api.LastError)
        return nil, Api.LastError
    end
    if type(DecompiledSource) ~= "string" or DecompiledSource:match("^%s*$") then
        Api.LastError = tostring(DecompileError or Api.LastError or "Native reconstruction did not return source")
        WarnFailure(Api.LastError)
        return nil, Api.LastError
    end
    Api.LastSuccessfulInput = "RawBytecode"
    SetStatus("OpcodeMultiplier", Api.LastOpcodeMultiplier or 1)
    Api.LastError = nil
    LastWarning = nil
    SetStatus("LastNativeError", nil)
    SetStatus("LastSuccessfulDecompiler", "Valm Decompiler")
    return DecompiledSource
end

local function LunaUXDecompile(ScriptInstance, RequestFunction, BytecodeProvider)
    local function AddRequest(Candidate)
        if type(RequestFunction) ~= "function" and type(Candidate) == "function" then
            RequestFunction = Candidate
        end
    end

    AddRequest(type(syn) == "table" and syn.request or nil)
    AddRequest(type(http) == "table" and http.request or nil)
    AddRequest(http_request)
    AddRequest(request)
    AddRequest(type(fluxus) == "table" and fluxus.request or nil)
    AddRequest(type(krnl) == "table" and krnl.request or nil)

    if type(RequestFunction) ~= "function" then
        return nil, "LunaUX requires an executor HTTP request function"
    end

    if type(BytecodeProvider) ~= "function" then
        BytecodeProvider = getscriptbytecode or dumpstring
    end

    if type(BytecodeProvider) ~= "function" then
        return nil, "LunaUX requires getscriptbytecode or dumpstring"
    end

    local BytecodeSuccess, Bytecode = pcall(BytecodeProvider, ScriptInstance)
    if not BytecodeSuccess then
        return nil, "LunaUX could not read script bytecode: " .. tostring(Bytecode)
    end

    if type(Bytecode) ~= "string" or Bytecode == "" then
        return nil, "LunaUX received empty script bytecode"
    end

    local EncodedBytecode
    local Base64Encoder

    if type(crypt) == "table" then
        Base64Encoder = crypt.base64encode or crypt.base64_encode
        if type(Base64Encoder) ~= "function" and type(crypt.base64) == "table" then
            Base64Encoder = crypt.base64.encode
        end
    end

    if type(Base64Encoder) ~= "function" and type(base64) == "table" then
        Base64Encoder = base64.encode
    end

    if type(Base64Encoder) ~= "function" then
        Base64Encoder = base64_encode or base64encode
    end

    if type(Base64Encoder) == "function" then
        local EncodeSuccess, EncodeResult = pcall(Base64Encoder, Bytecode)
        if EncodeSuccess and type(EncodeResult) == "string" and EncodeResult ~= "" then
            EncodedBytecode = EncodeResult
        end
    end

    if not EncodedBytecode then
        local Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local EncodedParts = {}
        for Index = 1, #Bytecode, 3 do
            local First = string.byte(Bytecode, Index)
            local Second = string.byte(Bytecode, Index + 1)
            local Third = string.byte(Bytecode, Index + 2)
            local Value = First * 65536 + (Second or 0) * 256 + (Third or 0)
            local FirstIndex = math.floor(Value / 262144) % 64 + 1
            local SecondIndex = math.floor(Value / 4096) % 64 + 1
            local ThirdIndex = math.floor(Value / 64) % 64 + 1
            local FourthIndex = Value % 64 + 1
            EncodedParts[#EncodedParts + 1] = Alphabet:sub(FirstIndex, FirstIndex)
            EncodedParts[#EncodedParts + 1] = Alphabet:sub(SecondIndex, SecondIndex)
            EncodedParts[#EncodedParts + 1] = Second and Alphabet:sub(ThirdIndex, ThirdIndex) or "="
            EncodedParts[#EncodedParts + 1] = Third and Alphabet:sub(FourthIndex, FourthIndex) or "="
        end
        EncodedBytecode = table.concat(EncodedParts)
    end

    local HttpOK, HttpService = pcall(function()
        return game:GetService("HttpService")
    end)

    if not HttpOK or not HttpService then
        return nil, "LunaUX could not access HttpService"
    end

    local BodySuccess, RequestBody = pcall(function()
        local EncodedData = HttpService:JSONEncode(EncodedBytecode)
        local EncodedName = "null"
        local NameSuccess, NameValue = pcall(function()
            return HttpService:JSONEncode(ScriptInstance.Name)
        end)
        if NameSuccess then
            EncodedName = NameValue
        end
        return "{\"bytecode\":" .. EncodedData .. ",\"filename\":" .. EncodedName .. ",\"options\":null}"
    end)

    if not BodySuccess then
        return nil, "LunaUX could not encode the request: " .. tostring(RequestBody)
    end

    local RequestSuccess, Response = pcall(RequestFunction, {
        Url = "https://lunaux-decompiler.dev/api/decompile",
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json",
            ["X-Telemetry-Enabled"] = "0"
        },
        Body = RequestBody
    })

    if not RequestSuccess then
        return nil, "LunaUX request failed: " .. tostring(Response)
    end

    if type(Response) ~= "table" then
        return nil, "LunaUX returned an invalid HTTP response"
    end

    local StatusCode = tonumber(Response.StatusCode or Response.Status) or 0
    local ResponseBody = tostring(Response.Body or "")

    if StatusCode ~= 200 then
        return nil, string.format("LunaUX HTTP %d: %s", StatusCode, ResponseBody:sub(1, 400))
    end

    if ResponseBody:match("^%s*$") then
        return nil, "LunaUX returned empty source"
    end

    return ResponseBody
end

