	local function PlayValmSound(AssetId, Volume, CacheKey)
		local Success, ErrorMessage = pcall(function()
			local Key = tostring(CacheKey or AssetId)
			local Sound = SoundCache[Key]
			if not Sound or not Sound.Parent then
				Sound = Instance.new("Sound")
				Sound.Name = "ValmDexSound_" .. Key:gsub("%W", "")
				Sound.Parent = SoundService
				SoundCache[Key] = Sound
			end
			Sound.SoundId = "rbxassetid://" .. tostring(AssetId):gsub("^rbxassetid://", "")
			Sound.Volume = math.clamp(tonumber(Volume) or 0.55, 0, 1)
			Sound.Looped = false
			Sound:Stop()
			pcall(function() Sound.TimePosition = 0 end)
			Sound:Play()
		end)
		if not Success then warn("[Valm Dex] Sound playback failed: " .. tostring(ErrorMessage)) end
		return Success
	end

	local function QueueNotification(TitleText, DescriptionText, Duration, TextureId)
