	local function GetScriptScore(ScriptObject, DecompiledSource)
		local LowerSource = string.lower(tostring(DecompiledSource or ""))
		local LowerName = string.lower(ScriptObject.Name)
		local HasRemoteHandler = LowerSource:find("onserverevent", 1, true) ~= nil or LowerSource:find("onserverinvoke", 1, true) ~= nil
		local HasLoadstring = LowerSource:find("loadstring", 1, true) ~= nil
		local HasNumericRequire = LowerSource:match("require%s*%(%s*%d+%s*%)") ~= nil
		local HasRequire = LowerSource:find("require", 1, true) ~= nil
		local HasDynamicRequire = HasRequire and not HasNumericRequire
		local HasRemoteModuleId = LowerSource:find("moduleid", 1, true) ~= nil or LowerSource:find("assetid", 1, true) ~= nil or LowerSource:find("requireid", 1, true) ~= nil or LowerSource:find("args", 1, true) ~= nil or LowerSource:find("arguments", 1, true) ~= nil
		local HasHttpFetch = LowerSource:find("httpservice", 1, true) ~= nil and (LowerSource:find("getasync", 1, true) ~= nil or LowerSource:find("postasync", 1, true) ~= nil)
		local HasHttpGet = LowerSource:find("httpget", 1, true) ~= nil
		local HasBackdoorName = LowerName:find("backdoor", 1, true) ~= nil or LowerName:find("rce", 1, true) ~= nil
		local Score = 0
		local Reasons = {}

		if HasRemoteHandler and HasLoadstring then
			Score = Score + 6
			Reasons[#Reasons + 1] = "remote handler and dynamic code compilation"
		end
		if HasRemoteHandler and HasNumericRequire then
			Score = Score + 6
			Reasons[#Reasons + 1] = "remote handler and numeric asset require"
		end
		if HasLoadstring and (HasHttpFetch or HasHttpGet) then
			Score = Score + 5
			Reasons[#Reasons + 1] = "downloaded content passed to dynamic code compilation"
		end
		if HasRemoteHandler and HasDynamicRequire and HasRemoteModuleId then
			Score = Score + 5
			Reasons[#Reasons + 1] = "remote handler with a client-supplied module or asset identifier"
		end
		if HasBackdoorName and (HasRemoteHandler or HasLoadstring or HasNumericRequire) then
			Score = Score + 4
			Reasons[#Reasons + 1] = "backdoor-like script name with execution indicators"
		end
		return Score, Reasons
	end

	local function StartBackdoorScan()
		if SecurityScanStarted then
			return
		end
		SecurityScanStarted = true
		task.spawn(function()
			local DescendantSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not DescendantSuccess or type(Descendants) ~= "table" then
				return
			end

			local Candidates = {}
			for _, Object in ipairs(Descendants) do
				if Object:IsA("ModuleScript") or Object:IsA("LocalScript") or Object:IsA("Script") then
					local IsViable = false
					if type(env) == "table" and type(env.isViableDecompileScript) == "function" then
						local ViabilitySuccess, ViabilityResult = pcall(env.isViableDecompileScript, Object)
						IsViable = ViabilitySuccess and ViabilityResult == true
					end
					if IsViable then
						local Name = string.lower(Object.Name)
						local Priority = 0
						for _, Word in ipairs({"backdoor", "remote", "admin", "command", "loader", "execute", "server"}) do
							if Name:find(Word, 1, true) then
								Priority = Priority + 2
							end
						end
						Candidates[#Candidates + 1] = {Object = Object, Priority = Priority}
					end
				end
			end
			table.sort(Candidates, function(Left, Right)
				return Left.Priority > Right.Priority
			end)

			local Scanned = 0
			local Findings = {}
			for _, Candidate in ipairs(Candidates) do
				if Scanned >= 48 or #Findings >= 2 then
					break
				end
				Scanned = Scanned + 1
				local DecompileSuccess, DecompiledSource = pcall(VDecomp, Candidate.Object)
				if DecompileSuccess and type(DecompiledSource) == "string" and DecompiledSource ~= "" then
					local Score, Reasons = GetScriptScore(Candidate.Object, DecompiledSource)
					if Score >= 5 then
						local PathSuccess, ScriptPath = pcall(function()
							return Candidate.Object:GetFullName()
						end)
						Findings[#Findings + 1] = {
							Path = PathSuccess and ScriptPath or Candidate.Object.Name,
							Reasons = Reasons
						}
					end
				end
				if Scanned % 4 == 0 then
					task.wait(0.08)
				end
			end

			if #Findings > 0 then
				QueueNotification(
					"This game is Backdoored!",
					"Our Agents flagged this game as a Backdoored Game.",
					5,
					9405925508
				)
				local SharedEnvironment = _G
				if type(getgenv) == "function" then
					local Success, Result = pcall(getgenv)
					if Success and type(Result) == "table" then
						SharedEnvironment = Result
					end
				end
				SharedEnvironment.ValmSecurityScanFindings = Findings
				SharedEnvironment.ValmSecurityScanCompleted = true
			else
				local SharedEnvironment = _G
				if type(getgenv) == "function" then
					local Success, Result = pcall(getgenv)
					if Success and type(Result) == "table" then
						SharedEnvironment = Result
					end
				end
				SharedEnvironment.ValmSecurityScanFindings = {}
				SharedEnvironment.ValmSecurityScanCompleted = true
			end
		end)
	end

	return {
		Queue = QueueNotification,
		PlaySound = PlayValmSound,
		StartBackdoorScan = StartBackdoorScan
	}
end)()


local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple

	if env then
		local NativeDecompile = env.nativeDecompile
		local ByteFallDecompile = env.byteFallDecompile

		if type(ByteFallDecompile) ~= "function" and type(env.decompile) == "function" and env.decompile ~= NativeDecompile then
			ByteFallDecompile = env.decompile
		end

		local function IsDecompOut(Output)
			if type(Output) ~= "string" or Output:match("^%s*$") then
				return false
			end

			local Header = string.lower(Output:sub(1, 768))
			local InvalidMarkers = {
				"decompilation failed",
				"failed to decompile",
				"decompile error",
				"unable to decompile",
				"unreachable",
				"failed to get script bytecode",
				"getscriptbytecode is not supported",
				"bytefall:",
				"bytefall (",
				"bytefall request failed",
				"bytefall returned",
				"lunaux error",
				"lunaux api request failed",
				"http 400",
				"http 404",
				"http 429",
				"http 500",
				"request failed:",
				"no http request function",
				"returned empty",
				"returned an invalid response"
			}

			for _, Marker in ipairs(InvalidMarkers) do
				if string.find(Header, Marker, 1, true) then
					return false
				end
			end

			return true
		end

		local function TryDecompiler(Decompiler, ScriptInstance)
			if type(Decompiler) ~= "function" then
				return nil, "unavailable"
			end

			local Success, Output, Detail = pcall(Decompiler, ScriptInstance)
			if Success and IsDecompOut(Output) then
				return Output
			end

			if not Success then
				return nil, tostring(Output)
			end

			return nil, tostring(Detail or Output or "invalid output")
		end

		env.decompile = function(ScriptInstance)
			if not ScriptInstance or type(env.isViableDecompileScript) ~= "function" or not env.isViableDecompileScript(ScriptInstance) then
				return nil, "This script does not run on the client or cannot be decompiled here."
			end

			local DecompFns = {
				["Valm Decompiler"] = VDecomp,
				ByteFall = ByteFallDecompile,
				LunaUX = function(TargetScript)
					return LunaUXDecompile(TargetScript, env.request, env.getscriptbytecode)
				end,
				Native = NativeDecompile
			}
			local ErrorMessages = {}
			for _, DecompilerName in ipairs(GetDecompOrder(Settings and Settings.Decompiler)) do
				local DecompFn = DecompFns[DecompilerName]
				if type(DecompFn) == "function" then
					local Output, Failure = TryDecompiler(DecompFn, ScriptInstance)
					if Output then
						return Output
					end
					table.insert(ErrorMessages, DecompilerName .. ": " .. tostring(Failure))
				end
			end

			return nil, #ErrorMessages > 0 and table.concat(ErrorMessages, "\n") or "No compatible decompiler is available."
		end

		env.isdecompile = function()
			return type(env.getscriptbytecode) == "function"
				or type(ByteFallDecompile) == "function"
				or type(LunaUXDecompile) == "function"
				or type(NativeDecompile) == "function"
		end

		env.isdecompilefallback = function()
			return type(ByteFallDecompile) == "function"
				or type(LunaUXDecompile) == "function"
				or type(NativeDecompile) == "function"
		end

		env.byteFallDecompile = ByteFallDecompile
		Fallback = ByteFallDecompile
	end
end

