		context:Register("TOGGLE_MODEL_ANCHORED",{Name = "Toggle Anchored Parts", Icon = "rbxassetid://115739619258011", OnClick = function()
			local Parts = {}
			local SeenParts = {}
			for _, Node in ipairs(selection.List) do
				local Object = Node.Obj
				if Object and Object:IsA("BasePart") then
					if not SeenParts[Object] then
						SeenParts[Object] = true
						table.insert(Parts, Object)
					end
			elseif Object and Object:IsA("Model") then
					for _, Descendant in ipairs(Object:GetDescendants()) do
						if Descendant:IsA("BasePart") and not SeenParts[Descendant] then
							SeenParts[Descendant] = true
							table.insert(Parts, Descendant)
						end
					end
				end
			end
			
			if #Parts == 0 then
				return
			end
			
			local ShouldAnchor = false
			for _, Part in ipairs(Parts) do
				if not Part.Anchored then
					ShouldAnchor = true
					break
				end
			end
			
			for _, Part in ipairs(Parts) do
				pcall(function()
					Part.Anchored = ShouldAnchor
				end)
			end
		end})

