		local PlayerHighlights = {}
		local PlayersService = service.Players or game:GetService("Players")
		local TeamsService = game:GetService("Teams")
		local function GetHighlightColor(Player)
			local Team = Player.Team
			if Team then
				return Team.TeamColor.Color
			end
			local HasTeams = false
			pcall(function()
				HasTeams = #TeamsService:GetTeams() > 0
			end)
			if not HasTeams then
				return Color3.new(1, 1, 1)
			end
			return Player.TeamColor.Color
		end
		local function RemoveHighlight(Player)
			local Record = PlayerHighlights[Player]
			if not Record then return end
			for _, Connection in ipairs(Record.Connections) do
				pcall(function() Connection:Disconnect() end)
			end
			if Record.Highlight then
				pcall(function() Record.Highlight:Destroy() end)
			end
			PlayerHighlights[Player] = nil
		end
		local function UpdateHighlight(Player)
			local Record = PlayerHighlights[Player]
			if not Record then return end
			local Highlight = Record.Highlight
			local Character = Player.Character
			if not Character or not Character.Parent then
				Highlight.Adornee = nil
				Highlight.Parent = workspace
				return
			end
			local TeamColor = GetHighlightColor(Player)
			Highlight.Name = "DexPlayerHighlight"
			Highlight.Adornee = Character
			Highlight.FillColor = TeamColor
			Highlight.OutlineColor = TeamColor
			Highlight.FillTransparency = 0.72
			Highlight.OutlineTransparency = 0
			Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			Highlight.Parent = workspace
		end
		local function AddHighlight(Player)
			if PlayerHighlights[Player] then
				RemoveHighlight(Player)
				return false
			end
			local Record = {Highlight = Instance.new("Highlight"), Connections = {}}
			PlayerHighlights[Player] = Record
			Record.Connections[#Record.Connections + 1] = Player:GetPropertyChangedSignal("Team"):Connect(function()
				UpdateHighlight(Player)
			end)
			Record.Connections[#Record.Connections + 1] = Player:GetPropertyChangedSignal("TeamColor"):Connect(function()
				UpdateHighlight(Player)
			end)
			Record.Connections[#Record.Connections + 1] = Player.CharacterAdded:Connect(function()
				task.defer(UpdateHighlight, Player)
			end)
			UpdateHighlight(Player)
			return true
		end
		PlayersService.PlayerRemoving:Connect(RemoveHighlight)

