		local function PlaceSearchPanel()
			local Content = Panel.Parent
			if not Content or not SearchFrame or not SearchFrame.Parent then return end
			local ParentPosition = Content.AbsolutePosition
			local ParentSize = Content.AbsoluteSize
			local PanelWidth = math.min(340, math.max(260, ParentSize.X - 16))
			local PanelHeight = 332
			Panel.Size = UDim2.new(0,PanelWidth,0,PanelHeight)
			local ColumnWidth = math.floor((PanelWidth - 36) / 2)
			local RightColumnX = PanelWidth - 10 - ColumnWidth
			for _, FilterKey in ipairs({"Name", "Path"}) do
				if FilterLabels[FilterKey] then FilterLabels[FilterKey].Size = UDim2.new(0,ColumnWidth,0,13) end
				if FilterInputs[FilterKey] then FilterInputs[FilterKey].Size = UDim2.new(0,ColumnWidth,0,21) end
			end
			for _, FilterKey in ipairs({"Class", "Tag"}) do
				if FilterLabels[FilterKey] then
					FilterLabels[FilterKey].Position = UDim2.new(0,RightColumnX,0,FilterLabels[FilterKey].Position.Y.Offset)
					FilterLabels[FilterKey].Size = UDim2.new(0,ColumnWidth,0,13)
				end
				if FilterInputs[FilterKey] then
					FilterInputs[FilterKey].Position = UDim2.new(0,RightColumnX,0,FilterInputs[FilterKey].Position.Y.Offset)
					FilterInputs[FilterKey].Size = UDim2.new(0,ColumnWidth,0,21)
				end
			end
			local FullWidth = PanelWidth - 20
			for _, FilterKey in ipairs({"Attribute", "Text"}) do
				if FilterLabels[FilterKey] then FilterLabels[FilterKey].Size = UDim2.new(0,FullWidth,0,13) end
				if FilterInputs[FilterKey] then FilterInputs[FilterKey].Size = UDim2.new(0,FullWidth,0,21) end
			end
			PresetNameBox.Size = UDim2.new(0,PanelWidth - 104,0,22)
			SaveButton.Position = UDim2.new(0,PanelWidth - 86,0,202)
			ApplyButton.Size = UDim2.new(0,PanelWidth / 2 - 15,0,24)
			ClearButton.Position = UDim2.new(0,PanelWidth / 2 + 5,0,232)
			ClearButton.Size = UDim2.new(0,PanelWidth / 2 - 15,0,24)
			local SearchRight = SearchFrame.AbsolutePosition.X + SearchFrame.AbsoluteSize.X
			local PanelX = SearchRight - ParentPosition.X - PanelWidth
			PanelX = math.clamp(PanelX, 8, math.max(8, ParentSize.X - PanelWidth - 8))
			local PanelY = SearchFrame.AbsolutePosition.Y + SearchFrame.AbsoluteSize.Y + 4 - ParentPosition.Y
			if PanelY + PanelHeight > ParentSize.Y - 8 then
				PanelY = SearchFrame.AbsolutePosition.Y - ParentPosition.Y - PanelHeight - 4
			end
			PanelY = math.clamp(PanelY, 8, math.max(8, ParentSize.Y - PanelHeight - 8))
			Panel.Position = UDim2.new(0,PanelX,0,PanelY)
		end

		local function ThemeSearchPanel()
			local CurrentTheme = Settings.Theme or Theme
			Panel.BackgroundColor3 = CurrentTheme.Main1 or CurrentTheme.Main2 or Color3.fromRGB(38,38,38)
			Panel.BorderColor3 = CurrentTheme.Outline1 or CurrentTheme.Outline2 or Color3.fromRGB(24,24,24)
			Header.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			Description.TextColor3 = CurrentTheme.PlaceholderText or CurrentTheme.TextDim or CurrentTheme.Text or Color3.fromRGB(170,170,170)
			CloseButton.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			SavedTitle.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			for _, Label in pairs(FilterLabels) do
				Label.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			end
			for _, Input in pairs(FilterInputs) do
				Input.BackgroundColor3 = CurrentTheme.TextBox or CurrentTheme.Main2 or Color3.fromRGB(30,30,30)
				Input.BorderColor3 = CurrentTheme.Outline3 or CurrentTheme.Outline2 or Color3.fromRGB(20,20,20)
				Input.PlaceholderColor3 = CurrentTheme.PlaceholderText or Color3.fromRGB(120,120,120)
				Input.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			end
			PresetNameBox.BackgroundColor3 = CurrentTheme.TextBox or CurrentTheme.Main2 or Color3.fromRGB(30,30,30)
			PresetNameBox.BorderColor3 = CurrentTheme.Outline3 or CurrentTheme.Outline2 or Color3.fromRGB(20,20,20)
			PresetNameBox.PlaceholderColor3 = CurrentTheme.PlaceholderText or Color3.fromRGB(120,120,120)
			PresetNameBox.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			for _, Button in ipairs({SaveButton, ApplyButton, ClearButton}) do
				Button.BackgroundColor3 = CurrentTheme.Button or CurrentTheme.Main2 or Color3.fromRGB(60,60,60)
				Button.BorderColor3 = CurrentTheme.Outline2 or Color3.fromRGB(40,40,40)
				Button.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			end
			SavedList.BackgroundColor3 = CurrentTheme.TextBox or CurrentTheme.Main2 or Color3.fromRGB(30,30,30)
			SavedList.BorderColor3 = CurrentTheme.Outline3 or CurrentTheme.Outline2 or Color3.fromRGB(20,20,20)
			SavedList.ScrollBarImageColor3 = CurrentTheme.Text or Color3.new(1,1,1)
			for _, Row in ipairs(SavedList:GetChildren()) do
				if Row:IsA("GuiObject") then
					for _, Child in ipairs(Row:GetChildren()) do
						if Child:IsA("TextButton") then
							Child.BackgroundColor3 = CurrentTheme.Button or CurrentTheme.Main2 or Color3.fromRGB(60,60,60)
							Child.TextColor3 = CurrentTheme.Text or Color3.new(1,1,1)
						end
					end
				end
			end
			if AdvancedButton then
				AdvancedButton.ImageColor3 = Explorer.HasActiveSearchFilters() and (CurrentTheme.Highlight or CurrentTheme.ButtonHover or Color3.fromRGB(90,150,230)) or Color3.new(1,1,1)
			end
		end

		Main.ApplyExplorerSearchTheme = ThemeSearchPanel
		Main.PositionExplorerAdvancedSearch = PlaceSearchPanel
		local function ReadFilterInputs()
			local Values = {}
			for FilterKey,Input in pairs(FilterInputs) do
				Values[FilterKey] = Input.Text:match("^%s*(.-)%s*$") or ""
			end
			return Values
		end

		local function SetFilterInputs(Values)
			for FilterKey,Input in pairs(FilterInputs) do
				Input.Text = tostring(Values and Values[FilterKey] or "")
			end
		end

		local function CopyFilterValues(Values)
			local Copy = {}
			for FilterKey,Value in pairs(Values or {}) do
				if FilterInputs[FilterKey] then
					Copy[FilterKey] = tostring(Value or "")
				end
			end
			return Copy
		end

		local function ApplyFilterValues(Values)
			Explorer.ActiveSearchFilters = CopyFilterValues(Values)
			Explorer.DoSearch(SearchBox.Text)
			if AdvancedButton then
				AdvancedButton.ImageColor3 = Explorer.HasActiveSearchFilters() and (Theme.Highlight or Color3.fromRGB(90,150,230)) or Color3.new(1,1,1)
			end
		end

		local function UpdateFilters()
			for _,Child in ipairs(SavedList:GetChildren()) do
				if Child:IsA("GuiObject") then Child:Destroy() end
			end
			local Names = {}
			for PresetName,PresetValues in pairs(SavedSearchFilters) do
				if type(PresetName) == "string" and type(PresetValues) == "table" then
					table.insert(Names, PresetName)
				end
			end
			table.sort(Names, function(A,B) return string.lower(A) < string.lower(B) end)
			for Index,PresetName in ipairs(Names) do
				local Row = Instance.new("Frame")
				Row.BackgroundTransparency = 1
				Row.BorderSizePixel = 0
				Row.Position = UDim2.new(0,0,0,(Index-1)*19)
				Row.Size = UDim2.new(1,-3,0,18)
				Row.ZIndex = 62
				Row.Parent = SavedList

				local LoadButton = Instance.new("TextButton")
				LoadButton.AutoButtonColor = true
				LoadButton.BackgroundColor3 = Theme.Button or Color3.fromRGB(60,60,60)
				LoadButton.BorderSizePixel = 0
				LoadButton.Font = Enum.Font.SourceSans
				LoadButton.Text = PresetName
				LoadButton.TextColor3 = Theme.Text or Color3.new(1,1,1)
				LoadButton.TextSize = 12
				LoadButton.TextXAlignment = Enum.TextXAlignment.Left
				LoadButton.Position = UDim2.new(0,0,0,0)
				LoadButton.Size = UDim2.new(1,-22,1,0)
				LoadButton.ZIndex = 63
				LoadButton.Parent = Row
				LoadButton.MouseButton1Click:Connect(function()
					SetFilterInputs(SavedSearchFilters[PresetName])
					ApplyFilterValues(SavedSearchFilters[PresetName])
				end)

				local DeleteButton = Instance.new("TextButton")
				DeleteButton.AutoButtonColor = true
				DeleteButton.BackgroundColor3 = Theme.Button or Color3.fromRGB(60,60,60)
				DeleteButton.BorderSizePixel = 0
				DeleteButton.Font = Enum.Font.SourceSansBold
				DeleteButton.Text = "×"
				DeleteButton.TextColor3 = Theme.Text or Color3.new(1,1,1)
				DeleteButton.TextSize = 14
				DeleteButton.Position = UDim2.new(1,-20,0,0)
				DeleteButton.Size = UDim2.new(0,20,1,0)
				DeleteButton.ZIndex = 63
				DeleteButton.Parent = Row
				DeleteButton.MouseButton1Click:Connect(function()
					SavedSearchFilters[PresetName] = nil
					UpdateFilters()
				end)
			end
			SavedList.CanvasSize = UDim2.new(0,0,0,#Names*19)
		end

		ApplyButton.MouseButton1Click:Connect(function()
			ApplyFilterValues(ReadFilterInputs())
			Panel.Visible = false
		end)

		ClearButton.MouseButton1Click:Connect(function()
			SetFilterInputs({})
			ApplyFilterValues({})
		end)

		SaveButton.MouseButton1Click:Connect(function()
			local PresetName = PresetNameBox.Text:match("^%s*(.-)%s*$") or ""
			local Values = ReadFilterInputs()
			local HasValue = false
			for _,Value in pairs(Values) do
				if Value ~= "" then HasValue = true break end
			end
			if PresetName == "" or not HasValue then return end
			SavedSearchFilters[PresetName] = Values
			UpdateFilters()
			PresetNameBox.Text = ""
		end)

		CloseButton.MouseButton1Click:Connect(function()
			Panel.Visible = false
		end)

		if AdvancedButton then
			AdvancedButton.MouseButton1Click:Connect(function()
				if Panel.Visible then
					Panel.Visible = false
				else
					PlaceSearchPanel()
					Panel.Visible = true
				end
			end)
			AdvancedButton.ImageColor3 = Explorer.HasActiveSearchFilters() and (Theme.Highlight or Theme.ButtonHover or Color3.fromRGB(90,150,230)) or Color3.new(1,1,1)
		end

		if ResetButton then
			ResetButton.MouseButton1Click:Connect(function()
				SearchBox.Text = ""
				SetFilterInputs({})
				Explorer.ActiveSearchFilters = {}
				Explorer.DoSearch("")
				if AdvancedButton then AdvancedButton.ImageColor3 = Color3.new(1,1,1) end
			end)
		end

		SearchBox.FocusLost:Connect(function()
			Explorer.DoSearch(SearchBox.Text)
		end)

		ThemeSearchPanel()
		UpdateFilters()
		if SearchFrame then
			SearchFrame:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
				if Panel.Visible then PlaceSearchPanel() end
			end)
		end
		if Panel.Parent then
			Panel.Parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
				if Panel.Visible then PlaceSearchPanel() end
			end)
		end
	end

	Explorer.InitEntryTemplate = function()
		entryTemplate = create({
			{1,"TextButton",{AutoButtonColor=false,BackgroundColor3=Color3.new(0,0,0),BackgroundTransparency=1,BorderColor3=Color3.new(0,0,0),Font=3,Name="Entry",Position=UDim2.new(0,1,0,1),Size=UDim2.new(0,250,0,20),Text="",TextSize=14,}},
			{2,"Frame",{BackgroundColor3=Color3.new(0.04313725605607,0.35294118523598,0.68627452850342),BackgroundTransparency=1,BorderColor3=Color3.new(0.33725491166115,0.49019610881805,0.73725491762161),BorderSizePixel=0,Name="Indent",Parent={1},Position=UDim2.new(0,20,0,0),Size=UDim2.new(1,-20,1,0),}},
			{3,"TextLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Font=3,Name="EntryName",Parent={2},Position=UDim2.new(0,26,0,0),Size=UDim2.new(1,-48,1,0),Text="Workspace",TextColor3=Color3.new(0.86274516582489,0.86274516582489,0.86274516582489),TextSize=14,TextXAlignment=0,}},
			{4,"TextButton",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,ClipsDescendants=true,Font=3,Name="Expand",Parent={2},Position=UDim2.new(0,-20,0,0),Size=UDim2.new(0,20,0,20),Text="",TextSize=14,}},
			{5,"ImageLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Image="rbxassetid://5642383285",ImageRectOffset=Vector2.new(144,16),ImageRectSize=Vector2.new(16,16),Name="Icon",Parent={4},Position=UDim2.new(0,2,0,2),ScaleType=4,Size=UDim2.new(0,16,0,16),}},
			{6,"ImageLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,ImageRectOffset=Vector2.new(304,0),ImageRectSize=Vector2.new(16,16),Name="Icon",Parent={2},Position=UDim2.new(0,4,0,2),ScaleType=4,Size=UDim2.new(0,16,0,16),}},
			{7,"ImageButton",{AutoButtonColor=false,BackgroundTransparency=1,BorderSizePixel=0,Image="rbxassetid://97742252878179",ImageColor3=Color3.new(1,1,1),Name="InsertObjectButton",Parent={2},Position=UDim2.new(1,-36,0,2),ScaleType=Enum.ScaleType.Fit,Size=UDim2.new(0,16,0,16),Visible=false,ZIndex=5,}},
		})

		local sys = Lib.ClickSystem.new()
		sys.AllowedButtons = {1,2}
		sys.OnDown:Connect(function(item,combo,button)
			local ind = table.find(listEntries,item)
			if not ind then return end
			local node = tree[ind + Explorer.Index]
			if not node then return end

			local entry = listEntries[ind]
			local InsertButton = entry.Indent:FindFirstChild("InsertObjectButton")
			if button == 1 and InsertButton and InsertButton.Visible and Lib.CheckMouseInGui(InsertButton) then return end

			if button == 1 then
				if combo == 2 then
					if node.Obj:IsA("LuaSourceContainer") then
						ScriptViewer.ViewScript(node.Obj)
					elseif #node > 0 and expanded[node] ~= 0 then
						expanded[node] = not expanded[node]
						Explorer.Update()
					end
				end

				if Properties.SelectObject(node.Obj) then
					sys.IsRenaming = false
					return
				end

				sys.IsRenaming = selection.Map[node]

				if Lib.IsShiftDown() then
					if not selection.Piviot then return end

					local fromIndex = table.find(tree,selection.Piviot)
					local toIndex = table.find(tree,node)
					if not fromIndex or not toIndex then return end
					fromIndex,toIndex = math.min(fromIndex,toIndex),math.max(fromIndex,toIndex)

					local sList = selection.List
					for i = #sList,1,-1 do
						local elem = sList[i]
						if selection.ShiftSet[elem] then
							selection.Map[elem] = nil
							table.remove(sList,i)
						end
					end
					selection.ShiftSet = {}
					for i = fromIndex,toIndex do
						local elem = tree[i]
						if not selection.Map[elem] then
							selection.ShiftSet[elem] = true
							selection.Map[elem] = true
							sList[#sList+1] = elem
						end
					end
					selection.Changed:Fire()
				elseif Lib.IsCtrlDown() then
					selection.ShiftSet = {}
					if selection.Map[node] then selection:Remove(node) else selection:Add(node) end
					selection.Piviot = node
					sys.IsRenaming = false
				elseif not selection.Map[node] then
					selection.ShiftSet = {}
					selection:Set(node)
					selection.Piviot = node
				end
			elseif button == 2 then
				if Properties.SelectObject(node.Obj) then
					return
				end

				if not Lib.IsCtrlDown() and not selection.Map[node] then
					selection.ShiftSet = {}
					selection:Set(node)
					selection.Piviot = node
					Explorer.Refresh()
				end
			end

			Explorer.Refresh()
		end)

		sys.OnRelease:Connect(function(item,combo,button,position)
			local ind = table.find(listEntries,item)
			if not ind then return end
			local node = tree[ind + Explorer.Index]
			if not node then return end
			local InsertButton = listEntries[ind].Indent:FindFirstChild("InsertObjectButton")
			if button == 1 and InsertButton and InsertButton.Visible and Lib.CheckMouseInGui(InsertButton) then return end

			if button == 1 then
				if selection.Map[node] and not Lib.IsShiftDown() and not Lib.IsCtrlDown() then
					selection.ShiftSet = {}
					selection:Set(node)
					selection.Piviot = node
					Explorer.Refresh()
				end

				local id = sys.ClickId
				Lib.FastWait(sys.ComboTime)
				if combo == 1 and id == sys.ClickId and sys.IsRenaming and selection.Map[node] then
					Explorer.SetRenamingNode(node)
				end
			elseif button == 2 then
				Explorer.ShowRightClick(position)
			end
		end)
		Explorer.ClickSystem = sys
	end

	Explorer.InitDelCleaner = function()
		coroutine.wrap(function()
			local fw = Lib.FastWait
			while true do
				local processed = false
				local c = 0
				for _,node in next,nodes do
					if node.HasDel then
						local delInd
						for i = 1,#node do
							if node[i].Del then
								delInd = i
								break
							end
						end
						if delInd then
							for i = delInd+1,#node do
								local cn = node[i]
								if not cn.Del then
									node[delInd] = cn
									delInd = delInd+1
								end
							end
							for i = delInd,#node do
								node[i] = nil
							end
						end
						node.HasDel = false
						processed = true
						fw()
					end
					c = c + 1
					if c > 10000 then
						c = 0
						fw()
					end
				end
				if processed and not refreshDebounce then Explorer.PerformRefresh() end
				fw(0.5)
			end
		end)()
	end

	Explorer.UpdateSelectionVisuals = function()
		local holder = Explorer.SelectionVisualsHolder
		local isa = game.IsA
		local clone = game.Clone
		if not holder then
			holder = Instance.new("ScreenGui")
			holder.Name = "ExplorerSelections"
			holder.DisplayOrder = Main.DisplayOrders.Core
			Lib.ShowGui(holder)
			Explorer.SelectionVisualsHolder = holder
			Explorer.SelectionVisualCons = {}

			local guiTemplate = create({
				{1,"Frame",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Size=UDim2.new(0,100,0,100),}},
				{2,"Frame",{BackgroundColor3=Color3.new(0.04313725605607,0.35294118523598,0.68627452850342),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,-1,0,-1),Size=UDim2.new(1,2,0,1),}},
				{3,"Frame",{BackgroundColor3=Color3.new(0.04313725605607,0.35294118523598,0.68627452850342),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,-1,1,0),Size=UDim2.new(1,2,0,1),}},
				{4,"Frame",{BackgroundColor3=Color3.new(0.04313725605607,0.35294118523598,0.68627452850342),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,-1,0,0),Size=UDim2.new(0,1,1,0),}},
				{5,"Frame",{BackgroundColor3=Color3.new(0.04313725605607,0.35294118523598,0.68627452850342),BorderSizePixel=0,Parent={1},Position=UDim2.new(1,0,0,0),Size=UDim2.new(0,1,1,0),}},
			})
			Explorer.SelectionVisualGui = guiTemplate

			local boxTemplate = Instance.new("SelectionBox")
			boxTemplate.LineThickness = 0.03
			boxTemplate.Color3 = Color3.fromRGB(0, 170, 255)
			Explorer.SelectionVisualBox = boxTemplate
		end
		holder:ClearAllChildren()

		-- Updates theme
		for i,v in pairs(Explorer.SelectionVisualGui:GetChildren()) do
			v.BackgroundColor3 = Color3.fromRGB(0, 170, 255)
		end

		local attachCons = Explorer.SelectionVisualCons
		for i = 1,#attachCons do
			attachCons[i].Destroy()
		end
		table.clear(attachCons)

		local partEnabled = Settings.Explorer.PartSelectionBox
		local guiEnabled = Settings.Explorer.GuiSelectionBox
		if not partEnabled and not guiEnabled then return end

		local svg = Explorer.SelectionVisualGui
		local svb = Explorer.SelectionVisualBox
		local attachTo = Lib.AttachTo
		local sList = selection.List
		local count = 1
		local boxCount = 0
		local workspaceNode = nodes[workspace]
		for i = 1,#sList do
			if boxCount > 1000 then break end
			local node = sList[i]
			local obj = node.Obj

			if node ~= workspaceNode then
				if isa(obj,"GuiObject") and guiEnabled then
					local newVisual = clone(svg)
					attachCons[count] = attachTo(newVisual,{Target = obj, Resize = true})
					count = count + 1
					newVisual.Parent = holder
					boxCount = boxCount + 1
				elseif isa(obj,"PVInstance") and partEnabled then
					local newBox = clone(svb)
					newBox.Adornee = obj
					newBox.Parent = holder
					boxCount = boxCount + 1
				end
			end
		end
	end

	Explorer.SetClassIconStyle = function(StyleName, RefreshNow, SkipPreload)
		local SafeName = tostring(StyleName or "Old")
		local Source = nil
		if SafeName ~= "Old" then
			local DataSuccess, Data = pcall(Lib.IconMap.getIconDataFromName, SafeName)
			if DataSuccess and type(Data) == "table" and type(Data.MapId) == "number" and Data.MapId > 0 and type(Data.Icons) == "table" and type(Data.IconSize) == "number" then
				Source = Data
			else
				SafeName = "Old"
			end
		end
		if SafeName == "Old" then
			local DataSuccess, Data = pcall(Lib.IconMap.getIconDataFromName, "Old")
			if DataSuccess and type(Data) == "table" then Source = Data end
		end
		Settings.ClassIcon = SafeName
		if Source and SafeName ~= "Old" then
			local FixedIcons = {}
			for ClassName, IconIndex in pairs(Source.Icons) do
				if type(IconIndex) == "number" then FixedIcons[ClassName] = math.max(0, IconIndex - 1) end
			end
			iconData = {MapId = Source.MapId, IconSize = Source.IconSize, Witdh = Source.Witdh, Height = Source.Height, Icons = FixedIcons}
		else
			iconData = nil
		end
		if not Explorer.ClassIcons then
			Explorer.ClassIcons = Lib.IconMap.newLinear("rbxasset://textures/ClassImages.PNG", 16, 16)
		end
		local ClassMap = Explorer.ClassIcons
		ClassMap.Style = SafeName
		if SafeName == "Old" then
			local OldIconData = Source or Lib.IconMap.getIconDataFromName("Old")
			ClassMap.MapId = "rbxassetid://" .. tostring(OldIconData.MapId)
			ClassMap.MapSizeX = 256
			ClassMap.MapSizeY = 256
			ClassMap.IconSizeX = 16
			ClassMap.IconSizeY = 16
			ClassMap.NumX = 14
			ClassMap.IndexDict = OldIconData.Icons
		else
			local IconSize = tonumber(Source.IconSize) or 32
			local Width = tonumber(Source.Witdh) or 18
			local Height = tonumber(Source.Height) or 18
			ClassMap.MapId = "rbxassetid://" .. tostring(Source.MapId)
			ClassMap.MapSizeX = IconSize * Width
			ClassMap.MapSizeY = IconSize * Height
			ClassMap.IconSizeX = IconSize
			ClassMap.IconSizeY = IconSize
			ClassMap.NumX = Width
			ClassMap.IndexDict = iconData.Icons
		end
		local MiscMap = Explorer.MiscIcons or Main.MiscIcons
		if MiscMap and type(MiscMap.SetExplorerIconStyle) == "function" then
			pcall(MiscMap.SetExplorerIconStyle, MiscMap, SafeName)
		end
		local function RefreshClassIcons()
			local Containers = {}
			local Seen = {}
			local function AddContainer(Container)
				if typeof(Container) == "Instance" and not Seen[Container] then
					Seen[Container] = true
					Containers[#Containers + 1] = Container
				end
			end
			if Main.GuiHolder then AddContainer(Main.GuiHolder) end
			pcall(function() AddContainer(Main.GetSecureContainer()) end)
			pcall(function() AddContainer(service.CoreGui) end)
			pcall(function() AddContainer(plr:FindFirstChildOfClass("PlayerGui")) end)
			for _, Container in ipairs(Containers) do
				local Descendants = {}
				pcall(function() Descendants = Container:GetDescendants() end)
				for _, Object in ipairs(Descendants) do
					if Object:IsA("ImageLabel") or Object:IsA("ImageButton") then
						local Key = nil
						pcall(function() Key = Object:GetAttribute("ValmClassIconKey") end)
						if Key then pcall(Explorer.ClassIcons.DisplayByKey, Explorer.ClassIcons, Object, Key) end
					end
				end
			end
		end
		if RefreshNow ~= false then
			if Explorer.InsertObjectContext and Explorer.InsertObjectContext.Gui then
				pcall(function() Explorer.InsertObjectContext.Gui:Destroy() end)
			end
			if type(Explorer.InitInsertObject) == "function" then pcall(Explorer.InitInsertObject) end
			if type(Explorer.Update) == "function" and type(Explorer.Refresh) == "function" then
				pcall(Explorer.Update)
				pcall(Explorer.Refresh)
			end
			RefreshClassIcons()
		end
		if not SkipPreload then
			Explorer.ClassIconLoadGeneration = (Explorer.ClassIconLoadGeneration or 0) + 1
			local Generation = Explorer.ClassIconLoadGeneration
			local MapUri = SafeName == "Old" and ("rbxassetid://" .. tostring(Source and Source.MapId or 483448923)) or ("rbxassetid://" .. tostring(Source.MapId))
			if type(task) == "table" and type(task.spawn) == "function" then
				task.spawn(function()
					local Probe = Instance.new("ImageLabel")
					Probe.Image = MapUri
					local FetchFailed = false
					local PreloadSuccess = pcall(function()
						service.ContentProvider:PreloadAsync({Probe}, function(_, FetchStatus)
							if FetchStatus ~= Enum.AssetFetchStatus.Success then FetchFailed = true end
						end)
					end)
					Probe:Destroy()
					if Explorer.ClassIconLoadGeneration ~= Generation then return end
					if (not PreloadSuccess or FetchFailed) and MiscMap and type(MiscMap.SetExplorerIconFallback) == "function" then
						pcall(MiscMap.SetExplorerIconFallback, MiscMap)
						ClassMap.Style = "OldFallback"
						ClassMap.MapId = "rbxasset://textures/ClassImages.PNG"
						ClassMap.MapSizeX = nil
						ClassMap.MapSizeY = nil
						ClassMap.IconSizeX = 16
						ClassMap.IconSizeY = 16
						ClassMap.NumX = nil
						ClassMap.IndexDict = {}
						if type(Explorer.Update) == "function" and type(Explorer.Refresh) == "function" then
							pcall(Explorer.Update)
							pcall(Explorer.Refresh)
						end
						RefreshClassIcons()
						warn("[Valm Dex] Class icon texture failed to load; using Roblox's built-in class icons.")
					end
				end)
			end
		end
		return true, SafeName
	end

	Explorer.Init = function()
		Explorer.LegacyClassIcons = Lib.IconMap.newLinear("rbxasset://textures/ClassImages.PNG", 16,16)
		Explorer.ClassIcons = Lib.IconMap.newLinear("rbxasset://textures/ClassImages.PNG", 16, 16)
		Explorer.MiscIcons = Main.MiscIcons
		Explorer.SetClassIconStyle(Settings.ClassIcon or "NewDark", false)

		clipboard = {}

		selection = Lib.Set.new()
		selection.ShiftSet = {}
		selection.Changed:Connect(Properties.ShowExplorerProps)
		Explorer.Selection = selection

		Explorer.InitRightClick()
		Explorer.InitInsertObject()
		Explorer.SetSortingEnabled(Settings.Explorer.Sorting)
		Explorer.Expanded = setmetatable({},{__mode = "k"})
		Explorer.SearchExpanded = setmetatable({},{__mode = "k"})
		expanded = Explorer.Expanded

		nilNode.Obj.Name = "Nil Instances"
		nilNode.Locked = true

		local explorerItems = create({
			{1,"Folder",{Name="ExplorerItems",}},
			{2,"Frame",{BackgroundColor3=Color3.new(0.20392157137394,0.20392157137394,0.20392157137394),BorderSizePixel=0,Name="ToolBar",Parent={1},Size=UDim2.new(1,0,0,22),}},
			{3,"Frame",{BackgroundColor3=Color3.new(0.14901961386204,0.14901961386204,0.14901961386204),BorderColor3=Color3.new(0.1176470592618,0.1176470592618,0.1176470592618),BorderSizePixel=0,Name="SearchFrame",Parent={2},Position=UDim2.new(0,3,0,1),Size=UDim2.new(1,-6,0,18),}},
			{4,"TextBox",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,ClearTextOnFocus=false,Font=3,Name="SearchBox",Parent={3},PlaceholderColor3=Color3.new(0.39215689897537,0.39215689897537,0.39215689897537),PlaceholderText="Search workspace",Position=UDim2.new(0,4,0,0),Size=UDim2.new(1,-42,0,18),Text="",TextColor3=Color3.new(1,1,1),TextSize=14,TextXAlignment=0,}},
			{5,"UICorner",{CornerRadius=UDim.new(0,2),Parent={3},}},
			{6,"UIStroke",{Thickness=1.4,Parent={3},Color=Color3.fromRGB(42,42,42)}},
			{7,"TextButton",{AutoButtonColor=false,BackgroundColor3=Color3.new(0.12549020349979,0.12549020349979,0.12549020349979),BackgroundTransparency=1,BorderSizePixel=0,Font=3,Name="Reset",Parent={3},Position=UDim2.new(1,-17,0,1),Size=UDim2.new(0,16,0,16),Text="",TextColor3=Color3.new(1,1,1),TextSize=14,}},
			{8,"ImageLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Image="rbxassetid://5034718129",ImageColor3=Color3.new(0.39215686917305,0.39215686917305,0.39215686917305),Parent={7},Size=UDim2.new(0,16,0,16),}},
			{13,"ImageButton",{AutoButtonColor=false,BackgroundTransparency=1,BorderSizePixel=0,Image="rbxassetid://104381845990658",ImageColor3=Color3.new(1,1,1),Name="AdvancedSearchButton",Parent={3},Position=UDim2.new(1,-37,0,1),ScaleType=Enum.ScaleType.Fit,Size=UDim2.new(0,16,0,16),ZIndex=6,}},
			{9,"TextButton",{AutoButtonColor=false,BackgroundColor3=Color3.new(0.12549020349979,0.12549020349979,0.12549020349979),BackgroundTransparency=1,BorderSizePixel=0,Font=3,Name="Refresh",Parent={2},Position=UDim2.new(1,-20,0,1),Size=UDim2.new(0,18,0,18),Text="",TextColor3=Color3.new(1,1,1),TextSize=14,Visible=false,}},
			{10,"ImageLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Image="rbxassetid://5642310344",Parent={9},Position=UDim2.new(0,3,0,3),Size=UDim2.new(0,12,0,12),}},
			{11,"Frame",{BackgroundColor3=Color3.new(0.15686275064945,0.15686275064945,0.15686275064945),BorderSizePixel=0,Name="ScrollCorner",Parent={1},Position=UDim2.new(1,-16,1,-16),Size=UDim2.new(0,16,0,16),Visible=false,}},
			{12,"Frame",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,ClipsDescendants=true,Name="List",Parent={1},Position=UDim2.new(0,0,0,23),Size=UDim2.new(1,0,1,-23),}}
		})

		toolBar = explorerItems.ToolBar
		treeFrame = explorerItems.List

		Explorer.GuiElems.ToolBar = toolBar
		Explorer.GuiElems.TreeFrame = treeFrame

		scrollV = Lib.ScrollBar.new()		
		scrollV.WheelIncrement = 3
		scrollV.Gui.Position = UDim2.new(1,-16,0,23)
		scrollV:SetScrollFrame(treeFrame)
		scrollV.Scrolled:Connect(function()
			Explorer.Index = scrollV.Index
			Explorer.Refresh()
		end)

		scrollH = Lib.ScrollBar.new(true)
		scrollH.Increment = 5
		scrollH.WheelIncrement = Explorer.EntryIndent
		scrollH.Gui.Position = UDim2.new(0,0,1,-16)
		scrollH.Scrolled:Connect(function()
			Explorer.Refresh()
		end)

		local window = Lib.Window.new()
		Explorer.Window = window
		window:SetTitle("Explorer")
		window.GuiElems.Line.Position = UDim2.new(0,0,0,22)

		Explorer.InitEntryTemplate()
		toolBar.Parent = window.GuiElems.Content
		treeFrame.Parent = window.GuiElems.Content
		explorerItems.ScrollCorner.Parent = window.GuiElems.Content
		scrollV.Gui.Parent = window.GuiElems.Content
		scrollH.Gui.Parent = window.GuiElems.Content

		-- Init stuff that requires the window
		Explorer.InitRenameBox()
		Explorer.InitSearch()
		Explorer.InitDelCleaner()
		selection.Changed:Connect(Explorer.UpdateSelectionVisuals)

		-- Window events
		window.GuiElems.Main:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if Explorer.Active then
				Explorer.UpdateView()
				Explorer.Refresh()
			end
		end)
		window.OnActivate:Connect(function()
			Explorer.Active = true
			Explorer.UpdateView()
			Explorer.Update()
			Explorer.Refresh()
		end)
		window.OnRestore:Connect(function()
			Explorer.Active = true
			Explorer.UpdateView()
			Explorer.Update()
			Explorer.Refresh()
		end)
		window.OnDeactivate:Connect(function() Explorer.Active = false end)
		window.OnMinimize:Connect(function() Explorer.Active = false end)

		-- Settings
		autoUpdateSearch = Settings.Explorer.AutoUpdateSearch

		-- Fill in nodes
		nodes[game] = {Obj = game}
		expanded[nodes[game]] = true

		-- Nil Instances
		if env.getnilinstances then
			nodes[nilNode.Obj] = nilNode
		end

		Explorer.SetupConnections()

		local insts = getDescendants(game)
		if Main.Elevated then
			for i = 1,#insts do
				local obj = insts[i]
				local par = nodes[ffa(obj,"Instance")]
				if not par then continue end
				local newNode = {
					Obj = obj,
					Parent = par,
				}
				nodes[obj] = newNode
				par[#par+1] = newNode
			end
		else
			for i = 1,#insts do
				local obj = insts[i]
				local s,parObj = pcall(ffa,obj,"Instance")
				local par = nodes[parObj]
				if not par then continue end
				local newNode = {
					Obj = obj,
					Parent = par,
				}
				nodes[obj] = newNode
				par[#par+1] = newNode
			end
		end

		local function AddServerNode(ServiceName)
			local ServiceObject
			local ServiceSuccess, ServiceResult = pcall(game.GetService, game, ServiceName)
			if ServiceSuccess and typeof(ServiceResult) == "Instance" then
				ServiceObject = ServiceResult
			else
				ServiceObject = Instance.new("Folder")
				ServiceObject.Name = ServiceName
			end

			local ServiceNode = nodes[ServiceObject]
			if not ServiceNode then
				ServiceNode = {
					Obj = ServiceObject,
					Parent = nodes[game],
					Class = ServiceName,
					DisplayName = ServiceName,
					ServerOnlyPlaceholder = true,
				}
				nodes[ServiceObject] = ServiceNode
				table.insert(nodes[game], ServiceNode)
			else
				ServiceNode.Class = ServiceName
				ServiceNode.DisplayName = ServiceName
				ServiceNode.ServerOnlyPlaceholder = true
			end

			local InfoObject = Instance.new("Folder")
			InfoObject.Name = "Contents Unavailable"
			local InfoNode = {
				Obj = InfoObject,
				Parent = ServiceNode,
				Class = "Folder",
				DisplayName = "Contents Unavailable",
				ServerOnlyInfo = true,
			}
			nodes[InfoObject] = InfoNode
			ServiceNode[#ServiceNode + 1] = InfoNode
		end

		AddServerNode("ServerStorage")
		AddServerNode("ServerScriptService")
		nodes[game].Sorted = nil
	end

	return Explorer
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
end,
["Lib"] = function()
--[[
	Lib Module
	
	Container for functions and classes
]]

-- Common Locals
local Main,Lib,Apps,Settings -- Main Containers
local Explorer, Properties, ScriptViewer, Notebook -- Major Apps
local API,RMD,env,service,plr,create,createSimple -- Main Locals

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple
end

local function initAfterMain()
	Explorer = Apps.Explorer
	Properties = Apps.Properties
	ScriptViewer = Apps.ScriptViewer
	Notebook = Apps.Notebook
end

local function main()
	local Lib: {[string]: any} = {}

	local renderStepped = service.RunService.RenderStepped
	local signalWait = renderStepped.wait
	local PH = newproxy() -- Placeholder, must be replaced in constructor
	local SIGNAL = newproxy()

	-- Usually for classes that work with a Roblox Object
	local function initObj(props,mt)
		local type = type
		local function copy(t)
			local res = {}
			for i,v in pairs(t) do
				if v == SIGNAL then
					res[i] = Lib.Signal.new()
				elseif type(v) == "table" then
					res[i] = copy(v)
				else
					res[i] = v
				end
			end		
			return res
		end

		local newObj = copy(props)
		return setmetatable(newObj,mt)
	end

	local function getGuiMT(props,funcs)
		return {__index = function(self,ind) if not props[ind] then return funcs[ind] or self.Gui[ind] end end,
		__newindex = function(self,ind,val) if not props[ind] then self.Gui[ind] = val else rawset(self,ind,val) end end}
	end

	-- Functions

	Lib.FormatLuaString = (function()
		local string = string
		local gsub = string.gsub
		local format = string.format
		local char = string.char
		local cleanTable = {['"'] = '\\"', ['\\'] = '\\\\'}
		for i = 0,31 do
			cleanTable[char(i)] = "\\"..format("%03d",i)
		end
		for i = 127,255 do
			cleanTable[char(i)] = "\\"..format("%03d",i)
		end

		return function(str)
			return gsub(str,"[\"\\\0-\31\127-\255]",cleanTable)
		end
	end)()

	Lib.CheckMouseInGui = function(gui)
		if gui == nil then return false end
		local mouse = Main.Mouse
		local guiPosition = gui.AbsolutePosition
		local guiSize = gui.AbsoluteSize	

		return mouse.X >= guiPosition.X and mouse.X < guiPosition.X + guiSize.X and mouse.Y >= guiPosition.Y and mouse.Y < guiPosition.Y + guiSize.Y
	end

	Lib.IsShiftDown = function()
		return service.UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or service.UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
	end

	Lib.IsCtrlDown = function()
		return service.UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or service.UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
	end

	Lib.CreateArrow = function(size,num,dir)
		local max = num
		local arrowFrame = createSimple("Frame",{
			BackgroundTransparency = 1,
			Name = "Arrow",
			Size = UDim2.new(0,size,0,size)
		})
		if dir == "up" then
			for i = 1,num do
				local newLine = createSimple("Frame",{
					BackgroundColor3 = Color3.new(220/255,220/255,220/255),
					BorderSizePixel = 0,
					Position = UDim2.new(0,math.floor(size/2)-(i-1),0,math.floor(size/2)+i-math.floor(max/2)-1),
					Size = UDim2.new(0,i+(i-1),0,1),
					Parent = arrowFrame
				})
			end
			return arrowFrame
		elseif dir == "down" then
			for i = 1,num do
				local newLine = createSimple("Frame",{
					BackgroundColor3 = Color3.new(220/255,220/255,220/255),
					BorderSizePixel = 0,
					Position = UDim2.new(0,math.floor(size/2)-(i-1),0,math.floor(size/2)-i+math.floor(max/2)+1),
					Size = UDim2.new(0,i+(i-1),0,1),
					Parent = arrowFrame
				})
			end
			return arrowFrame
		elseif dir == "left" then
			for i = 1,num do
				local newLine = createSimple("Frame",{
					BackgroundColor3 = Color3.new(220/255,220/255,220/255),
					BorderSizePixel = 0,
					Position = UDim2.new(0,math.floor(size/2)+i-math.floor(max/2)-1,0,math.floor(size/2)-(i-1)),
					Size = UDim2.new(0,1,0,i+(i-1)),
					Parent = arrowFrame
				})
			end
			return arrowFrame
		elseif dir == "right" then
			for i = 1,num do
				local newLine = createSimple("Frame",{
					BackgroundColor3 = Color3.new(220/255,220/255,220/255),
					BorderSizePixel = 0,
					Position = UDim2.new(0,math.floor(size/2)-i+math.floor(max/2)+1,0,math.floor(size/2)-(i-1)),
					Size = UDim2.new(0,1,0,i+(i-1)),
					Parent = arrowFrame
				})
			end
			return arrowFrame
		end
		error("r u ok")
	end

	Lib.ParseXML = (function()
		local func = function()
			-- Only exists to parse RMD
			-- from https://github.com/jonathanpoelen/xmlparser

			local string, print, pairs = string, print, pairs

			-- http://lua-users.org/wiki/StringTrim
			local trim = function(s)
				local from = s:match"^%s*()"
				return from > #s and "" or s:match(".*%S", from)
			end

			local gtchar = string.byte('>', 1)
			local slashchar = string.byte('/', 1)
			local D = string.byte('D', 1)
			local E = string.byte('E', 1)

			function parse(s, evalEntities)
				-- remove comments
				s = s:gsub('<!%-%-(.-)%-%->', '')

				local entities, tentities = {}

				if evalEntities then
					local pos = s:find('<[_%w]')
					if pos then
						s:sub(1, pos):gsub('<!ENTITY%s+([_%w]+)%s+(.)(.-)%2', function(name, q, entity)
							entities[#entities+1] = {name=name, value=entity}
						end)
						tentities = createEntityTable(entities)
						s = replaceEntities(s:sub(pos), tentities)
					end
				end

				local t, l = {}, {}

				local addtext = function(txt)
					txt = txt:match'^%s*(.*%S)' or ''
					if #txt ~= 0 then
						t[#t+1] = {text=txt}
					end		
				end

				s:gsub('<([?!/]?)([-:_%w]+)%s*(/?>?)([^<]*)', function(type, name, closed, txt)
					-- open
					if #type == 0 then
						local a = {}
						if #closed == 0 then
							local len = 0
							for all,aname,_,value,starttxt in string.gmatch(txt, "(.-([-_%w]+)%s*=%s*(.)(.-)%3%s*(/?>?))") do
								len = len + #all
								a[aname] = value
								if #starttxt ~= 0 then
									txt = txt:sub(len+1)
									closed = starttxt
									break
								end
							end
						end
						t[#t+1] = {tag=name, attrs=a, children={}}

						if closed:byte(1) ~= slashchar then
							l[#l+1] = t
							t = t[#t].children
						end

						addtext(txt)
						-- close
					elseif '/' == type then
						t = l[#l]
						l[#l] = nil

						addtext(txt)
						-- ENTITY
					elseif '!' == type then
						if E == name:byte(1) then
							txt:gsub('([_%w]+)%s+(.)(.-)%2', function(name, q, entity)
								entities[#entities+1] = {name=name, value=entity}
							end, 1)
						end
						-- elseif '?' == type then
						--	 print('?	' .. name .. ' // ' .. attrs .. '$$')
						-- elseif '-' == type then
						--	 print('comment	' .. name .. ' // ' .. attrs .. '$$')
						-- else
						--	 print('o	' .. #p .. ' // ' .. name .. ' // ' .. attrs .. '$$')
					end
				end)

				return {children=t, entities=entities, tentities=tentities}
			end

			function parseText(txt)
				return parse(txt)
			end

			function defaultEntityTable()
				return { quot='"', apos='\'', lt='<', gt='>', amp='&', tab='\t', nbsp=' ', }
			end

			function replaceEntities(s, entities)
				return s:gsub('&([^;]+);', entities)
			end

			function createEntityTable(docEntities, resultEntities)
				entities = resultEntities or defaultEntityTable()
				for _,e in pairs(docEntities) do
					e.value = replaceEntities(e.value, entities)
					entities[e.name] = e.value
				end
				return entities
			end

			return parseText
		end
		local newEnv = setmetatable({},{__index = getfenv()})
		setfenv(func,newEnv)
		return func()
	end)()

	Lib.FastWait = function(s)
		if not s then return signalWait(renderStepped) end
		local start = tick()
		while tick() - start < s do signalWait(renderStepped) end
	end

	Lib.ButtonAnim = function(button,data)
		local holding = false
		local disabled = false
		local mode = data and data.Mode or 1
		local control = {}

		if mode == 2 then
			local lerpTo = data.LerpTo or Color3.new(0,0,0)
			local delta = data.LerpDelta or 0.2
			control.StartColor = data.StartColor or button.BackgroundColor3
			control.PressColor = data.PressColor or control.StartColor:lerp(lerpTo,delta)
			control.HoverColor = data.HoverColor or control.StartColor:lerp(control.PressColor,0.6)
			control.OutlineColor = data.OutlineColor
		end

		button.InputBegan:Connect(function(input)
			if disabled then return end

			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				if not holding then
					if mode == 1 then
						button.BackgroundTransparency = 0.4
					elseif mode == 2 then
						button.BackgroundColor3 = control.HoverColor
					end
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				holding = true
				if mode == 1 then
					button.BackgroundTransparency = 0
				elseif mode == 2 then
					button.BackgroundColor3 = control.PressColor
					if control.OutlineColor then button.BorderColor3 = control.PressColor end
				end
			end
		end)

		button.InputEnded:Connect(function(input)
			if disabled then return end

			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				if not holding then
					if mode == 1 then
						button.BackgroundTransparency = 1
					elseif mode == 2 then
						button.BackgroundColor3 = control.StartColor
					end
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				holding = false
				if mode == 1 then
					button.BackgroundTransparency = Lib.CheckMouseInGui(button) and 0.4 or 1
				elseif mode == 2 then
					button.BackgroundColor3 = Lib.CheckMouseInGui(button) and control.HoverColor or control.StartColor
					if control.OutlineColor then button.BorderColor3 = control.OutlineColor end
				end
			end
		end)

		control.Disable = function()
			disabled = true
			holding = false

			if mode == 1 then
				button.BackgroundTransparency = 1
			elseif mode == 2 then
				button.BackgroundColor3 = control.StartColor
			end
		end

		control.Enable = function()
			disabled = false
		end

		return control
	end

	Lib.FindAndRemove = function(t,item)
		local pos = table.find(t,item)
		if pos then table.remove(t,pos) end
	end

	Lib.AttachTo = function(obj,data)
		local target,posOffX,posOffY,sizeOffX,sizeOffY,resize,con
		local disabled = false

		local function update()
			if not obj or not target then return end

			local targetPos = target.AbsolutePosition
			local targetSize = target.AbsoluteSize
			obj.Position = UDim2.new(0,targetPos.X + posOffX,0,targetPos.Y + posOffY)
			if resize then obj.Size = UDim2.new(0,targetSize.X + sizeOffX,0,targetSize.Y + sizeOffY) end
		end

		local function setup(o,data)
			obj = o
			data = data or {}
			target = data.Target
			posOffX = data.PosOffX or 0
			posOffY = data.PosOffY or 0
			sizeOffX = data.SizeOffX or 0
			sizeOffY = data.SizeOffY or 0
			resize = data.Resize or false

			if con then con:Disconnect() con = nil end
			if target then
				con = target.Changed:Connect(function(prop)
					if not disabled and prop == "AbsolutePosition" or prop == "AbsoluteSize" then
						update()
					end
				end)
			end

			update()
		end
		setup(obj,data)

		return {
			SetData = function(obj,data)
				setup(obj,data)
			end,
			Enable = function()
				disabled = false
				update()
			end,
			Disable = function()
				disabled = true
			end,
			Destroy = function()
				con:Disconnect()
				con = nil
			end,
		}
	end

