			{11,"Frame",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,ClipsDescendants=true,Name="List",Parent={1},Position=UDim2.new(0,0,0,23),Size=UDim2.new(1,0,1,-23),}},
		})

		-- Vars
		categoryOrder =  API.CategoryOrder
		for category,_ in next,categoryOrder do
			if not Properties.CollapsedCategories[category] then
				expanded["CAT_"..category] = true
			end
		end
		expanded["Sound.SoundId"] = true

		-- Init window
		window = Lib.Window.new()
		Properties.Window = window
		window:SetTitle("Properties")

		toolBar = guiItems.ToolBar
		propsFrame = guiItems.List

		Properties.GuiElems.ToolBar = toolBar
		Properties.GuiElems.PropsFrame = propsFrame

		Properties.InitEntryStuff()

		-- Window events
		window.GuiElems.Main:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if Properties.Window:IsContentVisible() then
				Properties.UpdateView()
				Properties.Refresh()
			end
		end)
		window.OnActivate:Connect(function()
			Properties.UpdateView()
			Properties.Update()
			Properties.Refresh()
		end)
		window.OnRestore:Connect(function()
			Properties.UpdateView()
			Properties.Update()
			Properties.Refresh()
		end)

		-- Init scrollbars
		scrollV = Lib.ScrollBar.new()		
		scrollV.WheelIncrement = 3
		scrollV.Gui.Position = UDim2.new(1,-16,0,23)
		scrollV:SetScrollFrame(propsFrame)
		scrollV.Scrolled:Connect(function()
			Properties.Index = scrollV.Index
			Properties.Refresh()
		end)

		scrollH = Lib.ScrollBar.new(true)
		scrollH.Increment = 5
		scrollH.WheelIncrement = 20
		scrollH.Gui.Position = UDim2.new(0,0,1,-16)
		scrollH.Scrolled:Connect(function()
			Properties.Refresh()
		end)

		-- Setup Gui
		window.GuiElems.Line.Position = UDim2.new(0,0,0,22)
		toolBar.Parent = window.GuiElems.Content
		propsFrame.Parent = window.GuiElems.Content
		guiItems.ScrollCorner.Parent = window.GuiElems.Content
		scrollV.Gui.Parent = window.GuiElems.Content
		scrollH.Gui.Parent = window.GuiElems.Content
		Properties.InitInputBox()
		Properties.InitSearch()
	end

	return Properties
end

-- TODO: Remove when open source
if gethsfuncs then
	_G.moduleData = {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
else
	return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
end
end,
["SaveInstance"] = function()
--[[
	Save Instance App Module
	
	Revival of the old dex's Save Instance
]] 

-- Common Locals
local Main,Lib,Apps,Settings -- Main Containers
local Explorer, Properties, ScriptViewer, SaveInstance, Notebook -- Major Apps
local API,RMD,env,service,plr,create,createSimple -- Main Locals

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple
end

local function initAfterMain()
	Explorer = Apps.Explorer
	Properties = Apps.Properties
	ScriptViewer = Apps.ScriptViewer
	SaveInstance = Apps.SaveInstance
	Notebook = Apps.Notebook
end

local function main()
	local SaveInstance = {}
	local window, ListFrame
	local fileName = "Place_"..game.PlaceId.."_"..game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name.."_{TIMESTAMP}"
	local Saving = false
	
	local SaveInstanceArgs = {
		Decompile = true,
		DecompileTimeout = 10,
		DecompileIgnore = {"Chat", "CoreGui", "CorePackages"},
		NilInstances = false,
		RemovePlayerCharacters = true,
		SavePlayers = false,
		MaxThreads = 3,
		ShowStatus = true,
		IgnoreDefaultProps = true,
		IsolateStarterPlayer = true
	}
	
	local function AddCheckbox(title, default)
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)
		
		local listlayout = Instance.new("UIListLayout")
		listlayout.Parent = frame.Gui
		listlayout.FillDirection = Enum.FillDirection.Horizontal
		listlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		listlayout.VerticalAlignment = Enum.VerticalAlignment.Center
		listlayout.Padding = UDim.new(0, 10)
		
		-- Checkbox
		local checkbox = Lib.Checkbox.new()
		
		checkbox.Gui.Parent = frame.Gui
		checkbox.Gui.Size = UDim2.new(0,15,0,15)
		
		-- Label
		local label = Lib.Label.new()
		
		label.Gui.Parent = frame.Gui
		label.Gui.Size = UDim2.new(1, 0,1, -15)
		label.Gui.Text = title
		label.TextTruncate = Enum.TextTruncate.AtEnd
		
		checkbox:SetState(default)
		
		return checkbox
	end
	
	local function AddTextbox(title, default, sizeX)
		default = tostring(default)
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)

		local listlayout = Instance.new("UIListLayout")
		listlayout.Parent = frame.Gui
		listlayout.FillDirection = Enum.FillDirection.Horizontal
		listlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		listlayout.VerticalAlignment = Enum.VerticalAlignment.Center
		listlayout.Padding = UDim.new(0, 10)

		-- Textbox
		local textbox = Instance.new("TextBox") -- replaced cuz why Moon make every inputs only work on mouse/pc users >:( 
		textbox.BackgroundColor3 = Settings.Theme.TextBox
		textbox.BorderColor3 = Settings.Theme.Outline3
		textbox.ClearTextOnFocus = false
		textbox.TextColor3 = Settings.Theme.Text
		textbox.Font = Enum.Font.SourceSans
		textbox.TextSize = 14
		textbox.ZIndex = 2

		textbox.Parent = frame.Gui
		if sizeX and type(sizeX) == "number" then
			textbox.Size = UDim2.new(0,sizeX,0,15)
		else
			textbox.Size = UDim2.new(0,45,0,15)
		end
		
		frame.Gui.AutomaticSize = Enum.AutomaticSize.X
		textbox.AutomaticSize = Enum.AutomaticSize.X

		-- Label
		local label = Lib.Label.new()

		label.Parent = frame.Gui
		label.Size = UDim2.new(1, 0,1, -15)
		label.Text = title
		label.TextTruncate = Enum.TextTruncate.AtEnd

		textbox.Text = default

		return {TextBox = textbox}
	end
	
	SaveInstance.Init = function()
		window = Lib.Window.new()
		window:SetTitle("Save Instance")
		window:Resize(350,350)
		SaveInstance.Window = window
		
		-- ListFrame
		
		-- Fake ScrollBar dex, because its too advanced
		ListFrame = Instance.new("ScrollingFrame")
		ListFrame.Parent = window.GuiElems.Content
		ListFrame.Size = UDim2.new(1, 0,1, -40)
		ListFrame.Position = UDim2.new(0, 0, 0, 0)
		ListFrame.Transparency = 1
		ListFrame.CanvasSize = UDim2.new(0,0,0,0)
		ListFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
		ListFrame.ScrollBarThickness = 16
		ListFrame.BottomImage = ""
		ListFrame.TopImage = ""
		ListFrame.ScrollBarImageColor3 = Color3.fromRGB(70, 70, 70)
		ListFrame.ScrollBarImageTransparency = 0
		ListFrame.ZIndex = 2
		ListFrame.BorderSizePixel = 0
		
		local scrollbar = Lib.ScrollBar.new()
		scrollbar.Gui.Parent = window.GuiElems.Content
		scrollbar.Gui.Size = UDim2.new(1, 0,1, -40)
		scrollbar.Gui.Up.ZIndex = 3
		scrollbar.Gui.Down.ZIndex = 3
		
		ListFrame:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(function()
			if ListFrame.AbsoluteCanvasSize ~= ListFrame.AbsoluteWindowSize then
				scrollbar.Gui.Visible = true
			else
				scrollbar.Gui.Visible = false
			end
		end)
		
		local ListLayout = Instance.new("UIListLayout")
		ListLayout.Parent = ListFrame
		ListLayout.Padding = UDim.new(0, 5)
		
		local Padding = Instance.new("UIPadding")
		Padding.Parent = ListFrame
		Padding.PaddingBottom = UDim.new(0, 5)
		Padding.PaddingLeft = UDim.new(0, 10)
		Padding.PaddingRight = UDim.new(0, 10)
		Padding.PaddingTop = UDim.new(0, 5)
		
		-- Options
		
		local Decompile = AddCheckbox("Decompile Scripts (LocalScript and ModuleScript)", SaveInstanceArgs.Decompile)
		Decompile.OnInput:Connect(function()
			SaveInstanceArgs.Decompile = Decompile.Toggled
		end)
		
		local decompileTimeout = AddTextbox("Decompile Timeout (s)", SaveInstanceArgs.DecompileTimeout, 15)
		decompileTimeout.TextBox.FocusLost:Connect(function()
			SaveInstanceArgs.DecompileTimeout = tonumber(decompileTimeout.TextBox.Text)
		end)
		
		local decompileThread = AddTextbox("Decompiler Max Threads", "3", 15)
		decompileThread.TextBox.FocusLost:Connect(function()
			SaveInstanceArgs.MaxThreads = tonumber(decompileThread.TextBox.Text)
		end)
		
		local decompileIgnore = AddTextbox("Decompile Ignore", table.concat(SaveInstanceArgs.DecompileIgnore, ","), 50)
		decompileIgnore.TextBox.FocusLost:Connect(function()
			local inputText = decompileIgnore.TextBox.Text
			local rawList = string.split(inputText, ", ") or string.split(inputText, ",")
			local finalList = {}

			for _, text in ipairs(rawList) do
				local split = string.split(text, ",") or string.split(text, ", ")
				for _, textFound in ipairs(split) do
					table.insert(finalList, textFound)
				end
			end
			SaveInstanceArgs.DecompileIgnore = finalList
		end)

		
		local NilObj = AddCheckbox("Save Nil Instances", SaveInstanceArgs.NilInstances)
		NilObj.OnInput:Connect(function()
			SaveInstanceArgs.NilInstances = NilObj.Toggled
		end)

		local RemovePlayerChar = AddCheckbox("Remove Player Characters", SaveInstanceArgs.RemovePlayerCharacters)
		RemovePlayerChar.OnInput:Connect(function()
			SaveInstanceArgs.RemovePlayerCharacters = RemovePlayerChar.Toggled
		end)
		
		local SavePlayerObj = AddCheckbox("Save Player Instance", SaveInstanceArgs.SavePlayers)
		SavePlayerObj.OnInput:Connect(function()
			SaveInstanceArgs.SavePlayers = SavePlayerObj.Toggled
		end)
		
		local IsolateStarterPlr = AddCheckbox("Isolate StarterPlayer", SaveInstanceArgs.IsolateStarterPlayer)
		IsolateStarterPlr.OnInput:Connect(function()
			SaveInstanceArgs.IsolateStarterPlayer = IsolateStarterPlr.Toggled
		end)
		
		local IgnoreDefaultProps = AddCheckbox("Ignore Default Properties", SaveInstanceArgs.IgnoreDefaultProps)
		IgnoreDefaultProps.OnInput:Connect(function()
			SaveInstanceArgs.IgnoreDefaultProps = IgnoreDefaultProps.Toggled
		end)
		
		local ShowStat = AddCheckbox("Show Status", SaveInstanceArgs.ShowStatus)
		ShowStat.OnInput:Connect(function()
			SaveInstanceArgs.ShowStatus = ShowStat.Toggled
		end)
		
		
		-- Decompile buttons below
		local FilenameTextBox = Lib.ViewportTextBox.new()
		FilenameTextBox.Gui.Parent = window.GuiElems.Content
		FilenameTextBox.Size = UDim2.new(1,0, 0,20)
		FilenameTextBox.Position = UDim2.new(0,0, 1,-40)
		
		local textpadding = Instance.new("UIPadding")
		textpadding.Parent = FilenameTextBox.Gui
		textpadding.PaddingLeft = UDim.new(0, 5)
		textpadding.PaddingRight = UDim.new(0, 5)
		
		local BackgroundButton = Lib.Frame.new()
		BackgroundButton.Gui.Parent = window.GuiElems.Content
		BackgroundButton.Size = UDim2.new(1,0, 0,20)
		BackgroundButton.Position = UDim2.new(0,0, 1,-20)
		
		local LabelButton = Lib.Label.new()
		LabelButton.Gui.Parent = window.GuiElems.Content
		LabelButton.Size = UDim2.new(1,0, 0,20)
		LabelButton.Position = UDim2.new(0,0, 1,-20)
		LabelButton.Gui.Text = "Save"
		LabelButton.Gui.TextXAlignment = Enum.TextXAlignment.Center
		
		local Button = Instance.new("TextButton")
		Button.Parent = BackgroundButton.Gui
		Button.Size = UDim2.new(1,0, 1,0)
		Button.Position = UDim2.new(0,0, 0,0)
		Button.Transparency = 1
		
		FilenameTextBox.TextBox.Text = fileName
		Button.MouseButton1Click:Connect(function()
			local fileName = FilenameTextBox.TextBox.Text:gsub("{TIMESTAMP}", os.date("%d-%m-%Y_%H-%M-%S"))
			window:SetTitle("Save Instance - Saving")
			local s, result = pcall(env.saveinstance, game, fileName, SaveInstanceArgs)
			if s then
				window:SetTitle("Save Instance - Saved")
			else
				window:SetTitle("Save Instance - Error")
				task.spawn(error("Failed to save the game: "..result))
			end
			task.wait(5)
			window:SetTitle("Save Instance")
			---env.saveinstance(game, fileName, SaveInstanceArgs)
		end)
	end

	return SaveInstance
end

-- TODO: Remove when open source
if gethsfuncs then
	_G.moduleData = {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
else
	return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
end
end,

["DeveloperTools"] = function()
local Main, Lib, Apps, Settings
local ScriptViewer
local env
local service

local function InitDeps(Data)
		Main = Data.Main
		Lib = Data.Lib
		Apps = Data.Apps
		Settings = Data.Settings
		env = Data.env
		service = Data.service
end

local function InitAfterMain(Data)
		ScriptViewer = Data.ScriptViewer
end

local function MainModule()
		local DeveloperTools = {}
		local Window
		local Pages = {}
		local PageButtons = {}
		local StatusLabel
		local DeviceOutput
		local AnalyzerSource
		local AnalyzerOutput
		local SearchQuery
		local SearchOutput
		local ActivePage = "Device"
		local Connections = {}

		local function GetDeviceInfo()
			if type(Main.GetDeviceInfo) == "function" then
				return Main.GetDeviceInfo()
			end
			local UserInput = service.UserInputService
			local Camera = workspace.CurrentCamera
			local Viewport = Camera and Camera.ViewportSize or Vector2.new(1280, 720)
			return {
				Device = UserInput.TouchEnabled and (UserInput.KeyboardEnabled and "Tablet / Hybrid" or "Mobile") or "Desktop",
				IsCompact = UserInput.TouchEnabled or Viewport.X < 700,
				TouchEnabled = UserInput.TouchEnabled,
				KeyboardEnabled = UserInput.KeyboardEnabled,
				MouseEnabled = UserInput.MouseEnabled,
				GamepadEnabled = UserInput.GamepadEnabled,
				Platform = "Unknown",
				Viewport = Viewport,
				ViewportWidth = Viewport.X,
				ViewportHeight = Viewport.Y
			}
		end

		local function GetThemeColor(Name, Fallback)
			local Theme = Settings and Settings.Theme
			local Value = Theme and Theme[Name]
			if typeof(Value) == "Color3" then
				return Value
			end
			return Fallback
		end

		local function FlattenWindow(WindowObject)
			if not WindowObject or not WindowObject.GuiElems or not WindowObject.GuiElems.Main then
				return
			end
			for _, Item in ipairs(WindowObject.GuiElems.Main:GetDescendants()) do
				if Item:IsA("UICorner") then
					Item:Destroy()
				end
			end
			if WindowObject.GuiElems.Outlines then
				WindowObject.GuiElems.Outlines.Visible = false
			end
		end

		local function SetStatus(Text, IsError)
			if StatusLabel then
				StatusLabel.Text = tostring(Text or "Ready")
				StatusLabel.TextColor3 = GetThemeColor("Text", Color3.fromRGB(240, 240, 240))
			end
		end

		local function CreateButton(Parent, Text, Position, Size, Callback)
			local Button = Instance.new("TextButton")
			Button.BackgroundColor3 = GetThemeColor("Button", Color3.fromRGB(60, 60, 60))
			Button.BorderColor3 = GetThemeColor("Outline2", Color3.fromRGB(55, 55, 55))
			Button.BorderSizePixel = 1
			Button.Font = Enum.Font.SourceSansSemibold
			Button.TextSize = 14
			Button.TextColor3 = GetThemeColor("Text", Color3.fromRGB(240, 240, 240))
			Button.Text = Text
			Button.AutoButtonColor = false
			Button.Position = Position
			Button.Size = Size
			Button.Parent = Parent
			Button.MouseEnter:Connect(function()
				Button.BackgroundColor3 = GetThemeColor("ButtonHover", Color3.fromRGB(68, 68, 68))
			end)
			Button.MouseLeave:Connect(function()
				Button.BackgroundColor3 = GetThemeColor("Button", Color3.fromRGB(60, 60, 60))
			end)
			if Callback then
				Button.Activated:Connect(Callback)
			end
			return Button
		end

		local function CreateTextBox(Parent, Placeholder, Position, Size, Editable)
			local Box = Instance.new("TextBox")
			Box.BackgroundColor3 = GetThemeColor("TextBox", Color3.fromRGB(38, 38, 38))
			Box.BorderColor3 = GetThemeColor("Outline3", Color3.fromRGB(30, 30, 30))
			Box.BorderSizePixel = 1
			Box.ClearTextOnFocus = false
			Box.Font = Enum.Font.Code
			Box.TextSize = 13
			Box.TextColor3 = GetThemeColor("Text", Color3.fromRGB(225, 225, 225))
			Box.PlaceholderColor3 = GetThemeColor("PlaceholderText", Color3.fromRGB(125, 125, 125))
			Box.PlaceholderText = Placeholder
			Box.Text = ""
			Box.TextWrapped = true
			Box.TextXAlignment = Enum.TextXAlignment.Left
			Box.TextYAlignment = Enum.TextYAlignment.Top
			Box.MultiLine = true
			Box.TextEditable = Editable
			Box.ClearTextOnFocus = false
			Box.Position = Position
			Box.Size = Size
			Box.Parent = Parent
			local Padding = Instance.new("UIPadding")
			Padding.PaddingLeft = UDim.new(0, 7)
			Padding.PaddingRight = UDim.new(0, 7)
			Padding.PaddingTop = UDim.new(0, 6)
			Padding.Parent = Box
			return Box
		end

		local function GetCurrentSource()
			if ScriptViewer and type(ScriptViewer.GetCurrentSource) == "function" then
				local Success, Source = pcall(ScriptViewer.GetCurrentSource)
				if Success and type(Source) == "string" then
					return Source
				end
			end
			return ""
		end

		local function RefreshDeviceInfo()
			local Info = GetDeviceInfo()
			local Viewport = Info.Viewport or Vector2.new(0, 0)
			local DeviceLines = {
				"DEVICE PROFILE",
				"Device: " .. tostring(Info.Device or "Unknown"),
				"Platform: " .. tostring(Info.Platform or "Unknown"),
				"Viewport: " .. tostring(math.floor(Viewport.X)) .. " × " .. tostring(math.floor(Viewport.Y)),
				"Touch input: " .. (Info.TouchEnabled and "Available" or "Unavailable"),
				"Keyboard: " .. (Info.KeyboardEnabled and "Available" or "Unavailable"),
				"Mouse: " .. (Info.MouseEnabled and "Available" or "Unavailable"),
				"Gamepad: " .. (Info.GamepadEnabled and "Available" or "Unavailable"),
				"Compact layout: " .. (Info.IsCompact and "Enabled" or "Disabled"),
				"",
				"Valm Dex adapts its editor and buttons to touch-capable and narrow screens."
			}
			if DeviceOutput then
				DeviceOutput.Text = table.concat(DeviceLines, "\n")
			end
			SetStatus("Device profile refreshed")
		end

		local function AnalyzeSource(Source)
			local Findings = {}
			local Lines = string.split(Source, "\n")
			local HasYield = Source:find("task.wait", 1, true) ~= nil or Source:find("wait(", 1, true) ~= nil or Source:find("RunService", 1, true) ~= nil
			local HasDynamicExecution = Source:match("%f[%w]loadstring%s*%(") ~= nil
			local HasRemoteFetch = Source:match("%f[%w]HttpGet%s*%(") ~= nil or Source:match("%f[%w]request%s*%(") ~= nil

			local function AddFinding(Severity, LineNumber, Message)
				Findings[#Findings + 1] = string.format("[%s] Line %d: %s", Severity, LineNumber, Message)
			end

			for LineNumber, Line in ipairs(Lines) do
				local LowerLine = string.lower(Line)
				if Line:match("%f[%w]wait%s*%(") and not Line:match("task%s*%.%s*wait%s*%(") then
					AddFinding("INFO", LineNumber, "Consider task.wait() instead of legacy wait().")
				end
				if Line:match("%f[%w]spawn%s*%(") and not Line:match("task%s*%.%s*spawn%s*%(") then
					AddFinding("INFO", LineNumber, "Consider task.spawn() for scheduled work.")
				end
				if Line:match("%f[%w]tick%s*%(%s*%)") then
					AddFinding("INFO", LineNumber, "Review tick() usage; use time() or os.clock() where appropriate.")
				end
				if LowerLine:match("while%s+true%s+do") and not HasYield then
					AddFinding("WARN", LineNumber, "Infinite loop candidate: no obvious yield was found in the source.")
				end
				if Line:find("GetDescendants()", 1, true) then
					AddFinding("INFO", LineNumber, "GetDescendants() can be expensive on large hierarchies; cache or narrow the result.")
				end
				local VariableName, SecretValue = LowerLine:match("([%w_]*key[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				if not VariableName then
					VariableName, SecretValue = LowerLine:match("([%w_]*token[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				end
				if not VariableName then
					VariableName, SecretValue = LowerLine:match("([%w_]*secret[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				end
				if not VariableName then
					VariableName, SecretValue = LowerLine:match("([%w_]*password[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				end
				if VariableName and SecretValue and #SecretValue >= 16 then
					AddFinding("REVIEW", LineNumber, "Possible hard-coded credential in " .. tostring(VariableName) .. "; rotate it and move it out of source code.")
				end
			end

			if HasDynamicExecution then
				Findings[#Findings + 1] = "[REVIEW] Dynamic code execution via loadstring was detected; only execute code from trusted sources."
			end
			if HasRemoteFetch and HasDynamicExecution then
				Findings[#Findings + 1] = "[WARN] The source combines remote fetching and dynamic execution; validate content and avoid executing downloaded code."
			end
			if #Findings == 0 then
				Findings[1] = "No common reliability or security patterns were flagged by this lightweight scan."
			end
			return "Static review only. These hints are not proof of safety or a complete vulnerability scan.\n\n" .. table.concat(Findings, "\n")
		end

		local function RunSearch()
			local Source = GetCurrentSource()
			local Query = SearchQuery and SearchQuery.Text or ""
			if Query == "" then
				SetStatus("Enter a search term", true)
				return
			end
			if Source == "" then
				SearchOutput.Text = "No open decompiled script. Open a client-accessible script in Decompiler first."
				SetStatus("No open source", true)
				return
			end
			local Results = {}
			local MatchCount = 0
			for LineNumber, Line in ipairs(string.split(Source, "\n")) do
				if string.find(string.lower(Line), string.lower(Query), 1, true) then
					MatchCount += 1
					if #Results < 150 then
						Results[#Results + 1] = string.format("%04d | %s", LineNumber, Line)
					end
				end
			end
			if MatchCount == 0 then
				SearchOutput.Text = "No matches found for: " .. Query
			else
				SearchOutput.Text = string.format("%d matching lines\n\n%s", MatchCount, table.concat(Results, "\n"))
			end
			SetStatus(string.format("Search completed: %d matching lines", MatchCount))
		end

		local function ShowPage(PageName)
			ActivePage = PageName
			for Name, Page in pairs(Pages) do
				Page.Visible = Name == PageName
			end
			for Name, Button in pairs(PageButtons) do
				Button.BackgroundColor3 = Name == PageName and GetThemeColor("ButtonHover", Color3.fromRGB(68, 68, 68)) or GetThemeColor("Button", Color3.fromRGB(60, 60, 60))
			end
			if PageName == "Device" then
