		local function ApplyWindowLayout()
			local Info = GetDeviceInfo()
			local Width = 340
			local Height = 300
			if Info.IsCompact then
				Width = math.max(270, math.min(300, Info.ViewportWidth - 32))
				Height = math.max(250, math.min(280, Info.ViewportHeight - 64))
			end
			if Window then
				Window:Resize(Width, Height)
				Window.GuiElems.Main.Position = UDim2.new(0.5, -Width / 2, 0.5, -Height / 2)
			end
			return Info
		end

		DeveloperTools.Init = function()
			Window = Lib.Window.new()
			FlattenWindow(Window)
			Window:SetTitle("Developer Tools")
