			PageContainer.Parent = Content

			for _, PageName in ipairs(PageNames) do
				local Page = Instance.new("Frame")
				Page.Name = PageName
				Page.BackgroundTransparency = 1
				Page.Size = UDim2.new(1, 0, 1, 0)
				Page.Visible = false
				Page.Parent = PageContainer
				Pages[PageName] = Page
			end

			local DevicePage = Pages.Device
			CreateButton(DevicePage, "Refresh Device Info", UDim2.new(0, 7, 0, 5), UDim2.new(0, 145, 0, 32), RefreshDeviceInfo)
			DeviceOutput = CreateTextBox(DevicePage, "Device information", UDim2.new(0, 7, 0, 44), UDim2.new(1, -14, 1, -52), false)

			local AnalyzerPage = Pages.Analyzer
			local LoadAnalyzerButton = CreateButton(AnalyzerPage, Info.IsCompact and "Load" or "Load Open Script", UDim2.new(0, 6, 0, 4), UDim2.new(0, Info.IsCompact and 84 or 112, 0, 30), function()
				AnalyzerSource.Text = GetCurrentSource()
				SetStatus("Loaded current Decompiler source")
			end)
			local AnalyzeButton = CreateButton(AnalyzerPage, "Analyze", UDim2.new(0, Info.IsCompact and 96 or 122, 0, 4), UDim2.new(0, Info.IsCompact and 64 or 82, 0, 30), function()
				AnalyzerOutput.Text = AnalyzeSource(AnalyzerSource.Text)
				SetStatus("Static review completed")
			end)
			local CopyReportButton = CreateButton(AnalyzerPage, "Copy Report", UDim2.new(0, Info.IsCompact and 166 or 208, 0, 4), UDim2.new(0, Info.IsCompact and 96 or 96, 0, 30), function()
				if type(env.setclipboard) == "function" then
					env.setclipboard(AnalyzerOutput.Text)
					SetStatus("Report copied")
				else
					SetStatus("Clipboard is unavailable in this environment", true)
				end
			end)
			if Info.IsCompact then
				LoadAnalyzerButton.TextSize = 12
				AnalyzeButton.TextSize = 12
				CopyReportButton.TextSize = 12
			end
			AnalyzerSource = CreateTextBox(AnalyzerPage, "Paste Luau source here, or load the current Decompiler source", UDim2.new(0, 7, 0, 42), UDim2.new(1, -14, 0.46, -48), true)
			AnalyzerOutput = CreateTextBox(AnalyzerPage, "Analysis results will appear here", UDim2.new(0, 7, 0.48, 0), UDim2.new(1, -14, 0.52, -8), false)

			local SearchPage = Pages.Search
			local LoadSearchButton = CreateButton(SearchPage, Info.IsCompact and "Load" or "Load Open Script", UDim2.new(0, 6, 0, 4), UDim2.new(0, Info.IsCompact and 78 or 112, 0, 30), function()
				local Source = GetCurrentSource()
				if Source == "" then
					SearchOutput.Text = "Open a client-accessible script in Decompiler first."
					SetStatus("No current Decompiler source", true)
				else
					SearchOutput.Text = "Current Decompiler source is ready. Enter a term and press Find."
					SetStatus("Current Decompiler source loaded")
				end
			end)
			SearchQuery = Instance.new("TextBox")
			SearchQuery.BackgroundColor3 = GetThemeColor("TextBox", Color3.fromRGB(38, 38, 38))
			SearchQuery.BorderColor3 = GetThemeColor("Outline3", Color3.fromRGB(30, 30, 30))
			SearchQuery.ClearTextOnFocus = false
			SearchQuery.Font = Enum.Font.SourceSans
			SearchQuery.TextSize = 14
			SearchQuery.TextColor3 = GetThemeColor("Text", Color3.fromRGB(240, 240, 240))
			SearchQuery.PlaceholderText = "Find text in open script"
			SearchQuery.PlaceholderColor3 = GetThemeColor("PlaceholderText", Color3.fromRGB(125, 125, 125))
			SearchQuery.Text = ""
			SearchQuery.Position = UDim2.new(0, 6, 0, 42)
			SearchQuery.Size = UDim2.new(1, -124, 0, 32)
			SearchQuery.Parent = SearchPage
			local FindButton = CreateButton(SearchPage, "Find", UDim2.new(1, -108, 0, 42), UDim2.new(0, 102, 0, 32), RunSearch)
			SearchOutput = CreateTextBox(SearchPage, "Search results", UDim2.new(0, 7, 0, 82), UDim2.new(1, -14, 1, -90), false)
			SearchQuery.FocusLost:Connect(function(EnterPressed)
				if EnterPressed then
					RunSearch()
				end
			end)

			local SnippetsPage = Pages.Snippets
			local Snippets = {
				{"Players Service", 'local Players = game:GetService("Players")\nlocal LocalPlayer = Players.LocalPlayer'},
				{"Safe Connection", 'local Connection\nConnection = SomeSignal:Connect(function(...)\n	print(...)\nend)\n\nConnection:Disconnect()'},
				{"Touch Input", 'local UserInputService = game:GetService("UserInputService")\n\nUserInputService.InputBegan:Connect(function(Input, GameProcessed)\n	if Input.UserInputType == Enum.UserInputType.Touch then\n		print("Touch input")\n	end\nend)'},
				{"Responsive Viewport", 'local Camera = workspace.CurrentCamera\nlocal Viewport = Camera and Camera.ViewportSize or Vector2.new(1280, 720)\nlocal IsCompact = Viewport.X < 700'}
			}
			for Index, Entry in ipairs(Snippets) do
				local Button = CreateButton(SnippetsPage, Entry[1] .. "  ·  Copy", UDim2.new(0, 7, 0, 6 + (Index - 1) * 42), UDim2.new(1, -14, 0, 36), function()
					if type(env.setclipboard) == "function" then
						env.setclipboard(Entry[2])
						SetStatus(Entry[1] .. " snippet copied")
					else
						SetStatus("Clipboard is unavailable in this environment", true)
					end
				end)
				Button.TextXAlignment = Enum.TextXAlignment.Left
				local Padding = Instance.new("UIPadding")
				Padding.PaddingLeft = UDim.new(0, 10)
				Padding.Parent = Button
			end

			StatusLabel = Instance.new("TextLabel")
			StatusLabel.BackgroundTransparency = 1
			StatusLabel.Font = Enum.Font.SourceSans
			StatusLabel.TextSize = 12
			StatusLabel.TextXAlignment = Enum.TextXAlignment.Left
			StatusLabel.TextColor3 = GetThemeColor("Text", Color3.fromRGB(240, 240, 240))
			StatusLabel.Text = "Ready"
			StatusLabel.Position = UDim2.new(0, 7, 1, -20)
			StatusLabel.Size = UDim2.new(1, -14, 0, 18)
			StatusLabel.Parent = Content

			RefreshDeviceInfo()
			ShowPage("Device")
			DeveloperTools.RefreshDeviceInfo = RefreshDeviceInfo
			DeveloperTools.ShowPage = ShowPage
			Window.OnActivate:Connect(RefreshDeviceInfo)

			local Camera = workspace.CurrentCamera
			if Camera then
				Connections[#Connections + 1] = Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
					ApplyWindowLayout()
					RefreshDeviceInfo()
				end)
			end
		end

		DeveloperTools.PluginData = {
			Name = "DeveloperTools",
			FriendlyName = "Developer Tools"
		}

		return DeveloperTools
end

return {
		InitDeps = InitDeps,
		InitAfterMain = InitAfterMain,
		Main = MainModule,
		PluginData = {
			Name = "DeveloperTools",
			FriendlyName = "Developer Tools"
		}
}
end,

["ScriptViewer"] = function()
local Main, Lib, Apps, Settings
local Explorer, Properties, ScriptViewer, Notebook
local API, RMD, env, service, plr, create, createSimple

local function initDeps(d)
	Main = d.Main
	Lib = d.Lib
	Apps = d.Apps
	Settings = d.Settings
	API = d.API
	RMD = d.RMD
	env = d.env
	service = d.service
	plr = d.plr
	create = d.create
	createSimple = d.createSimple
end

local function initAfterMain(t)
	Explorer = t.Explorer
	Properties = t.Properties
	ScriptViewer = t.ScriptViewer
	Notebook = t.Notebook
end

local exName, exVer = "Unknown", "???"
if identifyexecutor then
	local n, v = identifyexecutor()
	exName, exVer = n, v
elseif game:GetService("RunService"):IsStudio() then
	exName = "Studio"
	exVer = version()
end

local function GetScriptPath(Object)
	if Object.Parent == nil then
		return "Nil parented"
	end
	return Explorer.GetInstancePath(Object)
end

local KW = {
	["and"] = 1, ["break"] = 1, ["do"] = 1, ["else"] = 1, ["elseif"] = 1, ["end"] = 1, ["false"] = 1,
	["for"] = 1, ["function"] = 1, ["if"] = 1, ["in"] = 1, ["local"] = 1, ["nil"] = 1, ["not"] = 1,
	["or"] = 1, ["repeat"] = 1, ["return"] = 1, ["then"] = 1, ["true"] = 1, ["until"] = 1, ["while"] = 1,
	["continue"] = 1, ["export"] = 1, ["type"] = 1, ["self"] = 1,
}


local AUTO = {
    "^variable%d*$",
    "^callback%d*$",
    "^arg%d+$",
    "^local%d+$",
    "^var_?%d+_?%d*$",
    "^v_?%d+_?%d*$",
    "^t_?%d+_?%d*$",
    "^u_?%d+_?%d*$",
    "^unk_?%d+_?%d*$",
    "^_+%d+$",
    "^L_?%d+_%d+$",
    "^L_?%d+$",
    "^l_?%d+_%d+$",
    "^l_?%d+$",
    "^tmp_?%d+$",
    "^temp_?%d+$",
    "^a_?%d+$",
    "^b_?%d+$",
    "^c_?%d+$",
    "^r_?%d+_?%d*$",
    "^fn_?%d+_?%d*$",
    "^func_?%d+_?%d*$",
    "^local_?%d+$",
    "^arg_?%d+$",
    "^param_?%d+$",
    "^upv_?%d+$",
    "^upvalue_?%d+$",
    "^ok_?%d+$",
    "^err_?%d+$",
    "^result_?%d+$",
    "^success_?%d+$",
    "^ok$",
    "^err$",
    "^result$",
    "^success$"
}

local function isAuto(n)
	local Name = string.lower(n)
	for _, Pattern in ipairs(AUTO) do
		if Name:match(Pattern) then
			return true
		end
	end
	return false
end

local function Tokenize(Source)
	local t, i, n = {}, 1, #Source

	local function P(ty, v, s, e)
		t[#t + 1] = { type = ty, value = v, start = s, stop = e }
	end

	while i <= n do
		local c = Source:sub(i, i)

		if c:match("%s") then
			local j = i
			while j <= n and Source:sub(j, j):match("%s") do
				j = j + 1
			end
			P("ws", Source:sub(i, j - 1), i, j - 1)
			i = j

		elseif Source:sub(i, i + 1) == "--" then
			local eq = Source:match("^%[(=*)%[", i + 2)
			local e
			if eq then
				e = Source:find("]" .. eq .. "]", i + 2 + #eq + 2, true)
				e = e and (e + #eq + 1) or n
			else
				e = (Source:find("\n", i + 2, true) or n + 1) - 1
			end
			P("comment", Source:sub(i, e), i, e)
			i = e + 1

		elseif c == "[" then
			local eq = Source:match("^%[(=*)%[", i)
			if eq then
				local e = Source:find("]" .. eq .. "]", i + #eq + 2, true)
				e = e and (e + #eq + 1) or n
				P("string", Source:sub(i, e), i, e)
				i = e + 1
			else
				P("op", c, i, i)
				i = i + 1
			end

		elseif c == '"' or c == "'" then
			local j = i + 1
			while j <= n do
				local ch = Source:sub(j, j)
				if ch == "\\" then
					j = j + 2
				elseif ch == c then
					j = j + 1
					break
				elseif ch == "\n" then
					break
				else
					j = j + 1
				end
			end
			P("string", Source:sub(i, j - 1), i, j - 1)
			i = j

		elseif c:match("[%a_]") then
			local j = i
			while j <= n and Source:sub(j, j):match("[%w_]") do
				j = j + 1
			end
			local w = Source:sub(i, j - 1)
			P(KW[w] and "kw" or "name", w, i, j - 1)
			i = j

		elseif c:match("%d") then
			local j = i
			while j <= n and Source:sub(j, j):match("[%w%.]") do
				j = j + 1
			end
			P("num", Source:sub(i, j - 1), i, j - 1)
			i = j

		else
			local three = Source:sub(i, i + 2)
			local two = Source:sub(i, i + 1)
			if three == "..." or three == "..=" then
				P("op", three, i, i + 2)
				i = i + 3
			elseif two == "==" or two == "~=" or two == "<=" or two == ">=" or two == ".." or two == "::" or two == "->" then
				P("op", two, i, i + 1)
				i = i + 2
			else
				P("op", c, i, i)
				i = i + 1
			end
		end
	end

	return t
end

local function nx(t, i)
	i = i + 1
	while i <= #t and (t[i].type == "ws" or t[i].type == "comment") do
		i = i + 1
	end
	return i, t[i]
end

local function strlit(tk)
	if not tk or tk.type ~= "string" then
		return nil
	end
	local v = tk.value
	if v:sub(1, 1) == '"' or v:sub(1, 1) == "'" then
		return v:sub(2, -2)
	end
	local eq = v:match("^%[(=*)%[")
	if eq then
		return v:sub(#eq + 3, -#eq - 3)
	end
	return nil
end


local function Infer(Tokens, StartIndex)
    local FirstToken = Tokens[StartIndex]

    if not FirstToken then
        return nil
    end

    local function NextToken(Index)
        return nx(Tokens, Index)
    end

    local function CleanName(Value)
        if type(Value) ~= "string" then
            return nil
        end

        local Parts = {}

        for Part in Value:gmatch("[%a_][%w_]*") do
            Part = Part:gsub("^_+", "")

            if Part ~= "" then
                table.insert(Parts, Part:sub(1, 1):upper() .. Part:sub(2))
            end
        end

        local Name = table.concat(Parts)

        if Name == "" then
            return nil
        end

        if Name:match("^%d") then
            Name = "Value" .. Name
        end

        return Name
    end

    local function GetStringArgument(MethodIndex)
        local OpenIndex, OpenToken = NextToken(MethodIndex)

        if not OpenToken or OpenToken.value ~= "(" then
            return nil
        end

        local ArgumentIndex, ArgumentToken = NextToken(OpenIndex)

        if ArgumentToken and ArgumentToken.type == "string" then
            return strlit(ArgumentToken)
        end

        return nil
    end

    local function GetExpressionEnd()
        local Parentheses = 0
        local Braces = 0
        local Brackets = 0
        local LastValue

        local ContinueBefore = {
            ["="] = true,
            [","] = true,
            ["."] = true,
            [":"] = true,
            ["+"] = true,
            ["-"] = true,
            ["*"] = true,
            ["/"] = true,
            [".."] = true,
            ["and"] = true,
            ["or"] = true,
            ["not"] = true,
            ["("] = true,
            ["["] = true,
            ["{"] = true
        }

        local ContinueAfter = {
            ["."] = true,
            [":"] = true,
            ["("] = true,
            ["["] = true,
            [".."] = true,
            ["and"] = true,
            ["or"] = true
        }

        for Index = StartIndex, #Tokens do
            local Current = Tokens[Index]

            if Current.type == "ws" then
                if Current.value:find("\n", 1, true)
                    and Parentheses == 0
                    and Braces == 0
                    and Brackets == 0 then

                    local FollowingIndex, FollowingToken = NextToken(Index)

                    if not ContinueBefore[LastValue]
                        and not (FollowingToken and ContinueAfter[FollowingToken.value]) then

                        return Index - 1
                    end
                end
            else
                local Value = Current.value

                if Current.type == "op" then
                    if Value == "(" then
                        Parentheses += 1
                    elseif Value == ")" then
                        if Parentheses == 0 then
                            return Index - 1
                        end

                        Parentheses -= 1
                    elseif Value == "{" then
                        Braces += 1
                    elseif Value == "}" then
                        if Braces == 0 then
                            return Index - 1
                        end

                        Braces -= 1
                    elseif Value == "[" then
                        Brackets += 1
                    elseif Value == "]" then
                        if Brackets == 0 then
                            return Index - 1
                        end

                        Brackets -= 1
                    elseif (Value == "," or Value == ";")
                        and Parentheses == 0
                        and Braces == 0
                        and Brackets == 0 then

                        return Index - 1
                    end
                end

                LastValue = Value
            end
        end

        return #Tokens
    end

    local EndIndex = GetExpressionEnd()

    local PropertyHints = {
        LocalPlayer = "Player",
        CurrentCamera = "Camera",
        Character = "Character",
        Humanoid = "Humanoid",
        HumanoidRootPart = "HumanoidRootPart",
        RootPart = "RootPart",
        PrimaryPart = "PrimaryPart",
        PlayerGui = "PlayerGui",
        PlayerScripts = "PlayerScripts",
        Backpack = "Backpack",
        Position = "Position",
        CFrame = "CFrame",
        Size = "Size",
        Health = "Health",
        MaxHealth = "MaxHealth",
        WalkSpeed = "WalkSpeed",
        JumpPower = "JumpPower",
        JumpHeight = "JumpHeight",
        MoveDirection = "MoveDirection",
        AssemblyLinearVelocity = "Velocity",
        AssemblyAngularVelocity = "AngularVelocity",
        Name = "ObjectName",
        ClassName = "ClassName",
        Parent = "Parent",
        Value = "Value",
        Text = "Text",
        Image = "Image",
        Enabled = "Enabled",
        Visible = "Visible",
        CharacterAdded = "CharacterAdded",
        PlayerAdded = "PlayerAdded",
        ChildAdded = "ChildAdded",
        Touched = "Touched",
        Heartbeat = "Heartbeat",
        RenderStepped = "RenderStepped",
        MouseButton1Click = "MouseButton1Click",
        Activated = "Activated"
    }

    local MethodHints = {
        GetChildren = "Children",
        GetDescendants = "Descendants",
        GetPlayers = "Players",
        GetPlayerFromCharacter = "Player",
        GetPlayerFromUserId = "Player",
        GetMouse = "Mouse",
        GetPropertyChangedSignal = "PropertyChangedSignal",
        GetPivot = "Pivot",
        GetBoundingBox = "BoundingBox",
        GetFullName = "FullName",
        GetDebugId = "DebugId",
        Raycast = "RaycastResult",
        GetPartBoundsInBox = "Parts",
        GetPartBoundsInRadius = "Parts",
        GetTagged = "TaggedInstances",
        GetTags = "Tags",
        GetUserIdFromNameAsync = "UserId",
        GetNameFromUserIdAsync = "Username",
        LoadAnimation = "AnimationTrack",
        FindFirstAncestor = "Ancestor",
        FindFirstAncestorOfClass = "Ancestor",
        FindFirstAncestorWhichIsA = "Ancestor",
        Clone = "Clone",
        GetTextBoundsAsync = "TextBounds",
        format = "FormattedString",
        split = "SplitString",
        gsub = "ReplacedString",
        lower = "LowercaseString",
        upper = "UppercaseString",
        match = "MatchedString",
        floor = "Number",
        ceil = "Number",
        abs = "Number",
        max = "Number",
        min = "Number",
        clamp = "Number",
        JSONDecode = "DecodedData",
        JSONEncode = "JsonString",
        GetAsync = "Response",
        PostAsync = "Response"
    }

    local ChildMethods = {
        FindFirstChild = true,
        WaitForChild = true,
        FindFirstChildOfClass = true,
        FindFirstChildWhichIsA = true,
        FindFirstAncestorWhichIsA = true,
        FindFirstAncestorOfClass = true,
        GetAttribute = true,
        GetAttributeChangedSignal = true
    }

    local BooleanMethods = {
        IsA = true,
        IsDescendantOf = true,
        IsAncestorOf = true,
        IsLoaded = true,
        IsPlaying = true,
        IsStudio = true,
        IsServer = true,
        IsClient = true,
        IsFocused = true,
        IsEnabled = true,
        IsKeyDown = true,
        IsMouseButtonPressed = true,
        IsNetworkOwner = true,
        IsVisible = true
    }

    if FirstToken.type == "string" then
        return "Text"
    end

    if FirstToken.type == "num" then
        return "Number"
    end

    if FirstToken.value == "true" or FirstToken.value == "false" then
        return "Boolean"
    end

    if FirstToken.value == "nil" then
        return "Value"
    end

    if FirstToken.value == "function" then
        return "Callback"
    end

    if FirstToken.value == "workspace" then
        return "Workspace"
    end

    if FirstToken.value == "game" then
        return "Game"
    end

    if FirstToken.value == "script" then
        return "Script"
    end

    if FirstToken.value == "Enum" then
        return "EnumItem"
    end

    local ConstructorTypes = {
        Vector3 = "Vector3",
        Vector2 = "Vector2",
        CFrame = "CFrame",
        Color3 = "Color3",
        UDim2 = "UDim2",
        UDim = "UDim",
        BrickColor = "BrickColor",
        TweenInfo = "TweenInfo",
        RaycastParams = "RaycastParams",
        OverlapParams = "OverlapParams",
        Region3 = "Region3",
        NumberRange = "NumberRange",
        Rect = "Rect",
        DateTime = "DateTime"
    }

    if FirstToken.type == "name" then
        if FirstToken.value == "Instance" or FirstToken.value == "Drawing" then
            local DotIndex, DotToken = NextToken(StartIndex)

            if DotToken and DotToken.value == "." then
                local MethodIndex, MethodToken = NextToken(DotIndex)

                if MethodToken and MethodToken.value == "new" then
                    local ClassName = GetStringArgument(MethodIndex)

                    if ClassName then
                        return CleanName(ClassName)
                    end
                end
            end
        end

        if ConstructorTypes[FirstToken.value] then
            local DotIndex, DotToken = NextToken(StartIndex)

            if DotToken and DotToken.value == "." then
                local MethodIndex, MethodToken = NextToken(DotIndex)

                if MethodToken and (
                    MethodToken.value == "new"
                    or MethodToken.value == "fromRGB"
                    or MethodToken.value == "fromHSV"
                    or MethodToken.value == "fromScale"
                    or MethodToken.value == "fromOffset"
                ) then
                    return ConstructorTypes[FirstToken.value]
                end
            end
        end
    end

    local LastProperty
    local LastPropertyIndex = 0

    for Index = StartIndex, EndIndex do
        local Current = Tokens[Index]

        if Current.type == "op" and Current.value == "." then
            local PropertyIndex, PropertyToken = NextToken(Index)

            if PropertyToken and PropertyToken.type == "name" then
                LastProperty = PropertyToken.value
                LastPropertyIndex = PropertyIndex
            end
        end
    end

    local function GetCallEnd(OpenIndex)
        local Depth = 0

        for Index = OpenIndex, EndIndex do
            local Value = Tokens[Index].value

            if Value == "(" then
                Depth += 1
            elseif Value == ")" then
                Depth -= 1

                if Depth == 0 then
                    return Index
                end
            end
        end

        return OpenIndex
    end

    local LastMethodResult
    local LastMethodIndex = 0
    local LastMethodEnd = 0

    for Index = StartIndex, EndIndex do
        local Current = Tokens[Index]

        if Current.type == "name" then
            local Method = Current.value
            local OpenIndex, OpenToken = NextToken(Index)

            if OpenToken and OpenToken.value == "(" then
                local Result

                if Method == "GetService" then
                    local ServiceName = GetStringArgument(Index)
                    Result = ServiceName and CleanName(ServiceName) or "Service"

                elseif ChildMethods[Method] then
                    local ChildName = GetStringArgument(Index)

                    if ChildName and ChildName ~= "" then
                        Result = CleanName(ChildName)

                        if Method == "GetAttributeChangedSignal" then
                            Result = Result .. "Changed"
                        end
                    else
                        Result = Method:find("Ancestor") and "Ancestor" or "Child"
                    end

                elseif Method == "IsA" then
                    local ClassName = GetStringArgument(Index)
                    Result = ClassName and ("Is" .. CleanName(ClassName)) or "IsInstance"

                elseif BooleanMethods[Method] then
                    Result = CleanName(Method)

                else
                    Result = MethodHints[Method]
                end

                if Result and Index > LastMethodIndex then
                    LastMethodResult = Result
                    LastMethodIndex = Index
                    LastMethodEnd = GetCallEnd(OpenIndex)
                end
            end
        end
    end

    if LastProperty and LastPropertyIndex > LastMethodEnd then
        return PropertyHints[LastProperty] or CleanName(LastProperty)
    end

    if LastMethodResult then
        return CleanName(LastMethodResult)
    end

    if LastProperty then
        return PropertyHints[LastProperty] or CleanName(LastProperty)
    end

    local BuiltinHints = {
        require = "Module",
        tonumber = "Number",
        tostring = "Text",
        typeof = "ValueType",
        type = "ValueType",
        tick = "Timestamp",
        time = "Timestamp",
        wait = "WaitResult"
    }

    if FirstToken.type == "name" and BuiltinHints[FirstToken.value] then
        return BuiltinHints[FirstToken.value]
    end

    if FirstToken.value == "{" then
        local TableHints = {
            Settings = "Settings",
            Config = "Configuration",
            Configuration = "Configuration",
            Options = "Options",
            Connections = "Connections",
            Cache = "Cache",
            Players = "Players",
            Items = "Items",
            Remotes = "Remotes",
            Tweens = "Tweens",
            State = "State",
            Values = "Values",
            Keybinds = "Keybinds",
            Data = "Data"
        }

        for Index = StartIndex + 1, EndIndex do
            local Current = Tokens[Index]

            if Current.type == "name" then
                local EqualIndex, EqualToken = NextToken(Index)

                if EqualToken and EqualToken.value == "=" then
                    if TableHints[Current.value] then
                        return TableHints[Current.value]
                    end
                end
            end
        end

        return "DataTable"
    end

    if FirstToken.type == "name" and not isAuto(FirstToken.value) then
        return CleanName(FirstToken.value)
    end

    return nil
end

local function BeautifySource(Source)
	if type(Source) ~= "string" or Source == "" then
		return Source, 0
	end

	local t = Tokenize(Source)
	local rn, TypeTokens, ct = {}, {}, 0
	local sc = { {} }
	local UsedNameScopes = { {} }

	local function push()
		sc[#sc + 1] = {}
		UsedNameScopes[#UsedNameScopes + 1] = {}
	end

	local function pop()
		if #sc > 1 then
			table.remove(sc)
			table.remove(UsedNameScopes)
		end
	end

	local function cur()
		return sc[#sc]
	end

	local function used(n)
		if KW[n] then
			return true
		end
		for i = #sc, 1, -1 do
			local Scope = sc[i]
			if Scope[n] or (UsedNameScopes[i] and UsedNameScopes[i][n]) then
				return true
			end
		end
		return false
	end


local function InferUsage(OriginalName, TokenIndex)
    local MemberHints = {
        UserId = "Player",
        AccountAge = "Player",
        DisplayName = "Player",
        Team = "Player",
        Character = "Player",
        Backpack = "Player",
        PlayerGui = "Player",
        PlayerScripts = "Player",

        WalkSpeed = "Humanoid",
        JumpPower = "Humanoid",
        JumpHeight = "Humanoid",
        Health = "Humanoid",
        MaxHealth = "Humanoid",
        MoveDirection = "Humanoid",
        AutoRotate = "Humanoid",

        Position = "BasePart",
        CFrame = "BasePart",
        Anchored = "BasePart",
        CanCollide = "BasePart",
        AssemblyLinearVelocity = "BasePart",
        AssemblyAngularVelocity = "BasePart",
        Transparency = "BasePart",
        Material = "BasePart",

        Text = "TextLabel",
        TextColor3 = "TextLabel",
        TextSize = "TextLabel",
        TextBounds = "TextLabel",
        TextWrapped = "TextLabel",

        Image = "ImageLabel",
        ImageColor3 = "ImageLabel",
        ImageTransparency = "ImageLabel"
    }

    local MethodHints = {
        FindFirstChild = "Instance",
        WaitForChild = "Instance",
        FindFirstChildOfClass = "Instance",
        FindFirstChildWhichIsA = "Instance",
        GetChildren = "Instance",
        GetDescendants = "Instance",
        Destroy = "Instance",
        GetFullName = "Instance",
        IsA = "Instance",

        Connect = "RBXScriptSignal",
        Once = "RBXScriptSignal"
    }

    for Index = TokenIndex + 1, math.min(#t, TokenIndex + 200) do
        local Current = t[Index]

        if Current.type == "name" and Current.value == OriginalName then
            local AccessIndex, AccessToken = nx(t, Index)

            if AccessToken and (AccessToken.value == "." or AccessToken.value == ":") then
                local MemberIndex, MemberToken = nx(t, AccessIndex)

                if MemberToken and MemberToken.type == "name" then
                    if MemberHints[MemberToken.value] then
                        return MemberHints[MemberToken.value]
                    end

                    if MethodHints[MemberToken.value] then
                        return MethodHints[MemberToken.value]
                    end
                end
            elseif AccessToken and AccessToken.value == "(" then
                return "Callback"
            end
        end
    end

    return nil
end

	
local function Declare(OriginalName, TokenIndex, SuggestedName)
    local Entry = { NewName = nil }

    if isAuto(OriginalName) then
        local BestName = SuggestedName

        if not BestName
            or BestName == "Variable"
            or BestName == "Callback"
            or BestName:match("^[Aa]rg%d+$")
            or BestName:match("^[Ll]ocal%d+$") then

            BestName = InferUsage(OriginalName, TokenIndex) or BestName
        end

        local BaseName = tostring(BestName or ("Local" .. tostring(ct + 1)))
        if BaseName == "Variable" or BaseName == "Callback" or BaseName:match("^[Aa]rg%d+$") then
            BaseName = "Local" .. tostring(ct + 1)
        end

        BaseName = BaseName:gsub("[^%w_]", "")
        BaseName = BaseName:gsub("^_+", "")
        BaseName = BaseName:gsub("^([a-z])", string.upper)

        if BaseName == "" then
            BaseName = "Variable"
        end

        if BaseName:match("^%d") then
            BaseName = "Variable" .. BaseName
        end

        local NewName = BaseName
        local Suffix = 2

        while used(NewName) or NewName == OriginalName do
            NewName = BaseName .. tostring(Suffix)
            Suffix += 1
        end

        Entry.NewName = NewName
        UsedNameScopes[#UsedNameScopes][NewName] = true
        rn[TokenIndex] = NewName
        ct += 1
    end

    cur()[OriginalName] = Entry
end

	local function PreviousToken(Index)
		Index -= 1
		while Index >= 1 and (t[Index].type == "ws" or t[Index].type == "comment") do
			Index -= 1
		end
		return Index, t[Index]
	end
	
	local function IsTopBoundary(Index, StopValues)
		local Parentheses, Braces, Brackets, Angles = 0, 0, 0, 0
		for Cursor = Index, #t do
			local Current = t[Cursor]
			if Parentheses == 0 and Braces == 0 and Brackets == 0 and Angles == 0 and Current.type == "ws" and Current.value:find("\n", 1, true) then
				local PreviousIndex = Cursor - 1
				while PreviousIndex >= Index and (t[PreviousIndex].type == "ws" or t[PreviousIndex].type == "comment") do
					PreviousIndex -= 1
				end
				local Previous = t[PreviousIndex]
				local NextIndex, NextToken = nx(t, Cursor)
				local IsContinuation = Previous and ({ [":"] = true, ["|"] = true, ["&"] = true, ["<"] = true, [","] = true, ["."] = true, ["->"] = true })[Previous.value]
				local ContinuationAfter = NextToken and ({ [","] = true, ["="] = true, ["."] = true, [":"] = true, ["|"] = true, ["&"] = true, ["?"] = true, ["<"] = true, ["("] = true, ["["] = true, ["->"] = true })[NextToken.value]
				if not IsContinuation and not ContinuationAfter then
					return Cursor, nil
				end
			end
			if Current.type ~= "ws" and Current.type ~= "comment" then
				local Value = Current.value
				if Parentheses == 0 and Braces == 0 and Brackets == 0 and Angles == 0 and StopValues[Value] then
					return Cursor, Value
				end
				if Value == "(" then
					Parentheses += 1
			elseif Value == ")" then
					Parentheses = math.max(0, Parentheses - 1)
			elseif Value == "{" then
					Braces += 1
			elseif Value == "}" then
					Braces = math.max(0, Braces - 1)
			elseif Value == "[" then
					Brackets += 1
			elseif Value == "]" then
					Brackets = math.max(0, Brackets - 1)
			elseif Value == "<" then
					Angles += 1
			elseif Value == ">" and Angles > 0 then
					Angles -= 1
				end
			end
		end
		return #t + 1, nil
	end
	
	local function ParseLocal(StartIndex)
		if not StartIndex then
			return
		end
		local Declarations = {}
		local Cursor = StartIndex
		local AssignmentIndex
		
		while Cursor <= #t do
			local NameIndex, NameToken = Cursor, t[Cursor]
			if NameToken and (NameToken.type == "ws" or NameToken.type == "comment") then
				NameIndex, NameToken = nx(t, Cursor - 1)
			end
			if not NameToken or NameToken.type ~= "name" then
				break
			end
			table.insert(Declarations, { Name = NameToken.value, Index = NameIndex })
			
			local NextIndex, NextValue = nx(t, NameIndex)
			if NextValue and NextValue.value == ":" then
				local TypeStart = NextIndex + 1
				while TypeStart <= #t and (t[TypeStart].type == "ws" or t[TypeStart].type == "comment") do
					TypeStart += 1
				end
				local BoundaryIndex, BoundaryValue = IsTopBoundary(TypeStart, { [","] = true, ["="] = true, [";"] = true })
				for TypeIndex = TypeStart, BoundaryIndex - 1 do
					TypeTokens[TypeIndex] = true
				end
				if BoundaryValue == "," then
					Cursor = BoundaryIndex + 1
					while Cursor <= #t and (t[Cursor].type == "ws" or t[Cursor].type == "comment") do
						Cursor += 1
					end
			elseif BoundaryValue == "=" then
					AssignmentIndex = BoundaryIndex
					break
			else
					break
				end
			elseif NextValue and NextValue.value == "," then
				Cursor = NextIndex + 1
				while Cursor <= #t and (t[Cursor].type == "ws" or t[Cursor].type == "comment") do
					Cursor += 1
				end
			elseif NextValue and NextValue.value == "=" then
				AssignmentIndex = NextIndex
				break
			else
				break
			end
		end
		
		local RightIndex, RightToken
		if AssignmentIndex then
			RightIndex, RightToken = nx(t, AssignmentIndex)
		end
		local IsPcall = RightToken and (RightToken.value == "pcall" or RightToken.value == "xpcall")
		
		for DeclarationIndex, Declaration in ipairs(Declarations) do
			local SuggestedName
			if IsPcall then
				if DeclarationIndex == 1 then
					SuggestedName = "Success"
			elseif DeclarationIndex == 2 then
					SuggestedName = "Result"
				end
			elseif DeclarationIndex == 1 and RightIndex then
				SuggestedName = Infer(t, RightIndex)
			end
			Declare(Declaration.Name, Declaration.Index, SuggestedName)
		end
	end
	
	local function ParseParams(OpenParenIndex)
		local SegmentStart = OpenParenIndex + 1
		local Parentheses, Braces, Brackets, Angles = 0, 0, 0, 0
		local ParameterCount = 0
		
		local function ProcessSegment(FirstIndex, LastIndex)
			local FirstName
			local TypeStart
			local InnerParentheses, InnerBraces, InnerBrackets, InnerAngles = 0, 0, 0, 0
			for SegmentIndex = FirstIndex, LastIndex do
				local Current = t[SegmentIndex]
				if Current.type ~= "ws" and Current.type ~= "comment" then
					local Value = Current.value
					if not FirstName and not TypeStart and Current.type == "name" then
						FirstName = SegmentIndex
				elseif Value == ":" and InnerParentheses == 0 and InnerBraces == 0 and InnerBrackets == 0 and InnerAngles == 0 then
						TypeStart = SegmentIndex + 1
					end
					if TypeStart then
						TypeTokens[SegmentIndex] = true
					end
					if Value == "(" then
						InnerParentheses += 1
				elseif Value == ")" then
						InnerParentheses = math.max(0, InnerParentheses - 1)
				elseif Value == "{" then
						InnerBraces += 1
				elseif Value == "}" then
						InnerBraces = math.max(0, InnerBraces - 1)
				elseif Value == "[" then
						InnerBrackets += 1
				elseif Value == "]" then
						InnerBrackets = math.max(0, InnerBrackets - 1)
				elseif Value == "<" then
						InnerAngles += 1
				elseif Value == ">" and InnerAngles > 0 then
						InnerAngles -= 1
					end
				end
			end
			if FirstName then
				local FirstToken = t[FirstName]
				if FirstToken.type == "name" and not TypeTokens[FirstName] then
					ParameterCount += 1
					Declare(FirstToken.value, FirstName, "Arg" .. tostring(ParameterCount))
				end
			end
		end
		
		for Cursor = OpenParenIndex + 1, #t do
			local Current = t[Cursor]
			if Current.type ~= "ws" and Current.type ~= "comment" then
				local Value = Current.value
				if Value == "(" then
					Parentheses += 1
			elseif Value == ")" then
					if Parentheses == 0 and Braces == 0 and Brackets == 0 and Angles == 0 then
						ProcessSegment(SegmentStart, Cursor - 1)
						return
					end
					Parentheses = math.max(0, Parentheses - 1)
			elseif Value == "{" then
					Braces += 1
			elseif Value == "}" then
					Braces = math.max(0, Braces - 1)
			elseif Value == "[" then
					Brackets += 1
			elseif Value == "]" then
					Brackets = math.max(0, Brackets - 1)
			elseif Value == "<" then
					Angles += 1
			elseif Value == ">" and Angles > 0 then
					Angles -= 1
			elseif Value == "," and Parentheses == 0 and Braces == 0 and Brackets == 0 and Angles == 0 then
					ProcessSegment(SegmentStart, Cursor - 1)
					SegmentStart = Cursor + 1
				end
			end
		end
	end
	
	local function FindOpenParen(FunctionIndex)
		local Cursor, Current = nx(t, FunctionIndex)
		if Current and Current.value == "(" then
			return Cursor
		end
		local AngleDepth = 0
		while Cursor <= #t do
			Current = t[Cursor]
			if Current.type ~= "ws" and Current.type ~= "comment" then
				if Current.value == "<" then
					AngleDepth += 1
			elseif Current.value == ">" and AngleDepth > 0 then
					AngleDepth -= 1
			elseif Current.value == "(" and AngleDepth == 0 then
					return Cursor
			elseif (Current.value == "=" or Current.value == ";") and AngleDepth == 0 then
					return nil
				end
			end
			Cursor += 1
		end
		return nil
	end
	
	local PendingFor = nil
	local PendingIf = false
	local PendingUntil = false
	local UntilHasExpression = false
	local UntilParentheses = 0
	local i = 1
	
	while i <= #t do
		local tk = t[i]
		
		if PendingUntil and tk.type == "ws" and UntilHasExpression and UntilParentheses == 0 and tk.value:find("\n", 1, true) then
			pop()
			PendingUntil = false
			UntilHasExpression = false
		elseif PendingUntil and tk.type ~= "ws" and tk.type ~= "comment" and tk.value ~= "until" then
			UntilHasExpression = true
			if tk.value == "(" then
				UntilParentheses += 1
			elseif tk.value == ")" then
				UntilParentheses = math.max(0, UntilParentheses - 1)
			elseif tk.value == ";" and UntilParentheses == 0 then
				pop()
				PendingUntil = false
				UntilHasExpression = false
			end
		end
		
		if tk.type == "kw" then
			local Value = tk.value
			
			if Value == "local" then
				local NextIndex, NextToken = nx(t, i)
				if NextToken and NextToken.value == "function" then
					local NameIndex, NameToken = nx(t, NextIndex)
					if NameToken and NameToken.type == "name" then
						Declare(NameToken.value, NameIndex, "Function")
					end
			else
					ParseLocal(NextIndex)
				end
			elseif Value == "if" then
				PendingIf = true
			elseif Value == "then" then
				if PendingIf then
					push()
					PendingIf = false
				end
			elseif Value == "elseif" then
				pop()
				PendingIf = true
			elseif Value == "else" then
				pop()
				push()
			elseif Value == "for" then
				local Variables = {}
				local Cursor = i
				while true do
					local NameIndex, NameToken = nx(t, Cursor)
					if not NameToken or NameToken.type ~= "name" then
						break
					end
					table.insert(Variables, { Name = NameToken.value, Index = NameIndex })
					local SeparatorIndex, SeparatorToken = nx(t, NameIndex)
					if SeparatorToken and SeparatorToken.value == "," then
						Cursor = SeparatorIndex
				else
						break
					end
				end
				PendingFor = Variables
			elseif Value == "do" then
				push()
				if PendingFor then
					for VariableIndex, Variable in ipairs(PendingFor) do
						local Suggestion
						if #PendingFor == 1 then
							Suggestion = "Item"
					elseif #PendingFor == 2 then
							Suggestion = VariableIndex == 1 and "Index" or "Value"
					else
							Suggestion = ({"Index", "Value", "Entry"})[VariableIndex] or ("Value" .. tostring(VariableIndex))
						end
						Declare(Variable.Name, Variable.Index, Suggestion)
					end
					PendingFor = nil
				end
			elseif Value == "repeat" then
				push()
			elseif Value == "until" then
				PendingUntil = true
				UntilHasExpression = false
				UntilParentheses = 0
			elseif Value == "function" then
				local OpenParenIndex = FindOpenParen(i)
				push()
				if OpenParenIndex then
					ParseParams(OpenParenIndex)
				end
			elseif Value == "end" then
				pop()
			end
		elseif tk.type == "name" and not TypeTokens[i] then
			local PreviousIndex, Previous = PreviousToken(i)
			local NextIndex, Next = nx(t, i)
			local IsMemberName = Previous and (Previous.value == "." or Previous.value == ":")
			local IsTableKey = Next and Next.value == "=" and Previous and (Previous.value == "{" or Previous.value == ",")
			local IsLabel = (Previous and Previous.value == "::") or (Next and Next.value == "::")
			
			if not IsMemberName and not IsTableKey and not IsLabel then
				for ScopeIndex = #sc, 1, -1 do
					local Entry = sc[ScopeIndex][tk.value]
					if Entry then
						if Entry.NewName then
							rn[i] = Entry.NewName
						end
						break
					end
				end
			end
		end
		
		i += 1
	end
	
	if PendingUntil then
		pop()
	end
	local ps, last = {}, 1
	for i2 = 1, #t do
		local tk = t[i2]
		ps[#ps + 1] = Source:sub(last, tk.start - 1)
		ps[#ps + 1] = rn[i2] or tk.value
		last = tk.stop + 1
	end
	ps[#ps + 1] = Source:sub(last)
	return table.concat(ps), ct
end

local AI_PROMPT = [=[You are an expert Luau source beautifier. The code may come from a bytecode decompiler and may contain generated local names.

Rename only clearly generated identifiers to short, descriptive PascalCase names. Infer names from assignments, Roblox services, constructors, methods, properties, and how values are used. Prefer natural, specific names over generic names. Keep existing meaningful identifiers unchanged. Never rename standard loop variables (i, v, k) or self.

For pcall and xpcall results, identify the success boolean and returned value from their actual use. Give each a concise, descriptive name and update every reference within the correct scope.

COMMENT PRESERVATION IS MANDATORY:
The input contains protected comment markers in the form --[[VALM_KEEP_000001]]. Preserve every marker exactly once, as a comment, in its original relative position. Do not remove, rewrite, rename, duplicate, move, or combine these markers. They represent real comments from the original source and will be restored after formatting. Do not invent replacement comments.

READABILITY AND SPACING:
Use consistent indentation and readable line breaks. Put exactly one empty line between top-level functions, major declarations, and distinct logical sections. Also separate large logical blocks inside long functions with one empty line where appropriate. Do not compress the entire script into consecutive lines. Do not insert empty lines between every simple statement, function parameters, table fields, or continuation lines. Keep related statements together.

Preserve behavior 100%. Never change string literals, table keys, function call order, control flow, numeric values, or API names. Keep the code valid Luau. Do not change operators or simplify expressions in ways that could alter behavior.

CRITICAL OUTPUT INSTRUCTIONS:
1. Output only valid rewritten Luau source.
2. Do not invent new banners or metadata comments. Do not add markdown fences or explanations. Preserve existing source comments through their markers.
3. Keep all protected comment markers exactly as supplied. Preserve all program behavior, string literals, table keys, call order, control flow, and numeric values.]=]

local function ProtectAIComments(Source)
    local Output = {}
    local Comments = {}
    local Index = 1
    local Length = #Source
    while Index <= Length do
        local Character = Source:sub(Index, Index)
        if Character == "\"" or Character == "'" then
            local Quote = Character
            local Start = Index
            Index += 1
            while Index <= Length do
                local Current = Source:sub(Index, Index)
                if Current == "\\" then
                    Index += 2
                elseif Current == Quote then
                    Index += 1
                    break
                else
                    Index += 1
                end
            end
            Output[#Output + 1] = Source:sub(Start, Index - 1)
        elseif Character == "[" then
            local Equals = Source:sub(Index):match("^%[(=*)%[")
            if Equals ~= nil then
                local Start = Index
                local Closing = "]" .. Equals .. "]"
                local ClosingStart = Source:find(Closing, Index + #Equals + 2, true)
                Index = ClosingStart and ClosingStart + #Closing or Length + 1
                Output[#Output + 1] = Source:sub(Start, Index - 1)
            else
                Output[#Output + 1] = Character
                Index += 1
            end
        elseif Source:sub(Index, Index + 1) == "--" then
            local Start = Index
            local Equals = Source:sub(Index + 2):match("^%[(=*)%[")
            if Equals ~= nil then
                local Closing = "]" .. Equals .. "]"
                local ClosingStart = Source:find(Closing, Index + #Equals + 4, true)
                Index = ClosingStart and ClosingStart + #Closing or Length + 1
            else
                local Newline = Source:find("\n", Index, true)
                Index = Newline or Length + 1
            end
            local Marker = ("VALM_KEEP_%06d"):format(#Comments + 1)
            Comments[#Comments + 1] = {Marker = Marker, Text = Source:sub(Start, Index - 1)}
            Output[#Output + 1] = "--[[" .. Marker .. "]]"
        else
            Output[#Output + 1] = Character
            Index += 1
        end
    end
    return table.concat(Output), Comments
end

local function RestoreAIComments(Source, Comments)
    local Restored = Source
    local Positions = {}
    local LastPosition = 0
    for Index, Comment in ipairs(Comments) do
        local MarkerText = "--[[" .. Comment.Marker .. "]]"
        local Start, Finish = Restored:find(MarkerText, LastPosition + 1, true)
        if not Start or Restored:find(MarkerText, Finish + 1, true) then
            return nil, "AI Beautify did not preserve every original comment in order; the source was left unchanged"
        end
        Positions[Index] = {Start = Start, Finish = Finish}
        LastPosition = Finish
    end
    for Index = #Comments, 1, -1 do
        local Position = Positions[Index]
        local Comment = Comments[Index]
        Restored = Restored:sub(1, Position.Start - 1) .. Comment.Text .. Restored:sub(Position.Finish + 1)
    end
    return Restored
end

local function FixSpacing(Source)
    local Lines = string.split(Source, "\n")
    local Output = {}
    local LastNonEmpty = ""
    local LastIndent = 0
    for _, Line in ipairs(Lines) do
        local Trimmed = Line:match("^%s*(.-)%s*$") or ""
        if Trimmed ~= "" then
            local Indent = #(Line:match("^(%s*)") or "")
            local IsFunctionStart = Trimmed:match("^local%s+function%s+") ~= nil
                or Trimmed:match("^function%s+[%w_%.:]+") ~= nil
                or Trimmed:match("^local%s+[%w_%.]+%s*=%s*function%s*%(") ~= nil
                or Trimmed:match("=%s*function%s*%(") ~= nil
            local PreviousIsComment = LastNonEmpty:sub(1, 2) == "--"
            local WasTopEnd = LastIndent == 0 and (LastNonEmpty == "end" or LastNonEmpty:match("^end[%s%),;]*$") ~= nil)
            if #Output > 0 and Output[#Output] ~= "" and not PreviousIsComment then
                if IsFunctionStart or (Indent == 0 and WasTopEnd) then
                    Output[#Output + 1] = ""
                end
            end
            Output[#Output + 1] = Line
            LastNonEmpty = Trimmed
            LastIndent = Indent
        else
            Output[#Output + 1] = Line
        end
    end
    local Formatted = table.concat(Output, "\n")
    Formatted = Formatted:gsub("\n%s*\n%s*\n+", "\n\n")
    return Formatted
end

