local function GetAIEndpoint(ProviderName, ModelName, CurrentEndpoint)
	local Profile = AIProviderProfiles[ProviderName] or AIProviderProfiles.Groq
	local Endpoint = tostring(CurrentEndpoint or ""):gsub("^%s+", ""):gsub("%s+$", "")
	local DefaultEndpoint = tostring(Profile.Endpoint or "")
	if Endpoint ~= "" then
		local EndpointHost = Endpoint:lower():match("^https?://([^/]+)")
		if EndpointHost then
			for OtherProviderName, OtherProfile in pairs(AIProviderProfiles) do
				if OtherProviderName ~= ProviderName then
					local OtherHost = tostring(OtherProfile.Endpoint or ""):lower():match("^https?://([^/]+)")
					if OtherHost and EndpointHost == OtherHost then
						Endpoint = ""
						break
					end
				end
			end
		end
	end
	if Profile.Protocol == "Gemini" then
		local Model = tostring(ModelName or Profile.DefaultModel or "")
		local Base = tostring(Profile.EndpointBase or "https://generativelanguage.googleapis.com/v1beta"):gsub("/+$", "")
		local CanonicalEndpoint = Base .. "/models/" .. Model .. ":generateContent"
		local LowerEndpoint = Endpoint:lower()
		if Endpoint == "" or LowerEndpoint:find("generativelanguage.googleapis.com", 1, true) then
			return CanonicalEndpoint
		end
		if Endpoint:find("{model}", 1, true) then
			return (Endpoint:gsub("{model}", Model))
		end
		local ExistingBase = Endpoint:match("^(https?://[^/]+/.*/models)/[^/:]+:generateContent$")
		if ExistingBase then
			return ExistingBase .. "/" .. Model .. ":generateContent"
		end
		local CleanEndpoint = Endpoint:gsub("/+$", "")
		if CleanEndpoint:match("/v%d+beta?$") or CleanEndpoint:match("/v%d+$") then
			return CleanEndpoint .. "/models/" .. Model .. ":generateContent"
		end
		return Endpoint
	end
	if Endpoint == "" then
		return DefaultEndpoint
	end
	local Route = tostring(Profile.EndpointRoute or "")
	local Base = tostring(Profile.EndpointBase or "")
	local CleanEndpoint = Endpoint:gsub("/+$", "")
	local CleanBase = Base:gsub("/+$", "")
	local LowerEndpoint = CleanEndpoint:lower()
	local LowerDefault = DefaultEndpoint:lower()
	local LowerRoute = Route:lower()
	if LowerEndpoint == LowerDefault then
		return CleanEndpoint
	end
	if Route ~= "" and LowerEndpoint:sub(-#LowerRoute) == LowerRoute then
		return CleanEndpoint
	end
	local EndpointHost = LowerEndpoint:match("^https?://([^/]+)")
	local DefaultHost = LowerDefault:match("^https?://([^/]+)")
	local IsProviderHost = EndpointHost ~= nil and DefaultHost ~= nil and EndpointHost == DefaultHost
	if IsProviderHost then
		if CleanEndpoint == CleanBase or CleanEndpoint == CleanBase .. "/v1" or CleanEndpoint == CleanBase .. "/openai/v1" then
			return CleanEndpoint .. Route
		end
		return DefaultEndpoint
	end
	if Route ~= "" then
		local Path = LowerEndpoint:match("^https?://[^/]+(.*)$") or ""
		if Path == "" or Path == "/" or Path:match("/v%d+/?$") or Path:match("/openai/v%d+/?$") then
			return CleanEndpoint .. Route
		end
	end
	return Endpoint
end
local function MakeAIRequest(AIConfig, SystemText, UserText, MaxTokens, Temperature)
	if type(AIConfig) ~= "table" then
		return nil, nil, nil, "AI configuration is unavailable"
	end
	local Provider = tostring(AIConfig.Provider or "")
	local Profile = AIProviderProfiles[Provider]
	if not Profile then
		return nil, nil, nil, "Unsupported AI provider: " .. Provider
	end
	local Protocol = tostring(AIConfig.Protocol or Profile.Protocol)
	local Model = tostring(AIConfig.Model or Profile.DefaultModel or "")
	if Model == "" or not table.find(Profile.Models or {}, Model) then
		return nil, nil, nil, "The selected model is not supported by " .. Provider
	end
	local RequestPayload
	if Protocol == "Responses" then
		if Provider == "xAI" then
			RequestPayload = {
				model = Model,
				input = {
					{role = "system", content = tostring(SystemText or "")},
					{role = "user", content = tostring(UserText or "")}
				},
				max_output_tokens = tonumber(MaxTokens) or tonumber(AIConfig.MaxTokens) or 2048,
				temperature = tonumber(Temperature) or tonumber(AIConfig.Temperature) or 0.1
			}
		else
			RequestPayload = {
				model = Model,
				instructions = tostring(SystemText or ""),
				input = tostring(UserText or ""),
				max_output_tokens = tonumber(MaxTokens) or tonumber(AIConfig.MaxTokens) or 2048
			}
		end
	elseif Protocol == "Anthropic" then
		RequestPayload = {
			model = Model,
			system = tostring(SystemText or ""),
			max_tokens = tonumber(MaxTokens) or tonumber(AIConfig.MaxTokens) or 2048,
			temperature = tonumber(Temperature) or tonumber(AIConfig.Temperature) or 0.1,
			messages = {{role = "user", content = tostring(UserText or "")}}
		}
	elseif Protocol == "GeminiInteractions" then
		RequestPayload = {
			model = Model,
			system_instruction = tostring(SystemText or ""),
			input = tostring(UserText or ""),
			store = false,
			generation_config = {
				temperature = tonumber(Temperature) or tonumber(AIConfig.Temperature) or 0.1,
				max_output_tokens = tonumber(MaxTokens) or tonumber(AIConfig.MaxTokens) or 2048
			}
		}
	elseif Protocol == "Gemini" then
		RequestPayload = {
			systemInstruction = {parts = {{text = tostring(SystemText or "")}}},
			contents = {{role = "user", parts = {{text = tostring(UserText or "")}}}},
			generationConfig = {
				temperature = tonumber(Temperature) or tonumber(AIConfig.Temperature) or 0.1,
				maxOutputTokens = tonumber(MaxTokens) or tonumber(AIConfig.MaxTokens) or 2048
			}
		}
	else
		RequestPayload = {
			model = Model,
			messages = {
				{role = "system", content = tostring(SystemText or "")},
				{role = "user", content = tostring(UserText or "")}
			},
			temperature = tonumber(Temperature) or tonumber(AIConfig.Temperature) or 0.1
		}
		RequestPayload[AIConfig.MaxTokenField or Profile.MaxTokenField or "max_tokens"] = tonumber(MaxTokens) or tonumber(AIConfig.MaxTokens) or 2048
	end
	for OptionName, OptionValue in pairs(AIConfig.RequestOptions or {}) do
		if RequestPayload[OptionName] == nil then
			RequestPayload[OptionName] = OptionValue
		end
	end
	local AuthKey = tostring(AIConfig.ApiKey or ""):gsub("^[Bb][Ee][Aa][Rr][Ee][Rr]%s+", ""):gsub("^%s+", ""):gsub("%s+$", "")
	if AuthKey == "" then
		return nil, nil, nil, "No API key is configured for " .. Provider
	end
	local RequestHeaders = { ["Content-Type"] = "application/json" }
	if Protocol == "Anthropic" then
		RequestHeaders["x-api-key"] = AuthKey
		RequestHeaders["anthropic-version"] = tostring(AIConfig.ApiVersion or Profile.ApiVersion or "2026-10-21")
	elseif Protocol == "Gemini" or Protocol == "GeminiInteractions" then
		RequestHeaders["x-goog-api-key"] = AuthKey
	else
		RequestHeaders["Authorization"] = "Bearer " .. AuthKey
	end
	for HeaderName, HeaderValue in pairs(AIConfig.Headers or {}) do
		RequestHeaders[tostring(HeaderName)] = tostring(HeaderValue)
	end
	local Endpoint = GetAIEndpoint(Provider, Model, AIConfig.Endpoint or Profile.Endpoint)
	if Endpoint == "" then
		return nil, nil, nil, "No endpoint is configured for " .. Provider
	end
	return RequestPayload, RequestHeaders, Endpoint
end

local function ReadAIReply(DecodedResponse, Protocol)
	if type(DecodedResponse) ~= "table" then
		return nil
	end
	if Protocol == "Anthropic" then
		local TextParts = {}
		for _, ContentPart in ipairs(DecodedResponse.content or {}) do
			if type(ContentPart) == "table" and ContentPart.type == "text" and type(ContentPart.text) == "string" then
				TextParts[#TextParts + 1] = ContentPart.text
			end
		end
		return table.concat(TextParts, "\n")
	elseif Protocol == "GeminiInteractions" then
		local Interaction = type(DecodedResponse.interaction) == "table" and DecodedResponse.interaction or DecodedResponse
		if type(Interaction.output_text) == "string" and Interaction.output_text ~= "" then
			return Interaction.output_text
		end
		local TextParts = {}
		for _, Step in ipairs(type(Interaction.steps) == "table" and Interaction.steps or {}) do
			if type(Step) == "table" and (Step.type == "model_output" or Step.type == "output_text") then
				for _, ContentPart in ipairs(type(Step.content) == "table" and Step.content or {}) do
					if type(ContentPart) == "table" and type(ContentPart.text) == "string" then
						TextParts[#TextParts + 1] = ContentPart.text
					end
				end
			end
		end
		return table.concat(TextParts, "\n")
	elseif Protocol == "Gemini" then
		local Candidate = type(DecodedResponse.candidates) == "table" and DecodedResponse.candidates[1] or nil
		local TextParts = {}
		for _, ContentPart in ipairs(type(Candidate) == "table" and Candidate.content and Candidate.content.parts or {}) do
			if type(ContentPart) == "table" and type(ContentPart.text) == "string" then
				TextParts[#TextParts + 1] = ContentPart.text
			end
		end
		return table.concat(TextParts, "\n")
	elseif Protocol == "Responses" then
		if type(DecodedResponse.output_text) == "string" and DecodedResponse.output_text ~= "" then
			return DecodedResponse.output_text
		end
		local TextParts = {}
		for _, OutputItem in ipairs(type(DecodedResponse.output) == "table" and DecodedResponse.output or {}) do
			for _, ContentPart in ipairs(type(OutputItem.content) == "table" and OutputItem.content or {}) do
				if type(ContentPart) == "table" and (ContentPart.type == "output_text" or ContentPart.type == "text") and type(ContentPart.text) == "string" then
					TextParts[#TextParts + 1] = ContentPart.text
				end
			end
		end
		return table.concat(TextParts, "\n")
	else
		local Choice = type(DecodedResponse.choices) == "table" and DecodedResponse.choices[1] or nil
		local Message = type(Choice) == "table" and Choice.message or nil
		local Content = type(Message) == "table" and Message.content or nil
		if type(Content) == "string" then
			return Content
		elseif type(Content) == "table" then
			local TextParts = {}
			for _, Part in ipairs(Content) do
				if type(Part) == "string" then
					TextParts[#TextParts + 1] = Part
				elseif type(Part) == "table" and type(Part.text) == "string" then
					TextParts[#TextParts + 1] = Part.text
				end
			end
			return table.concat(TextParts, "\n")
		end
	end
	return nil
end
