local EmbeddedAIConfig = {
	Provider = "Groq",
	Protocol = "ChatCompletions",
	Endpoint = "",
	ApiKey = "",
	Model = "",
	Enabled = nil,
	Temperature = nil,
	MaxTokens = nil
}

if type(Main) == "table" then
	Main.DexHelperEmbeddedAIConfig = EmbeddedAIConfig
end

local function ResolveAIConfig()
	local ScriptSettings = Settings and Settings.ScriptViewer or {}
	local Sources = {}
	local RootSources = {}
	local function AddSource(Value)
		if type(Value) == "table" and not table.find(Sources, Value) then
			table.insert(Sources, Value)
		end
	end
	local function AddRoot(Value)
		if type(Value) ~= "table" then
			return
		end
		if not table.find(RootSources, Value) then
			table.insert(RootSources, Value)
		end
		AddSource(Value)
		for _, Name in ipairs({"DexAIConfig", "DexHelperAI", "AIConfig", "AISettings", "AI", "LLM", "Groq", "OpenAI", "ChatGPT", "ScriptViewer", "API", "Provider", "Config"}) do
			local Success, Nested = pcall(function()
				return Value[Name]
			end)
			if Success then
				AddSource(Nested)
			end
		end
	end
	AddRoot(EmbeddedAIConfig)
	AddSource(ScriptSettings)
	AddRoot(env)
	AddRoot(Main)
	AddRoot(shared)
	AddRoot(_G)
	local GlobalEnvironment
	if type(getgenv) == "function" then
		local Success, Value = pcall(getgenv)
		if Success then
			GlobalEnvironment = Value
			AddRoot(GlobalEnvironment)
		end
	end
	local function ReadConfig(Names, SkipSource, SkipSourceTwo)
		for _, ConfigSource in ipairs(Sources) do
			if ConfigSource ~= SkipSource and ConfigSource ~= SkipSourceTwo then
				for _, Name in ipairs(Names) do
					local Success, Value = pcall(function()
						return ConfigSource[Name]
					end)
					if Success and Value ~= nil and Value ~= "" then
						return Value
					end
				end
			end
		end
		return nil
	end
	local Endpoint = ReadConfig({"Endpoint", "endpoint", "AIEndpoint", "aiEndpoint", "AI_ENDPOINT", "APIEndpoint", "ApiEndpoint", "apiEndpoint", "API_ENDPOINT", "ChatCompletionsEndpoint", "ChatCompletionURL", "API_URL", "OPENAI_BASE_URL", "GROQ_URL", "BaseURL", "baseUrl", "base_url", "URL", "Url", "url"}, EmbeddedAIConfig, ScriptSettings)
	local ProviderKeyNames = {
		Groq = {"GROQ_API_KEY", "GroqAPIKey"},
		DeepSeek = {"DEEPSEEK_API_KEY", "DeepSeekAPIKey"},
		OpenAI = {"OPENAI_API_KEY", "OpenAIAPIKey"},
		Anthropic = {"ANTHROPIC_API_KEY", "AnthropicAPIKey"},
		["Google Gemini"] = {"GEMINI_API_KEY", "GOOGLE_API_KEY", "GeminiAPIKey"},
		xAI = {"XAI_API_KEY", "XAIAPIKey"},
		Mistral = {"MISTRAL_API_KEY", "MistralAPIKey"}
	}
	local Model = ReadConfig({"Model", "model", "AIModel", "aiModel", "AI_MODEL", "ModelName", "modelName", "MODEL"}, EmbeddedAIConfig, ScriptSettings)
	local Enabled = ReadConfig({"Enabled", "enabled", "AIEnabled", "aiEnabled"})
	local Temperature = ReadConfig({"Temperature", "temperature", "AITemperature", "aiTemperature"})
	local MaxTokens = ReadConfig({"MaxTokens", "maxTokens", "max_tokens", "AIMaxTokens"})
	local Headers = ReadConfig({"Headers", "headers", "RequestHeaders", "requestHeaders"})
	local Provider = tostring(ScriptSettings.AIProvider or ReadConfig({"AIProvider", "Provider", "provider"}) or "Groq")
	if not AIProviderProfiles[Provider] then
		Provider = "Groq"
		ScriptSettings.AIProvider = Provider
	end
	local Profile = AIProviderProfiles[Provider]
	local EndpointOverrides = type(ScriptSettings.AIEndpointOverrides) == "table" and ScriptSettings.AIEndpointOverrides or {}
	local SettingsEndpoint = tostring(EndpointOverrides[Provider] or "")
	if SettingsEndpoint == "" and (ScriptSettings.AIEndpointProvider == Provider or (ScriptSettings.AIEndpointProvider == nil and tostring(ScriptSettings.AIProvider or "Groq") == Provider)) then
		SettingsEndpoint = tostring(ScriptSettings.AIEndpoint or "")
	end
	local ProvKeys = type(ScriptSettings.AIKeys) == "table" and ScriptSettings.AIKeys or {}
	local ProviderStoredKey = tostring(ProvKeys[Provider] or "")
	local LegacyKey = tostring(ScriptSettings.AIKey or "")
	local LegacyKeyProvider = tostring(ScriptSettings.AIKeyProvider or "Groq")
	local SettingsKey = ProviderStoredKey ~= "" and ProviderStoredKey or (LegacyKeyProvider == Provider and LegacyKey or "")
	local ProviderApiKey = ReadConfig(ProviderKeyNames[Provider] or {}, EmbeddedAIConfig, ScriptSettings)
	local EmbeddedKey = EmbeddedAIConfig.Provider == Provider and EmbeddedAIConfig.ApiKey or ""
	ScriptSettings.AIModels = type(ScriptSettings.AIModels) == "table" and ScriptSettings.AIModels or {}
	local SettingsModel = tostring(ScriptSettings.AIModels[Provider] or ScriptSettings.AIModel or "")
	local ResolvedEnabled = ScriptSettings.AIEnabled ~= false
	if type(Enabled) == "boolean" then
		ResolvedEnabled = Enabled
	end
	local ResolvedModel = (SettingsModel ~= "" and SettingsModel) or Model or Profile.DefaultModel
	if type(Profile.Models) == "table" and not table.find(Profile.Models, ResolvedModel) then
		ResolvedModel = tostring(Profile.DefaultModel or Profile.Models[1] or "")
	end
	ScriptSettings.AIModels[Provider] = ResolvedModel
	ScriptSettings.AIModel = ResolvedModel
	local EndpointSeed = (SettingsEndpoint ~= "" and SettingsEndpoint) or Profile.Endpoint
	local ResolvedEndpoint = GetAIEndpoint(Provider, ResolvedModel, EndpointSeed)
	local ResolvedKey = SettingsKey ~= "" and SettingsKey or ProviderApiKey or EmbeddedKey
	local ResolvedProtocol = Profile.Protocol
	local RequestOptions = {}
	for OptionName, OptionValue in pairs(Profile.RequestOptions or {}) do
		RequestOptions[OptionName] = OptionValue
	end
	for OptionName, OptionValue in pairs((Profile.ModelOptions or {})[ResolvedModel] or {}) do
		RequestOptions[OptionName] = OptionValue
	end
	EmbeddedAIConfig.Provider = Provider
	EmbeddedAIConfig.Protocol = ResolvedProtocol
	EmbeddedAIConfig.Endpoint = tostring(ResolvedEndpoint)
	EmbeddedAIConfig.ApiKey = tostring(ResolvedKey or "")
	EmbeddedAIConfig.Model = tostring(ResolvedModel or "")
	return {
		Enabled = ResolvedEnabled,
		Provider = Provider,
		Protocol = ResolvedProtocol,
		ApiVersion = Profile.ApiVersion,
		Endpoint = tostring(ResolvedEndpoint),
		ApiKey = tostring(ResolvedKey or ""),
		Model = tostring(ResolvedModel or ""),
		Temperature = tonumber(Temperature) or tonumber(ScriptSettings.AITemperature) or 0.1,
		MaxTokens = tonumber(MaxTokens) or tonumber(ScriptSettings.AIMaxTokens) or 8000,
		Headers = type(Headers) == "table" and Headers or (type(ScriptSettings.AIHeaders) == "table" and ScriptSettings.AIHeaders or {}),
		MaxTokenField = Profile.MaxTokenField,
		RequestOptions = RequestOptions
	}
end

if type(Main) == "table" then
	Main.ResolveAIConfig = ResolveAIConfig
	Main.ResolveDexSettingsAIConfig = ResolveAIConfig
end

local function GetAIKey(ProviderName)
	local Provider = tostring(ProviderName or "")
	local ScriptSettings = Settings and Settings.ScriptViewer or {}
	local StoredKeys = type(ScriptSettings.AIKeys) == "table" and ScriptSettings.AIKeys or {}
	local ApiKey = tostring(StoredKeys[Provider] or "")
	if ApiKey == "" and tostring(ScriptSettings.AIKeyProvider or "Groq") == Provider then
		ApiKey = tostring(ScriptSettings.AIKey or "")
	end
	if ApiKey ~= "" then
		return ApiKey
	end
	if EmbeddedAIConfig.Provider == Provider then
		ApiKey = tostring(EmbeddedAIConfig.ApiKey or "")
		if ApiKey ~= "" then
			return ApiKey
		end
	end
	local ProviderKeyNames = {
		Groq = {"GROQ_API_KEY", "GroqAPIKey"},
		DeepSeek = {"DEEPSEEK_API_KEY", "DeepSeekAPIKey"},
		OpenAI = {"OPENAI_API_KEY", "OpenAIAPIKey"},
		Anthropic = {"ANTHROPIC_API_KEY", "AnthropicAPIKey"},
		["Google Gemini"] = {"GEMINI_API_KEY", "GOOGLE_API_KEY", "GeminiAPIKey"},
		xAI = {"XAI_API_KEY", "XAIAPIKey"},
		Mistral = {"MISTRAL_API_KEY", "MistralAPIKey"}
	}
	local Names = ProviderKeyNames[Provider] or {}
	local Sources = {}
	local function AddSource(Source)
		if type(Source) == "table" and not table.find(Sources, Source) then
			table.insert(Sources, Source)
		end
	end
	AddSource(env)
	AddSource(shared)
	AddSource(_G)
	if type(getgenv) == "function" then
		local Success, GlobalEnvironment = pcall(getgenv)
		if Success then
			AddSource(GlobalEnvironment)
		end
	end
	for _, Source in ipairs(Sources) do
		for _, KeyName in ipairs(Names) do
			local Success, Value = pcall(function()
				return Source[KeyName]
			end)
			if Success and type(Value) == "string" and Value:gsub("%s+", "") ~= "" then
				return Value
			end
		end
	end
	return ""
end
local function GetBeautifierConfig()
	local PluginSettings = Settings and Settings.AIBeautifierPlugin
	if type(PluginSettings) ~= "table" then
		PluginSettings = {}
		if type(Settings) == "table" then Settings.AIBeautifierPlugin = PluginSettings end
	end
	local DexSettings = Settings and Settings.ScriptViewer or {}
	DexSettings.AIKeys = type(DexSettings.AIKeys) == "table" and DexSettings.AIKeys or {}
	PluginSettings.Provider = tostring(PluginSettings.Provider or "Groq")
	if not AIProviderProfiles[PluginSettings.Provider] then PluginSettings.Provider = "Groq" end
	PluginSettings.EndpointOverrides = type(PluginSettings.EndpointOverrides) == "table" and PluginSettings.EndpointOverrides or {}
	PluginSettings.Models = type(PluginSettings.Models) == "table" and PluginSettings.Models or {}
	local LegacyKeys = type(PluginSettings.ApiKeys) == "table" and PluginSettings.ApiKeys or {}
	for LegacyProvider, LegacyKey in pairs(LegacyKeys) do
		if type(LegacyKey) == "string" and LegacyKey ~= "" and tostring(DexSettings.AIKeys[LegacyProvider] or "") == "" then
			DexSettings.AIKeys[LegacyProvider] = LegacyKey
		end
	end
	local LegacyApiKey = tostring(PluginSettings.ApiKey or "")
	local LegacyProvider = tostring(PluginSettings.ApiKeyProvider or PluginSettings.Provider)
	if LegacyApiKey ~= "" and tostring(DexSettings.AIKeys[LegacyProvider] or "") == "" then
		DexSettings.AIKeys[LegacyProvider] = LegacyApiKey
	end
	PluginSettings.ApiKeys = nil
	PluginSettings.ApiKey = nil
	PluginSettings.ApiKeyProvider = nil
	local Provider = PluginSettings.Provider
	local Profile = AIProviderProfiles[Provider]
	local Models = Profile.Models or {Profile.DefaultModel}
	local Model = tostring(PluginSettings.Models[Provider] or PluginSettings.Model or "")
	if Model == "" or not table.find(Models, Model) then
		Model = tostring(Profile.DefaultModel or Models[1] or "")
	end
	PluginSettings.Models[Provider] = Model
	PluginSettings.Model = Model
	local EndpointSeed = tostring(PluginSettings.EndpointOverrides[Provider] or "")
	if EndpointSeed == "" then EndpointSeed = tostring(Profile.Endpoint or "") end
	local ApiKey = GetAIKey(Provider)
	local RequestOptions = {}
	for OptionName, OptionValue in pairs(Profile.RequestOptions or {}) do
		RequestOptions[OptionName] = OptionValue
	end
	for OptionName, OptionValue in pairs((Profile.ModelOptions or {})[Model] or {}) do
		RequestOptions[OptionName] = OptionValue
	end
	for OptionName, OptionValue in pairs(type(PluginSettings.RequestOptions) == "table" and PluginSettings.RequestOptions or {}) do
		RequestOptions[OptionName] = OptionValue
	end
	local Endpoint = GetAIEndpoint(Provider, Model, EndpointSeed)
	PluginSettings.Endpoint = Endpoint
	PluginSettings.EndpointProvider = Provider
	return {
		Enabled = PluginSettings.Enabled ~= false,
		Provider = Provider,
		Protocol = Profile.Protocol,
		ApiVersion = Profile.ApiVersion,
		Endpoint = Endpoint,
		ApiKey = ApiKey,
		ApiKeySource = "Dex Settings",
		Model = Model,
		Temperature = tonumber(PluginSettings.Temperature) or 0.1,
		MaxTokens = tonumber(PluginSettings.MaxTokens) or 8000,
		Headers = type(PluginSettings.Headers) == "table" and PluginSettings.Headers or {},
		MaxTokenField = Profile.MaxTokenField,
		RequestOptions = RequestOptions
	}
end

if type(Main) == "table" then
	Main.ResolveAIBeautifierPluginConfig = GetBeautifierConfig
	Main.GetAIBeautifierPluginConfig = GetBeautifierConfig
	Main.GetSharedAIProviderKey = GetAIKey
	Main.AIBeautifierPluginSettings = Settings.AIBeautifierPlugin
	Main.GetPluginAIConfig = function(PluginName)
		local Normalized = tostring(PluginName or ""):lower():gsub("%W", "")
		if Normalized:find("aibeautifier", 1, true) or Normalized:find("aibeautify", 1, true) then
			local ActiveResolver = type(Main.ResolveAIBeautifierPluginConfig) == "function" and Main.ResolveAIBeautifierPluginConfig or GetBeautifierConfig
			return ActiveResolver()
		end
		return ResolveAIConfig()
	end
	Main.SyncAIBeautifierPluginConfig = function()
		local ActiveResolver = type(Main.ResolveAIBeautifierPluginConfig) == "function" and Main.ResolveAIBeautifierPluginConfig or GetBeautifierConfig
		local ResolveSuccess, PluginConfig = pcall(ActiveResolver)
		if not ResolveSuccess or type(PluginConfig) ~= "table" then
			return false, "AI Beautifier settings could not be resolved."
		end
		local PluginSettings = Settings.AIBeautifierPlugin
		Main.AIBeautifierPluginSettings = PluginSettings
		Main.AIBeautifierPluginConfig = PluginConfig
		for _, PluginRecord in ipairs(Main.Plugins or {}) do
			local PluginData = type(PluginRecord.PluginData) == "table" and PluginRecord.PluginData or {}
			local PluginIdentity = (tostring(PluginRecord.PluginPath or PluginRecord.Path or "") .. tostring(PluginData.Name or "") .. tostring(PluginData.FriendlyName or "")):lower():gsub("%W", "")
			if PluginRecord.IsAIBeautifierPlugin == true or PluginIdentity:find("aibeautifier", 1, true) or PluginIdentity:find("aibeautify", 1, true) then
				PluginRecord.AIBeautifierPluginSettings = PluginSettings
				PluginRecord.ResolveAIConfig = ActiveResolver
				PluginRecord.GetAIConfig = ActiveResolver
				PluginRecord.AIConfig = PluginConfig
				PluginData.AIBeautifierPluginSettings = PluginSettings
				PluginData.ResolveAIConfig = ActiveResolver
				PluginData.AIConfig = PluginConfig
				if type(PluginRecord.SetAIConfigResolver) == "function" then
					pcall(PluginRecord.SetAIConfigResolver, ActiveResolver)
				end
				if type(PluginRecord.OnAIConfigChanged) == "function" then
					pcall(PluginRecord.OnAIConfigChanged, PluginConfig)
				end
			end
		end
		return true, PluginConfig
	end
end

local function RunBeautify(SourceText, Callback)
	local function Complete(AIOutput, AIError)
		if type(Callback) == "function" then
			pcall(Callback, AIOutput, AIError)
		end
	end
	local AIConfig = GetBeautifierConfig()
	local ApiKey = tostring(AIConfig.ApiKey or ""):gsub("^%s+", ""):gsub("%s+$", "")
	local Endpoint = tostring(AIConfig.Endpoint or ""):gsub("^%s+", ""):gsub("%s+$", "")
	local Model = tostring(AIConfig.Model or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if not AIConfig.Enabled then return Complete(nil, "AI Beautifier Plugin is disabled in Dex Settings") end
	if ApiKey == "" then return Complete(nil, "No API key is configured for the AI Beautifier Plugin") end
	if Endpoint == "" or Model == "" then return Complete(nil, "The AI endpoint or model is missing") end
	if type(SourceText) ~= "string" or SourceText:gsub("%s+", "") == "" then return Complete(nil, "The active Decompiler tab is empty") end
	local HttpService = game:GetService("HttpService")
	local ProtectedSource, ProtectedComments = ProtectAIComments(SourceText)
	local Protocol = tostring(AIConfig.Protocol or "ChatCompletions")
	local RequestPayload, RequestHeaders, RequestUrl, RequestBuildError = MakeAIRequest(
		AIConfig,
		AI_PROMPT,
		ProtectedSource,
		AIConfig.MaxTokens,
		AIConfig.Temperature
	)
	if not RequestPayload then
		return Complete(nil, RequestBuildError or "Could not build the AI Beautifier request")
	end
	local EncodeSuccess, RequestBody = pcall(HttpService.JSONEncode, HttpService, RequestPayload)
	if not EncodeSuccess then return Complete(nil, "Could not encode the AI request: " .. tostring(RequestBody)) end
	local RequestFunction
	local function AddReqFn(Candidate)
		if not RequestFunction and type(Candidate) == "function" then
			RequestFunction = Candidate
		end
	end
	AddReqFn(type(env) == "table" and env.request or nil)
	AddReqFn(type(syn) == "table" and syn.request or nil)
	AddReqFn(type(http) == "table" and http.request or nil)
	AddReqFn(http_request)
	AddReqFn(request)
	AddReqFn(type(fluxus) == "table" and fluxus.request or nil)
	local GlobalEnvironment
	if type(getgenv) == "function" then
		local EnvTest, EnvironmentValue = pcall(getgenv)
		if EnvTest and type(EnvironmentValue) == "table" then
			GlobalEnvironment = EnvironmentValue
			AddReqFn(GlobalEnvironment.request)
		end
	end
	if type(_G) == "table" then
		AddReqFn(_G.request)
	end
	if type(RequestFunction) ~= "function" then return Complete(nil, "This executor does not expose a supported HTTP request function") end
	local RequestSuccess, Response
	local AttemptCount = 0
	repeat
		AttemptCount += 1
		RequestSuccess, Response = pcall(RequestFunction, {
			Url = RequestUrl,
			Method = "POST",
			Headers = RequestHeaders,
			Body = RequestBody
		})
		if RequestSuccess and type(Response) == "table" then
			local StatusValue = Response.StatusCode or Response.Status
			local StatusCode = tonumber(StatusValue) or tonumber(tostring(StatusValue or ""):match("(%d%d%d)")) or (Response.Success == true and 200 or 0)
			if StatusCode == 429 and AttemptCount < 3 then
				task.wait(5 * AttemptCount)
			else
				break
			end
		else
			break
		end
	until AttemptCount >= 3
	if not RequestSuccess or type(Response) ~= "table" then
		return Complete(nil, "The AI HTTP request failed: " .. tostring(Response))
	end
	local StatusValue = Response.StatusCode or Response.Status
	local StatusCode = tonumber(StatusValue) or tonumber(tostring(StatusValue or ""):match("(%d%d%d)")) or (Response.Success == true and 200 or 0)
	local ResponseBody = Response.Body or Response.body or Response.ResponseBody or ""
	if StatusCode < 200 or StatusCode >= 300 then
		local ErrorBody = tostring(ResponseBody)
		if ErrorBody == "" and type(Response.Error) == "string" then ErrorBody = Response.Error end
		return Complete(nil, ("AI endpoint returned HTTP %d: %s"):format(StatusCode, ErrorBody:sub(1, 500)))
	end
	local DecodeSuccess, DecodedResponse = pcall(HttpService.JSONDecode, HttpService, tostring(ResponseBody))
	if not DecodeSuccess or type(DecodedResponse) ~= "table" then
		return Complete(nil, "The AI endpoint returned invalid JSON: " .. tostring(ResponseBody):sub(1, 240))
	end
	local AIOutput = ReadAIReply(DecodedResponse, Protocol)
	if type(AIOutput) ~= "string" or AIOutput:gsub("%s+", "") == "" then
		local APIError = type(DecodedResponse.error) == "table" and DecodedResponse.error.message or nil
		return Complete(nil, tostring(APIError or "The AI endpoint returned an empty result"))
	end
	AIOutput = AIOutput:gsub("\r\n", "\n"):gsub("^%s+", ""):gsub("%s+$", "")
	local FencedOutput = AIOutput:match("^```[%w_%-]*%s*\n(.-)\n```%s*$")
	if FencedOutput then AIOutput = FencedOutput end
	AIOutput = AIOutput:gsub("^```[%w_%-]*%s*\n?", ""):gsub("\n?```%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
	if AIOutput == "" then return Complete(nil, "The AI response did not contain source code") end
	local RestoredOutput, RestoreError = RestoreAIComments(AIOutput, ProtectedComments)
	if not RestoredOutput then return Complete(nil, RestoreError) end
	AIOutput = FixSpacing(RestoredOutput)
	Complete(AIOutput)
end

if type(Main) == "table" then
	Main.AIBeautifySource = RunBeautify
end

