	local function ApplySyntaxTheme(ThemeName)
		local SelectedTheme = SyntaxPalettes[ThemeName] and ThemeName or "Default"
		local Palette = SyntaxPalettes[SelectedTheme]
		local SyntaxSettings = Settings.Theme.Syntax
		for _, ColorName in ipairs(TokenColors) do
			local ColorValue = Palette[ColorName]
			if ColorValue then
				SyntaxSettings[ColorName] = ColorValue
			end
		end
		Settings.ScriptViewer.SyntaxTheme = SelectedTheme
		if CodeFrame then
			CodeFrame:MakeRichTemplates()
			table.clear(CodeFrame.ColoredLines)
			CodeFrame:Refresh()
		end
		return SelectedTheme
	end

