SV.DumpFunctions = function(ScriptObject)
    local GetGC = env.getgc or getgc or get_gc_objects
    local GetUpvalues = (debug and debug.getupvalues) or env.getupvalues or getupvalues or getupvals
    local GetConstants = (debug and debug.getconstants) or env.getconstants or getconstants or getconsts
    local GetFunctionEnv = env.getfenv or getfenv
    local GetInfo = (debug and debug.getinfo) or env.getinfo or getinfo
    local DebugInfo = debug and debug.info

    if type(GetGC) ~= "function" then
        if AIStatus then AIStatus.Text = "Dumper: getgc unavailable" end
        return
    end

    if type(GetFunctionEnv) ~= "function" then
        if AIStatus then AIStatus.Text = "Dumper: getfenv unavailable" end
        return
    end

    local GCOK, Objects = pcall(GetGC)

    if not GCOK or type(Objects) ~= "table" then
        if AIStatus then AIStatus.Text = "Dumper: failed to enumerate objects" end
        return
    end

    local DumpLines = {}
    local SeenFunctions = {}
    local FunctionCount = 0
    local ScanCount = 0
    local ScanLimit = 100000
    local FunctionLimit = 500
    local ScanTruncated = false

    local function Add(Text, Depth)
        if #DumpLines < 16000 then
            table.insert(DumpLines, string.rep("\t\t", Depth or 0) .. tostring(Text))
        else
            ScanTruncated = true
        end
    end

    local function GetSortedKeys(TableValue)
        local Keys = {}
        for Key in pairs(TableValue) do
            Keys[#Keys + 1] = Key
        end
        table.sort(Keys, function(Left, Right)
            return tostring(Left) < tostring(Right)
        end)
        return Keys
    end

    local function ReadFunctionInfo(Function)
        if type(GetInfo) == "function" then
            local InfoOK, Info = pcall(GetInfo, Function)
            if InfoOK and type(Info) == "table" then
                return Info
            end
        end
        return {}
    end

    local function GetFunctionName(Function)
        local Info = ReadFunctionInfo(Function)
        if type(Info.name) == "string" and Info.name ~= "" then
            return Info.name
        end
        if type(Info.short_src) == "string" and Info.short_src ~= "" then
            return Info.short_src
        end
        if type(DebugInfo) == "function" then
            local InfoOK, Name = pcall(DebugInfo, Function, "n")
            if InfoOK and type(Name) == "string" and Name ~= "" then
                return Name
            end
        end
        return "Anonymous"
    end

    local function AddFuncMeta(Info)
        local SourceName = Info.short_src or Info.source
        if type(SourceName) == "string" and SourceName ~= "" then
            Add("Source: " .. SourceName, 1)
        end
        local FirstLine = tonumber(Info.linedefined or Info.currentline)
        local LastLine = tonumber(Info.lastlinedefined)
        if FirstLine and FirstLine >= 0 then
            Add("Defined at: " .. tostring(FirstLine) .. (LastLine and LastLine >= FirstLine and ("-" .. tostring(LastLine)) or ""), 1)
        end
        local ParameterCount = tonumber(Info.nparams or Info.numparams)
        if ParameterCount then
            Add("Parameters: " .. tostring(ParameterCount) .. " | Vararg: " .. tostring(Info.isvararg == true or Info.isvararg == 1), 1)
        end
        if tonumber(Info.nups) then
            Add("Upvalue slots: " .. tostring(Info.nups), 1)
        end
        if type(Info.what) == "string" and Info.what ~= "" then
            Add("Function type: " .. Info.what, 1)
        end
    end

    local function ReadUpvalues(Function)
        if type(GetUpvalues) == "function" then
            local ValuesOK, Values = pcall(GetUpvalues, Function)

            if ValuesOK and type(Values) == "table" then
                return Values
            end
        end

        local Values = {}

        if debug and type(debug.getupvalue) == "function" then
            for Index = 1, 100 do
                local ValueOK, Name, Value = pcall(debug.getupvalue, Function, Index)

                if not ValueOK or Name == nil then
                    break
                end

                Values[Name] = Value
            end
        end

        return Values
    end

    local function ReadConstants(Function)
        if type(GetConstants) == "function" then
            local ValuesOK, Values = pcall(GetConstants, Function)

            if ValuesOK and type(Values) == "table" then
                return Values
            end
        end

        local Values = {}

        if debug and type(debug.getconstant) == "function" then
            for Index = 1, 200 do
                local ValueOK, Value = pcall(debug.getconstant, Function, Index)

                if not ValueOK or Value == nil then
                    break
                end

                Values[Index] = Value
            end
        end

        return Values
    end

    local DumpTable

    local function AddValue(Key, Value, Depth, SeenTables)
        local ValueType = type(Value)

        if ValueType == "function" then
            Add(tostring(Key) .. " [function] = " .. GetFunctionName(Value), Depth)
        elseif ValueType == "table" then
            Add(tostring(Key) .. " [table]:", Depth)
            DumpTable(Value, Depth + 1, SeenTables)
        else
            local ValueText = tostring(Value)

            if #ValueText > 250 then
                ValueText = ValueText:sub(1, 250) .. "..."
            end

            Add(tostring(Key) .. " [" .. typeof(Value) .. "] = " .. ValueText, Depth)
        end
    end

    DumpTable = function(TableValue, Depth, SeenTables)
        if Depth > 4 then
            Add("Depth limit reached", Depth)
            return
        end

        if SeenTables[TableValue] then
            Add("Recursive table", Depth)
            return
        end

        SeenTables[TableValue] = true

        local EntryCount = 0

        for _, Key in ipairs(GetSortedKeys(TableValue)) do
            EntryCount += 1

            if EntryCount > 80 then
                Add("Table truncated", Depth)
                break
            end

            AddValue(Key, TableValue[Key], Depth, SeenTables)
        end
    end

    local function BelongsToScript(Function)
        local EnvironmentOK, FunctionEnvironment = pcall(GetFunctionEnv, Function)

        return EnvironmentOK
            and type(FunctionEnvironment) == "table"
            and rawget(FunctionEnvironment, "script") == ScriptObject
    end

    for _, Function in pairs(Objects) do
        ScanCount += 1
        if ScanCount > ScanLimit then
            ScanTruncated = true
            break
        end
        if type(Function) == "function" and not SeenFunctions[Function] then
            SeenFunctions[Function] = true

            if BelongsToScript(Function) then
                FunctionCount += 1
                local FunctionInfo = ReadFunctionInfo(Function)
                Add("Function #" .. tostring(FunctionCount) .. ": " .. GetFunctionName(Function), 0)
                AddFuncMeta(FunctionInfo)

                local SeenTables = {}
                local Upvalues = ReadUpvalues(Function)
                local Constants = ReadConstants(Function)
                Add("Upvalues found: " .. tostring(#GetSortedKeys(Upvalues)) .. " | Constants found: " .. tostring(#GetSortedKeys(Constants)), 1)

                if next(Upvalues) then
                    Add("Upvalues:", 1)
                    for _, Key in ipairs(GetSortedKeys(Upvalues)) do
                        AddValue("upvalue " .. tostring(Key), Upvalues[Key], 2, SeenTables)
                    end
                end

                if next(Constants) then
                    Add("Constants:", 1)
                    for _, Key in ipairs(GetSortedKeys(Constants)) do
                        AddValue("constant " .. tostring(Key), Constants[Key], 2, SeenTables)
                    end
                end

                Add(("="):rep(80), 0)
                if FunctionCount >= FunctionLimit then
                    ScanTruncated = true
                    break
                end
            end
        end
    end

    if FunctionCount == 0 then
        if AIStatus then
            AIStatus.Text = "Dumper: no matching script functions"
        end

        return
    end

    local PathOK, ScriptPath = pcall(GetScriptPath, ScriptObject)

    if not PathOK then
        ScriptPath = tostring(ScriptObject)
    end

    local Source = CodeFrame:GetText()
    local Marker = Source:find("\n-- // Function Dumper\n", 1, true)

    if Marker then
        Source = Source:sub(1, Marker - 1)
    end

    local Prefix = ("\n-- // Function Dumper\n-- // Path: %s\n-- // Functions: %d\n-- // GC Objects Scanned: %d\n-- // Scan Truncated: %s\n\n--[[\n"):format(tostring(ScriptPath), FunctionCount, ScanCount, tostring(ScanTruncated))

    CodeFrame:SetText(Source .. Prefix .. table.concat(DumpLines, "\n") .. "\n]]")
    if UpdateSearchResults then UpdateSearchResults(true) end
    Window:Show()

    if AIStatus then
        AIStatus.Text = ScanTruncated and ("Dumped %d functions (scan limited)"):format(FunctionCount) or ("Dumped %d functions"):format(FunctionCount)
    end
end


	local function MakeDecompButton(Parent, Text, X, Width, ButtonColor, OnClick)
		local Button = Instance.new("TextButton", Parent)
		local BaseColor = ButtonColor or Color3.fromRGB(55, 55, 55)
		local HoverColor = Color3.new(math.min(BaseColor.R * 1.16, 1), math.min(BaseColor.G * 1.16, 1), math.min(BaseColor.B * 1.16, 1))
		Button.BackgroundColor3 = BaseColor
		Button.BorderSizePixel = 0
		Button.Font = Enum.Font.SourceSansSemibold
		Button.TextSize = 15
		Button.TextColor3 = Color3.fromRGB(240, 240, 240)
		Button.Text = Text
		Button.AutoButtonColor = false
		Button.Size = UDim2.new(0, Width, 0, 20)
		Button.Position = UDim2.new(0, X, 0, 3)
		Button.MouseEnter:Connect(function()
			service.TweenService:Create(Button, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = HoverColor}):Play()
		end)
		Button.MouseLeave:Connect(function()
			service.TweenService:Create(Button, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = BaseColor}):Play()
		end)
		if OnClick then Button.Activated:Connect(OnClick) end
		return Button
	end

	local function SetDecompStatus(StatusText, IsError)
		if AIStatus then
			AIStatus.Text = tostring(StatusText or "")
			AIStatus.TextColor3 = IsError and Color3.fromRGB(185, 185, 185) or Color3.fromRGB(205, 205, 205)
		end
	end

	local function TextPos(Source, CharacterIndex)
		local Prefix = Source:sub(1, math.max(0, CharacterIndex - 1))
		local LineNumber = select(2, Prefix:gsub("\n", ""))
		local LastNewline = Prefix:match(".*()\n")
		local Column = #Prefix - (LastNewline or 0)
		return Column, LineNumber
	end

	local function ShowSearchMatch()
		if not CodeFrame or #SearchMatches == 0 then
			return
		end
		local Match = SearchMatches[SearchMatchIndex]
		if not Match then
			return
		end
		local Source = CodeFrame:GetText()
		local StartX, StartY = TextPos(Source, Match[1])
		local EndX, EndY = TextPos(Source, Match[2] + 1)
		CodeFrame.SelectionRange = {{StartX, StartY}, {EndX, EndY}}
		CodeFrame.CursorX = EndX
		CodeFrame.CursorY = EndY
		CodeFrame.FloatCursorX = EndX
		CodeFrame.ScrollV:ScrollTo(math.max(0, StartY - 2))
		CodeFrame.ScrollH:ScrollTo(math.max(0, StartX - 4))
		CodeFrame:Refresh()
		if FindCount then
			FindCount.Text = string.format("%d/%d", SearchMatchIndex, #SearchMatches)
		end
	end

	UpdateSearchResults = function(ResetIndex)
		if not CodeFrame or not FindBox then
			return
		end
		local Query = FindBox.Text or ""
		local Source = CodeFrame:GetText()
		SearchMatches = {}
		if Query == "" then
			SearchMatchIndex = 0
			CodeFrame:ResetSelection()
			if FindCount then
				FindCount.Text = "0/0"
			end
			return
		end
		local SearchSource = SearchCaseSensitive and Source or string.lower(Source)
		local SearchQuery = SearchCaseSensitive and Query or string.lower(Query)
		local SearchPosition = 1
		while SearchPosition <= #SearchSource do
			local MatchStart, MatchEnd = string.find(SearchSource, SearchQuery, SearchPosition, true)
			if not MatchStart then
				break
			end
			SearchMatches[#SearchMatches + 1] = {MatchStart, MatchEnd}
			SearchPosition = MatchEnd + 1
		end
		if #SearchMatches == 0 then
			SearchMatchIndex = 0
			CodeFrame:ResetSelection()
			if FindCount then
				FindCount.Text = "0/0"
			end
			return
		end
		if ResetIndex or SearchMatchIndex < 1 or SearchMatchIndex > #SearchMatches then
			SearchMatchIndex = 1
		end
		ShowSearchMatch()
	end

	local function ChangeSearchMatch(Direction)
		if #SearchMatches == 0 then
			UpdateSearchResults(true)
			return
		end
		SearchMatchIndex += Direction
		if SearchMatchIndex > #SearchMatches then
			SearchMatchIndex = 1
		elseif SearchMatchIndex < 1 then
			SearchMatchIndex = #SearchMatches
		end
		ShowSearchMatch()
	end

	
local function BeautifyLocal()
    local Source = CodeFrame:GetText()

    if Source == "" then
        return
    end

    SetDecompStatus("Beautifying locally...")

    local StartTime = tick()
    local Success, Output, RenameCount = pcall(BeautifySource, Source)

    if not Success then
        return SetDecompStatus("Failed: " .. tostring(Output), true)
    end

    if type(Output) ~= "string" then
        return SetDecompStatus("Invalid beautifier output", true)
    end

    CodeFrame:SetText(Output)
    if UpdateSearchResults then UpdateSearchResults(true) end

    local Elapsed = tick() - StartTime
    RenameCount = RenameCount or 0

    if RenameCount == 0 then
        SetDecompStatus(("Formatted; no generated names found (%.3fs)"):format(Elapsed))
    else
        SetDecompStatus(("Renamed %d variables in %.3fs"):format(RenameCount, Elapsed))
    end
end

	SV.BeautifyLocal = BeautifyLocal

	local BeautifyId = 0
	local function BeautifyWithAI(CompletionCallback)
		local TargetScript = ActiveTabScript or PreviousScr
		local StoredRecord = TargetScript and TabRecords[TargetScript] or nil
		local SourceText = CodeFrame and CodeFrame:GetText() or ""
		if type(SourceText) ~= "string" or SourceText:gsub("%s+", "") == "" then
			SourceText = StoredRecord and (StoredRecord.Source or StoredRecord.RawSource) or ""
		end
		if type(SourceText) ~= "string" or SourceText:gsub("%s+", "") == "" then
			SetDecompStatus("Open a script with source before using AI Beautify", true)
			if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, "The active Decompiler tab is empty") end
			return false, "The active Decompiler tab is empty"
		end
		local AIConfig = GetBeautifierConfig()
		if not AIConfig.Enabled then
			SetDecompStatus("Enable AI Beautifier Plugin in Dex Settings", true)
			if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, "AI Beautifier Plugin is disabled") end
			return false, "AI Beautifier Plugin is disabled"
		end
		if tostring(AIConfig.ApiKey or ""):gsub("%s+", "") == "" then
			SetDecompStatus("No key is saved for the AI Beautifier provider in Dex Settings", true)
			if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, "No key is saved for the AI Beautifier provider") end
			return false, "No key is saved for the AI Beautifier provider"
		end
		if TargetScript and StoredRecord then
			StoredRecord.Source = SourceText
			StoredRecord.UpdatedAt = os.time()
		end
		BeautifyId += 1
		local RequestSerial = BeautifyId
		SetDecompStatus(("Sending active Decompiler tab to AI... (%d bytes, %s)"):format(#SourceText, tostring(AIConfig.Model)))
		local StartSuccess, StartError = pcall(function()
			task.spawn(function()
				local RequestSuccess, RequestError = pcall(RunBeautify, SourceText, function(AIOutput, AIError)
					if not AIOutput then
						local FailureText = tostring(AIError or "Unknown AI error")
						if RequestSerial == BeautifyId then SetDecompStatus("AI Beautify failed: " .. FailureText, true) end
						if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, FailureText) end
						return
					end
					local CanSaveResult = false
					local ApplyResult = false
					if TargetScript and TabRecords[TargetScript] then
						local TargetRecord = TabRecords[TargetScript]
						if TargetRecord.Source == SourceText then
							if ActiveTabScript == TargetScript then
								ApplyResult = CodeFrame ~= nil and CodeFrame:GetText() == SourceText
								CanSaveResult = ApplyResult
							else
								CanSaveResult = true
							end
						end
					elseif not TargetScript and CodeFrame and CodeFrame:GetText() == SourceText then
						CanSaveResult = true
						ApplyResult = true
					end
					if CanSaveResult then
						if TargetScript and TabRecords[TargetScript] then
							TabRecords[TargetScript].Source = AIOutput
							TabRecords[TargetScript].UpdatedAt = os.time()
							AICache[TargetScript] = AIOutput
						end
						if ApplyResult then
							CodeFrame:SetText(AIOutput)
							if UpdateSearchResults then UpdateSearchResults(true) end
						end
						if RequestSerial == BeautifyId then
							if AIOutput == SourceText then
								SetDecompStatus("AI Beautify completed; the model made no source changes")
							elseif ApplyResult then
								SetDecompStatus(("AI Beautify complete (%d bytes)"):format(#AIOutput))
							else
								SetDecompStatus("AI Beautify saved the inactive script tab")
							end
						end
						if type(CompletionCallback) == "function" then pcall(CompletionCallback, true, AIOutput) end
					else
						local StatusText = "AI Beautify finished, but the active tab changed or its source was edited; the result was not applied"
						if RequestSerial == BeautifyId then SetDecompStatus(StatusText, true) end
						if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, StatusText) end
				end
				end)
				if not RequestSuccess then
					local FailureText = tostring(RequestError)
					if RequestSerial == BeautifyId then SetDecompStatus("AI Beautify failed: " .. FailureText, true) end
					if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, FailureText) end
				end
			end)
		end)
		if not StartSuccess then
			local FailureText = tostring(StartError)
			SetDecompStatus("AI Beautify couldn't start: " .. FailureText, true)
			if type(CompletionCallback) == "function" then pcall(CompletionCallback, false, FailureText) end
			return false, FailureText
		end
		return true
	end

	SV.BeautifyAI = BeautifyWithAI

	local function SaveActiveTab()
		if ActiveTabScript and CodeFrame then
			local Record = TabRecords[ActiveTabScript]
			if Record then
				Record.Source = CodeFrame:GetText()
				Record.RawSource = RawSource
				Record.UpdatedAt = os.time()
			end
		end
	end

	local function RenderTabStrip()
		if not TabStrip then return end
		for _, Child in ipairs(TabStrip:GetChildren()) do
			if Child:IsA("TextButton") then Child:Destroy() end
		end
		for Index, ScriptObject in ipairs(TabOrder) do
			local Record = TabRecords[ScriptObject]
			if Record then
				local TabName = tostring(Record.Name or ScriptObject.Name or "Script")
				local TextBounds = service.TextService:GetTextSize(TabName, 12, Enum.Font.SourceSans, Vector2.new(200, 20))
				local TabWidth = math.clamp(math.ceil(TextBounds.X) + 68, 142, 270)
				local TabButton = Instance.new("TextButton")
				TabButton.Name = "ScriptTab_" .. tostring(Index)
				TabButton.AutoButtonColor = false
				TabButton.BorderSizePixel = 0
				TabButton.ClipsDescendants = true
				TabButton.BackgroundColor3 = ScriptObject == ActiveTabScript and Color3.fromRGB(65,65,65) or Color3.fromRGB(43,43,43)
				TabButton.Text = ""
				TabButton.Size = UDim2.new(0, TabWidth, 1, 0)
				TabButton.LayoutOrder = Index
				TabButton.ZIndex = 5
				TabButton.Parent = TabStrip
				local CloseTabButton = Instance.new("ImageButton")
				CloseTabButton.Name = "CloseScriptTab"
				CloseTabButton.BackgroundTransparency = 1
				CloseTabButton.BorderSizePixel = 0
				CloseTabButton.AutoButtonColor = false
				CloseTabButton.Active = true
				CloseTabButton.Selectable = false
				CloseTabButton.Image = ""
				CloseTabButton.ImageTransparency = 1
				CloseTabButton.Size = UDim2.new(0, 19, 0, 19)
				CloseTabButton.Position = UDim2.new(1, -23, 0.5, -9)
				CloseTabButton.ZIndex = TabButton.ZIndex + 3
				CloseTabButton.Parent = TabButton
				local CloseTabIcon = Instance.new("ImageLabel")
				CloseTabIcon.Name = "CloseIcon"
				CloseTabIcon.BackgroundTransparency = 1
				CloseTabIcon.BorderSizePixel = 0
				CloseTabIcon.Image = "rbxassetid://130629964514885"
				CloseTabIcon.ImageColor3 = Color3.fromRGB(235, 235, 235)
				CloseTabIcon.ImageTransparency = 0
				CloseTabIcon.ScaleType = Enum.ScaleType.Fit
				CloseTabIcon.Size = UDim2.new(1, 0, 1, 0)
				CloseTabIcon.Position = UDim2.new(0, 0, 0, 0)
				CloseTabIcon.ZIndex = CloseTabButton.ZIndex + 1
				CloseTabIcon.Parent = CloseTabButton
				CloseTabButton.MouseEnter:Connect(function()
					CloseTabIcon.ImageColor3 = Color3.fromRGB(255, 255, 255)
				end)
				CloseTabButton.MouseLeave:Connect(function()
					CloseTabIcon.ImageColor3 = Color3.fromRGB(235, 235, 235)
				end)
				local TabIcon = Instance.new("ImageLabel")
				TabIcon.Name = "ScriptTypeIcon"
				TabIcon.BackgroundTransparency = 1
				TabIcon.Position = UDim2.new(0, 8, 0.5, -8)
				TabIcon.Size = UDim2.new(0, 16, 0, 16)
				TabIcon.ScaleType = Enum.ScaleType.Fit
				TabIcon.ZIndex = TabButton.ZIndex + 1
				TabIcon.Parent = TabButton
				local CanServerIcon = ScriptObject.ClassName == "Script" and Record.CanViewServerScript == true
				if CanServerIcon then
					TabIcon.ImageRectOffset = Vector2.new(0, 0)
					TabIcon.ImageRectSize = Vector2.new(0, 0)
					TabIcon.ScaleType = Enum.ScaleType.Fit
					TabIcon.Image = "rbxassetid://83179261688597"
				else
					TabIcon.Image = ""
					if Explorer and Explorer.ClassIcons then
						local IconSuccess = pcall(function()
							Explorer.ClassIcons:DisplayByKey(TabIcon, ScriptObject.ClassName)
						end)
						if not IconSuccess or TabIcon.Image == "" then
							TabIcon.Image = "rbxasset://textures/ClassImages.PNG"
						end
					else
						TabIcon.Image = "rbxasset://textures/ClassImages.PNG"
					end
				end
				local TabLabel = Instance.new("TextLabel")
				TabLabel.Name = "ScriptTabLabel"
				TabLabel.BackgroundTransparency = 1
				TabLabel.BorderSizePixel = 0
				TabLabel.Position = UDim2.new(0, 29, 0, 0)
				TabLabel.Size = UDim2.new(1, -57, 1, 0)
				TabLabel.Font = Enum.Font.SourceSans
				TabLabel.TextSize = 12
				TabLabel.TextColor3 = Color3.fromRGB(230,230,230)
				TabLabel.TextXAlignment = Enum.TextXAlignment.Center
				TabLabel.TextYAlignment = Enum.TextYAlignment.Center
				TabLabel.TextTruncate = Enum.TextTruncate.AtEnd
				TabLabel.Text = TabName
				TabLabel.ZIndex = TabButton.ZIndex + 1
				TabLabel.Parent = TabButton
				CloseTabButton.Activated:Connect(function()
					local TabIndex = table.find(TabOrder, ScriptObject)
					if not TabIndex then return end
					local WasActiveTab = ScriptObject == ActiveTabScript
					if WasActiveTab then SaveActiveTab() end
					table.remove(TabOrder, TabIndex)
					TabRecords[ScriptObject] = nil
					if WasActiveTab then
						local NextActiveScript = TabOrder[math.min(TabIndex, #TabOrder)]
						if NextActiveScript then
							local NextRecord = TabRecords[NextActiveScript]
							ActiveTabScript = NextActiveScript
							PreviousScr = NextActiveScript
							RawSource = NextRecord and NextRecord.RawSource or nil
							CodeFrame:SetText(NextRecord and NextRecord.Source or "")
						else
							ActiveTabScript = nil
							PreviousScr = nil
							RawSource = nil
							CodeFrame:SetText("")
						end
						if UpdateSearchResults then UpdateSearchResults(true) end
					end
					RenderTabStrip()
				end)
				TabButton.Activated:Connect(function()
					if ScriptObject == ActiveTabScript then return end
					SaveActiveTab()
					local TargetRecord = TabRecords[ScriptObject]
					if not TargetRecord then return end
					ActiveTabScript = ScriptObject
					PreviousScr = ScriptObject
					RawSource = TargetRecord.RawSource
					CodeFrame:SetText(TargetRecord.Source or "")
					if UpdateSearchResults then UpdateSearchResults(true) end
					RenderTabStrip()
					Window:Show()
				end)
			end
		end
		if TabLayout then
			TabStrip.CanvasSize = UDim2.new(0, TabLayout.AbsoluteContentSize.X, 0, 0)
		else
			TabStrip.CanvasSize = UDim2.new(0, 0, 0, 0)
		end
	end

	local function StoreTab(ScriptObject, Source, RawSourceValue, CanViewServerScript)
		if not ScriptObject then return end
		local Record = TabRecords[ScriptObject]
		if not Record then
			Record = {Script = ScriptObject, Name = tostring(ScriptObject.Name), Path = "", Source = Source or "", RawSource = RawSourceValue, CanViewServerScript = CanViewServerScript == true, UpdatedAt = os.time()}
			TabRecords[ScriptObject] = Record
			TabOrder[#TabOrder + 1] = ScriptObject
		end
		Record.Name = tostring(ScriptObject.Name)
		Record.Source = Source or Record.Source or ""
		Record.RawSource = RawSourceValue
		Record.CanViewServerScript = CanViewServerScript == true
		Record.UpdatedAt = os.time()
		while #TabOrder > 12 do
			local RemovedScript = table.remove(TabOrder, 1)
			if RemovedScript ~= ActiveTabScript then TabRecords[RemovedScript] = nil end
		end
		ActiveTabScript = ScriptObject
		RenderTabStrip()
	end

	local function CheckCode(SourceText)
		local Diagnostics = {}
		local function Add(Severity, Code, Line, Column, Width, Message, Suggestion)
			Line = math.max(1, tonumber(Line) or 1)
			Column = math.max(1, tonumber(Column) or 1)
			Diagnostics[#Diagnostics + 1] = {Severity = Severity, Code = Code, Line = Line, Column = Column, EndColumn = Column + math.max(1, Width or 1) - 1, Message = Message, Suggestion = Suggestion or ""}
		end
		local Compiler = type(env) == "table" and env.loadstring or loadstring
		local CompilerAvailable = type(Compiler) == "function"
		if SourceText:gsub("%s+", "") == "" then return Diagnostics, CompilerAvailable and "Luau compiler" or "Delimiter fallback" end
		if CompilerAvailable then
			local CallOK, Chunk, CompileError = pcall(Compiler, SourceText)
			local Failure = not CallOK and tostring(Chunk) or (type(Chunk) ~= "function" and tostring(CompileError or Chunk or "Luau compiler rejected source") or nil)
			if Failure then
				local ErrorLine, ErrorColumn = Failure:match(":(%d+):(%d+):")
				local Line = tonumber(ErrorLine) or tonumber(Failure:match(":(%d+):")) or tonumber(Failure:match("line%s+(%d+)")) or 1
				local Lines = string.split(SourceText, "\n")
				local LineText = Lines[Line] or ""
				local Column = tonumber(ErrorColumn) or 1
				local Near = Failure:match("near%s+['\"](.-)['\"]")
				if Near and Near ~= "" then
					local Found = LineText:find(Near, 1, true)
					if Found then Column = #(LineText:sub(1, Found - 1):gsub("\t", "    ")) + 1 end
				elseif Failure:find("<eof>", 1, true) then
					Column = #LineText + 1
				end
				local Message = Failure:match(":%d+:%s*(.+)") or Failure
				Add("Error", "syntax.compiler", Line, Column, #(Near or ""), Message, "Correct the Luau syntax reported by the compiler.")
				return Diagnostics, "Luau compiler"
			end
		end
		local Lines = string.split(SourceText, "\n")
		local MaskedCharacters = {}
		for Index = 1, #SourceText do MaskedCharacters[Index] = SourceText:sub(Index, Index) end
		local MaskError
		local function MaskRange(First, Last)
			for Position = First, Last do
				if MaskedCharacters[Position] ~= "\n" then MaskedCharacters[Position] = " " end
			end
		end
		local function GetSourceLocation(Position)
			local Prefix = SourceText:sub(1, Position - 1)
			local Line = select(2, Prefix:gsub("\n", "")) + 1
			local LastNewline = Prefix:match(".*()\n") or 0
			return Line, Position - LastNewline
		end
		local SourceIndex = 1
		while SourceIndex <= #SourceText do
			local Character = SourceText:sub(SourceIndex, SourceIndex)
			if SourceText:sub(SourceIndex, SourceIndex + 1) == "--" then
				local Equals = SourceText:sub(SourceIndex + 2):match("^%[(=*)%[")
				if Equals ~= nil then
					local Opening = "[" .. Equals .. "["
					local Closing = "]" .. Equals .. "]"
					local ClosingStart = SourceText:find(Closing, SourceIndex + 2 + #Opening, true)
					if not ClosingStart then
						local ErrorLine, ErrorColumn = GetSourceLocation(SourceIndex)
						MaskError = {Line = ErrorLine, Column = ErrorColumn, Message = "Unclosed long comment."}
						break
					end
					local ClosingEnd = ClosingStart + #Closing - 1
					MaskRange(SourceIndex, ClosingEnd)
					SourceIndex = ClosingEnd + 1
				else
					local Newline = SourceText:find("\n", SourceIndex, true)
					local CommentEnd = (Newline or (#SourceText + 1)) - 1
					MaskRange(SourceIndex, CommentEnd)
					SourceIndex = CommentEnd + 1
				end
			elseif Character == "\"" or Character == "'" or Character == "`" then
				local Quote = Character
				local QuoteStart = SourceIndex
				local Escaped = false
				local Closed = false
				SourceIndex += 1
				while SourceIndex <= #SourceText do
					local Current = SourceText:sub(SourceIndex, SourceIndex)
					if Escaped then
						Escaped = false
					elseif Current == "\\" then
						Escaped = true
					elseif Current == Quote then
						Closed = true
						break
					elseif Current == "\n" and Quote ~= "`" then
						break
					end
					SourceIndex += 1
				end
				if not Closed then
					local ErrorLine, ErrorColumn = GetSourceLocation(QuoteStart)
					MaskError = {Line = ErrorLine, Column = ErrorColumn, Message = "Unclosed string literal."}
					MaskRange(QuoteStart, math.min(SourceIndex, #SourceText))
					break
				end
				MaskRange(QuoteStart, SourceIndex)
				SourceIndex += 1
			elseif Character == "[" then
				local Equals = SourceText:sub(SourceIndex):match("^%[(=*)%[")
				if Equals ~= nil then
					local Opening = "[" .. Equals .. "["
					local Closing = "]" .. Equals .. "]"
					local ClosingStart = SourceText:find(Closing, SourceIndex + #Opening, true)
					if not ClosingStart then
						local ErrorLine, ErrorColumn = GetSourceLocation(SourceIndex)
						MaskError = {Line = ErrorLine, Column = ErrorColumn, Message = "Unclosed long-bracket string."}
						MaskRange(SourceIndex, #SourceText)
						break
					end
					local ClosingEnd = ClosingStart + #Closing - 1
					MaskRange(SourceIndex, ClosingEnd)
					SourceIndex = ClosingEnd + 1
				else
					SourceIndex += 1
				end
			else
				SourceIndex += 1
			end
		end
		local BareCode = table.concat(MaskedCharacters)
		local CodeLines = string.split(BareCode, "\n")
		local Declared = {}
		local GlobalNames = {game=true,workspace=true,script=true,plugin=true,Enum=true,Instance=true,Vector2=true,Vector3=true,CFrame=true,Color3=true,BrickColor=true,UDim=true,UDim2=true,TweenInfo=true,Ray=true,Random=true,task=true,math=true,string=true,table=true,coroutine=true,debug=true,os=true,utf8=true,buffer=true,bit32=true,print=true,warn=true,error=true,assert=true,pcall=true,xpcall=true,type=true,typeof=true,tostring=true,tonumber=true,pairs=true,ipairs=true,next=true,select=true,rawget=true,rawset=true,setmetatable=true,getmetatable=true,require=true,unpack=true,loadstring=true,getfenv=true,setfenv=true,wait=true,spawn=true,delay=true,tick=true,time=true,getgenv=true,getrenv=true,getsenv=true,getgc=true,getreg=true,getconnections=true,getupvalue=true,getupvalues=true,getconstants=true,getconstant=true,hookfunction=true,hookmetamethod=true,newcclosure=true,clonefunction=true,cloneref=true,checkcaller=true,Drawing=true,syn=true,http=true,request=true,http_request=true,decompile=true,saveinstance=true}
		if type(getfenv) == "function" then
			local EnvOK, RuntimeEnvironment = pcall(getfenv)
			if EnvOK and type(RuntimeEnvironment) == "table" then for Name in pairs(RuntimeEnvironment) do GlobalNames[Name] = true end end
		end
		local Keywords = {["and"]=true,["break"]=true,["do"]=true,["else"]=true,["elseif"]=true,["end"]=true,["false"]=true,["for"]=true,["function"]=true,["if"]=true,["in"]=true,["local"]=true,["nil"]=true,["not"]=true,["or"]=true,["repeat"]=true,["return"]=true,["then"]=true,["true"]=true,["until"]=true,["while"]=true,["continue"]=true,["type"]=true,["export"]=true}
		for LineNumber, LineText in ipairs(Lines) do
			local CleanLine = CodeLines[LineNumber] or ""
			local LocalFunction = CleanLine:match("^%s*local%s+function%s+([%a_][%w_]*)")
			if LocalFunction then
				Declared[LocalFunction] = Declared[LocalFunction] or {Line=LineNumber, Column=(CleanLine:find(LocalFunction, 1, true) or 1), Count=0}
			else
				local DeclarationText = CleanLine:match("^%s*local%s+(.+)")
				if DeclarationText then
					DeclarationText = DeclarationText:match("^(.-)%s*=") or DeclarationText
					for Part in DeclarationText:gmatch("[^,]+") do
						local Name = Part:match("^%s*([%a_][%w_]*)")
						if Name and Name ~= "function" and Name ~= "type" then
							Declared[Name] = Declared[Name] or {Line=LineNumber, Column=(CleanLine:find(Name, 1, true) or 1), Count=0}
						end
					end
				end
			end
			local ForDeclaration = CleanLine:match("^%s*for%s+(.+)%s+do")
			if ForDeclaration then
				for Part in ForDeclaration:gmatch("[^,]+") do
					local LoopName = Part:match("^%s*([%a_][%w_]*)")
					if LoopName then Declared[LoopName] = Declared[LoopName] or {Line=LineNumber, Column=(CleanLine:find(LoopName, 1, true) or 1), Count=0} end
				end
			end
			for Params in CleanLine:gmatch("function%s*[%w_%.:]*%s*%(([^)]*)%)") do
				for Part in Params:gmatch("[^,]+") do
					local ParamName = Part:match("^%s*([%a_][%w_]*)")
					if ParamName then Declared[ParamName] = Declared[ParamName] or {Line=LineNumber, Column=(CleanLine:find(ParamName, 1, true) or 1), Count=1} end
				end
			end
			if not CleanLine:match("^%s*local%s+function%f[%s]") then
				for Name in CleanLine:gmatch("function%s+([%a_][%w_]*)") do GlobalNames[Name] = true end
			end
			local AssignedGlobal = CleanLine:match("^%s*([%a_][%w_]*)%s*=")
			if AssignedGlobal and not CleanLine:match("^%s*local%s+") then GlobalNames[AssignedGlobal] = true end
		end
		if not CompilerAvailable then
			if MaskError then
				Add("Error", "syntax.string", MaskError.Line, MaskError.Column, 1, MaskError.Message, "Close the string or comment with its matching delimiter.")
				return Diagnostics, "Delimiter fallback"
			end
			local DelimiterStack = {}
			local DelimiterPairs = {["("] = ")", ["["] = "]", ["{"] = "}"}
			for Position, Character in BareCode:gmatch("()([%(%)%[%]{}])") do
				local Prefix = BareCode:sub(1, Position - 1)
				local Line = select(2, Prefix:gsub("\n", "")) + 1
				local LastNewline = Prefix:match(".*()\n") or 0
				local Column = #Prefix - LastNewline + 1
				if DelimiterPairs[Character] then
					DelimiterStack[#DelimiterStack + 1] = {Character = Character, Line = Line, Column = Column}
				else
					local Last = DelimiterStack[#DelimiterStack]
					if not Last or DelimiterPairs[Last.Character] ~= Character then
						Add("Error", "syntax.delimiter", Line, Column, 1, "Unexpected closing delimiter '" .. Character .. "'.", "Add the matching opening delimiter or remove this one.")
						return Diagnostics, "Delimiter fallback"
					end
					table.remove(DelimiterStack)
				end
			end
			if #DelimiterStack > 0 then
				local Last = DelimiterStack[#DelimiterStack]
				Add("Error", "syntax.delimiter", Last.Line, Last.Column, 1, "Unclosed '" .. Last.Character .. "'.", "Add the matching closing delimiter.")
				return Diagnostics, "Delimiter fallback"
			end
		end
		for Name, Record in pairs(Declared) do
			local _, Count = BareCode:gsub("%f[%w_]" .. Name .. "%f[^%w_]", "")
			if Count <= 1 and not GlobalNames[Name] then Add("Warning", "local.unused", Record.Line, Record.Column, #Name, "Local '" .. Name .. "' is never used.", "Remove the declaration or use the value.") end
		end
		local SeenGlobals = {}
		for LineNumber, LineText in ipairs(Lines) do
			local CleanLine = CodeLines[LineNumber] or ""
			for Name, Column in CleanLine:gmatch("()([%a_][%w_]*)%s*%(") do
				local Prefix = CleanLine:sub(1, Name - 1)
				local IsMember = Prefix:match("[%.:]%s*$") ~= nil
				local IsDeclaration = Prefix:match("function%s+$") ~= nil or Prefix:match("local%s+$") ~= nil
				if not IsMember and not IsDeclaration and not Declared[Column] and not GlobalNames[Column] and not Keywords[Column] and not SeenGlobals[Column] then
					SeenGlobals[Column] = true
					Add("Warning", "global.unknown", LineNumber, Name, #Column, "Potentially undefined global '" .. Column .. "'.", "Check spelling or define it in the script or runtime environment.")
				end
			end
			local NilStart, NilFinish = CleanLine:find(":FindFirstChild%s*%b()%s*[%.:]")
			if NilStart then Add("Warning", "nil.findfirstchild", LineNumber, NilFinish, 1, "Possible nil access after FindFirstChild().", "Check the returned instance before using it.") end
			for MethodName, Arguments in CleanLine:gmatch(":([%a_][%w_]*)%s*%(([^)]*)%)") do
				local Minimum, Maximum
				if MethodName == "GetService" then Minimum, Maximum = 1, 1 elseif MethodName == "WaitForChild" or MethodName == "FindFirstChild" or MethodName == "FindFirstChildOfClass" then Minimum, Maximum = 1, 2 end
				if Minimum then
					local _, Commas = Arguments:gsub(",", "")
					local HasArgument = Arguments:match("[^%s]") ~= nil
					local ActualCount = HasArgument and Commas + 1 or 0
					if ActualCount < Minimum or ActualCount > Maximum then
						local CallStart = CleanLine:find(":" .. MethodName, 1, true) or 1
						Add("Warning", "arguments." .. MethodName, LineNumber, CallStart, #MethodName + 1, MethodName .. "() has " .. tostring(ActualCount) .. " arguments; expected " .. tostring(Minimum) .. (Maximum ~= Minimum and ("-" .. tostring(Maximum)) or "") .. ".", "Check the API's expected argument count.")
					end
				end
			end
			local InstanceNewArgs = CleanLine:match("Instance%.new%s*%(([^)]*)%)")
			if InstanceNewArgs then
				local _, Commas = InstanceNewArgs:gsub(",", "")
				local HasArgument = InstanceNewArgs:match("[^%s]") ~= nil
				local ActualCount = HasArgument and Commas + 1 or 0
				if ActualCount < 1 or ActualCount > 2 then
					local CallStart = CleanLine:find("Instance%.new") or 1
					Add("Warning", "arguments.Instance.new", LineNumber, CallStart, 11, "Instance.new() expects one or two arguments.", "Pass a class name and optionally a parent.")
				end
			end
			if CleanLine:match("^%s*return[%s%(]?") or CleanLine:match("^%s*break[%s;]?") then
				if not CleanLine:match("%f[%a]end%f[%A]") then
					local NextLine = LineNumber + 1
					while NextLine <= #Lines and (Lines[NextLine]:match("^%s*$") or Lines[NextLine]:match("^%s*%-%-")) do NextLine += 1 end
					if NextLine <= #Lines then
						local NextText = Lines[NextLine]:match("^%s*(.-)%s*$") or ""
						if NextText ~= "end" and NextText ~= "else" and NextText ~= "elseif" and not NextText:match("^until[%s;]?") then
							Add("Warning", "flow.unreachable", NextLine, #(Lines[NextLine]:match("^(%s*)") or "") + 1, math.max(1, #NextText:match("^%S+") ), "Code may be unreachable after " .. (CleanLine:match("^%s*return") and "return" or "break") .. ".", "Move the statement before the control-flow exit or remove it.")
							break
						end
					end
				end
			end
		end
		for LineNumber, CleanLine in ipairs(CodeLines) do
			local LegacyConnectColumn = CleanLine:find(":%s*connect%s*%(")
			if LegacyConnectColumn then
				Add("Warning", "api.deprecated.connect", LineNumber, LegacyConnectColumn + 1, 7, "connect() is deprecated; use Connect().", "Replace :connect() with :Connect().")
			end
			if CleanLine:match("^%s*wait%s*%(") or CleanLine:match("[^%w_%.:]wait%s*%(") then
				Add("Warning", "api.deprecated.wait", LineNumber, CleanLine:find("wait%s*%(") or 1, 4, "wait() is deprecated in favor of task.wait().", "Use task.wait() for scheduler-aware yielding.")
			end
			if CleanLine:match("^%s*spawn%s*%(") or CleanLine:match("[^%w_%.:]spawn%s*%(") then
				Add("Warning", "api.deprecated.spawn", LineNumber, CleanLine:find("spawn%s*%(") or 1, 5, "spawn() is deprecated in favor of task.spawn().", "Use task.spawn() for scheduler-aware task creation.")
			end
			if CleanLine:match("^%s*delay%s*%(") or CleanLine:match("[^%w_%.:]delay%s*%(") then
				Add("Warning", "api.deprecated.delay", LineNumber, CleanLine:find("delay%s*%(") or 1, 5, "delay() is deprecated in favor of task.delay().", "Use task.delay() for scheduler-aware delayed tasks.")
			end
			if CleanLine:match("^%s*while%s+true%s+do") then
				local HasYield = false
				for ScanLine = LineNumber, math.min(#CodeLines, LineNumber + 32) do
					local ScanText = CodeLines[ScanLine] or ""
					if ScanText:find("task%s*%.%s*wait%s*%(") or ScanText:find("[^%w_%.:]wait%s*%(") or ScanText:find("Heartbeat%s*:%s*Wait%s*%(") or ScanText:find("Stepped%s*:%s*Wait%s*%(") then
						HasYield = true
						break
					end
					if ScanLine > LineNumber and ScanText:match("^%s*end%s*$") then break end
				end
				if not HasYield then
					Add("Warning", "flow.tightloop", LineNumber, #(CleanLine:match("^(%s*)") or "") + 1, 5, "while true do may run without yielding and freeze the client.", "Add task.wait() or another appropriate yield inside the loop.")
				end
			end
		end
		table.sort(Diagnostics, function(Left, Right) if Left.Line ~= Right.Line then return Left.Line < Right.Line end return Left.Column < Right.Column end)
		return Diagnostics, CompilerAvailable and "Luau compiler" or "Delimiter fallback"
	end
	SV.AnalyzeCodeDiagnostics = CheckCode
	if type(Main) == "table" then Main.AnalyzeCodeDiagnostics = CheckCode end


	SV.Init = function()
		Window = Lib.Window.new()
		Window:SetTitle("Decompiler")
		local DeviceInfo = Main.GetDeviceInfo()
		local IsCompact = DeviceInfo.IsCompact or DeviceInfo.ViewportWidth < 640
		Window:Resize(560, 430)
		Window.GuiElems.Main.Position = UDim2.new(0.5, -Window.SizeX / 2, 0.5, -Window.SizeY / 2)
		SV.Window = Window

		local Content = Window.GuiElems.Content
		local Toolbar = Instance.new("Frame", Content)
		Toolbar.BackgroundTransparency = 1
		Toolbar.Size = UDim2.new(1, 0, 0, IsCompact and 72 or 24)
		Toolbar.Position = UDim2.new(0, 0, 0, 0)

		local CopyButton = MakeDecompButton(Toolbar, "Copy", 2, 40, nil, function()
			local SelectionText = CodeFrame:GetSelectionText()
			local CopyText = SelectionText ~= "" and SelectionText or CodeFrame:GetText()
			local ClipboardFunction = env.setclipboard or setclipboard or toclipboard
			if type(ClipboardFunction) == "function" then pcall(ClipboardFunction, CopyText) end
		end)
		local SaveButton = MakeDecompButton(Toolbar, "Save", 44, 40, nil, function()
			Lib.SaveAsPrompt("Place_" .. game.PlaceId .. "_Script_" .. os.time() .. ".txt", CodeFrame:GetText())
		end)
		DumpButton = MakeDecompButton(Toolbar, "Dump", 86, 50, nil, function()
			if PreviousScr ~= nil then
				local Success, ErrorMessage = pcall(SV.DumpFunctions, PreviousScr)
				if not Success then
					SetDecompStatus("Dump failed: " .. tostring(ErrorMessage), true)
				end
			end
		end)
		if type(env.getgc or getgc or get_gc_objects) ~= "function" then
			DumpButton.TextColor3 = Color3.new(0.5, 0.5, 0.5)
			DumpButton.Interactable = false
		end
		RestoreButton = MakeDecompButton(Toolbar, "Restore Raw", 138, 75, nil, function()
			if RawSource then
				CodeFrame:SetText(RawSource)
				if UpdateSearchResults then UpdateSearchResults(true) end
				SetDecompStatus("Restored original")
			else
				SetDecompStatus("Nothing to restore", true)
			end
		end)
		LocalBeautifyButton = MakeDecompButton(Toolbar, "Beautify (Local)", 215, 85, nil, BeautifyLocal)
		AIBeautifyButton = MakeDecompButton(Toolbar, "Beautify (AI)", 302, 75, nil, BeautifyWithAI)
		local RefreshScriptButton = MakeDecompButton(Toolbar, "Refresh", 379, 58, nil, function()
			local CurrentScript = PreviousScr
			if not CurrentScript then return SetDecompStatus("No current script to refresh", true) end
			SaveActiveTab()
			TabRecords[CurrentScript] = nil
			for Index = #TabOrder,1,-1 do
				if TabOrder[Index] == CurrentScript then table.remove(TabOrder,Index) break end
			end
			ActiveTabScript = nil
			SV.ViewScript(CurrentScript)
		end)
		
		if IsCompact then
			RefreshScriptButton.Visible = false
		end

		if IsCompact then
			local MobileButtons = {
				{CopyButton, 2, 0, 50},
				{SaveButton, 54, 0, 48},
				{DumpButton, 104, 0, 54},
				{RestoreButton, 2, 24, 72},
				{LocalBeautifyButton, 76, 24, 96},
				{AIBeautifyButton, 174, 24, 84}
			}
			for _, Entry in ipairs(MobileButtons) do
				Entry[1].Position = UDim2.new(0, Entry[2], 0, Entry[3])
				Entry[1].Size = UDim2.new(0, Entry[4], 0, 22)
				Entry[1].TextSize = 12
			end
		end

		local StatusFrame = Instance.new("Frame", Content)
		StatusFrame.BackgroundTransparency = 1
		StatusFrame.Position = UDim2.new(0, 0, 0, IsCompact and 72 or 24)
		StatusFrame.Size = UDim2.new(1, 0, 0, 18)
		AIStatus = Instance.new("TextLabel", StatusFrame)
		AIStatus.BackgroundTransparency = 1
		AIStatus.Position = UDim2.new(0, 5, 0, 0)
		AIStatus.Size = UDim2.new(1, -10, 1, 0)
		AIStatus.Font = Enum.Font.SourceSans
		AIStatus.TextSize = 12
		AIStatus.TextColor3 = Color3.fromRGB(150, 210, 150)
		AIStatus.TextXAlignment = Enum.TextXAlignment.Left
		AIStatus.Text = ""

		local FindBar = Instance.new("Frame", Content)
		FindBar.BackgroundColor3 = Color3.fromRGB(38, 38, 38)
		FindBar.BorderSizePixel = 0
		FindBar.Position = UDim2.new(0, 0, 0, (IsCompact and 72 or 24) + 18)
		FindBar.Size = UDim2.new(1, 0, 0, 28)

		FindBox = Instance.new("TextBox", FindBar)
		FindBox.BackgroundColor3 = Color3.fromRGB(29, 29, 29)
		FindBox.BorderSizePixel = 0
		FindBox.ClearTextOnFocus = false
		FindBox.Font = Enum.Font.Code
		FindBox.TextSize = 13
		FindBox.TextColor3 = Color3.fromRGB(240, 240, 240)
		FindBox.PlaceholderColor3 = Color3.fromRGB(125, 125, 125)
		FindBox.PlaceholderText = "Find in decompiled / beautified source  (Ctrl+F)"
		FindBox.Text = ""
		FindBox.TextXAlignment = Enum.TextXAlignment.Left
		FindBox.Position = UDim2.new(0, 5, 0, 3)
		FindBox.Size = UDim2.new(1, -176, 0, 22)
		FindBox.Parent = FindBar

		FindPreviousButton = MakeDecompButton(FindBar, "‹", 0, 30, nil, function()
			ChangeSearchMatch(-1)
		end)
		FindPreviousButton.Position = UDim2.new(1, -168, 0, 3)
		FindNextButton = MakeDecompButton(FindBar, "›", 0, 30, nil, function()
			ChangeSearchMatch(1)
		end)
		FindNextButton.Position = UDim2.new(1, -136, 0, 3)
		FindCaseButton = MakeDecompButton(FindBar, "Aa", 0, 34, nil, function()
			SearchCaseSensitive = not SearchCaseSensitive
			FindCaseButton.BackgroundColor3 = SearchCaseSensitive and Color3.fromRGB(82, 82, 82) or Color3.fromRGB(55, 55, 55)
			UpdateSearchResults(true)
		end)
		FindCaseButton.Position = UDim2.new(1, -104, 0, 3)
		FindCount = Instance.new("TextLabel", FindBar)
		FindCount.BackgroundTransparency = 1
		FindCount.Font = Enum.Font.SourceSans
		FindCount.TextSize = 12
		FindCount.TextColor3 = Color3.fromRGB(190, 190, 190)
		FindCount.Text = "0/0"
		FindCount.Position = UDim2.new(1, -68, 0, 3)
		FindCount.Size = UDim2.new(0, 38, 0, 22)

		CodeFrame = Lib.CodeFrame.new()
		local EditorTop = (IsCompact and 72 or 24) + 18 + 28
		local BottomHeight = IsCompact and 38 or 22
		TabStrip = Instance.new("ScrollingFrame")
		TabStrip.Name = "ScriptTabs"
		TabStrip.BackgroundColor3 = Color3.fromRGB(32,32,32)
		TabStrip.BorderSizePixel = 0
		TabStrip.Position = UDim2.new(0,0,0,EditorTop)
		TabStrip.Size = UDim2.new(1,0,0,24)
		TabStrip.ScrollBarThickness = 3
		TabStrip.ScrollingDirection = Enum.ScrollingDirection.X
		TabStrip.CanvasSize = UDim2.new(0,0,0,0)
		TabStrip.Parent = Content
		TabLayout = Instance.new("UIListLayout")
		TabLayout.FillDirection = Enum.FillDirection.Horizontal
		TabLayout.SortOrder = Enum.SortOrder.LayoutOrder
		TabLayout.Padding = UDim.new(0, 2)
		TabLayout.Parent = TabStrip
		TabLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
			TabStrip.CanvasSize = UDim2.new(0,TabLayout.AbsoluteContentSize.X,0,0)
		end)
		EditorTop = EditorTop + 26
		CodeFrame.Frame.Position = UDim2.new(0, 0, 0, EditorTop)
		CodeFrame.Frame.Size = UDim2.new(1, 0, 1, -EditorTop - BottomHeight)
		CodeFrame.Frame.Parent = Content

		FindBox:GetPropertyChangedSignal("Text"):Connect(function()
			UpdateSearchResults(true)
		end)
		FindBox.FocusLost:Connect(function(EnterPressed)
			if EnterPressed then
				ChangeSearchMatch(1)
			end
		end)

		local BottomBar = Instance.new("Frame", Content)
		BottomBar.BackgroundTransparency = 1
		BottomBar.Size = UDim2.new(1, 0, 0, BottomHeight)
		BottomBar.Position = UDim2.new(0, 0, 1, -BottomHeight)
		ExecuteButton = MakeDecompButton(BottomBar, "Execute", 0, 0, nil, function()
			if env.loadstring then
				local Success, Compiled = pcall(env.loadstring, CodeFrame:GetText())
				if Success and type(Compiled) == "function" then
					local RunSuccess, RunError = pcall(Compiled)
					SetDecompStatus(RunSuccess and "Execution completed" or ("Execution error: " .. tostring(RunError)), not RunSuccess)
				else
					SetDecompStatus("Compile error: " .. tostring(Compiled), true)
				end
			end
		end)
		ExecuteButton.Size = UDim2.new(0.5, -2, 1, 0)
		ExecuteButton.Position = UDim2.new(0, 0, 0, 0)
		if not env.loadstring then
			ExecuteButton.TextColor3 = Color3.new(0.5, 0.5, 0.5)
			ExecuteButton.Interactable = false
		end
		ClearButton = MakeDecompButton(BottomBar, "Clear", 0, 0, nil, function()
			CodeFrame:SetText("")
			RawSource = nil
			UpdateSearchResults(true)
			SetDecompStatus("")
		end)
		ClearButton.Size = UDim2.new(0.5, -2, 1, 0)
		ClearButton.Position = UDim2.new(0.5, 2, 0, 0)
		if IsCompact then
			ExecuteButton.TextSize = 15
			ClearButton.TextSize = 15
		end

		local InputService = service.UserInputService
		local InputConnection = InputService.InputBegan:Connect(function(Input)
			if not Window or Window.Closed or not Window.GuiElems.Main.Visible then
				return
			end
			local CtrlDown = InputService:IsKeyDown(Enum.KeyCode.LeftControl) or InputService:IsKeyDown(Enum.KeyCode.RightControl)
			if CtrlDown and Input.KeyCode == Enum.KeyCode.F then
				FindBox:CaptureFocus()
				FindBox.CursorPosition = #FindBox.Text + 1
			elseif CtrlDown and Input.KeyCode == Enum.KeyCode.G then
				ChangeSearchMatch(1)
			elseif Input.KeyCode == Enum.KeyCode.Escape and FindBox:IsFocused() then
				FindBox:ReleaseFocus()
			end
		end)
		Window.OnDeactivate:Connect(function()
			if FindBox:IsFocused() then
				FindBox:ReleaseFocus()
			end
		end)

		UpdateSearchResults(true)
	end

	SV.ViewScript = function(ScriptObject)
		if not ScriptObject then return end
		local DecompHeader = "--[[\n____   ____      .__            \n\\   \\ /   /____  |  |   _____   \n \\   Y   /\\__  \\ |  |  /     \\  \n  \\     /  / __ \\|  |_|  Y Y  \\ \n   \\___/  (____  /____/__|_|  / \n               \\/           \\/  \n--]]"
		local DecompCredit = "-- Decompiler was made by [REDACTED] and Exirl (diffrent_.)"
		local function StripHeader(Source)
			if type(Source) ~= "string" then return Source end
			local Body = Source:gsub("\r\n", "\n")
			if Body:sub(1, #DecompHeader) == DecompHeader then
				Body = Body:sub(#DecompHeader + 1)
			end
			Body = Body:gsub("^\n+", "")
			if Body:sub(1, #DecompCredit) == DecompCredit then
				local FirstLineEnd = Body:find("\n", 1, true)
				local SecondLineEnd = FirstLineEnd and Body:find("\n", FirstLineEnd + 1, true)
				local ThirdLineEnd = SecondLineEnd and Body:find("\n", SecondLineEnd + 1, true)
				if SecondLineEnd and ThirdLineEnd and Body:sub(SecondLineEnd + 1, ThirdLineEnd - 1) == "-- Danke for using Valm Dex ++" then
					Body = Body:sub(ThirdLineEnd + 1):gsub("^\n+", "")
				end
			end
			local FirstLineEnd = Body:find("\n", 1, true)
			local FirstLine = FirstLineEnd and Body:sub(1, FirstLineEnd - 1) or Body
			if FirstLine:match("^%-%- Took .-s to Decompile") then
				Body = FirstLineEnd and Body:sub(FirstLineEnd + 1) or ""
				Body = Body:gsub("^\n+", "")
			end
			return Body
		end
		local function AddSuccessHeader(Source, ElapsedTime, ScriptPath, DecompilerName)
			if type(Source) ~= "string" then return Source end
			local Body = StripHeader(Source)
			local Duration = string.format("%.2f", math.max(0, tonumber(ElapsedTime) or 0))
			local SafeScriptPath = tostring(ScriptPath or "Unknown")
			SafeScriptPath = SafeScriptPath:gsub("[\r\n]", " ")
			local TimingLine = "-- Took " .. Duration .. "s to Decompile (Script Path: " .. SafeScriptPath .. ")"
			if DecompilerName ~= "Valm Decompiler" then
				return TimingLine .. "\n\n" .. Body
			end
			return DecompHeader
				.. "\n" .. DecompCredit
				.. "\n" .. TimingLine
				.. "\n-- Danke for using Valm Dex ++\n\n"
				.. Body
		end
		local ExistingRecord = TabRecords[ScriptObject]
		if ExistingRecord and ExistingRecord.RawSource and ExistingRecord.Source and ActiveTabScript ~= ScriptObject then
			SaveActiveTab()
			ActiveTabScript = ScriptObject
			PreviousScr = ScriptObject
			RawSource = ExistingRecord.RawSource
			CodeFrame:SetText(ExistingRecord.Source)
			if UpdateSearchResults then UpdateSearchResults(true) end
			RenderTabStrip()
			Window:Show()
			return
		end
		SaveActiveTab()
		local StartTime = tick()
		env.ValmDecompilerLastSuccessfulDecompiler = nil
		pcall(SetStatus, "LastSuccessfulDecompiler", nil)
		local CallSuccess, DecompiledSource, DecompileFailure = pcall(env.decompile or function()
			return nil, "No decompiler function is available"
		end, ScriptObject)
		local function IsUsableSource(Output)
			if not CallSuccess or type(Output) ~= "string" or Output:match("^%s*$") then return false end
			local Header = string.lower(Output:sub(1, 1024))
			local FailureMarkers = {
				"unable to view source", "decompilation failed", "failed to decompile",
				"decompile error", "unable to decompile", "failed to get script bytecode",
				"bytefall:", "bytefall (", "http 400", "http 404", "http 429", "http 500",
				"no http request function", "returned an invalid response"
			}
			for _, Marker in ipairs(FailureMarkers) do
				if string.find(Header, Marker, 1, true) then return false end
			end
			return true
		end
		local DecompileElapsed = math.max(0, tick() - StartTime)
		local DecompEnv = _G
		if type(getgenv) == "function" then
			local EnvGood, Env = pcall(getgenv)
			if EnvGood and type(Env) == "table" then
				DecompEnv = Env
			end
		end
		local SharedDecomp = DecompEnv and DecompEnv.ValmDecompilerLastSuccessfulDecompiler
		local LocalDecomp = env and env.ValmDecompilerLastSuccessfulDecompiler
		local LastDecomp = type(SharedDecomp) == "string" and SharedDecomp or LocalDecomp
		local UsedDecomp = LastDecomp == "Valm Decompiler" and "Valm Decompiler" or (type(LastDecomp) == "string" and LastDecomp or "External Decompiler")
		local ScriptPathSuccess, ScriptPathValue = pcall(GetScriptPath, ScriptObject)
		local SuccessfulScriptPath = ScriptPathSuccess and ScriptPathValue or ScriptObject.Name
		local RawSourceValue = IsUsableSource(DecompiledSource) and AddSuccessHeader(DecompiledSource, DecompileElapsed, SuccessfulScriptPath, UsedDecomp) or nil
		local RawSourceBody = RawSourceValue and StripHeader(RawSourceValue) or nil
		local CanViewServerScript = ScriptObject.ClassName == "Script" and ScriptObject.RunContext == Enum.RunContext.Client and RawSourceValue ~= nil
		local DisplaySource
		if not RawSourceValue then
			PreviousScr = nil
			RawSource = nil
			if DumpButton then DumpButton.TextColor3 = Color3.new(0.5, 0.5, 0.5) end
			DisplaySource = "-- Unable to view source.\n"
			if Settings.ScriptViewer.ShowMoreInfo then
				local PathSuccess, ScriptPath = pcall(GetScriptPath, ScriptObject)
				DisplaySource ..= "-- Path: " .. tostring(PathSuccess and ScriptPath or ScriptObject) .. "\n"
				local CanDecompile = type(env.isdecompile) == "function" and env.isdecompile()
				local ViabilitySuccess, IsViable = pcall(env.isViableDecompileScript or function() return false end, ScriptObject)
				if not ViabilitySuccess or not IsViable then
					DisplaySource ..= "-- Reason: This script is not client-visible in the current context.\n"
				elseif not CanDecompile then
					DisplaySource ..= "-- Reason: No compatible decompiler is available.\n"
				else
					local FailureReason = tostring(DecompileFailure or DecompiledSource or "Unknown decompilation failure")
					FailureReason = FailureReason:gsub("\r", ""):gsub("\n", "\n-- ")
					DisplaySource ..= "-- Reason: Decompilation failed: " .. FailureReason .. "\n"
				end
				DisplaySource ..= "-- Executor: " .. exName .. " (" .. exVer .. ")"
			end
			SetDecompStatus("Unable to decompile " .. tostring(ScriptObject.Name), true)
		else
			PreviousScr = ScriptObject
			RawSource = RawSourceValue
			if DumpButton then DumpButton.TextColor3 = Color3.new(1, 1, 1) end
			if AICache[ScriptObject] then
				local CachedSource = StripHeader(AICache[ScriptObject])
				DisplaySource = CachedSource
				SetDecompStatus("Loaded cached AI result")
			else
				DisplaySource = RawSourceBody
				if Settings.ScriptViewer.AutoBeautify then
					local BeautifyInput = RawSourceBody
					local BeautifySuccess, BeautifiedSource, RenameCount = pcall(BeautifySource, BeautifyInput)
					if BeautifySuccess and type(BeautifiedSource) == "string" then
						DisplaySource = StripHeader(BeautifiedSource)
						SetDecompStatus(("Auto Beautified: %d variables"):format(RenameCount or 0))
					else
						SetDecompStatus("Auto Beautify failed: " .. tostring(BeautifiedSource), true)
					end
				end
			end
		end
		if RawSourceValue then
			DisplaySource = AddSuccessHeader(DisplaySource, DecompileElapsed, SuccessfulScriptPath, UsedDecomp)
		end
		CodeFrame:SetText(DisplaySource)
		if ScriptObject:IsA("LocalScript") or ScriptObject:IsA("ModuleScript") or ScriptObject:IsA("Script") then
			StoreTab(ScriptObject, DisplaySource, RawSourceValue, CanViewServerScript)
			local HistoryEntry = {Script = ScriptObject, Name = tostring(ScriptObject.Name), Path = tostring(GetScriptPath(ScriptObject)), Source = DisplaySource, Time = os.time()}
			table.insert(DecompiledHistory, 1, HistoryEntry)
			while #DecompiledHistory > 40 do table.remove(DecompiledHistory) end
		end
		if UpdateSearchResults then UpdateSearchResults(true) end
		Window:Show()
	end
	SV.GetCurrentSource = function()
		SaveActiveTab()
		return CodeFrame and CodeFrame:GetText() or ""
	end

	SV.SetCurrentSource = function(Source)
		if not CodeFrame or type(Source) ~= "string" then return false end
		CodeFrame:SetText(Source)
		RawSource = Source
		SaveActiveTab()
		if UpdateSearchResults then UpdateSearchResults(true) end
		return true
	end

	SV.OpenSourceText = function(Source, DocumentName)
		if not CodeFrame or type(Source) ~= "string" then return false end
		SaveActiveTab()
		ActiveTabScript = nil
		PreviousScr = nil
		RawSource = Source
		CodeFrame:SetText(Source)
		if RenderTabStrip then RenderTabStrip() end
		if UpdateSearchResults then UpdateSearchResults(true) end
		if Window then Window:Show() end
		SetDecompStatus("Opened saved source: " .. tostring(DocumentName or "Untitled"))
		return true
	end

	SV.GetOpenTabs = function()
		SaveActiveTab()
		local Result = {}
		for _, ScriptObject in ipairs(TabOrder) do
			local Record = TabRecords[ScriptObject]
			if Record then
				Result[#Result + 1] = {Script = ScriptObject, Name = Record.Name, Path = Record.Path, Source = Record.Source, Active = ScriptObject == ActiveTabScript}
			end
		end
		return Result
	end

	SV.GetDecompileHistory = function()
		return DecompiledHistory
	end

	SV.CloseCurrentTab = function()
		if not ActiveTabScript then return false end
		local ClosingScript = ActiveTabScript
		TabRecords[ClosingScript] = nil
		for Index = #TabOrder,1,-1 do
			if TabOrder[Index] == ClosingScript then table.remove(TabOrder,Index) break end
		end
		ActiveTabScript = nil
		PreviousScr = nil
		RawSource = nil
		CodeFrame:SetText("")
		RenderTabStrip()
		if UpdateSearchResults then UpdateSearchResults(true) end
		return true
	end

	SV.GetRawSource = function()
		return RawSource
	end

	SV.GetCurrentScript = function()
		return PreviousScr
	end

	SV.FocusSearch = function(Query)
		if FindBox then
			if type(Query) == "string" then
				FindBox.Text = Query
			end
			FindBox:CaptureFocus()
			FindBox.CursorPosition = #FindBox.Text + 1
		end
	end

	if type(Main) == "table" then
		Main.AIProviderNames = AIProviderNames
		Main.AIProviderProfiles = AIProviderProfiles
		Main.BuildAIProviderEndpoint = GetAIEndpoint
		Main.BuildAIProviderRequest = MakeAIRequest
		Main.ExtractAIProviderText = ReadAIReply
		Main.AIBeautifySource = RunBeautify
	end

	return SV
end

if gethsfuncs then
	_G.moduleData = { InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main }
else
	return { InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main }
end
end,

["SettingsWindow"] = function()
--[[
	Save Instance App Module
	
	Revival of the old dex's Save Instance
]] 

-- Common Locals
local Main,Lib,Apps,Settings -- Main Containers
local Explorer, Properties, ScriptViewer, SettingsWindow, Notebook -- Major Apps
local API,RMD,env,service,plr,create,createSimple -- Main Locals

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple
end

local function initAfterMain()
	Explorer = Apps.Explorer
	Properties = Apps.Properties
	ScriptViewer = Apps.ScriptViewer
	SettingsWindow = Apps.SettingsWindow
	Notebook = Apps.Notebook
end

local function main()
	local SettingsWindow = {}
	local window, ListFrame
	local fileName = "Place_"..game.PlaceId.."_"..game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name.."_{TIMESTAMP}"
	local Saving = false
	
	local function AddCheckbox(title, default)
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)
		
		local listlayout = Instance.new("UIListLayout")
		listlayout.Parent = frame.Gui
		listlayout.FillDirection = Enum.FillDirection.Horizontal
		listlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		listlayout.VerticalAlignment = Enum.VerticalAlignment.Center
		listlayout.Padding = UDim.new(0, 10)
		
		-- Checkbox
		local checkbox = Lib.Checkbox.new()
		
		checkbox.Gui.Parent = frame.Gui
		checkbox.Gui.Size = UDim2.new(0,15,0,15)
		
		-- Label
		local label = Lib.Label.new()
		
		label.Gui.Parent = frame.Gui
		label.Gui.Size = UDim2.new(1, 0,1, -15)
		label.Gui.Text = title
		label.TextTruncate = Enum.TextTruncate.AtEnd
		
		checkbox:SetState(default or false)
		
		return checkbox
	end
	
	local function AddTextbox(title, default, sizeX)
		default = default and tostring(default) or ""
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)

		local listlayout = Instance.new("UIListLayout")
		listlayout.Parent = frame.Gui
		listlayout.FillDirection = Enum.FillDirection.Horizontal
		listlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		listlayout.VerticalAlignment = Enum.VerticalAlignment.Center
		listlayout.Padding = UDim.new(0, 10)

		-- Textbox
		local textbox = Instance.new("TextBox") -- replaced cuz why Moon make every inputs only work on mouse/pc users >:( 
		textbox.BackgroundColor3 = Settings.Theme.TextBox
		textbox.BorderColor3 = Settings.Theme.Outline3
		textbox.ClearTextOnFocus = false
		textbox.TextColor3 = Settings.Theme.Text
		textbox.Font = Enum.Font.SourceSans
		textbox.TextSize = 14
		textbox.ZIndex = 2

		textbox.Parent = frame.Gui
		if sizeX and type(sizeX) == "number" then
			textbox.Size = UDim2.new(0,sizeX,0,15)
		else
			textbox.Size = UDim2.new(0,45,0,15)
		end
		
		frame.Gui.AutomaticSize = Enum.AutomaticSize.X
		textbox.AutomaticSize = Enum.AutomaticSize.X

		-- Label
		local label = Lib.Label.new()

		label.Parent = frame.Gui
		label.Size = UDim2.new(1, 0,1, -15)
		label.Text = title
		label.TextTruncate = Enum.TextTruncate.AtEnd

		textbox.Text = default

		return textbox
	end
	
	local function AddDropdown(title, options, default, allowEmpty, sizeX)
		if allowEmpty == nil then allowEmpty = true end
		
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)

		local listlayout = Instance.new("UIListLayout")
