		if type(DecompilerSettings.Fallbacks) ~= "table" then
			local MigratedFallbacks = {}
			local SeenFallbacks = {}
			local LegacyFallback = DecompilerSettings.DecompilerFallback
			if table.find(PrimaryOptions, LegacyFallback) and LegacyFallback ~= PrimaryName then
				MigratedFallbacks[#MigratedFallbacks + 1] = LegacyFallback
				SeenFallbacks[LegacyFallback] = true
			end
			for _, DecompilerName in ipairs(DefaultFallbacks) do
				if DecompilerName ~= PrimaryName and not SeenFallbacks[DecompilerName] then
					MigratedFallbacks[#MigratedFallbacks + 1] = DecompilerName
					SeenFallbacks[DecompilerName] = true
				end
			end
			DecompilerSettings.Fallbacks = MigratedFallbacks
		end
		local OrderedFallbacks = {"ByteFall"}
		local SeenFallbacks = {ByteFall = true}
		for _, FallbackName in ipairs(DecompilerSettings.Fallbacks) do
			if FallbackName ~= "Disabled" and table.find(FallbackOptions, FallbackName) and not SeenFallbacks[FallbackName] then
				OrderedFallbacks[#OrderedFallbacks + 1] = FallbackName
				SeenFallbacks[FallbackName] = true
			end
		end
		DecompilerSettings.Fallbacks = OrderedFallbacks
		for Slot = 1, #DecompNames - 1 do
			if DecompilerSettings.Fallbacks[Slot] == nil then
				DecompilerSettings.Fallbacks[Slot] = "Disabled"
			end
		end
		local function SaveDecompSettings()
			DecompilerSettings.DecompilerFallback = DecompilerSettings.Fallbacks[1]
