			if table.find(PrimaryOptions, SelectedName) then
				DecompilerSettings.PrimaryDecompiler = SelectedName
				SaveDecompSettings()
			end
		end)
		for Slot = 1, #DecompNames - 1 do
			local SlotIndex = Slot
			local SelectedName = DecompilerSettings.Fallbacks[SlotIndex]
			if not table.find(FallbackOptions, SelectedName) then
				SelectedName = "Disabled"
				DecompilerSettings.Fallbacks[SlotIndex] = SelectedName
			end
			local FallbackDropdown = AddDropdown("Fallback " .. tostring(SlotIndex), FallbackOptions, SelectedName, false, 125)
			FallbackDropdown.OnSelect:Connect(function()
				local NextName = FallbackDropdown.Selected
				if table.find(FallbackOptions, NextName) then
					DecompilerSettings.Fallbacks[SlotIndex] = NextName
					SaveDecompSettings()
				end
			end)
		end
