		local function AddProviderIcon(Dropdown, ProviderName)
			if not Dropdown or not Dropdown.Gui then return end
			local IconAssetId = ProviderIcons[ProviderName]
			local ProviderIcon = Dropdown.Gui:FindFirstChild("AIProviderIcon")
			if not ProviderIcon then
				ProviderIcon = Instance.new("ImageLabel")
				ProviderIcon.Name = "AIProviderIcon"
				ProviderIcon.BackgroundTransparency = 1
				ProviderIcon.BorderSizePixel = 0
				ProviderIcon.Position = UDim2.new(0, 3, 0.5, -6)
				ProviderIcon.Size = UDim2.new(0, 12, 0, 12)
				ProviderIcon.ScaleType = Enum.ScaleType.Fit
				ProviderIcon.Active = false
				ProviderIcon.Selectable = false
				ProviderIcon.ZIndex = Dropdown.Gui.ZIndex
				ProviderIcon.Parent = Dropdown.Gui
			end
			ProviderIcon.Image = IconAssetId and ("rbxassetid://" .. tostring(IconAssetId)) or ""
			ProviderIcon.Visible = IconAssetId ~= nil
			local SelectedLabel = Dropdown.GuiElems and Dropdown.GuiElems.Label
			if SelectedLabel then
				SelectedLabel.Position = UDim2.new(0, IconAssetId and 19 or 2, 0, 0)
				SelectedLabel.Size = UDim2.new(1, IconAssetId and -40 or -22, 1, 0)
				SelectedLabel.ZIndex = Dropdown.Gui.ZIndex
			end
		end
		local function MakeProviderDrop(Title, Options, DefaultValue, Width)
			local Dropdown = AddDropdown(Title, Options, DefaultValue, false, Width)
			Dropdown.CanBeEmpty = false
			Dropdown:SetOptions(Options)
			Dropdown:SetSelected(DefaultValue)
			Dropdown.Context.Iconless = true
			Dropdown:Update()
			AddProviderIcon(Dropdown, DefaultValue)
			return Dropdown
		end
		local function MakeProviderMenu(Dropdown, Options, SelectionCallback)
			if not Dropdown or not Dropdown.Context or type(Options) ~= "table" then return false end
			local Context = Dropdown.Context
			Context.Iconless = false
			Context:Clear()
			for _, ProviderChoice in ipairs(Options) do
				local SelectedProvider = ProviderChoice
				local ProviderAssetId = ProviderIcons[SelectedProvider]
				Context:Add({
					Name = SelectedProvider,
					Icon = ProviderAssetId and ("rbxassetid://" .. tostring(ProviderAssetId)) or "",
					OnClick = function()
						Dropdown.Selected = SelectedProvider
						Dropdown:Update()
						if type(SelectionCallback) == "function" then
							local SelectionSuccess, SelectionError = pcall(SelectionCallback, SelectedProvider)
							if not SelectionSuccess and type(warn) == "function" then
								warn("[Valm Dex] AI provider selection failed: " .. tostring(SelectionError))
							end
						end
					end
				})
			end
			Context.Updated = nil
			return true
		end
		local function GetSettingsAIUrl(ProviderName, ModelName, CurrentEndpoint)
			if type(Main.BuildAIProviderEndpoint) == "function" and Main.BuildAIProviderEndpoint ~= GetSettingsAIUrl then
				local Success, Result = pcall(Main.BuildAIProviderEndpoint, ProviderName, ModelName, CurrentEndpoint)
				if Success and type(Result) == "string" and Result ~= "" then return Result end
			end
			local Profile = GetAIProfile(ProviderName)
			local Endpoint = tostring(CurrentEndpoint or ""):gsub("^%s+", ""):gsub("%s+$", "")
			if Endpoint == "" then return tostring(Profile.Endpoint or "") end
			local Route = tostring(Profile.EndpointRoute or "")
			local Base = tostring(Profile.EndpointBase or ""):gsub("/+$", "")
			local CleanEndpoint = Endpoint:gsub("/+$", "")
			if Route ~= "" and CleanEndpoint:lower():sub(-#Route) ~= Route:lower() then
				if CleanEndpoint == Base or CleanEndpoint == Base .. "/v1" or CleanEndpoint == Base .. "/openai/v1" then return CleanEndpoint .. Route end
			end
			return Endpoint
		end
		Main.BuildAIProviderEndpoint = type(Main.BuildAIProviderEndpoint) == "function" and Main.BuildAIProviderEndpoint or GetSettingsAIUrl
		local function GetAIKey(ProviderName)
			local Provider = tostring(ProviderName or "")
			if type(Main.GetSharedAIProviderKey) == "function" and Main.GetSharedAIProviderKey ~= GetAIKey then
				local Success, Value = pcall(Main.GetSharedAIProviderKey, Provider)
				if Success and type(Value) == "string" and Value ~= "" then return Value end
			end
			local ScriptSettings = type(Settings.ScriptViewer) == "table" and Settings.ScriptViewer or {}
			local StoredKeys = type(ScriptSettings.AIKeys) == "table" and ScriptSettings.AIKeys or {}
			local Value = tostring(StoredKeys[Provider] or "")
			if Value == "" and tostring(ScriptSettings.AIKeyProvider or "Groq") == Provider then Value = tostring(ScriptSettings.AIKey or "") end
			if Value ~= "" then return Value end
			local Embedded = Main.DexHelperEmbeddedAIConfig
			if type(Embedded) == "table" and tostring(Embedded.Provider or "") == Provider then
				Value = tostring(Embedded.ApiKey or "")
				if Value ~= "" then return Value end
			end
			local KeyNames = {
				Groq = {"GROQ_API_KEY", "GroqAPIKey"},
				DeepSeek = {"DEEPSEEK_API_KEY", "DeepSeekAPIKey"},
				OpenAI = {"OPENAI_API_KEY", "OpenAIAPIKey"},
				Anthropic = {"ANTHROPIC_API_KEY", "AnthropicAPIKey"},
				["Google Gemini"] = {"GEMINI_API_KEY", "GOOGLE_API_KEY", "GeminiAPIKey"},
				xAI = {"XAI_API_KEY", "XAIAPIKey"},
				Mistral = {"MISTRAL_API_KEY", "MistralAPIKey"}
			}
			local Sources = {}
			if type(env) == "table" then Sources[#Sources + 1] = env end
			if type(shared) == "table" then Sources[#Sources + 1] = shared end
			if type(_G) == "table" then Sources[#Sources + 1] = _G end
			if type(getgenv) == "function" then
				local Success, GlobalEnvironment = pcall(getgenv)
				if Success and type(GlobalEnvironment) == "table" then Sources[#Sources + 1] = GlobalEnvironment end
			end
			for _, Source in ipairs(Sources) do
				if type(Source) == "table" then
					for _, KeyName in ipairs(KeyNames[Provider] or {}) do
						local Success, Candidate = pcall(function() return Source[KeyName] end)
						if Success and type(Candidate) == "string" and Candidate ~= "" then return Candidate end
					end
				end
			end
			return ""
		end
		local function GetBeautifierConfig()
			local PluginSettings = type(Settings.AIBeautifierPlugin) == "table" and Settings.AIBeautifierPlugin or {}
			Settings.AIBeautifierPlugin = PluginSettings
			PluginSettings.Models = type(PluginSettings.Models) == "table" and PluginSettings.Models or {}
			PluginSettings.EndpointOverrides = type(PluginSettings.EndpointOverrides) == "table" and PluginSettings.EndpointOverrides or {}
			local Provider = tostring(PluginSettings.Provider or "Groq")
			if not AIProfiles[Provider] then Provider = "Groq" end
			local Profile = GetAIProfile(Provider)
			local Models = type(Profile.Models) == "table" and Profile.Models or {Profile.DefaultModel}
			local Model = tostring(PluginSettings.Models[Provider] or PluginSettings.Model or Profile.DefaultModel or Models[1] or "")
			if not table.find(Models, Model) then Model = tostring(Profile.DefaultModel or Models[1] or "") end
			PluginSettings.Provider = Provider
			PluginSettings.Model = Model
			PluginSettings.Models[Provider] = Model
			local EndpointSeed = tostring(PluginSettings.EndpointOverrides[Provider] or "")
			if EndpointSeed == "" then EndpointSeed = tostring(Profile.Endpoint or "") end
			local Endpoint = GetSettingsAIUrl(Provider, Model, EndpointSeed)
			PluginSettings.Endpoint = Endpoint
			PluginSettings.EndpointProvider = Provider
			local RequestOptions = {}
			for OptionName, OptionValue in pairs(Profile.RequestOptions or {}) do RequestOptions[OptionName] = OptionValue end
			for OptionName, OptionValue in pairs((Profile.ModelOptions or {})[Model] or {}) do RequestOptions[OptionName] = OptionValue end
			for OptionName, OptionValue in pairs(type(PluginSettings.RequestOptions) == "table" and PluginSettings.RequestOptions or {}) do RequestOptions[OptionName] = OptionValue end
			return {
				Enabled = PluginSettings.Enabled ~= false,
				Provider = Provider,
				Protocol = Profile.Protocol or "ChatCompletions",
				ApiVersion = Profile.ApiVersion,
				Endpoint = Endpoint,
				ApiKey = GetAIKey(Provider),
				ApiKeySource = "Dex Settings",
				Model = Model,
				Temperature = tonumber(PluginSettings.Temperature) or 0.1,
				MaxTokens = tonumber(PluginSettings.MaxTokens) or 8000,
				Headers = type(PluginSettings.Headers) == "table" and PluginSettings.Headers or {},
				MaxTokenField = Profile.MaxTokenField,
				RequestOptions = RequestOptions
			}
		end
