		end)
		local autoB = AddCheckbox("Auto Beautify on Decompile", Settings.ScriptViewer.AutoBeautify)
		autoB.OnInput:Connect(function() Settings.ScriptViewer.AutoBeautify = autoB.Toggled SaveAISettings() end)
		local function StyleAIConfigRow(Control)
			local Gui
			if typeof(Control) == "Instance" then
				Gui = Control
			elseif Control ~= nil then
				local Success, Result = pcall(function()
					return Control.Gui
				end)
				if Success then
					Gui = Result
				end
			end
			local Row = Gui and Gui.Parent
			if Row and Row:IsA("GuiObject") then
				Row.BackgroundTransparency = 0
				Row.BackgroundColor3 = Settings.Theme.Button or Settings.Theme.TextBox or Color3.fromRGB(38, 38, 38)
				Row.BorderSizePixel = 1
				Row.BorderColor3 = Settings.Theme.Outline2 or Color3.fromRGB(55, 55, 55)
			end
		end
		for _, Control in ipairs({aiEn, aiProvider, aiM, aiEp, aiK, autoB}) do StyleAIConfigRow(Control) end
		local function UpdateEndpoint()
			local ProviderName = tostring(Settings.ScriptViewer.AIProvider or "Groq")
			local Profile = GetAIProfile(ProviderName)
			local ModelName = tostring(Settings.ScriptViewer.AIModels[ProviderName] or Settings.ScriptViewer.AIModel or Profile.DefaultModel or "")
			local EndpointOverrides = Settings.ScriptViewer.AIEndpointOverrides
			local EndpointOverride = tostring(EndpointOverrides[ProviderName] or "")
			local EndpointSeed = EndpointOverride ~= "" and EndpointOverride or tostring(Profile.Endpoint or "")
			local ResolvedEndpoint = GetSettingsAIUrl(ProviderName, ModelName, EndpointSeed)
			if ResolvedEndpoint == "" then ResolvedEndpoint = tostring(Profile.Endpoint or "") end
			Settings.ScriptViewer.AIEndpoint = ResolvedEndpoint
			Settings.ScriptViewer.AIEndpointProvider = ProviderName
			aiEp.Text = ResolvedEndpoint
		end
		UpdateEndpoint()
		local function ApplyAIProvider(SelectedProvider)
			local ProviderName = tostring(SelectedProvider or aiProvider.Selected or Settings.ScriptViewer.AIProvider or "Groq")
			if not AIProfiles[ProviderName] then ProviderName = tostring(Settings.ScriptViewer.AIProvider or "Groq") end
			if not AIProfiles[ProviderName] then ProviderName = "Groq" end
			local Profile = GetAIProfile(ProviderName)
			local ModelOptions = type(Profile.Models) == "table" and Profile.Models or {}
			local SavedModel = tostring(Settings.ScriptViewer.AIModels[ProviderName] or "")
			local DefaultModel = SavedModel ~= "" and SavedModel or tostring(Profile.DefaultModel or ModelOptions[1] or "")
			if DefaultModel == "" or not table.find(ModelOptions, DefaultModel) then DefaultModel = tostring(Profile.DefaultModel or ModelOptions[1] or "") end
			if DefaultModel == "" or not table.find(ModelOptions, DefaultModel) then DefaultModel = tostring(ModelOptions[1] or "") end
			Settings.ScriptViewer.AIProvider = ProviderName
			Settings.ScriptViewer.AIModel = DefaultModel
			Settings.ScriptViewer.AIModels[ProviderName] = DefaultModel
			aiProvider:SetSelected(ProviderName)
			aiProvider:Update()
			AddProviderIcon(aiProvider, ProviderName)
			aiM:SetOptions(ModelOptions)
			aiM:SetSelected(DefaultModel)
			aiM:Update()
			UpdateEndpoint()
			local ProviderKey = GetProviderKey(ProviderName)
			aiK.Text = ""
			aiK.AutomaticSize = Enum.AutomaticSize.None
			aiK.Size = UDim2.new(0, 200, 0, 17)
			aiKeyMask.Text = ProviderKey ~= "" and MaskAIKey(ProviderKey) or "Paste API key"
			aiKeyMask.TextColor3 = ProviderKey ~= "" and Settings.Theme.Text or (Settings.Theme.PlaceholderText or Color3.fromRGB(130, 130, 130))
			RefreshKeyDisplay()
			if type(Main.ResolveAIConfig) == "function" then pcall(Main.ResolveAIConfig) end
			if type(Main.ResolveAIBeautifierPluginConfig) == "function" then pcall(Main.ResolveAIBeautifierPluginConfig) end
			SaveAISettings()
		end
		MakeProviderMenu(aiProvider, AIProviderOptions, ApplyAIProvider)
		aiM.OnSelect:Connect(function(SelectedModel)
			local ProviderName = tostring(Settings.ScriptViewer.AIProvider or "Groq")
			local Profile = GetAIProfile(ProviderName)
			local ModelName = tostring(SelectedModel or aiM.Selected or Profile.DefaultModel or "")
			if not table.find(Profile.Models or {}, ModelName) then ModelName = tostring(Profile.DefaultModel or (Profile.Models or {})[1] or "") end
			Settings.ScriptViewer.AIModel = ModelName
			Settings.ScriptViewer.AIModels[ProviderName] = ModelName
			aiM:SetSelected(ModelName)
			UpdateEndpoint()
			SaveAISettings()
		end)
		aiEp.FocusLost:Connect(function()
			local ProviderName = Settings.ScriptViewer.AIProvider or "Groq"
			Settings.ScriptViewer.AIEndpoint = aiEp.Text
			Settings.ScriptViewer.AIEndpointProvider = ProviderName
			Settings.ScriptViewer.AIEndpointOverrides[ProviderName] = aiEp.Text
			SaveAISettings()
		end)
		aiK.Focused:Connect(function()
			aiK.Text = ""
			aiKeyMask.Text = ""
		end)
		aiK.FocusLost:Connect(function()
			if aiK.Text ~= "" then
				local EnteredKey = aiK.Text
				local ProviderName = Settings.ScriptViewer.AIProvider or "Groq"
				Settings.ScriptViewer.AIKeys[ProviderName] = EnteredKey
				Settings.ScriptViewer.AIKey = EnteredKey
				Settings.ScriptViewer.AIKeyProvider = ProviderName
				if type(Main.DexHelperEmbeddedAIConfig) == "table" then
					Main.DexHelperEmbeddedAIConfig.Provider = ProviderName
					Main.DexHelperEmbeddedAIConfig.ApiKey = EnteredKey
				end
			end
			local ActiveKey = tostring(Settings.ScriptViewer.AIKeys[Settings.ScriptViewer.AIProvider] or "")
			if ActiveKey == "" and tostring(Settings.ScriptViewer.AIKeyProvider or "Groq") == Settings.ScriptViewer.AIProvider then ActiveKey = tostring(Settings.ScriptViewer.AIKey or "") end
			aiK.Text = ""
			aiKeyMask.Text = ActiveKey ~= "" and MaskAIKey(ActiveKey) or "Paste API key"
			aiKeyMask.TextColor3 = ActiveKey ~= "" and Settings.Theme.Text or (Settings.Theme.PlaceholderText or Color3.fromRGB(130, 130, 130))
			SaveAISettings()
			RefreshKeyDisplay()
		end)

		AddSeperator("AI Beautifier Plugin")
		AddText("Configure the AI Beautifier provider, model and endpoint here. The selected provider key comes from Dex Settings, and every saved change is pushed into the loaded AI Beautifier plugin automatically.")
		Settings.AIBeautifierPlugin = type(Settings.AIBeautifierPlugin) == "table" and Settings.AIBeautifierPlugin or {}
		local BeautySettings = Settings.AIBeautifierPlugin
		local BeautyConfig = GetBeautifierConfig()
		BeautySettings.Provider = BeautyConfig.Provider
		BeautySettings.Model = BeautyConfig.Model
		BeautySettings.Endpoint = BeautyConfig.Endpoint
		BeautySettings.EndpointOverrides = type(BeautySettings.EndpointOverrides) == "table" and BeautySettings.EndpointOverrides or {}
		BeautySettings.Models = type(BeautySettings.Models) == "table" and BeautySettings.Models or {}
		BeautySettings.Enabled = BeautySettings.Enabled ~= false
		BeautySettings.Temperature = tonumber(BeautySettings.Temperature) or 0.1
		BeautySettings.MaxTokens = tonumber(BeautySettings.MaxTokens) or 8000
		local BeautyProfile = GetAIProfile(BeautySettings.Provider)
	local BeautyModels = BeautyProfile.Models or {BeautyProfile.DefaultModel}
	BeautySettings.Model = tostring(BeautySettings.Models[BeautySettings.Provider] or BeautySettings.Model or "")
	if not table.find(BeautyModels, BeautySettings.Model) then
		BeautySettings.Model = BeautyProfile.DefaultModel or BeautyModels[1] or ""
	end
	BeautySettings.Models[BeautySettings.Provider] = BeautySettings.Model
	if not table.find(BeautyModels, BeautySettings.Model) then
		BeautySettings.Model = BeautyModels[1] or ""
	end
	local BeautifierEnabled = AddCheckbox("Enable AI Beautifier Plugin", BeautySettings.Enabled)
	BeautifierEnabled.OnInput:Connect(function()
		BeautySettings.Enabled = BeautifierEnabled.Toggled
		SaveAISettings()
	end)
	local BeautyProviderDrop = MakeProviderDrop("Beautifier Provider", AIProviderOptions, BeautySettings.Provider, 125)
	local BeautifierModel = AddDropdown("Beautifier Model", BeautyModels, BeautySettings.Model, false, 170)
	local BeautyEndpoint = AddTextbox("Beautifier Endpoint", tostring(BeautySettings.Endpoint or BeautyProfile.Endpoint or ""), 200)
	local BeautifierKey = AddTextbox("API Key from Dex Settings", MaskAIKey(GetProviderKey(BeautySettings.Provider)), 200)
	BeautifierKey.TextEditable = false
	BeautifierKey.ClearTextOnFocus = false
	BeautifierKey.TextColor3 = Settings.Theme.TextDim or Settings.Theme.Text
	BeautifierKeyDisplay = BeautifierKey
	local BeautyTemp = AddTextbox("Beautifier Temperature", tostring(BeautySettings.Temperature), 80)
	local BeautyMaxTokens = AddTextbox("Beautifier Max Tokens", tostring(BeautySettings.MaxTokens), 80)
	local function UpdateBeautyUrl()
		local ProviderName = tostring(BeautySettings.Provider or "Groq")
		local Profile = GetAIProfile(ProviderName)
		local ModelName = tostring(BeautySettings.Models[ProviderName] or BeautySettings.Model or Profile.DefaultModel or "")
		local EndpointOverride = tostring(BeautySettings.EndpointOverrides[ProviderName] or "")
		local EndpointSeed = EndpointOverride ~= "" and EndpointOverride or tostring(Profile.Endpoint or "")
		local ResolvedEndpoint = GetSettingsAIUrl(ProviderName, ModelName, EndpointSeed)
		if ResolvedEndpoint == "" then ResolvedEndpoint = tostring(Profile.Endpoint or "") end
		BeautySettings.Endpoint = ResolvedEndpoint
		BeautySettings.EndpointProvider = ProviderName
		BeautyEndpoint.Text = ResolvedEndpoint
	end
	local function SetBeautyProvider(SelectedProvider)
		local ProviderName = tostring(SelectedProvider or BeautyProviderDrop.Selected or BeautySettings.Provider or "Groq")
		if not AIProfiles[ProviderName] then ProviderName = tostring(BeautySettings.Provider or "Groq") end
		if not AIProfiles[ProviderName] then ProviderName = "Groq" end
		local Profile = GetAIProfile(ProviderName)
		local ModelOptions = type(Profile.Models) == "table" and Profile.Models or {}
		local SavedModel = tostring(BeautySettings.Models[ProviderName] or "")
		local DefaultModel = SavedModel ~= "" and SavedModel or tostring(Profile.DefaultModel or ModelOptions[1] or "")
		if DefaultModel == "" or not table.find(ModelOptions, DefaultModel) then DefaultModel = tostring(Profile.DefaultModel or ModelOptions[1] or "") end
		if DefaultModel == "" or not table.find(ModelOptions, DefaultModel) then DefaultModel = tostring(ModelOptions[1] or "") end
		BeautySettings.Provider = ProviderName
		BeautySettings.Model = DefaultModel
		BeautySettings.Models[ProviderName] = DefaultModel
		BeautyProviderDrop:SetSelected(ProviderName)
		BeautyProviderDrop:Update()
		AddProviderIcon(BeautyProviderDrop, ProviderName)
		BeautifierModel:SetOptions(ModelOptions)
		BeautifierModel:SetSelected(DefaultModel)
		BeautifierModel:Update()
		UpdateBeautyUrl()
		RefreshKeyDisplay()
		if type(Main.ResolveAIBeautifierPluginConfig) == "function" then pcall(Main.ResolveAIBeautifierPluginConfig) end
		SaveAISettings()
	end
	MakeProviderMenu(BeautyProviderDrop, AIProviderOptions, SetBeautyProvider)
	BeautifierModel.OnSelect:Connect(function(SelectedModel)
		local ProviderName = tostring(BeautySettings.Provider or "Groq")
		local Profile = GetAIProfile(ProviderName)
		local ModelName = tostring(SelectedModel or BeautifierModel.Selected or Profile.DefaultModel or "")
		if not table.find(Profile.Models or {}, ModelName) then ModelName = tostring(Profile.DefaultModel or (Profile.Models or {})[1] or "") end
		BeautySettings.Model = ModelName
		BeautySettings.Models[ProviderName] = ModelName
		BeautifierModel:SetSelected(ModelName)
		UpdateBeautyUrl()
		SaveAISettings()
	end)
	BeautyEndpoint.FocusLost:Connect(function()
		local ProviderName = BeautySettings.Provider
		BeautySettings.Endpoint = BeautyEndpoint.Text
		BeautySettings.EndpointProvider = ProviderName
		BeautySettings.EndpointOverrides[ProviderName] = BeautyEndpoint.Text
		SaveAISettings()
	end)
	BeautyTemp.FocusLost:Connect(function()
		local Value = tonumber(BeautyTemp.Text)
		if Value and Value >= 0 and Value <= 2 then
			BeautySettings.Temperature = Value
		else
			BeautyTemp.Text = tostring(BeautySettings.Temperature)
		end
		SaveAISettings()
	end)
	BeautyMaxTokens.FocusLost:Connect(function()
		local Value = tonumber(BeautyMaxTokens.Text)
		if Value and Value >= 1 then
			BeautySettings.MaxTokens = math.floor(Value)
		else
			BeautyMaxTokens.Text = tostring(BeautySettings.MaxTokens)
		end
		SaveAISettings()
	end)
	UpdateBeautyUrl()
		RefreshKeyDisplay()
		SaveAISettings()
	for _, Control in ipairs({BeautifierEnabled, BeautyProviderDrop, BeautifierModel, BeautyEndpoint, BeautifierKey, BeautyTemp, BeautyMaxTokens}) do
		StyleAIConfigRow(Control)
		end

		local ReloadBgButton = Lib.Frame.new()
		ReloadBgButton.Gui.Parent = window.GuiElems.Content
		ReloadBgButton.Size = UDim2.new(1,0, 0,20)
		ReloadBgButton.Position = UDim2.new(0,0, 1,-20)
		
		local LabelreloadButton = Lib.Label.new()
		LabelreloadButton.Gui.Parent = window.GuiElems.Content
		LabelreloadButton.Size = UDim2.new(1,0, 0,20)
		LabelreloadButton.Position = UDim2.new(0,0, 1,-20)
		LabelreloadButton.Gui.Text = "Restart"
		LabelreloadButton.Gui.TextXAlignment = Enum.TextXAlignment.Center
		
		local reloadButton = Instance.new("TextButton")
		reloadButton.Parent = ReloadBgButton.Gui
		reloadButton.Size = UDim2.new(1,0, 1,0)
		reloadButton.Position = UDim2.new(0,0, 0,0)
		reloadButton.Transparency = 1
		
		reloadButton.MouseButton1Click:Connect(function()
			window:SetTitle("Settings - Saving")
			
			Main.SaveCurrentSettings()
			
			window:SetTitle("Settings - Saved")
			SettingsWindow.ReloadPrompt()
			task.wait(3)
			
			window:SetTitle("Settings")
		end)
	end

	return SettingsWindow
end

