	Main.GetDeviceInfo = function()
		local UserInput = service.UserInputService
		local Camera = workspace.CurrentCamera
		local Viewport = Camera and Camera.ViewportSize or Vector2.new(1280, 720)
		local TouchEnabled = UserInput.TouchEnabled == true
		local KeyboardEnabled = UserInput.KeyboardEnabled == true
		local MouseEnabled = UserInput.MouseEnabled == true
		local GamepadEnabled = UserInput.GamepadEnabled == true
		local Platform = "Unknown"
		local InsetTopLeft = Vector2.new(0, 0)
		local InsetBottomRight = Vector2.new(0, 0)

		pcall(function()
			Platform = tostring(UserInput:GetPlatform())
		end)

		pcall(function()
			InsetTopLeft, InsetBottomRight = service.GuiService:GetGuiInset()
		end)

		local Device = "Desktop"
		if TouchEnabled and KeyboardEnabled then
			Device = "Tablet / Hybrid"
		elseif TouchEnabled then
			Device = "Mobile"
		elseif GamepadEnabled and not MouseEnabled then
			Device = "Console"
		end

		return {
			Device = Device,
			IsMobile = TouchEnabled and not KeyboardEnabled,
			IsTouch = TouchEnabled,
			IsCompact = TouchEnabled or Viewport.X < 700 or (Settings.Interface and Settings.Interface.ForceMobileLayout == true),
			TouchEnabled = TouchEnabled,
			KeyboardEnabled = KeyboardEnabled,
			MouseEnabled = MouseEnabled,
			GamepadEnabled = GamepadEnabled,
			Platform = Platform,
			Viewport = Viewport,
			ViewportWidth = Viewport.X,
			ViewportHeight = Viewport.Y,
			InsetTopLeft = InsetTopLeft,
			InsetBottomRight = InsetBottomRight
		}
	end
