	Main.GetRandomString = function()
		local output = ""
		for i = 2, 25 do
			output = output .. string.char(math.random(1,250))
		end
		
		return output
	end
	
	Main.GetSecureContainer = function()
		return
			syn and syn.protect_gui or
			gethui and gethui() or
			service.CoreGui or
			service.Players.LocalPlayer:WaitForChild("PlayerGui")
	end
	
	Main.SecureGui = function(gui)
		--warn("Secured: "..gui.Name)
		gui.Name = "_DPP_".. Main.GetRandomString()
		-- service already using cloneref
		if gethui then
			gui.Parent = gethui()
		elseif syn and syn.protect_gui then
			syn.protect_gui(gui)
			gui.Parent = service.CoreGui
		elseif protect_gui then
			protect_gui(gui)
			gui.Parent = service.CoreGui
		elseif protectgui then
			protectgui(gui)
			gui.Parent = service.CoreGui
		else
			if Main.Elevated then
				gui.Parent = service.CoreGui
			else
				gui.Parent = service.Players.LocalPlayer:WaitForChild("PlayerGui")
			end
		end
	end

	Main.PluginFunctions = Main.PluginFunctions or {}
	Main.PluginAPI = Main.PluginAPI or {}

	local function RunPluginCallback(Callback, ...)
		if type(Callback) ~= "function" then return end
		local Success, Result = pcall(Callback, ...)
		if not Success then warn("[Valm Plugin] " .. tostring(Result)) end
		return Success, Result
	end

	function Main.PluginAPI:Notify(Message, Duration)
		local Runtime = Notices
		if type(Runtime) == "table" and type(Runtime.Queue) == "function" then
			pcall(Runtime.Queue, "Valm Plugin", tostring(Message), tonumber(Duration) or 3)
		else
			print("[Valm Plugin] " .. tostring(Message))
		end
	end

	function Main.PluginAPI:GetService(ServiceName)
		if type(ServiceName) ~= "string" or ServiceName == "" then return nil, "Service name is required" end
		local Success, Result = pcall(function() return game:GetService(ServiceName) end)
		if Success then return Result end
		return nil, tostring(Result)
	end

	function Main.PluginAPI:GetLocalPlayer()
		return plr or (service and service.Players and service.Players.LocalPlayer) or game:GetService("Players").LocalPlayer
	end

	function Main.PluginAPI:GetTheme()
		local ThemeCopy = {}
		for Key, Value in pairs(Settings and Settings.Theme or {}) do ThemeCopy[Key] = Value end
		return ThemeCopy
	end

	function Main.PluginAPI:GetVersion()
		return tostring(Main.Version or "Unknown")
	end

	function Main.PluginAPI:Copy(TextValue)
		local ClipboardFunction
		pcall(function() ClipboardFunction = env and (env.setclipboard or env.toclipboard) end)
		ClipboardFunction = ClipboardFunction or setclipboard or toclipboard
		if type(ClipboardFunction) ~= "function" then return false, "Clipboard API is unavailable" end
		local Success, ErrorMessage = pcall(ClipboardFunction, tostring(TextValue or ""))
		if not Success then return false, tostring(ErrorMessage) end
		return true
	end

	function Main.PluginAPI:RegisterFunction(PluginName, FunctionName, Callback)
		if type(Callback) ~= "function" then error("Callback must be a function", 2) end
		local Owner = tostring(PluginName or "Plugin")
		local Name = tostring(FunctionName or "Function")
		local Key = Owner .. ":" .. Name
		Main.PluginFunctions[Key] = Callback
		return function(...)
			return RunPluginCallback(Main.PluginFunctions[Key], ...)
		end
	end

	function Main.PluginAPI:CallFunction(PluginName, FunctionName, ...)
		local Key = tostring(PluginName or "Plugin") .. ":" .. tostring(FunctionName or "Function")
		local Callback = Main.PluginFunctions[Key]
		if not Callback then return false, "Function was not registered" end
		return RunPluginCallback(Callback, ...)
	end

	function Main.PluginAPI:CreateTab(Name, Icon)
		if not Lib or not Lib.Window then error("Valm Dex UI is not ready", 2) end
		local Window = Lib.Window.new()
		Window:SetTitle(tostring(Name or "Community Plugin"))
		Window:Resize(380, 350)
		Window.ValmPluginPanel = true
		Window.PluginIcon = Icon

		local Content = Window.GuiElems.Content
		local Scroll = Instance.new("ScrollingFrame")
		Scroll.Name = "PluginContent"
		Scroll.BackgroundTransparency = 1
		Scroll.BorderSizePixel = 0
		Scroll.Size = UDim2.new(1, 0, 1, 0)
		Scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		Scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		Scroll.ScrollBarThickness = 8
		Scroll.Parent = Content

		local Layout = Instance.new("UIListLayout")
		Layout.Padding = UDim.new(0, 6)
		Layout.SortOrder = Enum.SortOrder.LayoutOrder
		Layout.Parent = Scroll

		local Padding = Instance.new("UIPadding")
		Padding.PaddingTop = UDim.new(0, 7)
		Padding.PaddingBottom = UDim.new(0, 7)
		Padding.PaddingLeft = UDim.new(0, 7)
		Padding.PaddingRight = UDim.new(0, 7)
		Padding.Parent = Scroll

		local Tab = {Window = Window, Name = tostring(Name or "Community Plugin"), Icon = Icon, Scroll = Scroll}
		function Tab:SetTitle(NewTitle)
			self.Name = tostring(NewTitle or "Community Plugin")
			if self.Window then self.Window:SetTitle(self.Name) end
		end
		function Tab:Close()
			if self.Window and not self.Window.Closed then self.Window:Close() end
		end
		function Tab:Destroy()
			self:Close()
		end
		Main.PluginAPI.LastCreatedWindow = Window
		Main.PluginAPI.LastCreatedTab = Tab
		local RowOrder = 0
		local Theme = Settings and Settings.Theme or {}
		local MainColor = Theme.Main1 or Color3.fromRGB(43, 43, 43)
		local PanelColor = Theme.Main2 or Color3.fromRGB(34, 34, 34)
		local TextColor = Theme.Text or Color3.fromRGB(242, 242, 242)
		local MutedColor = Theme.PlaceholderText or Color3.fromRGB(145, 145, 145)
		local ButtonColor = Theme.Button or Color3.fromRGB(52, 52, 52)
		local HighlightColor = Theme.Highlight or Color3.fromRGB(94, 94, 94)
		local UserInput = service and service.UserInputService

		local function NewFrame(Parent, Height, NameValue)
			RowOrder += 1
			local Frame = Instance.new("Frame")
			Frame.Name = NameValue or "PluginRow"
			Frame.BackgroundColor3 = PanelColor
			Frame.BorderSizePixel = 0
			Frame.Size = UDim2.new(1, -2, 0, Height)
			Frame.LayoutOrder = RowOrder
			Frame.Parent = Parent
			return Frame
		end

		local function NewText(Parent, TextValue, Position, Size, TextSize, Color)
			local Label = Instance.new("TextLabel")
			Label.BackgroundTransparency = 1
			Label.Position = Position
			Label.Size = Size
			Label.Font = Enum.Font.SourceSans
			Label.Text = tostring(TextValue or "")
			Label.TextSize = TextSize or 13
			Label.TextColor3 = Color or TextColor
			Label.TextXAlignment = Enum.TextXAlignment.Left
			Label.TextYAlignment = Enum.TextYAlignment.Center
			Label.TextWrapped = true
			Label.Parent = Parent
			return Label
		end

		local function NewButton(Parent, TextValue, Height, Callback)
			local Button = Instance.new("TextButton")
			Button.AutoButtonColor = true
			Button.BackgroundColor3 = ButtonColor
			Button.BorderSizePixel = 0
			Button.Size = UDim2.new(1, -2, 0, Height or 27)
			Button.Font = Enum.Font.SourceSans
			Button.Text = tostring(TextValue or "Button")
			Button.TextSize = 13
			Button.TextColor3 = TextColor
			Button.Parent = Parent
			Button.Activated:Connect(function() RunPluginCallback(Callback) end)
			return Button
		end

		function Tab:AddSection(SectionName, Subtitle)
			local SectionFrame = Instance.new("Frame")
			SectionFrame.Name = tostring(SectionName or "Section")
			SectionFrame.BackgroundColor3 = MainColor
			SectionFrame.BorderSizePixel = 0
			SectionFrame.Size = UDim2.new(1, -2, 0, 0)
			SectionFrame.AutomaticSize = Enum.AutomaticSize.Y
			SectionFrame.LayoutOrder = #Scroll:GetChildren() + 1
			SectionFrame.Parent = Scroll

			local SectionLayout = Instance.new("UIListLayout")
			SectionLayout.Padding = UDim.new(0, 4)
			SectionLayout.SortOrder = Enum.SortOrder.LayoutOrder
			SectionLayout.Parent = SectionFrame

			local SectionPadding = Instance.new("UIPadding")
			SectionPadding.PaddingTop = UDim.new(0, 6)
			SectionPadding.PaddingBottom = UDim.new(0, 6)
			SectionPadding.PaddingLeft = UDim.new(0, 6)
			SectionPadding.PaddingRight = UDim.new(0, 6)
			SectionPadding.Parent = SectionFrame

			local Header = NewText(SectionFrame, SectionName or "Section", UDim2.new(), UDim2.new(1, 0, 0, 20), 15, TextColor)
			Header.Font = Enum.Font.SourceSansBold
			if Subtitle and tostring(Subtitle) ~= "" then
				NewText(SectionFrame, Subtitle, UDim2.new(), UDim2.new(1, 0, 0, 16), 11, MutedColor)
			end

			local Items = Instance.new("Frame")
			Items.Name = "Items"
			Items.BackgroundTransparency = 1
			Items.Size = UDim2.new(1, 0, 0, 0)
			Items.AutomaticSize = Enum.AutomaticSize.Y
			Items.Parent = SectionFrame
			local ItemsLayout = Instance.new("UIListLayout")
			ItemsLayout.Padding = UDim.new(0, 4)
			ItemsLayout.SortOrder = Enum.SortOrder.LayoutOrder
			ItemsLayout.Parent = Items

			local Section = {Frame = SectionFrame, Items = Items}

			function Section:AddHeader(TextValue)
				local Frame = NewFrame(Items, 24, "Header")
				local Header = NewText(Frame, TextValue, UDim2.new(0, 7, 0, 0), UDim2.new(1, -14, 1, 0), 14, TextColor)
				Header.Font = Enum.Font.SourceSansBold
				return Header
			end

			function Section:AddDivider()
				local Divider = NewFrame(Items, 1, "Divider")
				Divider.BackgroundColor3 = HighlightColor
				return Divider
			end

			function Section:AddSpacer(Height)
				local SpacerHeight = math.clamp(math.floor(tonumber(Height) or 8), 1, 100)
				local Spacer = NewFrame(Items, SpacerHeight, "Spacer")
				Spacer.BackgroundTransparency = 1
				return Spacer
			end

			function Section:AddProgressBar(Name, DefaultValue, Callback)
				local Value = math.clamp(tonumber(DefaultValue) or 0, 0, 100)
				local Frame = NewFrame(Items, 39, "ProgressBar")
				local Label = NewText(Frame, tostring(Name or "Progress") .. ": " .. tostring(math.floor(Value + 0.5)) .. "%", UDim2.new(0, 7, 0, 1), UDim2.new(1, -14, 0, 16), 12, TextColor)
				local Bar = Instance.new("Frame")
				Bar.BackgroundColor3 = ButtonColor
				Bar.BorderSizePixel = 0
				Bar.Position = UDim2.new(0, 7, 0, 22)
				Bar.Size = UDim2.new(1, -14, 0, 9)
				Bar.Parent = Frame
				local Fill = Instance.new("Frame")
				Fill.BackgroundColor3 = HighlightColor
				Fill.BorderSizePixel = 0
				Fill.Size = UDim2.new(Value / 100, 0, 1, 0)
				Fill.Parent = Bar
				local Progress = {}
				function Progress:SetValue(NextValue)
					Value = math.clamp(tonumber(NextValue) or 0, 0, 100)
					Fill.Size = UDim2.new(Value / 100, 0, 1, 0)
					Label.Text = tostring(Name or "Progress") .. ": " .. tostring(math.floor(Value + 0.5)) .. "%"
					RunPluginCallback(Callback, Value)
				end
				function Progress:GetValue() return Value end
				Progress.Instance = Frame
				return Progress
			end

			function Section:AddLabel(TextValue, AllowEdit)
				local Frame = NewFrame(Items, 24, "Label")
				local Label
				if AllowEdit then
					Label = Instance.new("TextBox")
					Label.ClearTextOnFocus = false
					Label.BackgroundTransparency = 1
					Label.TextEditable = true
				else
					Label = Instance.new("TextLabel")
					Label.BackgroundTransparency = 1
				end
				Label.Position = UDim2.new(0, 7, 0, 0)
				Label.Size = UDim2.new(1, -14, 1, 0)
				Label.Font = Enum.Font.SourceSans
				Label.TextSize = 13
				Label.TextColor3 = TextColor
				Label.TextXAlignment = Enum.TextXAlignment.Left
				Label.Text = tostring(TextValue or "")
				Label.Parent = Frame
				return {SetValue = function(_, Value) Label.Text = tostring(Value or "") end, GetValue = function() return Label.Text end, Instance = Label}
			end

			function Section:AddParagraph(Title, Description)
				local Frame = NewFrame(Items, 53, "Paragraph")
				local TitleLabel = NewText(Frame, Title, UDim2.new(0, 7, 0, 3), UDim2.new(1, -14, 0, 18), 13, TextColor)
				TitleLabel.Font = Enum.Font.SourceSansBold
				local DescriptionLabel = NewText(Frame, Description, UDim2.new(0, 7, 0, 21), UDim2.new(1, -14, 0, 29), 11, MutedColor)
				DescriptionLabel.TextYAlignment = Enum.TextYAlignment.Top
				return {
					SetValue = function(_, Value) DescriptionLabel.Text = tostring(Value or "") end,
					SetTitle = function(_, Value) TitleLabel.Text = tostring(Value or "") end,
					SetDescription = function(_, Value) DescriptionLabel.Text = tostring(Value or "") end,
					Instance = Frame
				}
			end

			function Section:AddButton(Name, Callback)
				return NewButton(Items, Name, 27, Callback)
			end

			function Section:AddFunction(Name, Callback)
				local Action = function(...)
					return RunPluginCallback(Callback, ...)
				end
				local Button = NewButton(Items, Name, 27, Action)
				return Action, Button
			end

			function Section:AddToggle(Name, Callback)
				local State = false
				local Button
				Button = NewButton(Items, tostring(Name) .. "  [OFF]", 27, function()
					State = not State
					Button.Text = tostring(Name) .. (State and "  [ON]" or "  [OFF]")
					RunPluginCallback(Callback, State)
				end)
				return function(Value)
					State = Value == true
					Button.Text = tostring(Name) .. (State and "  [ON]" or "  [OFF]")
					RunPluginCallback(Callback, State)
				end
			end

			function Section:AddSlider(Name, Minimum, Maximum, Default, Callback)
				local MinValue = tonumber(Minimum) or 0
				local MaxValue = tonumber(Maximum) or 100
				if MaxValue < MinValue then MinValue, MaxValue = MaxValue, MinValue end
				local Value = math.clamp(tonumber(Default) or MinValue, MinValue, MaxValue)
				local Frame = NewFrame(Items, 43, "Slider")
				local Label = NewText(Frame, tostring(Name) .. ": " .. tostring(Value), UDim2.new(0, 7, 0, 1), UDim2.new(1, -14, 0, 17), 12, TextColor)
				local Bar = Instance.new("TextButton")
				Bar.Text = ""
				Bar.AutoButtonColor = false
				Bar.BorderSizePixel = 0
				Bar.BackgroundColor3 = ButtonColor
				Bar.Position = UDim2.new(0, 7, 0, 25)
				Bar.Size = UDim2.new(1, -14, 0, 9)
				Bar.Parent = Frame
				local Fill = Instance.new("Frame")
				Fill.BorderSizePixel = 0
				Fill.BackgroundColor3 = HighlightColor
				Fill.Size = UDim2.new(MaxValue == MinValue and 1 or (Value - MinValue) / (MaxValue - MinValue), 0, 1, 0)
				Fill.Parent = Bar
				local Dragging = false
				local function SetValue(NextValue, Fire)
					Value = math.clamp(tonumber(NextValue) or MinValue, MinValue, MaxValue)
					local Alpha = MaxValue == MinValue and 1 or (Value - MinValue) / (MaxValue - MinValue)
					Fill.Size = UDim2.new(Alpha, 0, 1, 0)
					Label.Text = tostring(Name) .. ": " .. string.format("%.2f", Value)
					if Fire then RunPluginCallback(Callback, Value) end
				end
				local function SetFromInput(Input)
					local Alpha = math.clamp((Input.Position.X - Bar.AbsolutePosition.X) / math.max(Bar.AbsoluteSize.X, 1), 0, 1)
					SetValue(MinValue + (MaxValue - MinValue) * Alpha, true)
				end
				Bar.InputBegan:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
						Dragging = true
						SetFromInput(Input)
					end
				end)
				if UserInput then
					UserInput.InputChanged:Connect(function(Input)
						if Dragging and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then SetFromInput(Input) end
					end)
					UserInput.InputEnded:Connect(function(Input)
						if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then Dragging = false end
					end)
				end
				SetValue(Value, false)
				return {SetValue = function(_, NextValue) SetValue(NextValue, true) end, GetValue = function() return Value end}
			end

			function Section:AddColorpicker(Name, DefaultColor, Callback)
				local CurrentColor = Color3.new(1, 1, 1)
				local Frame = NewFrame(Items, 27, "Colorpicker")
				NewText(Frame, Name, UDim2.new(0, 7, 0, 0), UDim2.new(0.45, -7, 1, 0), 12, TextColor)
				local Input = Instance.new("TextBox")
				Input.ClearTextOnFocus = false
				Input.BackgroundColor3 = ButtonColor
				Input.BorderSizePixel = 0
				Input.Position = UDim2.new(0.45, 0, 0, 3)
				Input.Size = UDim2.new(0.55, -6, 1, -6)
				Input.Font = Enum.Font.Code
				Input.TextSize = 12
				Input.TextColor3 = TextColor
				Input.Text = "#FFFFFF"
				Input.Parent = Frame
				local function SetRGBValue(Color, Fire)
					if typeof(Color) ~= "Color3" then return end
					CurrentColor = Color
					Input.Text = string.format("#%02X%02X%02X", math.floor(Color.R * 255 + 0.5), math.floor(Color.G * 255 + 0.5), math.floor(Color.B * 255 + 0.5))
					if Fire then RunPluginCallback(Callback, Color) end
				end
				local function SetHexValue(Hex, Fire)
					local Clean = tostring(Hex):gsub("#", "")
					if #Clean ~= 6 or not Clean:match("^%x%x%x%x%x%x$") then return end
					Input.Text = "#" .. Clean:upper()
					local Color = Color3.fromRGB(tonumber(Clean:sub(1, 2), 16), tonumber(Clean:sub(3, 4), 16), tonumber(Clean:sub(5, 6), 16))
					CurrentColor = Color
					if Fire then RunPluginCallback(Callback, Color) end
				end
				Input.FocusLost:Connect(function() SetHexValue(Input.Text, true) end)
				local ColorApi = {
					SetHexValue = function(_, Hex) SetHexValue(Hex, true) end,
					SetRGBValue = function(_, Color) SetRGBValue(Color, true) end,
					GetValue = function() return CurrentColor end,
					Instance = Frame
				}
				if typeof(DefaultColor) == "Color3" then SetRGBValue(DefaultColor, false) else SetHexValue(DefaultColor or "FFFFFF", false) end
				return ColorApi
			end

			function Section:AddDropdown(Name, DefaultList, Callback)
				local Options = type(DefaultList) == "table" and DefaultList or {}
				local Selected = Options[1]
				local Frame = NewFrame(Items, 27, "Dropdown")
				local Button = NewButton(Frame, tostring(Name) .. ": " .. tostring(Selected or "Select"), 25, nil)
				Button.Position = UDim2.new(0, 1, 0, 1)
				Button.Size = UDim2.new(1, -2, 0, 25)
				local function Select(Value)
					if not table.find(Options, Value) then return end
					Selected = Value
					Button.Text = tostring(Name) .. ": " .. tostring(Selected)
					RunPluginCallback(Callback, Selected)
				end
				local Dropdown = {Select = Select, ChangeItems = function(_, NewItems) Options = type(NewItems) == "table" and NewItems or {} Selected = Options[1] Button.Text = tostring(Name) .. ": " .. tostring(Selected or "Select") end, GetValue = function() return Selected end}
				Button.Activated:Connect(function()
					if #Options == 0 then return end
					local Index = table.find(Options, Selected) or 0
					Select(Options[Index % #Options + 1])
				end)
				return Dropdown
			end

			function Section:AddPlayerDropdown(Name, Callback)
				local Players = game:GetService("Players")
				local Options = Players:GetPlayers()
				local Index = 0
				local Frame = NewFrame(Items, 27, "PlayerDropdown")
				local Button = NewButton(Frame, tostring(Name) .. ": Select player", 25, nil)
				Button.Position = UDim2.new(0, 1, 0, 1)
				Button.Size = UDim2.new(1, -2, 0, 25)
				Button.Activated:Connect(function()
					Options = Players:GetPlayers()
					if #Options == 0 then Button.Text = tostring(Name) .. ": no players" return end
					Index = Index % #Options + 1
					local Player = Options[Index]
					Button.Text = tostring(Name) .. ": " .. Player.Name
					RunPluginCallback(Callback, Player)
				end)
				return Button
			end

			function Section:AddTextArea(Name, DefaultText, Callback)
				local Frame = NewFrame(Items, 112, "TextArea")
				NewText(Frame, Name, UDim2.new(0, 7, 0, 1), UDim2.new(1, -14, 0, 17), 12, TextColor)
				local Input = Instance.new("TextBox")
				Input.ClearTextOnFocus = false
				Input.BackgroundColor3 = ButtonColor
				Input.BorderSizePixel = 0
				Input.Position = UDim2.new(0, 4, 0, 21)
				Input.Size = UDim2.new(1, -8, 1, -25)
				Input.Font = Enum.Font.Code
				Input.TextSize = 12
				Input.TextColor3 = TextColor
				Input.TextXAlignment = Enum.TextXAlignment.Left
				Input.TextYAlignment = Enum.TextYAlignment.Top
				Input.TextWrapped = true
				Input.MultiLine = true
				Input.Text = tostring(DefaultText or "")
				Input.Parent = Frame
				Input.FocusLost:Connect(function(EnterPressed) RunPluginCallback(Callback, Input.Text, EnterPressed) end)
				return {
					SetValue = function(_, Value) Input.Text = tostring(Value or "") end,
					GetValue = function() return Input.Text end,
					Focus = function() Input:CaptureFocus() end,
					Instance = Input
				}
			end

			function Section:AddImage(ImageId, Height)
				local ImageHeight = math.clamp(math.floor(tonumber(Height) or 100), 32, 256)
				local Frame = NewFrame(Items, ImageHeight + 8, "Image")
				local Image = Instance.new("ImageLabel")
				Image.BackgroundTransparency = 1
				Image.BorderSizePixel = 0
				Image.Size = UDim2.new(1, -8, 1, -8)
				Image.Position = UDim2.fromOffset(4, 4)
				Image.ScaleType = Enum.ScaleType.Fit
				local ImageValue = tostring(ImageId or "")
				if ImageValue:match("^%d+$") then ImageValue = "rbxassetid://" .. ImageValue end
				Image.Image = ImageValue
				Image.Parent = Frame
				return {SetImage = function(_, NewImage) local Value = tostring(NewImage or "") if Value:match("^%d+$") then Value = "rbxassetid://" .. Value end Image.Image = Value end, Instance = Image, Frame = Frame}
			end

			function Section:AddTextBox(Name, Callback)
				local Frame = NewFrame(Items, 27, "TextBox")
				local Input = Instance.new("TextBox")
				Input.ClearTextOnFocus = false
				Input.BackgroundColor3 = ButtonColor
				Input.BorderSizePixel = 0
				Input.Position = UDim2.new(0, 4, 0, 2)
				Input.Size = UDim2.new(1, -8, 1, -4)
				Input.Font = Enum.Font.SourceSans
				Input.TextSize = 13
				Input.TextColor3 = TextColor
				Input.PlaceholderText = tostring(Name or "Text")
				Input.Text = ""
				Input.Parent = Frame
				Input.FocusLost:Connect(function(EnterPressed) RunPluginCallback(Callback, Input.Text, EnterPressed) end)
				return Input
			end

			function Section:AddKeybind(Name, DefaultKey, Callback)
				local Key = tostring(DefaultKey or "None")
				local Listening = false
				local Button
				Button = NewButton(Items, tostring(Name) .. ": " .. Key, 27, function() Listening = true Button.Text = tostring(Name) .. ": press a key" end)
				if UserInput then
					UserInput.InputBegan:Connect(function(Input, Processed)
						if Processed then return end
						if Listening and Input.UserInputType == Enum.UserInputType.Keyboard then
							Key = Input.KeyCode.Name
							Listening = false
							Button.Text = tostring(Name) .. ": " .. Key
						elseif not Listening and Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Key then
							RunPluginCallback(Callback)
						end
					end)
				end
				return Button
			end

			return Section
		end

		return Tab
	end

	Main.CreatePluginManager = function()
