		local function ShowPage(Name)
			AddPage.Visible = Name == "Add"
			ManagePage.Visible = Name == "Manage"
			EditPage.Visible = Name == "Edit"
			TutorialPage.Visible = Name == "Tutorial"
		end


		local function GetFileFunction(Name)
			local Candidate
			pcall(function() Candidate = env and env[Name] end)
			if type(Candidate) == "function" then return Candidate end
			pcall(function() Candidate = _G[Name] end)
			if type(Candidate) == "function" then return Candidate end
			if Name == "listfiles" then pcall(function() Candidate = listfiles end) end
			if Name == "isfile" then pcall(function() Candidate = isfile end) end
			if Name == "delfile" then pcall(function() Candidate = delfile end) end
			if type(Candidate) == "function" then return Candidate end
			return nil
		end

		local function ReadFile(Path)
			local Reader = GetFileFunction("readfile")
			if not Reader then return nil, "readfile is unavailable" end
			local Success, Result = pcall(Reader, Path)
			if Success and type(Result) == "string" then return Result end
			return nil, tostring(Result or "Could not read file")
		end

		local function WriteFile(Path, Data)
			local Writer = GetFileFunction("writefile")
			if not Writer then return false, "writefile is unavailable" end
			local Success, Result = pcall(Writer, Path, Data)
			if not Success or Result == false then return false, tostring(Result or "Could not write file") end
			return true
		end

		local function DeleteFile(Path)
			local Deleter = GetFileFunction("delfile") or GetFileFunction("removefile")
			if not Deleter then return false, "delfile is unavailable" end
			local Success, Result = pcall(Deleter, Path)
			if not Success or Result == false then return false, tostring(Result or "Could not delete file") end
			return true
		end

		local function MakeFolder(Path)
			local Maker = GetFileFunction("makefolder")
			if not Maker then return false end
			return pcall(Maker, Path)
		end

		local function IsFile(Path)
			local Checker = GetFileFunction("isfile")
			if Checker then
				local Success, Result = pcall(Checker, Path)
				if Success then return Result == true end
			end
			local NormalizedPath = tostring(Path):gsub("\\", "/")
			local Folder = NormalizedPath:match("^(.*)/[^/]+$") or "dex/plugins"
			local Leaf = NormalizedPath:match("([^/]+)$")
			local Lister = GetFileFunction("listfiles")
			if Lister then
				local Success, Files = pcall(Lister, Folder)
				if Success and type(Files) == "table" then
					for _, ExistingPath in ipairs(Files) do
						local CleanPath = tostring(ExistingPath):gsub("\\", "/")
						if CleanPath == NormalizedPath or CleanPath:match("([^/]+)$") == Leaf then return true end
					end
				end
			end
			return false
		end

		local function GetPluginBase(Path)
			local Normalized = tostring(Path or ""):gsub("\\", "/")
			local Leaf = Normalized:match("([^/]+)$") or "CommunityPlugin.lua"
			return Leaf:gsub("%.[lL][uU][aA][uU]?$", "")
		end

		local function GetPluginSourcePath(Path)
			return "dex/plugin_sources/" .. GetPluginBase(Path) .. ".lua"
		end

		local function GetPluginFiles()
			local Lister = GetFileFunction("listfiles")
			if not Lister then return nil, "listfiles is unavailable" end
			local Success, Files = pcall(Lister, "dex/plugins")
			if not Success or type(Files) ~= "table" then return nil, tostring(Files or "Could not list plugins") end
			local PluginFiles = {}
			for _, Path in ipairs(Files) do
				local LowerPath = tostring(Path):lower()
				if LowerPath:match("%.lua$") or LowerPath:match("%.luau$") then
					PluginFiles[#PluginFiles + 1] = tostring(Path)
				end
			end
			table.sort(PluginFiles, function(A, B) return A:lower() < B:lower() end)
			return PluginFiles
		end

