		local function UpdatePluginList()
			local Height = PluginListLayout.AbsoluteContentSize.Y + 8
			PluginList.CanvasSize = UDim2.new(0, 0, 0, Height)
			PluginList.CanvasPosition = Vector2.new(0, math.min(PluginList.CanvasPosition.Y, math.max(Height - PluginList.AbsoluteSize.Y, 0)))
