		PluginList.ChildRemoved:Connect(function() task.defer(UpdatePluginList) end)

		local function CleanGitUrl(Value)
			local Url = tostring(Value or ""):gsub("^%s+", ""):gsub("%s+$", "")
			Url = Url:gsub("^<", ""):gsub(">$", "")
			Url = Url:gsub("[%)%],;]+$", "")
			Url = Url:gsub("[?#].*$", "")
			local Owner, Repository, Branch, Path = Url:match("^https://github%.com/([^/]+)/([^/]+)/blob/([^/]+)/(.+)$")
			if Owner then
				if not Path:match("%.[lL][uU][aA][uU]?$") then return nil end
				return "https://raw.githubusercontent.com/" .. Owner .. "/" .. Repository .. "/" .. Branch .. "/" .. Path
			end
			local RawOwner, RawRepository, RawBranch, RawPath = Url:match("^https://raw%.githubusercontent%.com/([^/]+)/([^/]+)/([^/]+)/(.+)$")
			if RawOwner and RawPath:match("%.[lL][uU][aA][uU]?$") then return Url end
			return nil
		end

		local function AddReqFn(RequestFunctions, Value)
			if type(Value) ~= "function" then return end
			for _, Existing in ipairs(RequestFunctions) do if Existing == Value then return end end
			RequestFunctions[#RequestFunctions + 1] = Value
		end

		local function FetchPluginSource(Url)
			local Errors = {}
			local function TryHttpGet(GameObject)
				if not GameObject then return nil end
				local Success, Result = pcall(function() return GameObject:HttpGet(Url) end)
				if Success and type(Result) == "string" and Result ~= "" then return Result end
				Errors[#Errors + 1] = tostring(Result or "HttpGet returned no source")
				return nil
			end
			local PluginSource = TryHttpGet(oldgame) or TryHttpGet(game)
			if PluginSource then return PluginSource end
			local RequestFunctions = {}
			pcall(function() AddReqFn(RequestFunctions, env and env.request) end)
			pcall(function() AddReqFn(RequestFunctions, env and env.http_request) end)
			pcall(function() AddReqFn(RequestFunctions, request) end)
			pcall(function() AddReqFn(RequestFunctions, http_request) end)
			pcall(function() AddReqFn(RequestFunctions, syn and syn.request) end)
			pcall(function() AddReqFn(RequestFunctions, http and http.request) end)
			for _, RequestFunction in ipairs(RequestFunctions) do
				local Success, Response = pcall(RequestFunction, {Url = Url, Method = "GET"})
				if Success then
					if type(Response) == "string" and Response ~= "" then return Response end
					if type(Response) == "table" then
						local Body = Response.Body or Response.body
						local StatusCode = tonumber(Response.StatusCode or Response.Status or Response.status_code)
						if type(Body) == "string" and Body ~= "" and (not StatusCode or StatusCode >= 200 and StatusCode < 300) then return Body end
						Errors[#Errors + 1] = "HTTP request returned status " .. tostring(StatusCode or "unknown")
					end
				else
					Errors[#Errors + 1] = tostring(Response)
				end
			end
			return nil, table.concat(Errors, " | ")
		end

		local function GetPluginName(Url)
			local Name = tostring(Url):match("/([^/]+)$") or "CommunityPlugin"
			Name = Name:gsub("%.[lL][uU][aA][uU]?%s*$", "")
			Name = Name:gsub("[^%w_%-]", "")
			if Name == "" then Name = "CommunityPlugin" end
			return Name
		end

		local function WrapPluginSource(PluginSource, PluginName)
			local SafeName = tostring(PluginName):gsub("[^%w_%-]", "_")
			local FriendlyName = tostring(PluginName):gsub("_", " ")
			local WrapperLines = {
				"local __ValmPluginModule = (function()",
				PluginSource,
				"end)()",
				"if type(__ValmPluginModule) ~= \"table\" then error(\"Plugin must return a table\") end",
				"local __ValmPluginData = type(__ValmPluginModule.PluginData) == \"table\" and __ValmPluginModule.PluginData or {}",
				"__ValmPluginData.Name = __ValmPluginData.Name or __ValmPluginModule.Name or " .. QuoteLua(SafeName),
				"__ValmPluginData.FriendlyName = __ValmPluginData.FriendlyName or __ValmPluginModule.FriendlyName or __ValmPluginModule.Name or " .. QuoteLua(FriendlyName),
				"__ValmPluginData.Author = __ValmPluginData.Author or __ValmPluginModule.Author",
				"__ValmPluginData.Version = __ValmPluginData.Version or __ValmPluginModule.Version",
				"__ValmPluginData.Description = __ValmPluginData.Description or __ValmPluginModule.Description",
				"__ValmPluginData.Icon = __ValmPluginData.Icon or __ValmPluginModule.Icon or __ValmPluginModule.Texture or __ValmPluginModule.TextureId",
				"__ValmPluginModule.PluginData = __ValmPluginData",
				"if type(__ValmPluginModule.InitDeps) ~= \"function\" or type(__ValmPluginModule.Main) ~= \"function\" then",
				"if type(__ValmPluginModule.Init) ~= \"function\" then error(\"Plugin must expose Init(Api) or both InitDeps and Main\") end",
				"local __ValmOriginalInit = __ValmPluginModule.Init",
				"local __ValmDependencies",
				"__ValmPluginModule.InitDeps = function(Dependencies) __ValmDependencies = Dependencies end",
				"__ValmPluginModule.Main = function()",
				"local __ValmApp = {PluginData = __ValmPluginData}",
				"function __ValmApp.Init()",
				"local __ValmAPI = __ValmDependencies and __ValmDependencies.PluginAPI",
				"if type(__ValmAPI) ~= \"table\" then error(\"Valm Plugin API is unavailable\") end",
				"local __ValmPreviousWindow = __ValmAPI.LastCreatedWindow",
				"local __ValmResult = __ValmOriginalInit(__ValmAPI)",
				"if type(__ValmResult) == \"table\" then __ValmApp.Window = __ValmResult.Window end",
				"if not __ValmApp.Window and __ValmAPI.LastCreatedWindow ~= __ValmPreviousWindow then __ValmApp.Window = __ValmAPI.LastCreatedWindow end",
				"local __ValmTab = __ValmAPI.LastCreatedTab",
				"if not __ValmPluginData.Icon and type(__ValmTab) == \"table\" and __ValmTab.Window == __ValmApp.Window then __ValmPluginData.Icon = __ValmTab.Icon end",
				"return __ValmResult",
				"end",
				"return __ValmApp",
				"end",
				"end",
				"return __ValmPluginModule"
			}
			return table.concat(WrapperLines, "\n")
		end

		local function CompilePlugin(PluginSource, WrappedSource)
			local Compiler = env and env.loadstring or loadstring
			if type(Compiler) ~= "function" then return false, "loadstring is unavailable" end
			local Success, Result, CompileError = pcall(Compiler, PluginSource)
			if not Success then return false, tostring(Result) end
			if not Result then return false, tostring(CompileError or "Plugin source has a syntax error") end
			local HasInitEntry = PluginSource:find("Init%s*=") ~= nil or PluginSource:find("function%s+[%w_%.:]+Init%s*%(") ~= nil
			local HasModuleEntry = PluginSource:find("InitDeps", 1, true) ~= nil and PluginSource:find("Main", 1, true) ~= nil
			if not HasInitEntry and not HasModuleEntry then return false, "Plugin must expose Init(Api) or both InitDeps and Main" end
			local WrapperSuccess, WrapperChunk, WrapperError = pcall(Compiler, WrappedSource)
			if not WrapperSuccess then return false, "Plugin adapter failed: " .. tostring(WrapperChunk) end
			if not WrapperChunk then return false, "Plugin adapter failed: " .. tostring(WrapperError or "invalid wrapper") end
			return true
		end

		local function SavePlugin(PluginSource, WrappedSource, SuggestedName)
			MakeFolder("dex")
			MakeFolder("dex/plugins")
			MakeFolder("dex/plugin_sources")
			local FileBase = tostring(SuggestedName or "CommunityPlugin"):gsub("[^%w_%-]", "_")
			if FileBase == "" then FileBase = "CommunityPlugin" end
			local FilePath = "dex/plugins/" .. FileBase .. ".lua"
			local Suffix = 1
			while IsFile(FilePath) do
				Suffix += 1
				FilePath = "dex/plugins/" .. FileBase .. "_" .. tostring(Suffix) .. ".lua"
			end
			local SourcePath = "dex/plugin_sources/" .. GetPluginBase(FilePath) .. ".lua"
			local SourceSuccess, SourceError = WriteFile(SourcePath, PluginSource)
			if not SourceSuccess then return false, "Could not save editable source: " .. tostring(SourceError) end
			local PluginSuccess, PluginError = WriteFile(FilePath, WrappedSource)
			if not PluginSuccess then DeleteFile(SourcePath) return false, "Could not install plugin: " .. tostring(PluginError) end
			return true, FilePath, SourcePath
		end

		local function FinishPluginChange(Message, PluginName)
			StatusLabel.Text = Message
			RefreshPluginList()
			if SettingsWindow and type(SettingsWindow.ReloadPrompt) == "function" then
				SettingsWindow.ReloadPrompt("Plugin Files Updated", tostring(PluginName) .. " was updated. Restart Dex now to apply the change?", "Restart Now", "Later")
			end
		end

		local function OpenEditor(PluginPath)
			local SourcePath = GetPluginSourcePath(PluginPath)
			local SourceText = ReadFile(SourcePath)
			EditingRawSource = type(SourceText) == "string"
			if not EditingRawSource then
				SourcePath = PluginPath
				SourceText = ReadFile(PluginPath)
			end
			if type(SourceText) ~= "string" then
				StatusLabel.Text = "Could not read plugin source."
				ShowPage("Manage")
				return
			end
			EditingPath = PluginPath
			EditingSourcePath = SourcePath
			EditTitle.Text = "Edit: " .. GetPluginBase(PluginPath) .. (EditingRawSource and " (source)" or " (packaged)")
			SourceEditor.Text = SourceText
			ShowPage("Edit")
		end

		local function CreatePluginRow(PluginPath, Order)
			local Row = Instance.new("Frame")
			Row.Name = "PluginRow"
			Row.BackgroundColor3 = PanelColor
			Row.BorderSizePixel = 0
			Row.Size = UDim2.new(1, -6, 0, 38)
			Row.LayoutOrder = Order
			Row.Parent = PluginList
			local NameLabel = MakeLabel(Row, GetPluginBase(PluginPath), UDim2.fromOffset(8, 0), UDim2.new(1, -150, 1, 0), 12, TextColor, true)
			NameLabel.TextTruncate = Enum.TextTruncate.AtEnd
			MakeButton(Row, "Edit", UDim2.new(1, -132, 0, 5), UDim2.fromOffset(58, 28), function() OpenEditor(PluginPath) end)
			local DeleteButton = MakeButton(Row, "Delete", UDim2.new(1, -68, 0, 5), UDim2.fromOffset(60, 28), function()
				PendingDeletePath = PluginPath
				ConfirmLabel.Text = "Delete " .. GetPluginBase(PluginPath) .. "?"
				ConfirmFrame.Visible = true
			end)
			DeleteButton.BackgroundColor3 = Color3.fromRGB(120, 48, 48)
			PluginRows[#PluginRows + 1] = Row
		end

		RefreshPluginList = function()
			for _, Row in ipairs(PluginRows) do if Row and Row.Parent then Row:Destroy() end end
			PluginRows = {}
			EmptyPluginLabel.Visible = false
			local PluginFiles, ListError = GetPluginFiles()
			if not PluginFiles then
				EmptyPluginLabel.Visible = true
				EmptyPluginLabel.Text = "Unable to list plugins: " .. tostring(ListError)
				PluginCountLabel.Text = ""
				task.defer(UpdatePluginList)
				return
			end
			PluginCountLabel.Text = tostring(#PluginFiles) .. (#PluginFiles == 1 and " plugin installed" or " plugins installed")
			if #PluginFiles == 0 then
				EmptyPluginLabel.Visible = true
				EmptyPluginLabel.Text = "No community plugins installed."
			else
				for Index, PluginPath in ipairs(PluginFiles) do CreatePluginRow(PluginPath, Index) end
			end
			task.defer(UpdatePluginList)
		end

		local function RemovePlugin(PluginPath)
			local PluginSuccess, PluginError = DeleteFile(PluginPath)
			if not PluginSuccess then return false, PluginError end
			local SourcePath = GetPluginSourcePath(PluginPath)
			DeleteFile(SourcePath)
			return true
		end

		ConfirmDeleteButton.Activated:Connect(function()
			local PluginPath = PendingDeletePath
			if not PluginPath then ConfirmFrame.Visible = false return end
			local Success, DeleteError = RemovePlugin(PluginPath)
			ConfirmFrame.Visible = false
			PendingDeletePath = nil
			if not Success then
				StatusLabel.Text = "Delete failed: " .. tostring(DeleteError)
				return
			end
			RefreshPluginList()
			FinishPluginChange("Deleted " .. GetPluginBase(PluginPath) .. ".", GetPluginBase(PluginPath))
		end)

		SaveSourceButton.Activated:Connect(function()
			if not EditingPath then return end
			local NewSource = SourceEditor.Text
			if NewSource:gsub("%s+", "") == "" then
				StatusLabel.Text = "Plugin source cannot be empty."
				return
			end
			if #NewSource > 1024 * 1024 then
				StatusLabel.Text = "Plugin source exceeds the 1 MB limit."
				return
			end
			local Compiler = env and env.loadstring or loadstring
			if type(Compiler) ~= "function" then StatusLabel.Text = "loadstring is unavailable." return end
			local CompiledSuccess, CompiledResult, CompiledError = pcall(Compiler, NewSource)
			if not CompiledSuccess or not CompiledResult then
				StatusLabel.Text = "Save blocked: " .. tostring(CompiledError or CompiledResult or "syntax error")
				return
			end
			local PluginSource = NewSource
			local PackagedSource = NewSource
			if EditingRawSource then
				PluginSource = NewSource
				PackagedSource = WrapPluginSource(PluginSource, GetPluginBase(EditingPath))
				local Valid, ValidationError = CompilePlugin(PluginSource, PackagedSource)
				if not Valid then StatusLabel.Text = "Save blocked: " .. tostring(ValidationError) return end
			end
			if EditingRawSource then
				local SourceSuccess, SourceError = WriteFile(EditingSourcePath, PluginSource)
				if not SourceSuccess then StatusLabel.Text = "Save failed: " .. tostring(SourceError) return end
			end
			local SaveSuccess, SaveError = WriteFile(EditingPath, PackagedSource)
			if not SaveSuccess then StatusLabel.Text = "Save failed: " .. tostring(SaveError) return end
			ShowPage("Manage")
			FinishPluginChange("Saved changes to " .. GetPluginBase(EditingPath) .. ".", GetPluginBase(EditingPath))
		end)

		CancelEditButton.Activated:Connect(function() ShowPage("Manage") end)
		MakeButton(AddPage, "Add Plugin", UDim2.new(0, 8, 0, 80), UDim2.new(0.333, -12, 0, 30), function()
			local Url = CleanGitUrl(PluginUrlBox.Text)
			if not Url then StatusLabel.Text = "Paste a valid GitHub raw URL or /blob/ URL ending in .lua or .luau." return end
			local PluginName = GetPluginName(Url)
			StatusLabel.Text = "Downloading " .. PluginName .. "..."
			task.spawn(function()
				local PluginSource, FetchError = FetchPluginSource(Url)
				if type(PluginSource) ~= "string" or #PluginSource == 0 then StatusLabel.Text = "Download failed: " .. tostring(FetchError or "No source returned") return end
				if #PluginSource > 1024 * 1024 then StatusLabel.Text = "Plugin source exceeds the 1 MB limit." return end
				local WrappedSource = WrapPluginSource(PluginSource, PluginName)
				local Compiled, CompileError = CompilePlugin(PluginSource, WrappedSource)
				if not Compiled then StatusLabel.Text = "Plugin validation failed: " .. tostring(CompileError) return end
				local SaveSuccess, FilePath, SourcePath = SavePlugin(PluginSource, WrappedSource, PluginName)
				if not SaveSuccess then StatusLabel.Text = "Plugin install failed: " .. tostring(FilePath) return end
				PluginUrlBox.Text = ""
				RefreshPluginList()
				ShowPage("Manage")
				FinishPluginChange("Installed " .. PluginName .. " · " .. FilePath, PluginName)
			end)
		end)
		MakeButton(AddPage, "Manage", UDim2.new(0.333, 2, 0, 80), UDim2.new(0.333, -12, 0, 30), function()
			RefreshPluginList()
			ShowPage("Manage")
		end)
		MakeButton(AddPage, "Tutorial", UDim2.new(0.666, -4, 0, 80), UDim2.new(0.333, -12, 0, 30), function()
			ShowPage("Tutorial")
		end)
		MakeButton(ManagePage, "Refresh", UDim2.new(1, -94, 0, 34), UDim2.fromOffset(84, 18), function() RefreshPluginList() end).TextSize = 11
		ShowPage("Add")
		RefreshPluginList()

		if Main.RegisterPluginWindow then Main.RegisterPluginWindow(Window) end
		Main.CreateApp({Name = "Plugins", Icon = "rbxassetid://77864449231390", Window = Window})
		Main.PluginManager = {Window = Window, UrlBox = PluginUrlBox, Status = StatusLabel, Refresh = RefreshPluginList, ManagePage = ManagePage, TutorialPage = TutorialPage, TutorialText = TutorialText, Editor = SourceEditor}
		return Main.PluginManager
	end

	Main.GetInitDeps = function(PluginPath)
		local PluginIdentity = tostring(PluginPath or ""):lower():gsub("%W", "")
		local IsBeautyPlugin = PluginIdentity:find("aibeautifier", 1, true) or PluginIdentity:find("aibeautify", 1, true)
		return {
			Main = Main,
			Lib = Lib,
			Apps = Apps,
			Settings = Settings,
			AIProviderNames = Main.AIProviderNames,
			AIProviderProfiles = Main.AIProviderProfiles,
			BuildAIProviderEndpoint = Main.BuildAIProviderEndpoint,
			AIBeautifierPluginSettings = Settings.AIBeautifierPlugin,
			ResolveAIBeautifierPluginConfig = function()
				if type(Main.ResolveAIBeautifierPluginConfig) == "function" then return Main.ResolveAIBeautifierPluginConfig() end
				return nil
			end,
			GetPluginAIConfig = function(PluginName)
				if type(Main.GetPluginAIConfig) == "function" then return Main.GetPluginAIConfig(PluginName) end
				return nil
			end,
			GetSharedAIProviderKey = function(ProviderName)
				if type(Main.GetSharedAIProviderKey) == "function" then return Main.GetSharedAIProviderKey(ProviderName) end
				return ""
			end,
			RunBeautify = Main.AIBeautifySource,
			PluginAIConfig = IsBeautyPlugin and type(Main.ResolveAIBeautifierPluginConfig) == "function" and Main.ResolveAIBeautifierPluginConfig() or nil,

			API = API,
			RMD = RMD,
			env = env,
			service = service,
			plr = plr,
			create = create,
			createSimple = createSimple,
			PluginAPI = Main.PluginAPI
		}
	end

	Main.Error = function(str)
		if rconsoleprint then
			rconsoleprint("DEX ERROR: "..tostring(str).."\n")
			wait(9e9)
		else
			error(str)
		end
	end

	Main.LoadModule = function(name)
		if Main.Elevated then -- If you don't have filesystem api then ur outta luck tbh
			local control

			if EmbeddedModules then -- Offline Modules
				control = EmbeddedModules[name]()

				-- TODO: Remove when open source
				if gethsfuncs then
					control = _G.moduleData
				end

				if not control then Main.Error("Missing Embedded Module: "..name) end
			else
				-- Get hash data
				local hashs = Main.ModuleHashData
				if not hashs then
					local s,hashDataStr = pcall(oldgame.HttpGet, game, "https://api.github.com/repos/"..Main.GitRepoName.."/ModuleHashs.dat")
					if not s then Main.Error("Failed to get module hashs") end

					local s,hashData = pcall(service.HttpService.JSONDecode,service.HttpService,hashDataStr)
					if not s then Main.Error("Failed to decode module hash JSON") end

					hashs = hashData
					Main.ModuleHashData = hashs
				end

				-- Check if local copy exists with matching hashs
				local hashfunc = (syn and syn.crypt.hash) or function() return "" end
				local filePath = "dex/ModuleCache/"..name..".lua"
				local s,moduleStr = pcall(env.readfile,filePath)

				if s and hashfunc(moduleStr) == hashs[name] then
					control = loadstring(moduleStr)()
				else
					-- Download and cache
					local s,moduleStr = pcall(oldgame.HttpGet, game, "https://api.github.com/repos/"..Main.GitRepoName.."/Modules/"..name..".lua")
					if not s then Main.Error("Failed to get external module data of "..name) end

					env.writefile(filePath,moduleStr)
					control = loadstring(moduleStr)()
				end
			end

			Main.AppControls[name] = control
			control.InitDeps(Main.GetInitDeps(name))

			local moduleData = control.Main()
			Apps[name] = moduleData
			return moduleData
		else
			local Modules = script:FindFirstChild("Modules")
			local Module = Modules and Modules:FindFirstChild(name)
			local Control

			if Module then
				Control = require(Module)
			elseif EmbeddedModules and EmbeddedModules[name] then
				Control = EmbeddedModules[name]()
			else
				Main.Error("CANNOT FIND MODULE "..name)
			end

			Main.AppControls[name] = Control
			Control.InitDeps(Main.GetInitDeps())

			local ModuleData = Control.Main()
			Apps[name] = ModuleData
			return ModuleData
		end
	end
	
	Main.LoadPluginFile = function(pluginDir)
		if env.readfile then
			if isfile(pluginDir) then
				local preloadedPlugin = loadfile and loadfile(pluginDir) or loadstring(env.readfile(pluginDir))
				local loadedPlugin = preloadedPlugin()
				
				local control = loadedPlugin
				control.InitDeps(Main.GetInitDeps(pluginDir))

				local moduleData = control.Main()
				Apps[pluginDir] = moduleData
				Main.AppControls[pluginDir] = control
				
				moduleData.PluginData = control.PluginData
				
				return moduleData
			else
				Main.Error("CANNOT FIND FILE MODULE "..pluginDir)
			end
		end
	end

	Main.LoadModules = function()
		for i,v in pairs(Main.ModuleList) do
			local s,e = pcall(Main.LoadModule,v)
			if not s then
				Main.Error("FAILED LOADING " .. v .. " CAUSE " .. e)
			end
		end

		-- Init Major Apps and define them in modules
		Explorer = Apps.Explorer
		Properties = Apps.Properties
		
		ScriptViewer = Apps.ScriptViewer
		Console = Apps.Console
		SaveInstance = Apps.SaveInstance
		ModelViewer = Apps.ModelViewer
		Notebook = Apps.Notebook
		SettingsWindow = Apps.SettingsWindow
		DeveloperTools = Apps.DeveloperTools
		
		
		--SecretServicePanel = Apps.SecretServicePanel
		local appTable = {
			Explorer = Explorer,
			Properties = Properties,
			ScriptViewer = ScriptViewer,
			Console = Console,
			SaveInstance = SaveInstance,
			ModelViewer = ModelViewer,
			Notebook = Notebook,
			SettingsWindow = SettingsWindow,
			DeveloperTools = DeveloperTools
			--SecretServicePanel = SecretServicePanel,
		}
		
		

		Main.AppControls.Lib.InitAfterMain(appTable)
		for i,v in pairs(Main.ModuleList) do
			local control = Main.AppControls[v]
			if control then
				control.InitAfterMain(appTable)
			end
		end
	end

	Main.InitEnv = function()
		setmetatable(env,{__newindex = function(self,name,func)
			if not func then Main.MissingEnv[#Main.MissingEnv+1] = name return end
			rawset(self,name,func)
		end})

		env.isonmobile = Main.GetDeviceInfo().IsMobile
		env.deviceinfo = Main.GetDeviceInfo()
		
		env.loadstring = (pcall(loadstring,"local a = 1") and loadstring) or (game:GetService("RunService"):IsStudio() and script.Modules:FindFirstChild("Loadstring") and require(script.Modules:FindFirstChild("Loadstring")))

		-- file
		env.isfile = isfile
		env.isfolder = isfolder
		env.readfile = readfile
		env.writefile = writefile
		env.appendfile = appendfile
		env.makefolder = makefolder
		env.listfiles = listfiles
		env.loadfile = loadfile
					env.saveinstance = (function()
				if game:GetService("RunService"):IsStudio() then
					return function()
						error("This execution environment is not supported.")
					end
				end

				local Params = {
					RepoURL = "https://raw.githubusercontent.com/luau/SynSaveInstance/main/",
					SSI = "saveinstance",
				}

				local Loader = env.loadstring or loadstring

				if type(Loader) ~= "function" then
					return function()
						error("SaveInstance requires loadstring support.")
					end
				end

				local DownloadSuccess, Source = pcall(function()
					return oldgame:HttpGet(
						Params.RepoURL .. Params.SSI .. ".luau",
						true
					)
				end)

				if not DownloadSuccess or type(Source) ~= "string" or Source == "" then
					return function()
						error("Failed to download SynSaveInstance: " .. tostring(Source))
					end
				end

				local CompileSuccess, Compiled = pcall(
					Loader,
					Source,
					Params.SSI
				)

				if not CompileSuccess or type(Compiled) ~= "function" then
					return function()
						error("Failed to compile SynSaveInstance: " .. tostring(Compiled))
					end
				end

				local ExecuteSuccess, SynSaveInstance = pcall(Compiled)

				if not ExecuteSuccess or type(SynSaveInstance) ~= "function" then
					return function()
						error("Failed to initialize SynSaveInstance: " .. tostring(SynSaveInstance))
					end
				end

				local function WrappedSaveInstance(Object, FilePath, Options)
					Options = type(Options) == "table" and Options or {}

					Options.FilePath = FilePath
					Options.Object = Object

					return SynSaveInstance(Options)
				end

				if type(getgenv) == "function" then
					pcall(function()
						getgenv().saveinstance = WrappedSaveInstance
					end)
				end

				return WrappedSaveInstance
			end)()
		
		env.parsefile = function(name)
			return tostring(name):gsub("[*\\?:<>|]+", ""):sub(1, 175)
		end

		-- debug
		env.getupvalues = debug.getupvalues or getupvalues or getupvals
		env.getconstants = debug.getconstants or getconstants or getconsts
		env.islclosure = islclosure or is_l_closure
