			return type(env.nativeDecompile) == "function"
				or (type(env.getscriptbytecode) == "function" and type(env.request) == "function")
		end
		
		env.isdecompilefallback = function()
			return type(env.nativeDecompile) ~= "function"
				and type(env.getscriptbytecode) == "function"
				and type(env.request) == "function"
		end

		-- another decompiler fix for bytecode 12
		local ByteFallEndpoint = "https://decompiler.bytefall.dev/decompile"
		local function IsDecompSrc(Output)
			if type(Output) ~= "string" or Output:match("^%s*$") then return false end
			local Header = string.lower(Output:sub(1, 1024))
			local InvalidMarkers = {
				"unable to view source",
				"decompilation failed",
				"failed to decompile",
				"decompile error",
				"unable to decompile",
				"failed to get script bytecode",
				"getscriptbytecode is not supported",
				"bytefall:",
				"bytefall (",
				"bytefall request failed",
				"lunaux error",
				"lunaux api request failed",
				"http 400",
				"http 404",
				"http 429",
				"http 500",
				"request failed:",
				"no http request function",
				"returned empty",
				"returned an invalid response",
				"<!doctype html",
				"<html"
			}
			for _, Marker in ipairs(InvalidMarkers) do
				if string.find(Header, Marker, 1, true) then return false end
			end
			return true
		end
		local function ByteFallDecompile(ScriptObject)
			if type(env.getscriptbytecode) ~= "function" then
				return nil, "getscriptbytecode is unavailable"
			end
			local BytecodeSuccess, Bytecode = pcall(env.getscriptbytecode, ScriptObject)
			if not BytecodeSuccess then return nil, "Could not read script bytecode: " .. tostring(Bytecode) end
			if type(Bytecode) ~= "string" or Bytecode == "" then return nil, "getscriptbytecode returned empty bytecode" end
			local Base64Encoder = base64_encode or (crypt and crypt.base64encode) or (crypt and crypt.base64 and crypt.base64.encode)
			if type(Base64Encoder) ~= "function" then
				Base64Encoder = function(Data)
					local Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
					return ((Data:gsub(".", function(Character)
						local Bits = ""
						local Byte = Character:byte()
						for BitIndex = 8, 1, -1 do
							Bits ..= (Byte % 2 ^ BitIndex - Byte % 2 ^ (BitIndex - 1) > 0) and "1" or "0"
						end
						return Bits
					end) .. "0000"):gsub("%d%d%d?%d?%d?%d?", function(Bits)
						if #Bits < 6 then return "" end
						local Value = 0
						for BitIndex = 1, 6 do
							Value += (Bits:sub(BitIndex, BitIndex) == "1" and 2 ^ (6 - BitIndex) or 0)
						end
						return Alphabet:sub(Value + 1, Value + 1)
					end) .. ({"", "==", "="})[#Data % 3 + 1])
				end
			end
			local EncodeSuccess, EncodedBytecode = pcall(Base64Encoder, Bytecode)
			if not EncodeSuccess or type(EncodedBytecode) ~= "string" or EncodedBytecode == "" then
				return nil, "Could not encode bytecode: " .. tostring(EncodedBytecode)
			end
			local RequestFunction = env.request or (syn and syn.request) or (http and http.request) or http_request or request
			if type(RequestFunction) ~= "function" then return nil, "No HTTP request function is available" end
			local HttpService = game:GetService("HttpService")
			local JsonSuccess, RequestBody = pcall(function()
				return HttpService:JSONEncode({script = EncodedBytecode})
			end)
			if not JsonSuccess then return nil, "Could not encode the ByteFall request: " .. tostring(RequestBody) end
			local RequestSuccess, HttpResult = pcall(RequestFunction, {
				Url = ByteFallEndpoint,
				Method = "POST",
				Headers = { ["Content-Type"] = "application/json" },
				Body = RequestBody
			})
			if not RequestSuccess then return nil, "ByteFall request failed: " .. tostring(HttpResult) end
			if type(HttpResult) ~= "table" then return nil, "ByteFall returned an invalid response" end
			local StatusCode = tonumber(HttpResult.StatusCode or HttpResult.Status) or 0
			local ResponseBody = tostring(HttpResult.Body or "")
			if StatusCode ~= 200 then
				return nil, string.format("ByteFall HTTP %d: %s", StatusCode, ResponseBody:sub(1, 400))
			end
			if ResponseBody:sub(1, 1) == "{" then
				local DecodeSuccess, DecodedResponse = pcall(HttpService.JSONDecode, HttpService, ResponseBody)
				if DecodeSuccess and type(DecodedResponse) == "table" then
					local ReturnedSource = DecodedResponse.source or DecodedResponse.Source or DecodedResponse.output or DecodedResponse.Output or DecodedResponse.code or DecodedResponse.Code
					if type(ReturnedSource) == "string" then ResponseBody = ReturnedSource end
				end
			end
			if not IsDecompSrc(ResponseBody) then
				return nil, "ByteFall returned an empty or invalid decompilation result"
			end
			return ResponseBody
		end
		local RemoteCache = {}
		local OldNativeDecomp = env.nativeDecompile
		local function GetRemoteDecomp(Result)
			if type(Result) == "function" then
				return Result
			end
			if type(Result) == "table" then
				for _, Key in ipairs({"decompile", "Decompile", "DecompileScript", "decompileScript", "Decompiler"}) do
					if type(Result[Key]) == "function" then
						return Result[Key]
					end
				end
			end
			local SharedEnvironment = _G
			if type(getgenv) == "function" then
				local EnvTest, EnvironmentResult = pcall(getgenv)
				if EnvTest and type(EnvironmentResult) == "table" then
					SharedEnvironment = EnvironmentResult
				end
			end
			for _, Key in ipairs({"decompile", "Decompile", "DecompileScript", "decompileScript"}) do
				local Candidate = SharedEnvironment and SharedEnvironment[Key]
				if type(Candidate) == "function" and Candidate ~= OldNativeDecomp then
					return Candidate
				end
			end
			return nil
		end
		local function LoadRemoteDecomp(Name, Url)
			if RemoteCache[Name] then
				return RemoteCache[Name]
			end
			local HttpSuccess, ScriptSource = pcall(function()
				return game:HttpGet(Url)
			end)
			if not HttpSuccess or type(ScriptSource) ~= "string" or ScriptSource == "" then
				return nil, Name .. " download failed: " .. tostring(ScriptSource)
			end
			local Compiler = loadstring or (env and env.loadstring)
			if type(Compiler) ~= "function" then
				return nil, Name .. " cannot run because loadstring is unavailable"
			end
			local CompileSuccess, CompiledChunk = pcall(Compiler, ScriptSource)
			if not CompileSuccess or type(CompiledChunk) ~= "function" then
				return nil, Name .. " compile failed: " .. tostring(CompiledChunk)
			end
			local ExecuteSuccess, LoaderResult = pcall(CompiledChunk)
			if not ExecuteSuccess then
				return nil, Name .. " loader failed: " .. tostring(LoaderResult)
			end
			local Handler = GetRemoteDecomp(LoaderResult)
			if type(Handler) ~= "function" then
				return nil, Name .. " did not expose a decompile function"
			end
			RemoteCache[Name] = Handler
			return Handler
		end
		local function LuaCIDDecompile(ScriptObject)
			local Handler, Failure = LoadRemoteDecomp("LuaCID", "https://luacid.dev/script.lua")
			if not Handler then return nil, Failure end
			return Handler(ScriptObject)
		end
		local function X2125Decompile(ScriptObject)
			local Handler, Failure = LoadRemoteDecomp("X2125", "https://x2125.xyz/loader.lua")
			if not Handler then return nil, Failure end
			return Handler(ScriptObject)
		end
		local DecompFns = {
			["Valm Decompiler"] = VDecomp,
			ByteFall = ByteFallDecompile,
			LunaUX = function(ScriptObject)
				return LunaUXDecompile(ScriptObject, env.request, env.getscriptbytecode)
			end,
			LuaCID = LuaCIDDecompile,
			X2125 = X2125Decompile,
			Native = env.nativeDecompile
		}
		local DecompileOutputHeader = "--[[\n____   ____      .__            \n\\   \\ /   /____  |  |   _____   \n \\   Y   /\\__  \\ |  |  /     \\  \n  \\     /  / __ \\|  |_|  Y Y  \\ \n   \\___/  (____  /____/__|_|  / \n               \\/           \\/  \n--]]"
		local DecompCredit = "-- Decompiler was made by [REDACTED] and Exirl (diffrent_.)"
		local function StripOutputHeader(Output)
			local Body = Output
			if Body:sub(1, #DecompileOutputHeader) == DecompileOutputHeader then
				Body = Body:sub(#DecompileOutputHeader + 1)
			end
			Body = Body:gsub("\r\n", "\n"):gsub("^\n+", "")
			if Body:sub(1, #DecompCredit) == DecompCredit then
				local FirstLineEnd = Body:find("\n", 1, true)
				local SecondLineEnd = FirstLineEnd and Body:find("\n", FirstLineEnd + 1, true)
				local ThirdLineEnd = SecondLineEnd and Body:find("\n", SecondLineEnd + 1, true)
				if SecondLineEnd and ThirdLineEnd and Body:sub(SecondLineEnd + 1, ThirdLineEnd - 1) == "-- Danke for using Valm Dex ++" then
					Body = Body:sub(ThirdLineEnd + 1):gsub("^\n+", "")
				end
			end
			return Body
		end
		local function MakeDecompHeader(Output, ElapsedTime, ScriptPath, DecompilerName)
			local Duration = string.format("%.2f", math.max(0, tonumber(ElapsedTime) or 0))
			local SafeScriptPath = tostring(ScriptPath or "Unknown")
			SafeScriptPath = SafeScriptPath:gsub("[\r\n]", " ")
			local TimingLine = "-- Took " .. Duration .. "s to Decompile (Script Path: " .. SafeScriptPath .. ")"
			local CleanOutput = StripOutputHeader(Output)
			if DecompilerName ~= "Valm Decompiler" then
				return TimingLine .. "\n\n" .. CleanOutput
			end
			return DecompileOutputHeader
				.. "\n" .. DecompCredit
				.. "\n" .. TimingLine
				.. "\n-- Danke for using Valm Dex ++\n\n"
				.. CleanOutput
		end
		local function DecompileScript(ScriptObject)
			local DecompStart = tick()
			pcall(SetStatus, "LastSuccessfulDecompiler", nil)
			env.ValmDecompilerLastSuccessfulDecompiler = nil
			if not ScriptObject or typeof(ScriptObject) ~= "Instance" or not ScriptObject:IsA("LuaSourceContainer") then
				return nil, "Select a script instance first"
			end
			if type(env.isViableDecompileScript) ~= "function" then
				return nil, "The executor does not expose a client-visibility check for scripts"
			end
			local ViabilitySuccess, IsViable = pcall(env.isViableDecompileScript, ScriptObject)
			if not ViabilitySuccess or not IsViable then
				return nil, "This script does not replicate to the client; server-only source and bytecode are unavailable here"
			end
			local DecompilerSettings = Settings.Decompiler or {}
			local DecompilerOrder = GetDecompOrder(DecompilerSettings)
			local Tried = {}
			local Failures = {}
			for _, DecompilerName in ipairs(DecompilerOrder) do
				local DecompFn = DecompFns[DecompilerName]
				if type(DecompFn) == "function" and not Tried[DecompFn] then
					Tried[DecompFn] = true
					local CallSuccess, Output, Detail = pcall(DecompFn, ScriptObject)
					if CallSuccess and IsDecompSrc(Output) then
						local PathSuccess, ScriptPath = pcall(function()
							return ScriptObject:GetFullName()
						end)
						Output = MakeDecompHeader(Output, tick() - DecompStart, PathSuccess and ScriptPath or ScriptObject.Name, DecompilerName)
						env.ValmDecompilerLastSuccessfulDecompiler = DecompilerName
						pcall(SetStatus, "LastSuccessfulDecompiler", DecompilerName)
						if DecompilerName == "Valm Decompiler" then
							env.ValmDecompilerLastNativeError = nil
						end
						return Output
					end
					local Failure = CallSuccess and (Detail or "returned invalid source") or Output
					if DecompilerName == "Valm Decompiler" then
						env.ValmDecompilerLastNativeError = tostring(Failure or "unknown error")
					end
					Failures[#Failures + 1] = DecompilerName .. ": " .. tostring(Failure or "unknown error")
				else
					Failures[#Failures + 1] = DecompilerName .. ": unavailable"
				end
			end
			return nil, #Failures > 0 and table.concat(Failures, "\n") or "No compatible decompiler is available"
		end
		env.byteFallDecompile = ByteFallDecompile
		Fallback = ByteFallDecompile
		env.decompile = DecompileScript
		env.isdecompile = function()
			for _, DecompFn in pairs(DecompFns) do
				if type(DecompFn) == "function" then return true end
			end
			return false
		end
		env.isdecompilefallback = function()
			return type(ByteFallDecompile) == "function" or type(LunaUXDecompile) == "function" or type(LuaCIDDecompile) == "function" or type(X2125Decompile) == "function" or type(env.nativeDecompile) == "function"
		end

		if identifyexecutor then
			Main.Executor = identifyexecutor()
		end

		Main.GuiHolder = Main.Elevated and service.CoreGui or plr:FindFirstChildOfClass("PlayerGui")

		setmetatable(env,nil)
	end

