	local function serialize(val)
		if typeof(val) == "Color3" then
			local serializedColor = {}
			serializedColor.R = val.R
			serializedColor.G = val.G
			serializedColor.B = val.B
			return serializedColor
		else
			return val
		end
	end
	
	local function deserialize(val)
		if typeof(val) == "table" then
			if val.R and val.G and val.B then
				return Color3.new(val.R, val.G, val.B)
			else
				return val
			end
		else
			return val
		end
	end
	
	Main.ExportSettings = function()
		local rawData = Settings or DefaultSettings

		local function recur(tbl)
			local newTbl = {}
			for i, v in pairs(tbl) do
				if typeof(v) == "table" then
					newTbl[i] = recur(v)
				else
					newTbl[i] = serialize(v)
				end
			end
			return newTbl
		end

		-- serialize color3 sebelum encode
		local serializedData = recur(rawData)

		local s, json = pcall(service.HttpService.JSONEncode, service.HttpService, serializedData)
		if s and json then
			return json
		end
	end


	--warn(Main.ExportSettings())

	Main.LoadSettings = function()
		local s, data = pcall(function()
			if type(env.readfile) ~= "function" then
				error("readfile is unavailable")
			end
			return env.readfile("DexPlusPlusSettings.json")
		end)
		if s and data and data ~= "" then
			
			local s, decoded = pcall(service.HttpService.JSONDecode, service.HttpService, data)
			if s and decoded then

				local function recur(tbl)
					local newTbl = {}
					for i, v in pairs(tbl) do
						if typeof(v) == "table" then
							newTbl[i] = deserialize(recur(v))
						else
							newTbl[i] = deserialize(v)
						end
					end
					return newTbl
				end

				local deserializedData = recur(decoded)
				for k, v in pairs(deserializedData) do
					Settings[k] = v
				end
			else
				warn("failed to decode settings json")
			end
		else
			Main.ResetSettings()
		end
	end

	
	

	Main.ResetSettings = function()
		local function recur(t,res)
			for set,val in pairs(t) do
				if type(val) == "table" and val._Recurse then
					if type(res[set]) ~= "table" then
						res[set] = {}
					end
					recur(val,res[set])
				else
					res[set] = val
				end
			end
			return res
		end
		recur(DefaultSettings,Settings)
	end

	Main.ApplyInterfaceTheme = function()
		Settings.Theme = Settings.Theme or {}
		local Theme = Settings.Theme
		local PreviousPalette = {}
		for Key, Value in pairs(Theme) do
			if typeof(Value) == "Color3" then
				PreviousPalette[Key] = Value
			end
		end
		Main.PreviousInterfaceThemePalette = PreviousPalette
		local PresetName = Theme.Preset or "Default Dark"
		local Preset = ThemePresets[PresetName] or ThemePresets["Default Dark"]
		for Key, Value in pairs(Preset) do
			Theme[Key] = Value
		end
		Theme.Style = ThemeStyles[PresetName] or ThemeStyles["Default Dark"]
		if PresetName == "Custom" then
			local Hex = tostring(Theme.CustomAccentHex or "#0B5AAF"):gsub("^#", "")
			if #Hex == 6 and Hex:match("^%x%x%x%x%x%x$") then
				local Accent = Color3.fromRGB(tonumber(Hex:sub(1, 2), 16), tonumber(Hex:sub(3, 4), 16), tonumber(Hex:sub(5, 6), 16))
				Theme.Button = Accent
				Theme.ButtonHover = Accent:Lerp(Color3.new(1, 1, 1), 0.16)
				Theme.ButtonPress = Accent:Lerp(Color3.new(0, 0, 0), 0.2)
				Theme.ListSelection = Accent
				Theme.Highlight = Accent:Lerp(Theme.Main1, 0.38)
			end
		end
		Theme.Preset = PresetName
	end

	Main.ApplyFullInterfaceTheme = function()
		local Theme = Settings.Theme
		local Style = type(Theme.Style) == "table" and Theme.Style or ThemeStyles[Theme.Preset or "Default Dark"] or ThemeStyles["Default Dark"]
		local ThemeObjectRoles = Main.ThemeObjectRoles or setmetatable({}, {__mode = "k"})
		local ThemeTextRoles = Main.ThemeTextRoles or setmetatable({}, {__mode = "k"})
		local TextBases = Main.ThemeTextBaselines or setmetatable({}, {__mode = "k"})
		local ThemeStrokeRoles = Main.ThemeStrokeRoles or setmetatable({}, {__mode = "k"})
		local ThemeBorderRoles = Main.ThemeBorderRoles or setmetatable({}, {__mode = "k"})
		local ThemeStrokes = Main.ThemeGeneratedStrokes or setmetatable({}, {__mode = "k"})
		local ThemeGradients = Main.ThemeGeneratedGradients or setmetatable({}, {__mode = "k"})
		Main.ThemeObjectRoles = ThemeObjectRoles
		Main.ThemeTextRoles = ThemeTextRoles
		Main.ThemeTextBaselines = TextBases
		Main.ThemeStrokeRoles = ThemeStrokeRoles
		Main.ThemeBorderRoles = ThemeBorderRoles
		Main.ThemeGeneratedStrokes = ThemeStrokes
		Main.ThemeGeneratedGradients = ThemeGradients
		local Connections = Main.ThemeConnections or {}
		local WatchedContainers = Main.ThemeWatchedContainers or {}
		local WatchedRoots = Main.ThemeWatchedRoots or {}
		Main.ThemeConnections = Connections
		Main.ThemeWatchedContainers = WatchedContainers
		Main.ThemeWatchedRoots = WatchedRoots

		local function IsNeutral(Color)
			local Red = math.floor(Color.R * 255 + 0.5)
			local Green = math.floor(Color.G * 255 + 0.5)
			local Blue = math.floor(Color.B * 255 + 0.5)
			return math.max(Red, Green, Blue) - math.min(Red, Green, Blue) <= 5, Red, Green, Blue
		end

		local function IsBlueAccent(Color)
			return Color.B > 0.48 and Color.G > 0.22 and Color.B > Color.R * 1.35 and Color.G > Color.R * 1.25
		end

		local function IsEditorObject(Object)
			local Current = Object
			while Current do
				if Current:IsA("GuiObject") and Current:FindFirstChild("Lines") and Current:FindFirstChild("LineNumbers") then
					return true
				end
				if Current.Name == "SelectionHighlight" or Current.Name == "LineNumbers" or Current.Name == "Cursor" then
					return true
				end
				Current = Current.Parent
			end
			return false
		end

		local function HasName(Name, Values)
			local LowerName = string.lower(Name)
			for _, Value in ipairs(Values) do
				if string.find(LowerName, Value, 1, true) then
					return true
				end
			end
			return false
		end

		local PaletteRoleNames = {"Main1", "Main2", "Outline1", "Outline2", "Outline3", "TextBox", "Menu", "ListSelection", "Button", "ButtonHover", "ButtonPress", "Highlight"}

		local function MatchPaletteRole(Color, Palette)
			if type(Palette) ~= "table" then return nil end
			local BestRole, BestDistance = nil, math.huge
			for _, Role in ipairs(PaletteRoleNames) do
				local Candidate = Palette[Role]
				if typeof(Candidate) == "Color3" then
					local Distance = math.max(math.abs(Color.R - Candidate.R), math.abs(Color.G - Candidate.G), math.abs(Color.B - Candidate.B))
					if Distance < BestDistance then
						BestDistance = Distance
						BestRole = Role
					end
				end
			end
			return BestDistance <= 0.035 and BestRole or nil
		end

		local function GetSurfaceRole(Object, Color)
			local Name = Object.Name
			if Object:IsA("TextBox") or HasName(Name, {"searchbox", "inputbox", "textbox", "textinput", "renamebox"}) then return "TextBox" end
			if HasName(Name, {"selectionhighlight", "selectedrow", "selecteditem", "selectionindicator", "listselection"}) then return "ListSelection" end
			if HasName(Name, {"modalshade", "overlay", "dimlayer", "backdrop"}) then return "Outline1" end
			if HasName(Name, {"context", "dropdown", "popup", "tooltip", "menu", "flyout"}) then return "Menu" end
			if HasName(Name, {"toolbar", "titlebar", "tabbar", "bottomframe", "header", "footer", "topbar"}) then return "Main1" end
			if Object:IsA("TextButton") or Object:IsA("ImageButton") then return "Button" end
			local CachedRole = ThemeObjectRoles[Object]
			if CachedRole and Theme[CachedRole] then return CachedRole end
			local MatchedRole = MatchPaletteRole(Color, Main.PreviousInterfaceThemePalette) or MatchPaletteRole(Color, Theme)
			if MatchedRole then return MatchedRole end
			local Neutral, Red, Green, Blue = IsNeutral(Color)
			if not Neutral and IsBlueAccent(Color) then return "ListSelection" end
			if Object:IsA("ScrollingFrame") or HasName(Name, {"container", "content", "rightside", "leftside", "mainframe", "panel", "root", "section", "body", "surface"}) then return "Main2" end
			if Neutral then
				local Brightness = (Red + Green + Blue) / 3
				if Brightness <= 15 then return "Outline1"
				elseif Brightness <= 31 then return "Outline3"
				elseif Brightness <= 44 then return "Menu"
				elseif Brightness <= 56 then return "Main2"
				elseif Brightness <= 72 then return "Main1"
				elseif Brightness <= 94 then return "Button"
				elseif Brightness <= 145 then return "ButtonHover" end
			end
			return "Main2"
		end

		local function MatchTextRole(Color, Palette)
			if type(Palette) ~= "table" then return nil end
			local BestRole, BestDistance = nil, math.huge
			for _, Role in ipairs({"Text", "PlaceholderText"}) do
				local Candidate = Palette[Role]
				if typeof(Candidate) == "Color3" then
					local Distance = math.max(math.abs(Color.R - Candidate.R), math.abs(Color.G - Candidate.G), math.abs(Color.B - Candidate.B))
					if Distance < BestDistance then BestDistance, BestRole = Distance, Role end
				end
			end
			return BestDistance <= 0.035 and BestRole or nil
		end

		local function GetThemeTextRole(Object, Color)
			local Name = Object.Name
			if HasName(Name, {"error", "failed", "failure", "danger", "critical"}) then return "Important" end
			if HasName(Name, {"placeholder", "hint", "subtitle", "description", "muted", "secondarytext"}) then return "PlaceholderText" end
			local CachedRole = ThemeTextRoles[Object]
			if CachedRole and Theme[CachedRole] then return CachedRole end
			local MatchedRole = MatchTextRole(Color, Main.PreviousInterfaceThemePalette) or MatchTextRole(Color, Theme)
			if MatchedRole then return MatchedRole end
			local Neutral, Red, Green, Blue = IsNeutral(Color)
			if Neutral and ((Red + Green + Blue) / 3) <= 145 then return "PlaceholderText" end
			return "Text"
		end

		local function ResolveThemeFont(FontName, Fallback)
			local Success, FontValue = pcall(function() return Enum.Font[FontName] end)
			if Success and FontValue then return FontValue end
			return Fallback
		end

		local function ApplyObjectTheme(Object)
			if not Object or not Object.Parent or IsEditorObject(Object) then
				return
			end
			local IgnoreTheme = false
			pcall(function() IgnoreTheme = Object:GetAttribute("ValmThemeIgnore") == true end)
			if IgnoreTheme then return end

			local IsGui = Object:IsA("GuiObject")
			if IsGui then
				local ObjectNameLower = string.lower(Object.Name)
				local IsSearchSurface = ObjectNameLower == "searchbox"
				if IsSearchSurface then
					ThemeBorderRoles[Object] = "Outline3"
					if Object.BorderSizePixel < 1 then Object.BorderSizePixel = 1 end
					Object.BorderColor3 = Theme.Outline3
				end
				local SurfaceRole = ThemeObjectRoles[Object]
				if Object.BackgroundTransparency < 1 then
					SurfaceRole = SurfaceRole or GetSurfaceRole(Object, Object.BackgroundColor3)
					if SurfaceRole and Theme[SurfaceRole] then
						ThemeObjectRoles[Object] = SurfaceRole
						Object.BackgroundColor3 = Theme[SurfaceRole]
					end
				end

				if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then
					local TextRole = GetThemeTextRole(Object, Object.TextColor3)
					if TextRole then
						ThemeTextRoles[Object] = TextRole
						Object.TextColor3 = Theme[TextRole]
					end
					Object.Font = (string.find(string.lower(Object.Name), "title", 1, true) or string.find(string.lower(Object.Name), "header", 1, true)) and ResolveThemeFont(Style.HeadingFontName or "GothamBold", Enum.Font.GothamBold) or ResolveThemeFont(Style.FontName or "Gotham", Enum.Font.Gotham)
					if Object.TextStrokeTransparency < 1 then
						Object.TextStrokeColor3 = Theme.Outline1
					end
					if not TextBases[Object] then TextBases[Object] = Object.TextSize end
					local Scale = tonumber(Style.TextScale) or 1
					local LowerName = string.lower(Object.Name)
					if string.find(LowerName, "title", 1, true) or string.find(LowerName, "header", 1, true) then Scale = Scale * (tonumber(Style.HeadingScale) or 1) end
					if TextBases[Object] > 0 then Object.TextSize = math.clamp(math.floor(TextBases[Object] * Scale + 0.5), 8, 36) end
				end

				if Object:IsA("TextBox") then Object.PlaceholderColor3 = Theme.PlaceholderText end
				if Object:IsA("ScrollingFrame") then
					Object.ScrollBarImageColor3 = Theme.ButtonHover
					Object.ScrollBarThickness = math.clamp(tonumber(Style.ScrollBarThickness) or 6, 3, 12)
				end

				local ThemeCorner = Object:FindFirstChild("ValmThemeCorner")
				if ThemeCorner and ThemeCorner:IsA("UICorner") then
					ThemeCorner:Destroy()
				end

				local IsControl = Object:IsA("TextButton") or Object:IsA("ImageButton") or Object:IsA("TextBox")
				local Stroke = Object:FindFirstChild("ValmThemeStroke")
				if Style.AddControlStrokes and IsControl then
					if not Stroke then
						Stroke = Instance.new("UIStroke")
						Stroke.Name = "ValmThemeStroke"
						Stroke.Parent = Object
						ThemeStrokes[Stroke] = true
					end
					Stroke.Enabled = true
					Stroke.Color = Theme.Outline2
					Stroke.Thickness = math.clamp(tonumber(Style.StrokeThickness) or 1, 0.5, 3)
					Stroke.Transparency = math.clamp(tonumber(Style.StrokeTransparency) or 0.35, 0, 0.9)
				elseif Stroke and ThemeStrokes[Stroke] then
					Stroke.Enabled = false
				end

				local Gradient = Object:FindFirstChild("ValmThemeGradient")
				local GradientRole = SurfaceRole == "Button" or SurfaceRole == "Main1" or SurfaceRole == "Main2"
				if Style.Gradients and GradientRole and Object.BackgroundTransparency < 1 then
					if not Gradient then
						Gradient = Instance.new("UIGradient")
						Gradient.Name = "ValmThemeGradient"
						Gradient.Parent = Object
						ThemeGradients[Gradient] = true
					end
					local BaseColor = Theme[SurfaceRole]
					local Strength = math.clamp(tonumber(Style.GradientStrength) or 0.08, 0, 0.25)
					Gradient.Color = ColorSequence.new(BaseColor:Lerp(Color3.new(1, 1, 1), Strength), BaseColor:Lerp(Color3.new(0, 0, 0), Strength * 0.55))
					Gradient.Rotation = 90
					Gradient.Enabled = true
				elseif Gradient and ThemeGradients[Gradient] then
					Gradient.Enabled = false
				end

				if Object:IsA("ImageLabel") or Object:IsA("ImageButton") then
					local IconRole = ThemeTextRoles[Object] or MatchPaletteRole(Object.ImageColor3, Main.PreviousInterfaceThemePalette) or MatchPaletteRole(Object.ImageColor3, Theme) or MatchTextRole(Object.ImageColor3, Main.PreviousInterfaceThemePalette)
					if not IconRole then
						local NeutralIcon = IsNeutral(Object.ImageColor3)
						if NeutralIcon then IconRole = "Text" end
					end
					if IconRole and Theme[IconRole] then
						ThemeTextRoles[Object] = IconRole
						Object.ImageColor3 = Theme[IconRole]
					end
				end
				if Object.BorderSizePixel > 0 then
					local BorderRole = ThemeBorderRoles[Object] or MatchPaletteRole(Object.BorderColor3, Main.PreviousInterfaceThemePalette) or MatchPaletteRole(Object.BorderColor3, Theme) or "Outline2"
					if IsSearchSurface then BorderRole = "Outline3" end
					if BorderRole ~= "Outline1" and BorderRole ~= "Outline2" and BorderRole ~= "Outline3" then BorderRole = "Outline2" end
					ThemeBorderRoles[Object] = BorderRole
					Object.BorderColor3 = Theme[BorderRole]
				end
			elseif Object:IsA("UIStroke") and not ThemeStrokes[Object] then
				local StrokeParent = Object.Parent
				local IsSearchStroke = StrokeParent ~= nil and string.lower(StrokeParent.Name) == "searchframe" and StrokeParent:FindFirstChild("SearchBox") ~= nil
				local StrokeRole = ThemeStrokeRoles[Object] or MatchPaletteRole(Object.Color, Main.PreviousInterfaceThemePalette) or MatchPaletteRole(Object.Color, Theme) or "Outline2"
				if IsSearchStroke then StrokeRole = "Outline3" end
				if StrokeRole ~= "Outline1" and StrokeRole ~= "Outline2" and StrokeRole ~= "Outline3" then StrokeRole = "Outline2" end
				ThemeStrokeRoles[Object] = StrokeRole
				Object.Color = Theme[StrokeRole]
				Object.Thickness = math.clamp(tonumber(Style.StrokeThickness) or Object.Thickness, 0.5, 3)
				Object.Transparency = math.clamp(tonumber(Style.StrokeTransparency) or Object.Transparency, 0, 0.9)
			elseif Object:IsA("UIGradient") and not ThemeGradients[Object] then
				local Parent = Object.Parent
				if Parent and Parent:IsA("GuiObject") then
					local ParentRole = ThemeObjectRoles[Parent] or GetSurfaceRole(Parent, Parent.BackgroundColor3)
					local TargetColor = Theme[ParentRole] or Theme.Main2
					local OldParentColor = Main.PreviousInterfaceThemePalette and Main.PreviousInterfaceThemePalette[ParentRole] or Parent.BackgroundColor3
					local OldLuma = OldParentColor.R * 0.2126 + OldParentColor.G * 0.7152 + OldParentColor.B * 0.0722
					local Keypoints = {}
					for _, Keypoint in ipairs(Object.Color.Keypoints) do
						local Role = MatchPaletteRole(Keypoint.Value, Main.PreviousInterfaceThemePalette) or MatchPaletteRole(Keypoint.Value, Theme)
						local NewColor = Role and Theme[Role] or nil
						if not NewColor then
							local Luma = Keypoint.Value.R * 0.2126 + Keypoint.Value.G * 0.7152 + Keypoint.Value.B * 0.0722
							local Contrast = math.clamp(math.abs(Luma - OldLuma) * 2.2, 0.035, 0.2)
							NewColor = Luma >= OldLuma and TargetColor:Lerp(Color3.new(1, 1, 1), Contrast) or TargetColor:Lerp(Color3.new(0, 0, 0), Contrast)
						end
						Keypoints[#Keypoints + 1] = ColorSequenceKeypoint.new(Keypoint.Time, NewColor)
					end
					Object.Color = ColorSequence.new(Keypoints)
				end
			end
		end

		local function ApplyRootTheme(Root)
			if not Root or not Root.Parent or WatchedRoots[Root] then
				return
			end
			WatchedRoots[Root] = true

			for _, Object in ipairs(Root:GetDescendants()) do
				pcall(ApplyObjectTheme, Object)
			end

			Connections[#Connections + 1] = Root.DescendantAdded:Connect(function(Object)
				local function ApplyLater()
					if Object.Parent then
						pcall(ApplyObjectTheme, Object)
					end
				end
				if type(task) == "table" and type(task.defer) == "function" then
					task.defer(ApplyLater)
				else
					task.spawn(ApplyLater)
				end
			end)
		end

		local function IsDexRoot(Object)
			if not Object:IsA("ScreenGui") then
				return false
			end
			return string.sub(Object.Name, 1, 5) == "_DPP_" or Object.Name == "ValmDexNotification" or Object.Name == "DexGoHomeBro"
		end

		local function WatchContainer(Container)
			if typeof(Container) ~= "Instance" or WatchedContainers[Container] then
				return
			end
			WatchedContainers[Container] = true

			for _, Child in ipairs(Container:GetDescendants()) do
				if IsDexRoot(Child) then ApplyRootTheme(Child) end
			end
			for _, Child in ipairs(Container:GetChildren()) do
				if IsDexRoot(Child) then ApplyRootTheme(Child) end
			end

			Connections[#Connections + 1] = Container.DescendantAdded:Connect(function(Child)
				if IsDexRoot(Child) then
					local function ApplyLater()
						if Child.Parent then ApplyRootTheme(Child) end
					end
					if type(task) == "table" and type(task.defer) == "function" then task.defer(ApplyLater) else task.spawn(ApplyLater) end
				end
			end)
		end

		local Containers = {}
		local SeenContainers = {}
		local function AddContainer(Container)
			if typeof(Container) == "Instance" and not SeenContainers[Container] then
				SeenContainers[Container] = true
				Containers[#Containers + 1] = Container
			end
		end

		AddContainer(Main.GuiHolder)
		local SecureSuccess, SecureContainer = pcall(Main.GetSecureContainer)
		if SecureSuccess then
			AddContainer(SecureContainer)
		end
		if type(gethui) == "function" then
			local HUISuccess, HUIContainer = pcall(gethui)
			if HUISuccess then
				AddContainer(HUIContainer)
			end
		end
		pcall(function()
			AddContainer(service.CoreGui)
		end)
		pcall(function()
			AddContainer(plr:FindFirstChildOfClass("PlayerGui"))
		end)

		for _, Container in ipairs(Containers) do
			WatchContainer(Container)
		end
		if type(Main.RefreshDropdownTheme) == "function" then
			pcall(Main.RefreshDropdownTheme)
		end
	end

	Main.RefreshInterfaceTheme = function()
		if type(Main.ApplyInterfaceTheme) == "function" then
			Main.ApplyInterfaceTheme()
		end
		if type(Main.ApplyFinUIOverrides) == "function" then
			pcall(Main.ApplyFinUIOverrides)
		end
		for _, Connection in ipairs(Main.ThemeConnections or {}) do
			pcall(function() Connection:Disconnect() end)
		end
		Main.ThemeConnections = {}
		Main.ThemeWatchedContainers = {}
		Main.ThemeWatchedRoots = {}
		if type(Main.ApplyFullInterfaceTheme) == "function" then
			Main.ApplyFullInterfaceTheme()
		end
		if type(Main.ApplyExplorerSearchTheme) == "function" then
			pcall(Main.ApplyExplorerSearchTheme)
		end
		return true
	end

	Main.FetchAPI = function(callbackiflong, callbackiftoolong, XD)
		local downloaded = false
		local api,rawAPI
		if Main.Elevated then
			if Main.LocalDepsUpToDate() then
				local localAPI = Lib.ReadFile("dex/rbx_api.dat")
				if localAPI then 
					rawAPI = localAPI
				else
					Main.DepsVersionData[1] = ""
				end
			end
			task.spawn(function()
				task.wait(10)
				if not downloaded and callbackiflong then callbackiflong() end

				task.wait(20) -- 30
				if not downloaded and callbackiftoolong then callbackiftoolong() end

				task.wait(30) -- 60
				if not downloaded and XD then XD() end
			end)
			-- lmfao async makes it work to load big file
			rawAPI = rawAPI or game:HttpGet("http://setup.roblox.com/"..Main.RobloxVersion.."-API-Dump.json")
		else
			if script:FindFirstChild("API") then
				rawAPI = require(script.API)
			else
				error("NO API EXISTS")
			end
		end
		downloaded = true
		
		Main.RawAPI = rawAPI
		api = service.HttpService:JSONDecode(rawAPI)

		local classes,enums = {},{}
		local categoryOrder,seenCategories = {},{}

		local function insertAbove(t,item,aboveItem)
			local findPos = table.find(t,item)
			if not findPos then return end
			table.remove(t,findPos)

			local pos = table.find(t,aboveItem)
			if not pos then return end
			table.insert(t,pos,item)
		end

		for _,class in pairs(api.Classes) do
			local newClass = {}
			newClass.Name = class.Name
			newClass.Superclass = class.Superclass
			newClass.Properties = {}
			newClass.Functions = {}
			newClass.Events = {}
			newClass.Callbacks = {}
			newClass.Tags = {}

			if class.Tags then for c,tag in pairs(class.Tags) do newClass.Tags[tag] = true end end
			for __,member in pairs(class.Members) do
				local newMember = {}
				newMember.Name = member.Name
				newMember.Class = class.Name
				newMember.Security = member.Security
				newMember.Tags ={}
				if member.Tags then for c,tag in pairs(member.Tags) do newMember.Tags[tag] = true end end

				local mType = member.MemberType
				if mType == "Property" then
					local propCategory = member.Category or "Other"
					propCategory = propCategory:match("^%s*(.-)%s*$")
					if not seenCategories[propCategory] then
						categoryOrder[#categoryOrder+1] = propCategory
						seenCategories[propCategory] = true
					end
					newMember.ValueType = member.ValueType
					newMember.Category = propCategory
					newMember.Serialization = member.Serialization
					table.insert(newClass.Properties,newMember)
				elseif mType == "Function" then
					newMember.Parameters = {}
					newMember.ReturnType = member.ReturnType.Name
					for c,param in pairs(member.Parameters) do
						table.insert(newMember.Parameters,{Name = param.Name, Type = param.Type.Name})
					end
					table.insert(newClass.Functions,newMember)
				elseif mType == "Event" then
					newMember.Parameters = {}
					for c,param in pairs(member.Parameters) do
						table.insert(newMember.Parameters,{Name = param.Name, Type = param.Type.Name})
					end
					table.insert(newClass.Events,newMember)
				end
			end

			classes[class.Name] = newClass
		end

		for _,class in pairs(classes) do
			class.Superclass = classes[class.Superclass]
		end

		for _,enum in pairs(api.Enums) do
			local newEnum = {}
			newEnum.Name = enum.Name
			newEnum.Items = {}
			newEnum.Tags = {}

			if enum.Tags then for c,tag in pairs(enum.Tags) do newEnum.Tags[tag] = true end end
			for __,item in pairs(enum.Items) do
				local newItem = {}
				newItem.Name = item.Name
				newItem.Value = item.Value
				table.insert(newEnum.Items,newItem)
			end

			enums[enum.Name] = newEnum
		end

		local function getMember(class,member)
			if not classes[class] or not classes[class][member] then return end
			local result = {}

			local currentClass = classes[class]
			while currentClass do
				for _,entry in pairs(currentClass[member]) do
					result[#result+1] = entry
				end
				currentClass = currentClass.Superclass
			end

			table.sort(result,function(a,b) return a.Name < b.Name end)
			return result
		end

		insertAbove(categoryOrder,"Behavior","Tuning")
		insertAbove(categoryOrder,"Appearance","Data")
		insertAbove(categoryOrder,"Attachments","Axes")
		insertAbove(categoryOrder,"Cylinder","Slider")
		insertAbove(categoryOrder,"Localization","Jump Settings")
		insertAbove(categoryOrder,"Surface","Motion")
		insertAbove(categoryOrder,"Surface Inputs","Surface")
		insertAbove(categoryOrder,"Part","Surface Inputs")
		insertAbove(categoryOrder,"Assembly","Surface Inputs")
		insertAbove(categoryOrder,"Character","Controls")
		categoryOrder[#categoryOrder+1] = "Unscriptable"
		categoryOrder[#categoryOrder+1] = "Attributes"

		local categoryOrderMap = {}
		for i = 1,#categoryOrder do
			categoryOrderMap[categoryOrder[i]] = i
		end

		return {
			Classes = classes,
			Enums = enums,
			CategoryOrder = categoryOrderMap,
			GetMember = getMember
		}
	end

	Main.FetchRMD = function()
		local rawXML
		if Main.Elevated then
			if Main.LocalDepsUpToDate() then
				local localRMD = Lib.ReadFile("dex/rbx_rmd.dat")
				if localRMD then 
					rawXML = localRMD
				else
					Main.DepsVersionData[1] = ""
				end
			end
			rawXML = rawXML or game:HttpGet("https://raw.githubusercontent.com/CloneTrooper1019/Roblox-Client-Tracker/roblox/ReflectionMetadata.xml")
		else
			if script:FindFirstChild("RMD") then
				rawXML = require(script.RMD)
			else
				error("NO RMD EXISTS")
			end
		end
		Main.RawRMD = rawXML
		local parsed = Lib.ParseXML(rawXML)
		local classList = parsed.children[1].children[1].children
		local enumList = parsed.children[1].children[2].children
		local propertyOrders = {}

		local classes,enums = {},{}
		for _,class in pairs(classList) do
			local className = ""
			for _,child in pairs(class.children) do
				if child.tag == "Properties" then
					local data = {Properties = {}, Functions = {}}
					local props = child.children
					for _,prop in pairs(props) do
						local name = prop.attrs.name
						name = name:sub(1,1):upper()..name:sub(2)
						data[name] = prop.children[1].text
					end
					className = data.Name
					classes[className] = data
				elseif child.attrs.class == "ReflectionMetadataProperties" then
					local members = child.children
					for _,member in pairs(members) do
						if member.attrs.class == "ReflectionMetadataMember" then
							local data = {}
							if member.children[1].tag == "Properties" then
								local props = member.children[1].children
								for _,prop in pairs(props) do
									if prop.attrs then
										local name = prop.attrs.name
										name = name:sub(1,1):upper()..name:sub(2)
										data[name] = prop.children[1].text
									end
								end
								if data.PropertyOrder then
									local orders = propertyOrders[className]
									if not orders then orders = {} propertyOrders[className] = orders end
									orders[data.Name] = tonumber(data.PropertyOrder)
								end
								classes[className].Properties[data.Name] = data
							end
						end
					end
				elseif child.attrs.class == "ReflectionMetadataFunctions" then
					local members = child.children
					for _,member in pairs(members) do
						if member.attrs.class == "ReflectionMetadataMember" then
							local data = {}
							if member.children[1].tag == "Properties" then
								local props = member.children[1].children
								for _,prop in pairs(props) do
									if prop.attrs then
										local name = prop.attrs.name
										name = name:sub(1,1):upper()..name:sub(2)
										data[name] = prop.children[1].text
									end
								end
								classes[className].Functions[data.Name] = data
							end
						end
					end
				end
			end
		end

		for _,enum in pairs(enumList) do
			local enumName = ""
			for _,child in pairs(enum.children) do
				if child.tag == "Properties" then
					local data = {Items = {}}
					local props = child.children
					for _,prop in pairs(props) do
						local name = prop.attrs.name
						name = name:sub(1,1):upper()..name:sub(2)
						data[name] = prop.children[1].text
					end
					enumName = data.Name
					enums[enumName] = data
				elseif child.attrs.class == "ReflectionMetadataEnumItem" then
					local data = {}
					if child.children[1].tag == "Properties" then
						local props = child.children[1].children
						for _,prop in pairs(props) do
							local name = prop.attrs.name
							name = name:sub(1,1):upper()..name:sub(2)
							data[name] = prop.children[1].text
						end
						enums[enumName].Items[data.Name] = data
					end
				end
			end
		end

		return {Classes = classes, Enums = enums, PropertyOrders = propertyOrders}
	end

