			{7,"TextLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Font=3,Name="StatusText",Parent={3},Position=UDim2.new(0,20,0,155),Size=UDim2.new(0,310,0,22),Text="Fetching API",TextColor3=Color3.new(1,1,1),TextSize=14,TextTransparency=1,TextXAlignment=Enum.TextXAlignment.Center,}},
			{8,"Frame",{BackgroundColor3=Color3.new(0.20392157137394,0.20392157137394,0.20392157137394),BorderSizePixel=0,Name="ProgressBar",Parent={3},Position=UDim2.new(0,110,0,188),Size=UDim2.new(0,0,0,4),}},
			{9,"Frame",{BackgroundColor3=Color3.new(0.2392156869173,0.56078433990479,0.86274510622025),BorderSizePixel=0,Name="Bar",Parent={8},Size=UDim2.new(0,0,1,0),}},
			{10,"ImageLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Image="rbxassetid://2764171053",ImageColor3=Color3.new(0.17647059261799,0.17647059261799,0.17647059261799),Parent={8},ScaleType=1,Size=UDim2.new(1,0,1,0),SliceCenter=Rect.new(2,2,254,254),}},
			{11,"TextLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Font=3,Name="Creator",Parent={2},Position=UDim2.new(1,-110,1,-20),Size=UDim2.new(0,105,0,20),Text="",TextColor3=Color3.new(1,1,1),TextSize=14,TextXAlignment=1,}},
			{12,"UIGradient",{Parent={11},Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1,0),NumberSequenceKeypoint.new(1,1,0),}),}},
			{13,"TextLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,Font=3,Name="Version",Parent={2},Position=UDim2.new(1,-110,1,-35),Size=UDim2.new(0,105,0,20),Text=Main.Version,TextColor3=Color3.new(1,1,1),TextSize=14,TextXAlignment=1,}},
			{14,"UIGradient",{Parent={13},Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1,0),NumberSequenceKeypoint.new(1,1,0),}),}},
			{15,"ImageLabel",{BackgroundColor3=Color3.new(1,1,1),BackgroundTransparency=1,BorderSizePixel=0,Image="rbxassetid://1427967925",Name="Outlines",Parent={2},Position=UDim2.new(0,-5,0,-5),ScaleType=1,Size=UDim2.new(1,10,1,10),SliceCenter=Rect.new(6,6,25,25),TileSize=UDim2.new(0,20,0,20),}},
			{16,"UIGradient",{Parent={15},Rotation=-30,Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1,0),NumberSequenceKeypoint.new(1,1,0),}),}},
			{17,"UIGradient",{Parent={2},Rotation=-30,Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1,0),NumberSequenceKeypoint.new(1,1,0),}),}},
			{18,"UIDragDetector", {Parent={2}}}
		})
		Main.ShowGui(gui)
		local Logo = Instance.new("ImageLabel")
		Logo.Name = "ValmLogo"
		Logo.BackgroundTransparency = 1
		Logo.Image = "rbxassetid://76787745974873"
		Logo.ImageTransparency = 1
		Logo.ScaleType = Enum.ScaleType.Fit
		Logo.AnchorPoint = Vector2.new(0.5, 0)
		Logo.Position = UDim2.new(0.5, 0, 0, -10)
		Logo.Size = UDim2.new(0, 46, 0, 46)
		Logo.Parent = gui.Main.Holder
		local backGradient = gui.Main.UIGradient
		local outlinesGradient = gui.Main.Outlines.UIGradient
		local holderGradient = gui.Main.Holder.UIGradient
		local titleText = gui.Main.Holder.Title
		local descText = gui.Main.Holder.Desc
		local versionText = gui.Main.Version
		local versionGradient = versionText.UIGradient
		local creatorText = gui.Main.Creator
		local creatorGradient = creatorText.UIGradient
		local statusText = gui.Main.Holder.StatusText
		local progressBar = gui.Main.Holder.ProgressBar
		local tweenS = service.TweenService

		local renderStepped = service.RunService.RenderStepped
		local signalWait = renderStepped.wait
		local fastwait = function(s)
			if not s then return signalWait(renderStepped) end
			local start = tick()
			while tick() - start < s do signalWait(renderStepped) end
		end

		statusText.Text = initStatus

		local function tweenNumber(n,ti,func)
			local tweenVal = Instance.new("IntValue")
			tweenVal.Value = 0
			tweenVal.Changed:Connect(func)
			local tween = tweenS:Create(tweenVal,ti,{Value = n})
			tween:Play()
			tween.Completed:Connect(function()
				tweenVal:Destroy()
			end)
		end

		local ti = TweenInfo.new(0.4,Enum.EasingStyle.Quad,Enum.EasingDirection.Out)
		tweenNumber(100,ti,function(val)
			val = val/200
			local start = NumberSequenceKeypoint.new(0,0)
			local a1 = NumberSequenceKeypoint.new(val,0)
			local a2 = NumberSequenceKeypoint.new(math.min(0.5,val+math.min(0.05,val)),1)
			if a1.Time == a2.Time then a2 = a1 end
			local b1 = NumberSequenceKeypoint.new(1-val,0)
			local b2 = NumberSequenceKeypoint.new(math.max(0.5,1-val-math.min(0.05,val)),1)
			if b1.Time == b2.Time then b2 = b1 end
			local goal = NumberSequenceKeypoint.new(1,0)
			backGradient.Transparency = NumberSequence.new({start,a1,a2,b2,b1,goal})
			outlinesGradient.Transparency = NumberSequence.new({start,a1,a2,b2,b1,goal})
		end)

		fastwait(0.4)

		tweenNumber(100,ti,function(val)
			val = val/166.66
			local start = NumberSequenceKeypoint.new(0,0)
			local a1 = NumberSequenceKeypoint.new(val,0)
			local a2 = NumberSequenceKeypoint.new(val+0.01,1)
			local goal = NumberSequenceKeypoint.new(1,1)
			holderGradient.Transparency = NumberSequence.new({start,a1,a2,goal})
		end)

		local LogoIntroTween = TweenInfo.new(0.58, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
		tweenS:Create(Logo, LogoIntroTween, {
			ImageTransparency = 0,
			Position = UDim2.new(0.5, 0, 0, 6),
			Size = UDim2.new(0, 62, 0, 62)
		}):Play()
		tweenS:Create(titleText,ti,{Position = UDim2.new(0,35,0,75), TextTransparency = 0}):Play()
		tweenS:Create(descText,ti,{Position = UDim2.new(0,20,0,115), TextTransparency = 0}):Play()

		local function RightTextAlpha(obj)
			tweenNumber(100,ti,function(val)
				val = val/100
				local a1 = NumberSequenceKeypoint.new(1-val,0)
				local a2 = NumberSequenceKeypoint.new(math.max(0,1-val-0.01),1)
				if a1.Time == a2.Time then a2 = a1 end
				local start = NumberSequenceKeypoint.new(0,a1 == a2 and 0 or 1)
				local goal = NumberSequenceKeypoint.new(1,0)
				obj.Transparency = NumberSequence.new({start,a2,a1,goal})
			end)
		end
		RightTextAlpha(versionGradient)
		RightTextAlpha(creatorGradient)

		fastwait(0.9)

		local progressTI = TweenInfo.new(0.25,Enum.EasingStyle.Quad,Enum.EasingDirection.Out)

		tweenS:Create(statusText,progressTI,{Position = UDim2.new(0,20,0,155), TextTransparency = 0}):Play()
		tweenS:Create(progressBar,progressTI,{Position = UDim2.new(0,60,0,188), Size = UDim2.new(0,230,0,4)}):Play()

		fastwait(0.25)

		local function setProgress(text,n)
			statusText.Text = text
			tweenS:Create(progressBar.Bar,progressTI,{Size = UDim2.new(n,0,1,0)}):Play()
		end

		local function close()
			tweenS:Create(Logo,progressTI,{ImageTransparency = 1}):Play()
			tweenS:Create(titleText,progressTI,{TextTransparency = 1}):Play()
			tweenS:Create(descText,progressTI,{TextTransparency = 1}):Play()
			tweenS:Create(versionText,progressTI,{TextTransparency = 1}):Play()
			tweenS:Create(creatorText,progressTI,{TextTransparency = 1}):Play()
			tweenS:Create(statusText,progressTI,{TextTransparency = 1}):Play()
			tweenS:Create(progressBar,progressTI,{BackgroundTransparency = 1}):Play()
			tweenS:Create(progressBar.Bar,progressTI,{BackgroundTransparency = 1}):Play()
			tweenS:Create(progressBar.ImageLabel,progressTI,{ImageTransparency = 1}):Play()

			tweenNumber(100,TweenInfo.new(0.4,Enum.EasingStyle.Back,Enum.EasingDirection.In),function(val)
				val = val/250
				local start = NumberSequenceKeypoint.new(0,0)
				local a1 = NumberSequenceKeypoint.new(0.6+val,0)
				local a2 = NumberSequenceKeypoint.new(math.min(1,0.601+val),1)
				if a1.Time == a2.Time then a2 = a1 end
				local goal = NumberSequenceKeypoint.new(1,a1 == a2 and 0 or 1)
				holderGradient.Transparency = NumberSequence.new({start,a1,a2,goal})
			end)

			fastwait(0.5)
			gui.Main.BackgroundTransparency = 1
			outlinesGradient.Rotation = 30

			tweenNumber(100,ti,function(val)
				val = val/100
				local start = NumberSequenceKeypoint.new(0,1)
				local a1 = NumberSequenceKeypoint.new(val,1)
				local a2 = NumberSequenceKeypoint.new(math.min(1,val+math.min(0.05,val)),0)
				if a1.Time == a2.Time then a2 = a1 end
				local goal = NumberSequenceKeypoint.new(1,a1 == a2 and 1 or 0)
				outlinesGradient.Transparency = NumberSequence.new({start,a1,a2,goal})
				holderGradient.Transparency = NumberSequence.new({start,a1,a2,goal})
			end)

			fastwait(0.45)
			gui:Destroy()
		end

		return {SetProgress = setProgress, Close = close, Object = gui}
	end

	Main.CreateApp = function(Data)
		if Main.MenuApps[Data.Name] then return end
		local Control = {}
		local App = Main.AppTemplate:Clone()
		local AppGradient = nil
		if Data.GradientColor then
			local GradientSuccess = pcall(function()
				AppGradient = Instance.new("UIGradient")
				AppGradient.Name = "ValmDexHelperGradient"
				AppGradient.Color = Data.GradientColor
				AppGradient.Rotation = tonumber(Data.GradientRotation) or 28
				AppGradient:SetAttribute("ValmThemeIgnore", true)
				AppGradient.Parent = App.Main
				App.Main.BackgroundColor3 = Color3.new(1, 1, 1)
				App.Main:SetAttribute("ValmThemeIgnore", true)
			end)
			if not GradientSuccess then AppGradient = nil end
		end
		local IconIndex = Data.Icon
		if Data.IconMap and IconIndex then
			if type(IconIndex) == "number" then
				Data.IconMap:Display(App.Main.Icon, IconIndex)
			elseif type(IconIndex) == "string" then
				Data.IconMap:DisplayByKey(App.Main.Icon, IconIndex)
			end
		elseif type(IconIndex) == "string" then
			local IconObject = App.Main.Icon
			IconObject.BackgroundTransparency = 1
			IconObject.ImageRectOffset = Vector2.new(0, 0)
			IconObject.ImageRectSize = Vector2.new(0, 0)
			IconObject.ScaleType = Enum.ScaleType.Fit
			IconObject.ImageColor3 = Color3.new(1, 1, 1)
			IconObject.ImageTransparency = 0
			IconObject.Visible = true
			local IconAssetId = IconIndex:match("rbxassetid://(%d+)") or IconIndex:match("[?&]id=(%d+)")
			IconObject.Image = IconAssetId and ("rbxassetid://" .. IconAssetId) or IconIndex
			if IconAssetId then
				task.spawn(function()
					local IconSources = {
						"rbxassetid://" .. IconAssetId,
						"rbxthumb://type=Asset&id=" .. IconAssetId .. "&w=420&h=420"
					}
					for _, IconSource in ipairs(IconSources) do
						if not IconObject.Parent then return end
						IconObject.Image = IconSource
						local FetchSucceeded = false
						pcall(function()
							service.ContentProvider:PreloadAsync({IconObject}, function(_, FetchStatus)
								FetchSucceeded = FetchStatus == Enum.AssetFetchStatus.Success
							end)
						end)
						if FetchSucceeded then return end
						task.wait(0.25)
					end
					if IconObject.Parent then IconObject.Image = "rbxassetid://" .. IconAssetId end
				end)
			end
		else
			App.Main.Icon.Image = ""
		end
		if type(Data.IconSize) == "number" then
			local IconSize = math.clamp(Data.IconSize, 32, 40)
			App.Main.Icon.Size = UDim2.new(0, IconSize, 0, IconSize)
			App.Main.Icon.Position = UDim2.new(0.5, -IconSize / 2, 0, 1)
		end
		local function UpdateState()
			if AppGradient then
				App.Main.BackgroundTransparency = Data.Open and 0 or (Lib.CheckMouseInGui(App.Main) and 0.015 or 0.045)
				App.Main.BackgroundColor3 = Color3.new(1, 1, 1)
			else
				App.Main.BackgroundTransparency = Data.Open and 0 or (Lib.CheckMouseInGui(App.Main) and 0 or 1)
				App.Main.BackgroundColor3 = Data.Open and (Data.ActiveColor or Data.ButtonColor or Settings.Theme.Button) or (Data.ButtonColor or Settings.Theme.Button)
			end
			App.Main.Highlight.Visible = Data.Open
		end
		local function Enable(Silent)
			if Data.Open then return end
			Data.Open = true
			UpdateState()
			if not Silent then
				if Data.Window then
					if Data.Window.ValmPluginPanel and type(Main.ArrangePluginWindow) == "function" then
						Main.ArrangePluginWindow(Data.Window)
					end
					Data.Window:Show()
				end
				if Data.OnClick then Data.OnClick(Data.Open) end
			end
		end
		local function Disable(Silent)
			if not Data.Open then return end
			Data.Open = false
			UpdateState()
			if not Silent then
				if Data.Window then Data.Window:Hide() end
				if Data.OnClick then Data.OnClick(Data.Open) end
			end
		end
		UpdateState()
		local AppIconHeight = App.Main.Icon.Size.Y.Offset
		local AppIconTop = AppIconHeight >= 36 and 1 or 2
		local AppNameTop = 38
		App.Main.Size = UDim2.new(1, 0, 1, 0)
		App.Main.Icon.Size = UDim2.fromOffset(AppIconHeight, AppIconHeight)
		App.Main.Icon.Position = UDim2.new(0.5, -AppIconHeight / 2, 0, AppIconTop)
		App.Main.AppName.Position = UDim2.new(0, 2, 0, AppNameTop)
		App.Main.AppName.Size = UDim2.new(1, -4, 1, -40)
		App.Main.AppName.Text = Data.Name
		App.Main.AppName.TextColor3 = Settings.Theme.Text
		App.Main.BorderSizePixel = 0
		Main.AppLayoutIndex = (Main.AppLayoutIndex or 0) + 1
		App.LayoutOrder = Main.AppLayoutIndex
		if Data.HighlightColor then App.Main.Highlight.BackgroundColor3 = Data.HighlightColor end
		if Data.ButtonColor then App.Main.BackgroundColor3 = Data.ButtonColor end
		App.Main.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
				App.Main.BackgroundTransparency = 0
				App.Main.BackgroundColor3 = AppGradient and Color3.new(1, 1, 1) or (Data.HoverColor or Settings.Theme.ButtonHover)
			end
		end)
		App.Main.InputEnded:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
				App.Main.BackgroundTransparency = AppGradient and (Data.Open and 0 or 0.045) or (Data.Open and 0 or 1)
				App.Main.BackgroundColor3 = AppGradient and Color3.new(1, 1, 1) or (Data.ButtonColor or Settings.Theme.Button)
			end
		end)
		App.Main.MouseButton1Click:Connect(function()
			if Data.Open then Disable() else Enable() end
		end)
		local Window = Data.Window
		if Window then
			Window.OnActivate:Connect(function() Enable(true) end)
			Window.OnDeactivate:Connect(function() Disable(true) end)
		end
		App.Visible = true
		App.Parent = Main.AppsContainer
		task.defer(function()
			if Main.AppsFrame and Main.AppsContainerGrid then
				Main.AppsFrame.CanvasSize = UDim2.new(0, 0, 0, math.max(Main.AppsFrame.AbsoluteSize.Y, Main.AppsContainerGrid.AbsoluteContentSize.Y + 8))
			end
		end)
		Control.Enable = Enable
		Control.Disable = Disable
		Main.MenuApps[Data.Name] = Control
		return Control
	end

	Main.CreateDexHelper = function()
		if Main.DexHelper and Main.DexHelper.Gui and Main.DexHelper.Gui.Parent then
			return Main.DexHelper
		end

		local AIConfigGet = ResolveAIConfig
		local AIRequestBuilder = type(Main) == "table" and Main.BuildAIProviderRequest or nil
		local AIResponseReader = type(Main) == "table" and Main.ExtractAIProviderText or nil
		local function GetRequestBuilder()
			local Current = type(Main) == "table" and Main.BuildAIProviderRequest or nil
			if type(Current) == "function" then AIRequestBuilder = Current end
			return AIRequestBuilder
		end
		local function GetResponseReader()
			local Current = type(Main) == "table" and Main.ExtractAIProviderText or nil
			if type(Current) == "function" then AIResponseReader = Current end
			return AIResponseReader
		end
		local function ResolveAIConfig()
			if type(AIConfigGet) == "function" then
				local ResolveSuccess, Config = pcall(AIConfigGet)
				if ResolveSuccess and type(Config) == "table" then
					return Config
				end
			end
			local ScriptSettings = Settings and Settings.ScriptViewer or {}
			local Provider = tostring(ScriptSettings.AIProvider or "Groq")
			local ProviderKeys = type(ScriptSettings.AIKeys) == "table" and ScriptSettings.AIKeys or {}
			local ApiKey = tostring(ProviderKeys[Provider] or "")
			if ApiKey == "" and tostring(ScriptSettings.AIKeyProvider or "Groq") == Provider then
				ApiKey = tostring(ScriptSettings.AIKey or "")
			end
			local Profiles = Main.AIProviderProfiles or {}
			local Profile = Profiles[Provider] or Profiles.Groq or {}
			local Model = tostring(ScriptSettings.AIModel or Profile.DefaultModel or "")
			local EndpointOverrides = type(ScriptSettings.AIEndpointOverrides) == "table" and ScriptSettings.AIEndpointOverrides or {}
			local Endpoint = tostring(EndpointOverrides[Provider] or ScriptSettings.AIEndpoint or Profile.Endpoint or "")
			if type(Main.BuildAIProviderEndpoint) == "function" then
				Endpoint = Main.BuildAIProviderEndpoint(Provider, Model, Endpoint)
			end
			return {
				Enabled = ScriptSettings.AIEnabled ~= false,
				Provider = Provider,
				Protocol = Profile.Protocol,
				Endpoint = tostring(Endpoint or ""),
				ApiKey = ApiKey,
				Model = Model,
				Temperature = tonumber(ScriptSettings.AITemperature) or 0.1,
				MaxTokens = tonumber(ScriptSettings.AIMaxTokens) or 8000,
				Headers = type(ScriptSettings.AIHeaders) == "table" and ScriptSettings.AIHeaders or {},
				MaxTokenField = Profile.MaxTokenField,
				RequestOptions = Profile.RequestOptions or {}
			}
		end

		local Info = Main.GetDeviceInfo()
		local ViewportWidth = tonumber(Info.ViewportWidth) or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 800
		local IsCompact = Info.IsCompact == true or ViewportWidth < 600
		local AvatarAreaExtra = IsCompact and 36 or 56
		local RootWidth = math.max(240, math.min(ViewportWidth - 24, IsCompact and (360 + AvatarAreaExtra) or (520 + AvatarAreaExtra)))
		local AvatarTopY = math.min(149, math.max(24, (tonumber(Info.ViewportHeight) or 700) - 174))
		local AvatarHeight = IsCompact and 96 or 123
		local SpriteScale = 1.08
		local MaxAspect = 0.995
		local AvatarWidth = math.ceil(AvatarHeight * MaxAspect * SpriteScale) + 60 + AvatarAreaExtra
		local PanelHeadInset = math.floor(AvatarHeight * (57 / 341) + 0.5)
		local RootBaseHeight = 154
		local AvatarInnerTop = PanelHeadInset + math.floor((RootBaseHeight - AvatarHeight) / 2)
		local SpriteHeight = math.max(1, math.floor(AvatarHeight * SpriteScale + 0.5))
		local AvatarButtonHeight = AvatarHeight + 23
		local SpriteTop = math.floor((AvatarButtonHeight - SpriteHeight) / 2)
		local CompanionTopY = AvatarTopY + AvatarInnerTop - SpriteTop
		local TextLeft = math.max(AvatarHeight * SpriteScale + 12, AvatarWidth - (IsCompact and 60 or 78))
		local Nickname = tostring(Settings.DexHelperName or Main.DexHelperName or "")
		Nickname = Nickname:gsub("^%s+", ""):gsub("%s+$", "")

		if Nickname == "" and type(env.readfile) == "function" then
			local ReadSuccess, StoredName = pcall(env.readfile, "dex/DexHelperName.txt")
			if ReadSuccess and type(StoredName) == "string" then
				Nickname = StoredName:gsub("^%s+", ""):gsub("%s+$", "")
			end
		end

		local Helper = {
			IsOpen = false,
			Animating = false,
			DialogueToken = 0,
			AIRequestToken = 0,
			CommandToken = 0,
			LastReply = "",
			Nickname = Nickname,
			Introduced = Settings.DexHelperIntroCompleted == true
		}

		local function SaveHelperData()
			Settings.DexHelperName = Nickname
			Settings.DexHelperIntroCompleted = Helper.Introduced
			Main.DexHelperName = Nickname
			if type(env.writefile) == "function" then
				pcall(env.writefile, "dex/DexHelperName.txt", Nickname)
				if type(Main.ExportSettings) == "function" then
					local ExportSuccess, ExportedSettings = pcall(Main.ExportSettings)
					if ExportSuccess and type(ExportedSettings) == "string" then
						pcall(env.writefile, "DexPlusPlusSettings.json", ExportedSettings)
					end
				end
			end
			if type(Main.SaveCurrentSettings) == "function" then
				pcall(Main.SaveCurrentSettings)
			end
		end

		local TextureId = "rbxassetid://126946675773281"
		local GridColumns = 15
		local GridRows = 20
		local TotalFrames = 300
		local FrameCount = 60
		local SpriteViewSize = math.max(1, math.floor(AvatarHeight * SpriteScale + 0.5))
		local SpriteFrameSize = SpriteViewSize
		local PlaybackFPS = 25
		local FrameInterval = 1 / PlaybackFPS
