		local function LoadSpriteSheet(ImageObject)
			ImageObject.Image = TextureId
			ImageObject.ImageRectOffset = Vector2.zero
			ImageObject.ImageRectSize = Vector2.zero
			ImageObject.Position = UDim2.fromOffset(0, 0)
			ImageObject.Size = UDim2.fromOffset(SpriteFrameSize * GridColumns, SpriteFrameSize * GridRows)
			ImageObject.ScaleType = Enum.ScaleType.Stretch
			ImageObject.ImageColor3 = Color3.new(1, 1, 1)
			ImageObject.ImageTransparency = 0
			ImageObject.Visible = true
			task.spawn(function()
				for Attempt = 1, 3 do
					if not ImageObject.Parent then
						return
					end
					local FetchSucceeded = false
					local FetchCallbackReceived = false
					local PreloadSucceeded = pcall(function()
						service.ContentProvider:PreloadAsync({ImageObject}, function(_, FetchStatus)
							FetchCallbackReceived = true
							FetchSucceeded = FetchStatus == Enum.AssetFetchStatus.Success
						end)
					end)
					local LoadOK, IsLoaded = pcall(function()
						return ImageObject.IsLoaded
					end)
					if PreloadSucceeded and FetchCallbackReceived and FetchSucceeded then
						return
					end
					if LoadOK and IsLoaded then
						return
					end
					if Attempt < 3 then
						ImageObject.Image = ""
						task.wait(0.2)
						ImageObject.Image = TextureId
						ImageObject.ImageRectOffset = Vector2.zero
						ImageObject.ImageRectSize = Vector2.zero
						ImageObject.Position = UDim2.fromOffset(0, 0)
						ImageObject.Size = UDim2.fromOffset(SpriteFrameSize * GridColumns, SpriteFrameSize * GridRows)
					end
				end
			end)
		end

