		local function SetSpriteFrame(FrameIndex)
			local SafeFrameIndex = math.clamp(math.floor(tonumber(FrameIndex) or 0), 0, TotalFrames - 1)
			local Column = SafeFrameIndex % GridColumns
			local Row = math.floor(SafeFrameIndex / GridColumns)
			if Column >= GridColumns or Row >= GridRows then
				return
			end
			SpriteSheetImage.ImageRectOffset = Vector2.zero
			SpriteSheetImage.ImageRectSize = Vector2.zero
			SpriteSheetImage.Position = UDim2.fromOffset(-Column * SpriteFrameSize, -Row * SpriteFrameSize)
			SpriteSheetImage.Size = UDim2.fromOffset(SpriteFrameSize * GridColumns, SpriteFrameSize * GridRows)
		end

		local AnimToken = 0
		local SpriteState = "Idle"
		local function SetSpriteState(State, OneShot)
			SpriteState = SpriteStates[State] and State or "Idle"
			AnimToken = AnimToken + 1
			local ActiveToken = AnimToken
			local AnimationState = {
				Token = ActiveToken,
				Completed = false,
				Cancelled = false
			}
			local AnimationName = SpriteStates[State] or "Open"
			local AnimationStart = AnimationStarts[AnimationName]
			local CurrentFrame = 0
			local FrameAccumulator = 0
			SetSpriteFrame(AnimationStart)
			task.spawn(function()
				while Helper.IsOpen and ActiveToken == AnimToken and AvatarButton.Parent and SpriteViewport.Parent and SpriteSheetImage.Parent do
					local DeltaTime = service.RunService.RenderStepped:Wait()
					FrameAccumulator = FrameAccumulator + DeltaTime
					while FrameAccumulator >= FrameInterval do
						FrameAccumulator = FrameAccumulator - FrameInterval
						if CurrentFrame + 1 >= FrameCount then
							if OneShot then
								AnimationState.Completed = true
								if State == "Finished" and ActiveToken == AnimToken then
									SetSpriteState("Idle", false)
								end
								return
							end
							CurrentFrame = 0
						else
							CurrentFrame = CurrentFrame + 1
						end
						SetSpriteFrame(AnimationStart + CurrentFrame)
					end
				end
				if not AnimationState.Completed then
					AnimationState.Cancelled = true
				end
			end)
			return AnimationState
		end
		Helper.SetSpriteState = SetSpriteState
		SetSpriteFrame(AnimationStarts.Open)


