		local TalkPulseToken = 0
		local function StartFinTalkPulse(DialogueToken, IsCrashoutSpeech)
			TalkPulseToken = TalkPulseToken + 1
			local ActivePulseToken = TalkPulseToken
			task.spawn(function()
				while Helper.IsOpen and DialogueToken == Helper.DialogueToken and ActivePulseToken == TalkPulseToken and AvatarScale.Parent do
					local PeakScale = IsCrashoutSpeech and 1.065 or 1.035
					local RiseTime = IsCrashoutSpeech and 0.075 or 0.11
					local FallTime = IsCrashoutSpeech and 0.07 or 0.10
					local RiseTween = service.TweenService:Create(AvatarScale, TweenInfo.new(RiseTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = PeakScale})
					RiseTween:Play()
					task.wait(RiseTime)
					if not Helper.IsOpen or DialogueToken ~= Helper.DialogueToken or ActivePulseToken ~= TalkPulseToken then break end
					local FallTween = service.TweenService:Create(AvatarScale, TweenInfo.new(FallTime, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {Scale = 1})
					FallTween:Play()
					task.wait(FallTime + (IsCrashoutSpeech and 0.035 or 0.09))
				end
				if ActivePulseToken == TalkPulseToken and Helper.IsOpen and AvatarScale.Parent then
					service.TweenService:Create(AvatarScale, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
				end
			end)
		end

