		local SpeechBaseHeight = 48
		local SpeechExpanded = false
		local SpeechLayoutToken = 0
		local function FitSpeech(Message, AnimateLayout)
			local TextWidth = math.max(80, RootWidth - TextLeft - 12)
			local TextBounds = service.TextService:GetTextSize(tostring(Message or ""), SpeechText.TextSize, SpeechText.Font, Vector2.new(TextWidth, 10000))
			local MaxSpeechHeight = math.max(220, (tonumber(Info.ViewportHeight) or 700) - CompanionTopY - 76)
			local SpeechHeight = math.clamp(TextBounds.Y + 2, SpeechBaseHeight, MaxSpeechHeight)
			local HintPosition = UDim2.new(0, TextLeft, 0, 26 + SpeechHeight + 4)
			local InputPosition = UDim2.new(0, TextLeft, 0, 26 + SpeechHeight + 25)
			local TargetRootHeight = math.max(RootBaseHeight, InputPosition.Y.Offset + InputRow.Size.Y.Offset + 10)
			local WasExpanded = SpeechExpanded
			SpeechExpanded = TargetRootHeight > RootBaseHeight + 8
			SpeechLayoutToken = SpeechLayoutToken + 1
			SpeechText.Size = UDim2.new(1, -TextLeft - 12, 0, SpeechHeight)
			if AnimateLayout then
				local LayoutTweenInfo = TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
				service.TweenService:Create(HintText, LayoutTweenInfo, {Position = HintPosition}):Play()
				service.TweenService:Create(InputRow, LayoutTweenInfo, {Position = InputPosition}):Play()
				service.TweenService:Create(Root, LayoutTweenInfo, {Size = UDim2.new(0, RootWidth, 0, TargetRootHeight)}):Play()
			else
				HintText.Position = HintPosition
				InputRow.Position = InputPosition
				Root.Size = UDim2.new(0, RootWidth, 0, TargetRootHeight)
			end
			return SpeechExpanded, WasExpanded
		end

