		local function ContainsAny(Text, Terms)
			for _, Term in ipairs(Terms) do
				if string.find(Text, Term, 1, true) then
					return true
				end
			end
			return false
		end

		local function GetScriptObj()
			local ExplorerApp = Apps.Explorer
			local Selection = ExplorerApp and ExplorerApp.Selection
			local SelectedList = Selection and Selection.List
			for _, Entry in ipairs(SelectedList or {}) do
				local Object = Entry and Entry.Obj
				if Object and (Object:IsA("LocalScript") or Object:IsA("ModuleScript") or (Object:IsA("Script") and type(env.isViableDecompileScript) == "function" and env.isViableDecompileScript(Object))) then
					return Object
				end
			end
			return nil
		end

		local function GetCurrentCode()
			local Viewer = Apps.ScriptViewer
			if not Viewer then
				return "", nil
			end
			local CurrentScript = type(Viewer.GetCurrentScript) == "function" and Viewer.GetCurrentScript() or nil
			local CurrentSource = type(Viewer.GetCurrentSource) == "function" and Viewer.GetCurrentSource() or ""
			if type(CurrentSource) == "string" and CurrentSource:gsub("%s+", "") ~= "" then
				return CurrentSource, CurrentScript
			end
			local SelectedScript = GetScriptObj()
			if SelectedScript and type(Viewer.ViewScript) == "function" then
				local ViewSuccess = pcall(Viewer.ViewScript, SelectedScript)
				if ViewSuccess then
					CurrentSource = type(Viewer.GetCurrentSource) == "function" and Viewer.GetCurrentSource() or ""
					return type(CurrentSource) == "string" and CurrentSource or "", SelectedScript
				end
			end
			return "", CurrentScript
		end

		local function ShowDecompiler()
			local Viewer = Apps.ScriptViewer
			if Viewer and Viewer.Window then
				pcall(function()
					Viewer.Window:Show()
				end)
			end
		end

		local function FindScriptByName(ScriptName)
			local SearchName = string.lower(tostring(ScriptName or "")):gsub("%.lua$", "")
			SearchName = SearchName:gsub("^%s+", ""):gsub("%s+$", "")
			local SearchKey = SearchName:gsub("[%s_%-%.]", "")
			if SearchKey == "" then
				return nil
			end
			local SearchSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not SearchSuccess or type(Descendants) ~= "table" then
				return nil
			end
			local PartialMatch
			for _, Object in ipairs(Descendants) do
				if Object:IsA("LocalScript") or Object:IsA("ModuleScript") or (Object:IsA("Script") and type(env.isViableDecompileScript) == "function" and env.isViableDecompileScript(Object)) then
					local ObjectKey = string.lower(Object.Name):gsub("[%s_%-%.]", "")
					if ObjectKey == SearchKey then
						return Object
					elseif not PartialMatch and (ObjectKey:find(SearchKey, 1, true) or SearchKey:find(ObjectKey, 1, true)) then
						PartialMatch = Object
					end
				end
			end
			return PartialMatch
		end

		local function ListClientScripts()
			local SearchSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not SearchSuccess or type(Descendants) ~= "table" then
				return 0, {}
			end
			local TotalCount = 0
			local ScriptNames = {}
			for _, Object in ipairs(Descendants) do
				if Object:IsA("LocalScript") or Object:IsA("ModuleScript") or (Object:IsA("Script") and type(env.isViableDecompileScript) == "function" and env.isViableDecompileScript(Object)) then
					TotalCount = TotalCount + 1
					if #ScriptNames < 7 then
						table.insert(ScriptNames, Object.Name .. " (" .. Object.ClassName .. ")")
					end
				end
			end
			return TotalCount, ScriptNames
		end

		local function ExtractScriptName(Query)
			local QuotedName = Query:match('"(.-)"') or Query:match("'(.-)'")
			if QuotedName and QuotedName ~= "" then
				return QuotedName
			end
			local LowerQuery = string.lower(Query)
			local Candidate = LowerQuery:match("name%s+(.+)$")
				or LowerQuery:match("called%s+(.+)$")
				or LowerQuery:match("named%s+(.+)$")
				or LowerQuery:match("script%s+([%w_%.%-]+)%s*$")
				or LowerQuery:match("([%w_%.%-]+)%s+script%s*$")
			if not Candidate then
				Candidate = LowerQuery:match("^%s*open%s+(.+)$")
					or LowerQuery:match("^%s*find%s+(.+)$")
					or LowerQuery:match("^%s*locate%s+(.+)$")
					or LowerQuery:match("^%s*load%s+(.+)$")
			end
			if Candidate then
				Candidate = Candidate:gsub("[%p]+$", ""):gsub("^%s+", ""):gsub("%s+$", "")
				Candidate = Candidate:gsub("^the%s+", ""):gsub("^a%s+", "")
				Candidate = Candidate:gsub("^code%s+for%s+me%s+that%s+has%s+its%s+name%s+", "")
				Candidate = Candidate:gsub("^code%s+named%s+", "")
				Candidate = Candidate:gsub("^script%s+named%s+", "")
				Candidate = Candidate:gsub("^is%s+", "")
				for _, Suffix in ipairs({" please", " pls", " for me", " thanks", " if possible", " right now"}) do
					if Candidate:sub(-#Suffix) == Suffix then
						Candidate = Candidate:sub(1, -#Suffix - 1):gsub("%s+$", "")
					end
				end
				Candidate = Candidate:gsub("%.lua$", "")
				if Candidate ~= "" and Candidate ~= "script" and Candidate ~= "code" and Candidate ~= "local" and Candidate ~= "module" and Candidate ~= "please" and Candidate ~= "for" and Candidate ~= "me" then
					return Candidate
				end
			end
			local FinalWord = LowerQuery:match("([%w_%.%-]+)%s*[%.%!%?]*$")
			if FinalWord and not ContainsAny(FinalWord, {"script", "code", "local", "module", "me", "please", "for", "it"}) then
				return FinalWord
			end
			return nil
		end

		local function IsOpenIntent(LowerQuery)
			if ContainsAny(LowerQuery, {"open script", "open code", "open a code", "open the code", "find script", "find code", "locate script", "load script", "script named", "code named", "local script", "module script", "decompile script", "can you open", "could you open", "please open", "show me the script", "show me the code", "view script"}) then
				return true
			end
			if LowerQuery:match("^%s*open%s+.+$") or LowerQuery:match("^%s*find%s+.+$") or LowerQuery:match("^%s*locate%s+.+$") then
				return not ContainsAny(LowerQuery, {"explorer", "notepad", "script viewer", "decompiler", "developer tools", "console", "save instance", "model viewer", "3d viewer"})
			end
			return false
		end

		local function OpenScriptObject(Object)
			if not Object then
				return false, "I couldn't find that script in the client-visible instance tree."
			end
			local ExplorerApp = Apps.Explorer
			if ExplorerApp then
				if ExplorerApp.Window then
					pcall(function()
						ExplorerApp.Window:Show()
					end)
				end
				if type(ExplorerApp.ViewObj) == "function" then
					pcall(ExplorerApp.ViewObj, Object)
				end
			end
			local Viewer = Apps.ScriptViewer
			if not Viewer or type(Viewer.ViewScript) ~= "function" then
				return false, "Decompiler isn't ready yet. Try again after Dex finishes loading."
			end
			local OpenSuccess, OpenError = pcall(Viewer.ViewScript, Object)
			if not OpenSuccess then
				return false, "I found it, but Decompiler couldn't open it: " .. tostring(OpenError)
			end
			return true, Object:GetFullName()
		end

		local function GetCodeInfo(Source)
			local _, FunctionCount = Source:gsub("function%s*[%w_%.:]*%s*%(", "")
			local _, EventCount = Source:gsub(":Connect%s*%(", "")
			local _, LoopCount = Source:gsub("for%s+", "")
			local _, ServiceCount = Source:gsub("GetService%s*%(", "")
			local DetectedServices = {}
			for ServiceName in Source:gmatch("GetService%s*%(%s*['\"]([^'\"]+)['\"]%s*%)") do
				if not table.find(DetectedServices, ServiceName) and #DetectedServices < 4 then
					table.insert(DetectedServices, ServiceName)
				end
			end
			local Summary = "I scanned the code locally. I found " .. tostring(FunctionCount) .. " function declaration(s), " .. tostring(EventCount) .. " event connection(s), " .. tostring(LoopCount) .. " for-loop(s), and " .. tostring(ServiceCount) .. " service lookup(s)."
			if #DetectedServices > 0 then
				Summary = Summary .. " Services used: " .. table.concat(DetectedServices, ", ") .. "."
			end
			local AIConfig = ResolveAIConfig()
			if AIConfig.Enabled and AIConfig.ApiKey ~= "" then
				Summary = Summary .. " Ask me to explain it again for a deeper AI walkthrough."
			else
				Summary = Summary .. " For a deeper line-by-line explanation, add an endpoint and key in Dex Settings or EmbeddedAIConfig."
			end
			return Summary
		end

		local GetDexInfo
		local RequestFinAI
		local function SendFinAIRequest(SystemPrompt, Source, Callback)
			local AIConfig = ResolveAIConfig()
			if not AIConfig.Enabled then
				return false, "Dex Settings AI is disabled."
			end
			if tostring(AIConfig.ApiKey or ""):gsub("%s+", "") == "" then
				return false, "No API key is configured for Dex Settings AI."
			end
			if tostring(AIConfig.Endpoint or "") == "" or tostring(AIConfig.Model or "") == "" then
				return false, "Dex Settings AI is missing an endpoint or model."
			end
			local HttpService = service.HttpService
			local RuntimeContext = type(GetDexInfo) == "function" and GetDexInfo() or "Dex runtime context is unavailable."
			local SystemText = tostring(SystemPrompt or "") .. "\n\nLive Valm Dex runtime context:\n" .. RuntimeContext
			local UserText = tostring(Source or ""):sub(1, 20000)
			local Protocol = tostring(AIConfig.Protocol or "ChatCompletions")
			local MaxTokens = math.min(tonumber(AIConfig.MaxTokens) or 2200, 2200)
			local Temperature = tonumber(AIConfig.Temperature) or 0.1
			local Builder = GetRequestBuilder()
			if type(Builder) ~= "function" then
				return false, "The shared AI request builder is unavailable. Reopen Dex Helper after Dex finishes loading."
			end
			local BuildSuccess, RequestPayload, RequestHeaders, RequestEndpoint, RequestBuildError = pcall(
				Builder,
				AIConfig,
				SystemText,
				UserText,
				MaxTokens,
				Temperature
			)
			if not BuildSuccess then
				return false, "Could not build the AI request: " .. tostring(RequestPayload)
			end
			if not RequestPayload then
				return false, RequestBuildError or "Could not build the Dex Settings AI request."
			end
			local EncodeSuccess, Body = pcall(HttpService.JSONEncode, HttpService, RequestPayload)
			if not EncodeSuccess then
				return false, "Could not encode the Dex Settings AI request: " .. tostring(Body)
			end
			local RequestFunction = (env and env.request) or (syn and syn.request) or (http and http.request) or http_request or request
			if type(RequestFunction) ~= "function" then
				return false, "This executor doesn't provide an HTTP request function."
			end
			task.spawn(function()
				local RequestSuccess, Response = pcall(RequestFunction, {
					Url = RequestEndpoint,
					Method = "POST",
					Headers = RequestHeaders,
					Body = Body
				})
				if not RequestSuccess or type(Response) ~= "table" then
					pcall(Callback, nil, "The " .. tostring(AIConfig.Provider) .. " request failed: " .. tostring(Response))
					return
				end
				local StatusValue = Response.StatusCode or Response.Status
				local StatusCode = tonumber(StatusValue) or tonumber(tostring(StatusValue or ""):match("(%d%d%d)")) or (Response.Success == true and 200 or 0)
				local ResponseBody = Response.Body or Response.body or Response.ResponseBody or ""
				if StatusCode < 200 or StatusCode >= 300 then
					local ErrorText = tostring(ResponseBody)
					local DecodeOK, DecodeError = pcall(HttpService.JSONDecode, HttpService, ErrorText)
					if DecodeOK and type(DecodeError) == "table" then
						ErrorText = tostring((DecodeError.error and (DecodeError.error.message or DecodeError.error.type)) or DecodeError.message or ErrorText)
					end
					pcall(Callback, nil, ("%s returned HTTP %d: %s"):format(tostring(AIConfig.Provider), StatusCode, ErrorText:sub(1, 420)))
					return
				end
				local DecodeSuccess, Decoded = pcall(HttpService.JSONDecode, HttpService, tostring(ResponseBody))
				local Content
				if DecodeSuccess and type(Decoded) == "table" then
					local Reader = GetResponseReader()
					if type(Reader) == "function" then
						local ReadSuccess, ReadResult = pcall(Reader, Decoded, Protocol)
						if ReadSuccess then Content = ReadResult end
					end
				end
				if type(Content) ~= "string" or Content == "" then
					pcall(Callback, nil, "The " .. tostring(AIConfig.Provider) .. " response did not contain text.")
					return
				end
				Content = Content:gsub("^%s+", ""):gsub("%s+$", "")
				if #Content > 6000 then Content = Content:sub(1, 5997) .. "..." end
				pcall(Callback, Content)
			end)
			return true
		end

		local function OpenRelatedTool(LowerQuery)
			local TargetName
			if ContainsAny(LowerQuery, {"developer tools", "device detection", "device info"}) then
				TargetName = "DeveloperTools"
			elseif ContainsAny(LowerQuery, {"explorer", "instance tree"}) then
				TargetName = "Explorer"
			elseif ContainsAny(LowerQuery, {"properties", "property panel", "property window", "object properties", "inspector"}) then
				TargetName = "Properties"
			elseif ContainsAny(LowerQuery, {"code editing", "code editor", "text editor", "script editor"}) then
				TargetName = "Code Editing"
			elseif ContainsAny(LowerQuery, {"notepad", "notes window", "saved notes"}) then
				TargetName = "Notepad"
			elseif ContainsAny(LowerQuery, {"script viewer", "decompiler", "decompile"}) then
				TargetName = "ScriptViewer"
			elseif ContainsAny(LowerQuery, {"console", "output log"}) then
				TargetName = "Console"
			elseif ContainsAny(LowerQuery, {"save instance", "save model", "export instance"}) then
				TargetName = "SaveInstance"
			elseif ContainsAny(LowerQuery, {"3d viewer", "model viewer"}) then
				TargetName = "ModelViewer"
			elseif ContainsAny(LowerQuery, {"settings", "preferences", "configuration"}) then
				TargetName = "SettingsWindow"
			elseif ContainsAny(LowerQuery, {"runtime options", "performance mode", "mobile ui"}) then
				TargetName = "Runtime Options"
			elseif ContainsAny(LowerQuery, {"todo", "to-do", "task list", "task manager"}) then
				TargetName = "Todo"
			elseif ContainsAny(LowerQuery, {"remote spy", "remotespy"}) then
				TargetName = "Remote Spy"
			elseif ContainsAny(LowerQuery, {"dex helper", "fin panel", "helper panel"}) then
				TargetName = "DexHelper"
			end
			if not TargetName then
				for _, PluginRecord in ipairs(Main.Plugins or {}) do
					local PluginData = PluginRecord and PluginRecord.PluginData or {}
					local FriendlyName = tostring(PluginData.FriendlyName or "")
					local InternalName = tostring(PluginData.Name or "")
					if (FriendlyName ~= "" and LowerQuery:find(string.lower(FriendlyName), 1, true)) or (InternalName ~= "" and LowerQuery:find(string.lower(InternalName), 1, true)) then
						TargetName = FriendlyName ~= "" and FriendlyName or InternalName
						local PluginWindow = PluginRecord.Window or PluginData.Window or (PluginRecord.App and PluginRecord.App.Window)
						if PluginWindow then
							pcall(function() PluginWindow:Show() PluginWindow:Focus() end)
							return TargetName
						end
					end
				end
			end
			if TargetName == "DexHelper" then
				if Main.DexHelper and type(Main.DexHelper.Open) == "function" then
					pcall(Main.DexHelper.Open)
					return TargetName
				end
				return nil
			end
			if TargetName then
				if type(Main.OpenDexWindow) == "function" then
					local OpenSuccess, OpenResult = pcall(Main.OpenDexWindow, TargetName)
					if OpenSuccess and OpenResult then return TargetName end
				end
				local Target = Apps[TargetName]
				local Window = Target and Target.Window
				if not Window and Main.WindowRegistry then Window = Main.WindowRegistry[TargetName] end
				if not Window and Main.PowerWindows then
					local PowerWindowNames = { ["Runtime Options"] = "Runtime", ["Code Editing"] = "Notepad" }
					Window = Main.PowerWindows[PowerWindowNames[TargetName] or TargetName]
				end
				if Window then
					pcall(function() Window:Show() Window:Focus() end)
					if TargetName == "DeveloperTools" and Target and type(Target.ShowPage) == "function" then
						pcall(function()
							Target.ShowPage("Device")
							if type(Target.RefreshDeviceInfo) == "function" then Target.RefreshDeviceInfo() end
						end)
					end
					return TargetName
				end
			end
			return nil
		end

		local function NormalizeFinName(Value)
			local NormalizedValue = string.lower(tostring(Value or ""))
			NormalizedValue = NormalizedValue:gsub("[%c]", " ")
			NormalizedValue = NormalizedValue:gsub("[%s_%-%.%p]", "")
			return NormalizedValue
		end

		local function GetObjectFullName(Object)
			local PathSuccess, ObjectPath = pcall(function()
				return Object:GetFullName()
			end)
			return PathSuccess and tostring(ObjectPath) or tostring(Object)
		end

		local function EnsureExpNode(Object, Depth)
			if typeof(Object) ~= "Instance" then return nil end
			local ExistingNode = nodes[Object]
			if ExistingNode then return ExistingNode end
			Depth = (Depth or 0) + 1
			if Depth > 256 then return nil end
			local ParentSuccess, ParentObject = pcall(function() return Object.Parent end)
			local ParentNode
			if ParentSuccess and ParentObject then
				ParentNode = nodes[ParentObject] or EnsureExpNode(ParentObject, Depth)
			end
			if not ParentNode then ParentNode = nodes[game] end
			if not ParentNode then return nil end
			local NewNode = {Obj = Object, Parent = ParentNode}
			nodes[Object] = NewNode
			table.insert(ParentNode, NewNode)
			return NewNode
		end

		local function CopyFinText(Value)
			local ClipboardFunction = (env and env.setclipboard) or setclipboard or toclipboard
			if type(ClipboardFunction) ~= "function" then
				return false, "Your executor doesn't expose a clipboard function."
			end
			local CopySuccess, CopyError = pcall(ClipboardFunction, tostring(Value or ""))
			return CopySuccess, CopySuccess and "Copied to your clipboard." or ("Clipboard copy failed: " .. tostring(CopyError))
		end

		local function GetSelectedObject()
			local ExplorerApp = Apps.Explorer
			local Selection = ExplorerApp and ExplorerApp.Selection
			for _, Entry in ipairs(Selection and Selection.List or {}) do
				local Object = Entry and Entry.Obj
				if Object then
					return Object
				end
			end
			return nil
		end

		GetDexInfo = function()
			local AvailableApps = {}
			local AddedAppNames = {}
			local function AddAvailableApp(AppName)
				local NormalizedName = tostring(AppName or "")
				if NormalizedName ~= "" and not AddedAppNames[NormalizedName] then
					AddedAppNames[NormalizedName] = true
					AvailableApps[#AvailableApps + 1] = NormalizedName
				end
			end
			for AppName, App in pairs(Apps or {}) do
				if type(App) == "table" and App.Window then AddAvailableApp(AppName) end
			end
			for WindowName, Window in pairs(Main.WindowRegistry or {}) do
				if Window then AddAvailableApp(WindowName) end
			end
			for _, PluginRecord in ipairs(Main.Plugins or {}) do
				local PluginData = PluginRecord and PluginRecord.PluginData or {}
				if PluginRecord and PluginRecord.Window then AddAvailableApp(PluginData.FriendlyName or PluginData.Name) end
			end
			table.sort(AvailableApps)
			local SelectedObject = GetSelectedObject()
			local SelectedPath = SelectedObject and GetObjectFullName(SelectedObject) or "Nothing is selected in Explorer."
			local CurrentSource, CurrentScript = GetCurrentCode()
			local OpenScript = CurrentScript and GetObjectFullName(CurrentScript) or "No script is open in the Decompiler."
			local DeviceInfo = {}
			if type(Main.GetDeviceInfo) == "function" then
				local DeviceSuccess, DeviceResult = pcall(Main.GetDeviceInfo)
				if DeviceSuccess and type(DeviceResult) == "table" then DeviceInfo = DeviceResult end
			end
			local ContextLines = {
				"Available Dex apps and windows: " .. (#AvailableApps > 0 and table.concat(AvailableApps, ", ") or "Not available"),
				"Selected Explorer object: " .. tostring(SelectedPath),
				"Current Decompiler script: " .. tostring(OpenScript),
				"Current Decompiler source length: " .. tostring(#tostring(CurrentSource or "")) .. " bytes",
				"Dex plugins can be opened through their registered windows when loaded.",
				"Dex object operations include natural-language smart selection, workspace audits, inspection, property editing, CollectionService tags, welds, PrimaryPart setup, and physical-property tuning.",
				"Device: " .. tostring(DeviceInfo.Device or "Unknown") .. " / " .. tostring(DeviceInfo.Platform or "Unknown"),
				"Dex theme: dark grayscale"
			}
			return table.concat(ContextLines, "\n")
		end

		local function SelectExplorerObject(Object)
			if typeof(Object) ~= "Instance" then
				return false, "I couldn't find a valid instance to select."
			end
			local ExplorerApp = Apps.Explorer
			if not ExplorerApp then
				return false, "Explorer isn't ready yet."
			end
			local Node = EnsureExpNode(Object)
			if not Node then
				return false, "I found the instance, but Explorer couldn't create a node for it."
			end
			if type(ExplorerApp.Refresh) == "function" then pcall(ExplorerApp.Refresh) end
			if ExplorerApp.Window then
				pcall(function()
					ExplorerApp.Window:Show()
				end)
			end
			if type(ExplorerApp.ViewObj) == "function" then
				local ViewSuccess, ViewError = pcall(ExplorerApp.ViewObj, Object)
				if not ViewSuccess then
					return false, "I found it, but Explorer couldn't focus that instance: " .. tostring(ViewError)
				end
			elseif type(ExplorerApp.ViewNode) == "function" then
				local ViewSuccess, ViewError = pcall(ExplorerApp.ViewNode, Node)
				if not ViewSuccess then
					return false, "I found it, but Explorer couldn't reveal that instance: " .. tostring(ViewError)
				end
			end
			local Selection = ExplorerApp.Selection
			if not Selection then
				return false, "Explorer's selection controller isn't available."
			end
			local SelectSuccess, SelectError = pcall(function()
				if type(Selection.Set) == "function" then
					Selection:Set(Node)
				elseif type(Selection.SetTable) == "function" then
					Selection:SetTable({Node})
				else
					error("Explorer does not expose a selection setter")
				end
			end)
			if not SelectSuccess then
				return false, "Explorer couldn't select that instance: " .. tostring(SelectError)
			end
			local IsSelected = Selection.Map and Selection.Map[Node] == true
			if not IsSelected then
				for _, SelectedNode in ipairs(Selection.List or {}) do
					if SelectedNode == Node or SelectedNode and SelectedNode.Obj == Object then
						IsSelected = true
						break
					end
				end
			end
			if not IsSelected then
				return false, "Explorer opened the instance, but the selection did not stick."
			end
			if type(ExplorerApp.ForceUpdate) == "function" then pcall(ExplorerApp.ForceUpdate, true) end
			if type(ExplorerApp.Refresh) == "function" then pcall(ExplorerApp.Refresh) end
			local PropertiesApp = Apps.Properties
			if PropertiesApp then
				if PropertiesApp.Window then
					pcall(function() PropertiesApp.Window:Show() end)
				end
				if type(PropertiesApp.Update) == "function" then
					pcall(PropertiesApp.Update)
				end
				if type(PropertiesApp.Refresh) == "function" then
					pcall(PropertiesApp.Refresh)
				end
			end
			return true, GetObjectFullName(Object)
		end

		local function MatchesFinClass(Object, ClassFilter)
			local Filter = NormalizeFinName(ClassFilter)
			if Filter == "" or Filter == "any" or Filter == "object" or Filter == "instance" then
				return true
			elseif Filter == "remote" or Filter == "remotes" then
				return Object:IsA("RemoteEvent") or Object:IsA("RemoteFunction")
			elseif Filter == "remoteevent" or Filter == "remoteevents" then
				return Object:IsA("RemoteEvent")
			elseif Filter == "remotefunction" or Filter == "remotefunctions" then
				return Object:IsA("RemoteFunction")
			elseif Filter == "script" or Filter == "scripts" then
				return Object:IsA("LocalScript") or Object:IsA("ModuleScript")
			elseif Filter == "localscript" or Filter == "localscripts" then
				return Object:IsA("LocalScript")
			elseif Filter == "modulescript" or Filter == "modulescripts" then
				return Object:IsA("ModuleScript")
			elseif Filter == "part" or Filter == "parts" or Filter == "basepart" then
				return Object:IsA("BasePart")
			elseif Filter == "model" or Filter == "models" then
				return Object:IsA("Model")
			elseif Filter == "folder" or Filter == "folders" then
				return Object:IsA("Folder")
			elseif Filter == "tool" or Filter == "tools" then
				return Object:IsA("Tool")
			elseif Filter == "sound" or Filter == "sounds" then
				return Object:IsA("Sound")
			elseif Filter == "player" or Filter == "players" then
				return Object:IsA("Player")
			elseif Filter == "gui" or Filter == "guis" or Filter == "guiobject" or Filter == "guiobjects" then
				return Object:IsA("GuiObject") or Object:IsA("ScreenGui") or Object:IsA("BillboardGui") or Object:IsA("SurfaceGui")
			elseif Filter == "button" or Filter == "buttons" then
				return Object:IsA("GuiButton")
			elseif Filter == "label" or Filter == "labels" then
				return Object:IsA("TextLabel") or Object:IsA("ImageLabel")
			elseif Filter == "value" or Filter == "values" then
				return Object:IsA("ValueBase")
			elseif Filter == "constraint" or Filter == "constraints" then
				return Object:IsA("Constraint") or Object:IsA("JointInstance")
			elseif Filter == "attachment" or Filter == "attachments" then
				return Object:IsA("Attachment")
			elseif Filter == "effect" or Filter == "effects" then
				return Object:IsA("ParticleEmitter") or Object:IsA("Trail") or Object:IsA("Beam") or Object:IsA("Highlight") or Object:IsA("Smoke") or Object:IsA("Fire") or Object:IsA("Sparkles")
			elseif Filter == "light" or Filter == "lights" then
				return Object:IsA("Light")
			elseif Filter == "animation" or Filter == "animations" then
				return Object:IsA("Animation")
			elseif Filter == "humanoid" or Filter == "humanoids" then
				return Object:IsA("Humanoid")
			end
			local ClassSuccess, ClassMatch = pcall(function()
				return Object:IsA(tostring(ClassFilter))
			end)
			return ClassSuccess and ClassMatch == true
		end

		local function FindInstanceByName(SearchName, ClassFilter)
			local RawSearchName = tostring(SearchName or ""):gsub("^%s+", ""):gsub("%s+$", "")
			RawSearchName = RawSearchName:gsub('^["\'](.-)["\']$', "%1")
			RawSearchName = RawSearchName:gsub("^the%s+", "")
			local SearchKey = NormalizeFinName(RawSearchName)
			if SearchKey == "" then
				return nil, 0
			end
			local SearchSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not SearchSuccess or type(Descendants) ~= "table" then
				Descendants = {}
			end
			local SeenObjects = {}
			for _, Object in ipairs(Descendants) do SeenObjects[Object] = true end
			local NilFunction = type(env) == "table" and env.getnilinstances or nil
			if type(NilFunction) ~= "function" and type(getnilinstances) == "function" then NilFunction = getnilinstances end
			if type(NilFunction) == "function" then
				local NilSuccess, NilObjects = pcall(NilFunction)
				if NilSuccess and type(NilObjects) == "table" then
					for _, Object in ipairs(NilObjects) do
						if typeof(Object) == "Instance" and not SeenObjects[Object] then
							SeenObjects[Object] = true
							Descendants[#Descendants + 1] = Object
						end
					end
				end
			end
			local SearchTokens = {}
			for Token in string.lower(RawSearchName):gmatch("[%w_]+") do
				if #Token > 1 and Token ~= "the" and Token ~= "object" and Token ~= "instance" then
					SearchTokens[#SearchTokens + 1] = Token
				end
			end
			local BestObject
			local BestScore = 0
			local MatchCount = 0
			local ExactMatchCount = 0
			local SelectedObject = GetSelectedObject()
			for _, Object in ipairs(Descendants) do
				local ClassSuccess, ClassMatch = pcall(MatchesFinClass, Object, ClassFilter)
				if ClassSuccess and ClassMatch then
					local ObjectName = string.lower(tostring(Object.Name or ""))
					local ObjectKey = NormalizeFinName(ObjectName)
					local Score = 0
					if ObjectKey == SearchKey then
						Score = 10000
						ExactMatchCount = ExactMatchCount + 1
					elseif ObjectKey:sub(1, #SearchKey) == SearchKey then
						Score = 7600
					elseif ObjectKey:find(SearchKey, 1, true) then
						Score = 6800
					elseif SearchKey:find(ObjectKey, 1, true) and #ObjectKey >= 3 then
						Score = 6100
					else
						local MatchedTokens = 0
						for _, Token in ipairs(SearchTokens) do
							if ObjectName:find(Token, 1, true) then
								MatchedTokens = MatchedTokens + 1
							end
						end
						if #SearchTokens > 0 and MatchedTokens > 0 then
							Score = 4200 + math.floor(1800 * MatchedTokens / #SearchTokens)
						end
					end
					if Score > 0 then
						MatchCount = MatchCount + 1
						if SelectedObject then
							local RelatedOK, IsRelatedToSelection = pcall(function() return Object == SelectedObject or Object:IsDescendantOf(SelectedObject) end)
							if RelatedOK and IsRelatedToSelection then Score = Score + 120 end
						end
						local InWorkspaceOK, IsInWorkspace = pcall(function() return Object:IsDescendantOf(workspace) end)
						if InWorkspaceOK and IsInWorkspace then Score = Score + 15 end
						if Score > BestScore then
							BestScore = Score
							BestObject = Object
						end
					end
				end
			end
			if ExactMatchCount > 0 then
				MatchCount = ExactMatchCount
			end
			return BestObject, MatchCount
		end

		local function FindInstanceByPath(SearchPath)
			local TargetPath = tostring(SearchPath or ""):gsub("^%s+", ""):gsub("%s+$", "")
			TargetPath = TargetPath:gsub("^game%.", "")
			TargetPath = TargetPath:gsub("^game/", "")
			TargetPath = TargetPath:gsub("/", ".")
			if TargetPath == "" then
				return nil
			end
			local SearchSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not SearchSuccess or type(Descendants) ~= "table" then
				return nil
			end
			local NormalizedPath = string.lower(TargetPath):gsub("%s+", "")
			for _, Object in ipairs(Descendants) do
				local FullName = string.lower(GetObjectFullName(Object)):gsub("%s+", "")
				if FullName == NormalizedPath then
					return Object
				end
			end
			return nil
		end

		local function CleanObj(TargetText)
			local CleanTarget = tostring(TargetText or ""):gsub("^%s+", ""):gsub("%s+$", "")
			local LowerTarget = string.lower(CleanTarget)
			if LowerTarget == "this" or LowerTarget == "that" or LowerTarget == "it" or LowerTarget == "this one" or LowerTarget == "that one" or LowerTarget == "this thing" or LowerTarget == "that thing" or LowerTarget == "this guy" or LowerTarget == "that guy" or LowerTarget == "the one i selected" or LowerTarget == "the selected one" or LowerTarget == "the thing i selected" or LowerTarget == "that thing i selected" or LowerTarget == "the thing i picked" or LowerTarget == "whatever is selected" or LowerTarget == "the current item" or LowerTarget == "this part" or LowerTarget == "that part" or LowerTarget == "the part" or LowerTarget == "this model" or LowerTarget == "that model" or LowerTarget == "the model" or LowerTarget == "this instance" or LowerTarget == "that instance" or LowerTarget == "the instance" or LowerTarget == "the current selection" or LowerTarget == "current selection" then return "selected" end
			CleanTarget = CleanTarget:gsub('^["\'](.-)["\']$', "%1")
			CleanTarget = CleanTarget:gsub("^the%s+", "")
			CleanTarget = CleanTarget:gsub("^a%s+", "")
			CleanTarget = CleanTarget:gsub("^an%s+", "")
			CleanTarget = CleanTarget:gsub("^this%s+", "")
			CleanTarget = CleanTarget:gsub("^that%s+", "")
			CleanTarget = CleanTarget:gsub("^my%s+", "")
			CleanTarget = CleanTarget:gsub("’s$", ""):gsub("'s$", "")
			CleanTarget = CleanTarget:gsub("^of%s+", "")
			CleanTarget = CleanTarget:gsub("^inside%s+", "")
			CleanTarget = CleanTarget:gsub("^within%s+", "")
			CleanTarget = CleanTarget:gsub("^under%s+", "")
			CleanTarget = CleanTarget:gsub("^beneath%s+", "")
			CleanTarget = CleanTarget:gsub("^in%s+", "")
			CleanTarget = CleanTarget:gsub("^from%s+", "")
			CleanTarget = CleanTarget:gsub("^object%s+named%s+", "")
			CleanTarget = CleanTarget:gsub("^instance%s+named%s+", "")
			CleanTarget = CleanTarget:gsub("^named%s+", "")
			CleanTarget = CleanTarget:gsub("^called%s+", "")
			CleanTarget = CleanTarget:gsub("^object%s+called%s+", "")
			CleanTarget = CleanTarget:gsub("^instance%s+called%s+", "")
			CleanTarget = CleanTarget:gsub("%s+object$", "")
			CleanTarget = CleanTarget:gsub("%s+instance$", "")
			CleanTarget = CleanTarget:gsub("[%s%!%?]+$", "")
			if CleanTarget == "" then CleanTarget = "selected" end
			return CleanTarget
		end

		local function FindObj(TargetText, ClassFilter)
			local CleanTarget = CleanObj(TargetText)
			local TargetAliases = {selected = true, selection = true, it = true, this = true, object = true, instance = true, part = false, ["this object"] = true, ["this instance"] = true, ["the object"] = true, ["the instance"] = true, ["the selected object"] = true, ["selected object"] = true, ["selected part"] = true, ["selected model"] = true, ["selected instance"] = true, ["this selection"] = true, ["current selection"] = true}
			if TargetAliases[string.lower(CleanTarget)] then
				local SelectedObject = GetSelectedObject()
				return SelectedObject, SelectedObject and 1 or 0, CleanTarget
			end
			local ClassAliases = {part = "BasePart", parts = "BasePart", basepart = "BasePart", meshpart = "MeshPart", model = "Model", models = "Model", folder = "Folder", folders = "Folder", script = "script", scripts = "script", localscript = "LocalScript", modulescript = "ModuleScript", remote = "remote", remotes = "remote", remoteevent = "RemoteEvent", remotefunction = "RemoteFunction", tool = "Tool", tools = "Tool", sound = "Sound", sounds = "Sound", humanoid = "Humanoid", attachment = "Attachment", button = "button", buttons = "button", label = "label", labels = "label", gui = "gui", player = "Player", value = "value", constraint = "constraint", effect = "effect", light = "light", animation = "Animation", frame = "Frame", textlabel = "TextLabel", textbutton = "TextButton", textbox = "TextBox", imagebutton = "ImageButton", imagelabel = "ImageLabel", screengui = "ScreenGui", billboardgui = "BillboardGui", surfacegui = "SurfaceGui", decal = "Decal", texture = "Texture", emitter = "ParticleEmitter", particleemitter = "ParticleEmitter"}
			local Prefix, Remaining = CleanTarget:match("^(%S+)%s+(.+)$")
			if Prefix and ClassAliases[NormalizeFinName(Prefix)] then
				ClassFilter = ClassFilter or ClassAliases[NormalizeFinName(Prefix)]
				CleanTarget = Remaining:gsub("^named%s+", ""):gsub("^called%s+", "")
			else
				local NamePart, Suffix = CleanTarget:match("^(.+)%s+(%S+)$")
				if Suffix and ClassAliases[NormalizeFinName(Suffix)] then
					ClassFilter = ClassFilter or ClassAliases[NormalizeFinName(Suffix)]
					CleanTarget = NamePart
				end
			end
			if CleanTarget == "" then return nil, 0, CleanTarget end
			local PathObject = FindInstanceByPath(CleanTarget)
			if PathObject and MatchesFinClass(PathObject, ClassFilter) then
				return PathObject, 1, CleanTarget
			end
			local FoundObject, MatchCount = FindInstanceByName(CleanTarget, ClassFilter)
			return FoundObject, MatchCount, CleanTarget
		end

		local function GetPicked()
			local SelectedObjects = {}
			local SeenObjects = {}
			local ExplorerApp = Apps.Explorer
			local Selection = ExplorerApp and ExplorerApp.Selection
			for _, Entry in ipairs(Selection and Selection.List or {}) do
				local Object = Entry and Entry.Obj
				if Object and not SeenObjects[Object] then
					SeenObjects[Object] = true
					table.insert(SelectedObjects, Object)
				end
			end
			return SelectedObjects
		end

		local function SetExpSelection(Objects)
			local ExplorerApp = Apps.Explorer
			if not ExplorerApp then
				return false, "Explorer isn't ready yet."
			end
			local Selection = ExplorerApp.Selection
			if not Selection then
				return false, "Explorer selection isn't available."
			end
			local NewSelection = {}
			local SeenNodes = {}
			local MissingCount = 0
			local FirstObject
			for _, Object in ipairs(Objects or {}) do
				local Node = EnsureExpNode(Object)
				if Node and not SeenNodes[Node] then
					SeenNodes[Node] = true
					table.insert(NewSelection, Node)
					FirstObject = FirstObject or Object
				elseif not Node then
					MissingCount = MissingCount + 1
				end
			end
			if #(Objects or {}) > 0 and #NewSelection == 0 then
				return false, "I found the objects, but Explorer couldn't build selectable nodes for them."
			end
			if ExplorerApp.Window then
				pcall(function() ExplorerApp.Window:Show() end)
			end
			if FirstObject and type(ExplorerApp.ViewObj) == "function" then
				local ViewSuccess, ViewError = pcall(ExplorerApp.ViewObj, FirstObject)
				if not ViewSuccess then
					return false, "Explorer couldn't reveal the first match: " .. tostring(ViewError)
				end
			end
			local SelectSuccess, SelectError = pcall(function()
				if type(Selection.SetTable) == "function" then
					Selection:SetTable(NewSelection)
				elseif #NewSelection == 1 and type(Selection.Set) == "function" then
					Selection:Set(NewSelection[1])
				elseif #NewSelection == 0 and type(Selection.Clear) == "function" then
					Selection:Clear()
				else
					error("Explorer does not expose the required selection method")
				end
			end)
			if not SelectSuccess then
				return false, "Explorer couldn't update the selection: " .. tostring(SelectError)
			end
			if type(ExplorerApp.ForceUpdate) == "function" then pcall(ExplorerApp.ForceUpdate, true) end
			if type(ExplorerApp.Refresh) == "function" then pcall(ExplorerApp.Refresh) end
			local VerifiedCount = 0
			for _, Node in ipairs(NewSelection) do
				local IsSelected = Selection.Map and Selection.Map[Node] == true
				if not IsSelected then
					for _, SelectedNode in ipairs(Selection.List or {}) do
						if SelectedNode == Node then IsSelected = true break end
					end
				end
				if IsSelected then VerifiedCount = VerifiedCount + 1 end
			end
			if #NewSelection > 0 and VerifiedCount == 0 then
				return false, "Explorer did not retain the requested selection. Try refreshing Explorer once."
			end
			local PropertiesApp = Apps.Properties
			if PropertiesApp then
				if PropertiesApp.Window then pcall(function() PropertiesApp.Window:Show() end) end
				if type(PropertiesApp.Update) == "function" then pcall(PropertiesApp.Update) end
				if type(PropertiesApp.Refresh) == "function" then pcall(PropertiesApp.Refresh) end
			end
			local Message = #NewSelection
			if MissingCount > 0 then
				Message = tostring(#NewSelection) .. " selected; " .. tostring(MissingCount) .. " could not be added to Explorer."
			end
			return true, Message
		end

		local function PickSmartFilter(FilterName)
			local SearchSuccess, AllObjects = pcall(function() return game:GetDescendants() end)
			if not SearchSuccess or type(AllObjects) ~= "table" then
				return false, "I couldn't read the client-visible instance tree."
			end
			local Matches = {}
			for CandidateIndex, Candidate in ipairs(AllObjects) do
				local MatchSuccess, IsMatch = pcall(function()
					if FilterName == "unanchored" then
						return Candidate:IsA("BasePart") and not Candidate.Anchored
					elseif FilterName == "anchored" then
						return Candidate:IsA("BasePart") and Candidate.Anchored
					elseif FilterName == "invisible" then
						return Candidate:IsA("BasePart") and Candidate.Transparency >= 0.95
					elseif FilterName == "noncollidable" then
						return Candidate:IsA("BasePart") and not Candidate.CanCollide
					elseif FilterName == "scripts" then
						return Candidate:IsA("LuaSourceContainer")
					elseif FilterName == "disabledscripts" then
						return Candidate:IsA("BaseScript") and Candidate.Disabled
					elseif FilterName == "enabledscripts" then
						return Candidate:IsA("BaseScript") and not Candidate.Disabled
					elseif FilterName == "remotes" then
						return Candidate:IsA("RemoteEvent") or Candidate:IsA("RemoteFunction")
					elseif FilterName == "remoteevents" then
						return Candidate:IsA("RemoteEvent")
					elseif FilterName == "remotefunctions" then
						return Candidate:IsA("RemoteFunction")
					elseif FilterName == "emptyfolders" then
						return Candidate:IsA("Folder") and #Candidate:GetChildren() == 0
					elseif FilterName == "modelswithoutprimarypart" then
						return Candidate:IsA("Model") and Candidate.PrimaryPart == nil
					elseif FilterName == "untouchable" then
						return Candidate:IsA("BasePart") and not Candidate.CanTouch
					elseif FilterName == "nonqueryable" then
						return Candidate:IsA("BasePart") and not Candidate.CanQuery
					elseif FilterName == "massless" then
						return Candidate:IsA("BasePart") and Candidate.Massless
					elseif FilterName == "shadowless" then
						return Candidate:IsA("BasePart") and not Candidate.CastShadow
					end
					return false
				end)
				if MatchSuccess and IsMatch then Matches[#Matches + 1] = Candidate end
			end
			local SelectSuccess, SelectResult = SetExpSelection(Matches)
			if not SelectSuccess then return false, tostring(SelectResult) end
			local FilterLabels = {unanchored = "unanchored part(s)", anchored = "anchored part(s)", invisible = "nearly or fully invisible part(s)", noncollidable = "non-collidable part(s)", untouchable = "part(s) with CanTouch disabled", nonqueryable = "part(s) with CanQuery disabled", massless = "massless part(s)", shadowless = "part(s) with CastShadow disabled", scripts = "script(s)", disabledscripts = "disabled script(s)", enabledscripts = "enabled script(s)", remotes = "remote object(s)", remoteevents = "RemoteEvent(s)", remotefunctions = "RemoteFunction(s)", emptyfolders = "empty folder(s)", modelswithoutprimarypart = "Model(s) without a PrimaryPart"}
			return true, "Selected " .. tostring(SelectResult) .. " " .. tostring(FilterLabels[FilterName] or "matching object(s)") .. " from the client-visible instance tree."
		end

		local function WorkspaceAudit()
			local SearchSuccess, AllObjects = pcall(function() return workspace:GetDescendants() end)
			if not SearchSuccess or type(AllObjects) ~= "table" then return "I couldn't read Workspace descendants for the audit." end
			local Counts = {Parts = 0, Anchored = 0, Unanchored = 0, NonCollidable = 0, Invisible = 0, Untouchable = 0, NonQueryable = 0, Massless = 0, Shadowless = 0, Scripts = 0, DisabledScripts = 0, EnabledScripts = 0, Models = 0, ModelsWithoutPrimaryPart = 0, EmptyFolders = 0, Remotes = 0}
			for CandidateIndex, Candidate in ipairs(AllObjects) do
				local ReadSuccess = pcall(function()
					if Candidate:IsA("BasePart") then
						Counts.Parts = Counts.Parts + 1
						if Candidate.Anchored then Counts.Anchored = Counts.Anchored + 1 else Counts.Unanchored = Counts.Unanchored + 1 end
						if not Candidate.CanCollide then Counts.NonCollidable = Counts.NonCollidable + 1 end
						if Candidate.Transparency >= 0.95 then Counts.Invisible = Counts.Invisible + 1 end
						if not Candidate.CanTouch then Counts.Untouchable = Counts.Untouchable + 1 end
						if not Candidate.CanQuery then Counts.NonQueryable = Counts.NonQueryable + 1 end
						if Candidate.Massless then Counts.Massless = Counts.Massless + 1 end
						if not Candidate.CastShadow then Counts.Shadowless = Counts.Shadowless + 1 end
					end
					if Candidate:IsA("BaseScript") then
						Counts.Scripts = Counts.Scripts + 1
						if Candidate.Disabled then Counts.DisabledScripts = Counts.DisabledScripts + 1 else Counts.EnabledScripts = Counts.EnabledScripts + 1 end
					elseif Candidate:IsA("ModuleScript") then
						Counts.Scripts = Counts.Scripts + 1
					end
					if Candidate:IsA("Model") then
						Counts.Models = Counts.Models + 1
						if Candidate.PrimaryPart == nil then Counts.ModelsWithoutPrimaryPart = Counts.ModelsWithoutPrimaryPart + 1 end
					end
					if Candidate:IsA("Folder") and #Candidate:GetChildren() == 0 then Counts.EmptyFolders = Counts.EmptyFolders + 1 end
					if Candidate:IsA("RemoteEvent") or Candidate:IsA("RemoteFunction") then Counts.Remotes = Counts.Remotes + 1 end
				end)
			end
			return table.concat({
				"Workspace audit (Workspace descendants visible to this client):",
				"BaseParts: " .. tostring(Counts.Parts) .. " (anchored " .. tostring(Counts.Anchored) .. ", unanchored " .. tostring(Counts.Unanchored) .. ")",
				"Non-collidable: " .. tostring(Counts.NonCollidable) .. " | nearly/fully invisible: " .. tostring(Counts.Invisible),
				"CanTouch disabled: " .. tostring(Counts.Untouchable) .. " | CanQuery disabled: " .. tostring(Counts.NonQueryable) .. " | massless: " .. tostring(Counts.Massless) .. " | shadows disabled: " .. tostring(Counts.Shadowless),
				"Scripts and ModuleScripts: " .. tostring(Counts.Scripts) .. " (disabled " .. tostring(Counts.DisabledScripts) .. ", enabled " .. tostring(Counts.EnabledScripts) .. ")",
				"Models: " .. tostring(Counts.Models) .. " (without PrimaryPart " .. tostring(Counts.ModelsWithoutPrimaryPart) .. ")",
				"Empty folders: " .. tostring(Counts.EmptyFolders) .. " | remotes: " .. tostring(Counts.Remotes),
				"This report only includes instances visible to the client; it cannot inspect server-only content."
			}, "\n")
		end

		local function PickObjGroup(Object, FilterName, DirectChildren)
			if not Object then
				return false, "Select an object in Explorer first, or tell me which object to use."
			end
			local ReadSuccess, ObjectList = pcall(function()
				return DirectChildren and Object:GetChildren() or Object:GetDescendants()
			end)
			if not ReadSuccess or type(ObjectList) ~= "table" then
				return false, "I couldn't read that object's hierarchy."
			end
			local MatchedObjects = {}
			for _, Candidate in ipairs(ObjectList) do
				local IsMatch = FilterName == nil or FilterName == "any" or MatchesFinClass(Candidate, FilterName)
				if IsMatch then
					table.insert(MatchedObjects, Candidate)
				end
			end
			local SelectSuccess, SelectedCount = SetExpSelection(MatchedObjects)
			if not SelectSuccess then
				return false, SelectedCount
			end
			local ScopeName = DirectChildren and "direct child object(s)" or "descendant object(s)"
			if FilterName and FilterName ~= "any" then
				ScopeName = ScopeName .. " matching " .. tostring(FilterName)
			end
			return true, "Selected " .. tostring(SelectedCount) .. " " .. ScopeName .. " under " .. GetObjectFullName(Object) .. "."
		end

		local function FindDupScripts()
			local SearchSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not SearchSuccess or type(Descendants) ~= "table" then
				return 0, {}
			end
			local ScriptGroups = {}
			for _, Object in ipairs(Descendants) do
				if Object:IsA("LocalScript") or Object:IsA("ModuleScript") then
					ScriptGroups[Object.Name] = ScriptGroups[Object.Name] or {}
					table.insert(ScriptGroups[Object.Name], Object)
				end
			end
			local DuplicateCount = 0
			local DuplicateNames = {}
			for ScriptName, ScriptList in pairs(ScriptGroups) do
				if #ScriptList > 1 then
					DuplicateCount = DuplicateCount + 1
					if #DuplicateNames < 4 then
						local Paths = {}
						for Index = 1, math.min(2, #ScriptList) do
							Paths[#Paths + 1] = GetObjectFullName(ScriptList[Index])
						end
						DuplicateNames[#DuplicateNames + 1] = ScriptName .. " (" .. tostring(#ScriptList) .. "): " .. table.concat(Paths, " / ")
					end
				end
			end
			table.sort(DuplicateNames)
			return DuplicateCount, DuplicateNames
		end

		local function FindDupInstances()
			local SearchSuccess, Descendants = pcall(function() return game:GetDescendants() end)
			if not SearchSuccess or type(Descendants) ~= "table" then return 0, {} end
			local NameGroups = {}
			for InstanceIndex, Candidate in ipairs(Descendants) do
				local NameSuccess, ObjectName = pcall(function() return Candidate.Name end)
				if NameSuccess and ObjectName and ObjectName ~= "" then
					NameGroups[ObjectName] = NameGroups[ObjectName] or {}
					NameGroups[ObjectName][#NameGroups[ObjectName] + 1] = Candidate
				end
			end
			local DuplicateGroups = {}
			local DupeCount = 0
			for ObjectName, ObjectList in pairs(NameGroups) do
				if #ObjectList > 1 then
					DupeCount = DupeCount + #ObjectList
					local PathList = {}
					for PathIndex = 1, math.min(2, #ObjectList) do
						PathList[#PathList + 1] = GetObjectFullName(ObjectList[PathIndex]) .. " [" .. ObjectList[PathIndex].ClassName .. "]"
					end
					DuplicateGroups[#DuplicateGroups + 1] = {Name = ObjectName, Count = #ObjectList, Paths = table.concat(PathList, " / ")}
				end
			end
			table.sort(DuplicateGroups, function(Left, Right)
				if Left.Count == Right.Count then return string.lower(Left.Name) < string.lower(Right.Name) end
				return Left.Count > Right.Count
			end)
			local Results = {}
			for ResultIndex = 1, math.min(6, #DuplicateGroups) do
				local Group = DuplicateGroups[ResultIndex]
				Results[#Results + 1] = Group.Name .. " x" .. tostring(Group.Count) .. ": " .. Group.Paths
			end
			return DupeCount, Results
		end

		local function ListRemoteObjects()
			local SearchSuccess, Descendants = pcall(function()
				return game:GetDescendants()
			end)
			if not SearchSuccess or type(Descendants) ~= "table" then
				return 0, {}
			end
			local TotalCount = 0
			local RemoteNames = {}
			for _, Object in ipairs(Descendants) do
				if Object:IsA("RemoteEvent") or Object:IsA("RemoteFunction") then
					TotalCount = TotalCount + 1
					if #RemoteNames < 6 then
						table.insert(RemoteNames, Object.Name .. " [" .. Object.ClassName .. "] — " .. GetObjectFullName(Object))
					end
				end
			end
			return TotalCount, RemoteNames
		end

		local function InspectFinObject(Object)
			if not Object then
				return "Select an instance in Explorer first, then ask me to inspect the selection."
			end
			local ChildSuccess, Children = pcall(function() return Object:GetChildren() end)
			Children = ChildSuccess and Children or {}
			local DescendantSuccess, Descendants = pcall(function() return Object:GetDescendants() end)
			Descendants = DescendantSuccess and Descendants or {}
			local AttributeSuccess, Attributes = pcall(function() return Object:GetAttributes() end)
			Attributes = AttributeSuccess and Attributes or {}
			local DetailLines = {Object.Name .. " is a " .. Object.ClassName, "Path: " .. GetObjectFullName(Object), "Direct children: " .. tostring(#Children) .. "; descendants: " .. tostring(#Descendants)}
			local ChildNames = {}
			for Index, Child in ipairs(Children) do
				if Index > 7 then break end
				ChildNames[#ChildNames + 1] = Child.Name .. " (" .. Child.ClassName .. ")"
			end
			if #ChildNames > 0 then
				DetailLines[#DetailLines + 1] = "Children: " .. table.concat(ChildNames, ", ") .. (#Children > #ChildNames and ", plus " .. tostring(#Children - #ChildNames) .. " more" or "")
			else
				DetailLines[#DetailLines + 1] = "No direct children."
			end
			local AttributeNames = {}
			for AttributeName in pairs(Attributes) do AttributeNames[#AttributeNames + 1] = tostring(AttributeName) end
			table.sort(AttributeNames)
			local AttributeDetails = {}
			for Index, AttributeName in ipairs(AttributeNames) do
				if Index > 6 then break end
				AttributeDetails[#AttributeDetails + 1] = AttributeName .. "=" .. tostring(Attributes[AttributeName])
			end
			DetailLines[#DetailLines + 1] = "Attributes: " .. tostring(#AttributeNames) .. (#AttributeDetails > 0 and " (" .. table.concat(AttributeDetails, ", ") .. ")" or "")
			local function AddProperty(PropertyName)
				local ReadSuccess, PropertyValue = pcall(function() return Object[PropertyName] end)
				if ReadSuccess then DetailLines[#DetailLines + 1] = PropertyName .. ": " .. tostring(PropertyValue) end
			end
			if Object:IsA("BasePart") then
				for _, PropertyName in ipairs({"Position", "Size", "Orientation", "Color", "Material", "Transparency", "Anchored", "CanCollide", "CanTouch", "CanQuery", "CollisionGroup"}) do AddProperty(PropertyName) end
			elseif Object:IsA("Model") then
				AddProperty("PrimaryPart")
				local PivotSuccess, Pivot = pcall(function() return Object:GetPivot() end)
				if PivotSuccess then DetailLines[#DetailLines + 1] = "Pivot position: " .. tostring(Pivot.Position) end
			elseif Object:IsA("GuiObject") then
				for _, PropertyName in ipairs({"Size", "Position", "Visible", "BackgroundColor3", "BackgroundTransparency", "Rotation", "ZIndex"}) do AddProperty(PropertyName) end
				if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then AddProperty("Text") AddProperty("TextColor3") end
			elseif Object:IsA("ValueBase") then
				AddProperty("Value")
			elseif Object:IsA("Humanoid") then
				for _, PropertyName in ipairs({"Health", "MaxHealth", "WalkSpeed", "JumpPower", "JumpHeight", "HipHeight", "AutoRotate"}) do AddProperty(PropertyName) end
			elseif Object:IsA("Sound") then
				for _, PropertyName in ipairs({"SoundId", "Volume", "PlaybackSpeed", "Looped", "Playing"}) do AddProperty(PropertyName) end
			elseif Object:IsA("BaseScript") then
				AddProperty("Disabled")
			end
			local TagsSuccess, Tags = pcall(function() return game:GetService("CollectionService"):GetTags(Object) end)
			if TagsSuccess then
				table.sort(Tags)
				DetailLines[#DetailLines + 1] = "CollectionService tags: " .. (#Tags > 0 and table.concat(Tags, ", ") or "none")
			end
			return table.concat(DetailLines, ". ")
		end


		local FinMCP = {Name = "Valm Dex Fin MCP", Version = "1.3.0", ProtocolVersion = "2025-06-18", Tools = {}, ToolMap = {}, NextId = 0}
		local function AddFinMCPTool(Name, Description, InputSchema, Handler)
			local Definition = {name = Name, description = Description, inputSchema = InputSchema or {type = "object", properties = {}, additionalProperties = false}}
			FinMCP.Tools[#FinMCP.Tools + 1] = Definition
			FinMCP.ToolMap[Name] = {Definition = Definition, Handler = Handler}
		end
		local function FinMCPText(Value, IsError)
			local TextValue = tostring(Value or "")
			if #TextValue > 12000 then TextValue = TextValue:sub(1, 11997) .. "..." end
			return {content = {{type = "text", text = TextValue}}, isError = IsError == true}
		end
		function FinMCP.Handle(RequestData)
			if type(RequestData) ~= "table" or RequestData.jsonrpc ~= "2.0" then
				return {jsonrpc = "2.0", id = type(RequestData) == "table" and RequestData.id or nil, error = {code = -32600, message = "Invalid JSON-RPC request"}}
			end
			local Method = tostring(RequestData.method or "")
			local Params = type(RequestData.params) == "table" and RequestData.params or {}
			if Method == "notifications/initialized" or Method:match("^notifications/") then
				return nil
			elseif Method == "ping" then
				return {jsonrpc = "2.0", id = RequestData.id, result = {}}
			elseif Method == "initialize" then
				return {jsonrpc = "2.0", id = RequestData.id, result = {protocolVersion = FinMCP.ProtocolVersion, capabilities = {tools = {listChanged = false}}, serverInfo = {name = FinMCP.Name, version = FinMCP.Version}}}
			elseif Method == "tools/list" then
				return {jsonrpc = "2.0", id = RequestData.id, result = {tools = FinMCP.Tools}}
			elseif Method == "tools/call" then
				local ToolName = tostring(Params.name or "")
				local ToolRecord = FinMCP.ToolMap[ToolName]
				if not ToolRecord then
					return {jsonrpc = "2.0", id = RequestData.id, result = FinMCPText("Unknown MCP tool: " .. ToolName, true)}
				end
				local Args = type(Params.arguments) == "table" and Params.arguments or {}
				local CallSuccess, CallResult = pcall(ToolRecord.Handler, Args)
				if not CallSuccess then
					return {jsonrpc = "2.0", id = RequestData.id, result = FinMCPText("Tool failed: " .. tostring(CallResult), true)}
				end
				return {jsonrpc = "2.0", id = RequestData.id, result = FinMCPText(CallResult, false)}
			end
			return {jsonrpc = "2.0", id = RequestData.id, error = {code = -32601, message = "Method not found: " .. Method}}
		end

		AddFinMCPTool("dex_runtime_status", "Read the current Valm Dex app, selection, device and decompiler state.", {type = "object", properties = {}, additionalProperties = false}, function()
			return type(GetDexInfo) == "function" and GetDexInfo() or "Dex runtime context is not ready."
		end)
		AddFinMCPTool("dex_list_apps", "List currently registered Valm Dex apps and installed plugin panels.", {type = "object", properties = {}, additionalProperties = false}, function()
			local Names = {}
			local Seen = {}
			local function AddName(Value)
				local AppName = tostring(Value or "")
				if AppName ~= "" and not Seen[AppName] and AppName ~= "Workspace Layouts" and AppName ~= "Command Palette" then
					Seen[AppName] = true
					Names[#Names + 1] = AppName
				end
			end
			for AppName, AppData in pairs(Apps or {}) do
				if type(AppData) == "table" and AppData.Window then AddName(AppName) end
			end
			for AppName, Window in pairs(Main.WindowRegistry or {}) do if Window then AddName(AppName) end end
			for _, PluginRecord in ipairs(Main.Plugins or {}) do
				local PluginData = PluginRecord and PluginRecord.PluginData or {}
				if PluginRecord and PluginRecord.Window then AddName(PluginData.FriendlyName or PluginData.Name) end
			end
			table.sort(Names)
			return table.concat(Names, "\n")
		end)
		AddFinMCPTool("dex_open_app", "Open a registered Valm Dex app or plugin panel. Provide its displayed name.", {type = "object", properties = {name = {type = "string", description = "Displayed app or plugin name"}}, required = {"name"}, additionalProperties = false}, function(Args)
			local AppName = tostring(Args.name or "")
			if AppName == "" then return "Provide an app name." end
			local OpenedName = OpenRelatedTool(string.lower(AppName))
