		AddFinMCPTool("dex_get_active_script", "Read the active Decompiler script and its path. Source is truncated to a safe length.", {type = "object", properties = {}, additionalProperties = false}, function()
			local SourceText, ScriptObject = GetCurrentCode()
			if not ScriptObject and (SourceText == nil or SourceText == "") then return "No script is currently open in Decompiler." end
