		AddFinMCPTool("dex_search_active_script", "Search the currently open Decompiler source for a literal string and return matching line numbers.", {type = "object", properties = {query = {type = "string", description = "Literal text to search for"}}, required = {"query"}, additionalProperties = false}, function(Args)
			local Needle = string.lower(tostring(Args.query or ""))
			if Needle == "" then return "Provide text to search for." end
			local SourceText = GetCurrentCode()
			if type(SourceText) ~= "string" or SourceText == "" then return "No source is open in Decompiler." end
			local Hits = {}
			for LineNumber, LineText in ipairs((function()
				local Lines = {}
				for Line in (SourceText .. "\n"):gmatch("(.-)\n") do Lines[#Lines + 1] = Line end
				return Lines
			end)()) do
				if string.find(string.lower(LineText), Needle, 1, true) then
					Hits[#Hits + 1] = tostring(LineNumber) .. ": " .. LineText
					if #Hits >= 15 then break end
				end
			end
			return #Hits > 0 and table.concat(Hits, "\n") or "No matching lines were found."
		end)
		AddFinMCPTool("dex_list_children", "List direct children or descendants of an instance visible to the client. Results are capped for readability.", {type = "object", properties = {target = {type = "string", description = "Instance path, name, or selected"}, recursive = {type = "boolean", description = "Whether to list all descendants"}, limit = {type = "integer", description = "Maximum results from 1 to 100"}}, additionalProperties = false}, function(Args)
			local Target = tostring(Args.target or "selected")
			local Object, MatchCount = FindObj(Target)
			if not Object then return "No matching instance was found for " .. Target .. ". Match count: " .. tostring(MatchCount) end
			local Recursive = Args.recursive == true
			local ReadSuccess, Children = pcall(function() return Recursive and Object:GetDescendants() or Object:GetChildren() end)
			if not ReadSuccess or type(Children) ~= "table" then return "I couldn't read the selected object's hierarchy." end
			local Limit = math.clamp(math.floor(tonumber(Args.limit) or 40), 1, 100)
			local Lines = {tostring(#Children) .. (Recursive and " descendants under " or " direct children under ") .. GetObjectFullName(Object) .. ":"}
			for Index, Child in ipairs(Children) do
				if Index > Limit then break end
				Lines[#Lines + 1] = tostring(Index) .. ". " .. GetObjectFullName(Child) .. " [" .. Child.ClassName .. "]"
			end
			if #Children > Limit then Lines[#Lines + 1] = "...and " .. tostring(#Children - Limit) .. " more." end
			return table.concat(Lines, "\n")
		end)
		AddFinMCPTool("dex_get_attributes", "Read all custom attributes on a client-visible instance.", {type = "object", properties = {target = {type = "string", description = "Instance path, name, or selected"}}, additionalProperties = false}, function(Args)
