		AddFinMCPTool("dex_get_property", "Read a named Roblox property from a client-visible instance. This tool is read-only.", {type = "object", properties = {target = {type = "string", description = "Instance path, name, or selected"}, property = {type = "string", description = "Property name"}}, required = {"property"}, additionalProperties = false}, function(Args)
			local Target = tostring(Args.target or "selected")
			local Object, MatchCount = FindObj(Target)
			if not Object then return "No matching instance was found. Match count: " .. tostring(MatchCount) end
			local Property = tostring(Args.property or "")
			local Allowed = {Name = true, ClassName = true, Archivable = true, Parent = true, Position = true, Size = true, CFrame = true, Orientation = true, Anchored = true, CanCollide = true, CanTouch = true, CanQuery = true, Transparency = true, LocalTransparencyModifier = true, Reflectance = true, Material = true, Color = true, BrickColor = true, Shape = true, MeshId = true, TextureID = true, WalkSpeed = true, JumpPower = true, JumpHeight = true, Health = true, MaxHealth = true, HipHeight = true, AutoRotate = true, Text = true, TextColor3 = true, TextSize = true, TextTransparency = true, BackgroundColor3 = true, BackgroundTransparency = true, Image = true, ImageColor3 = true, ImageTransparency = true, Visible = true, Enabled = true, Value = true, Volume = true, PlaybackSpeed = true, Looped = true, SoundId = true, Brightness = true, Range = true, Rate = true, TimeOfDay = true, ClockTime = true, FieldOfView = true}
			if not Allowed[Property] then return "That property isn't in Fin's read-only property allowlist." end
			local ReadSuccess, Value = pcall(function() return Object[Property] end)
			if not ReadSuccess then return "Property " .. Property .. " isn't available on " .. Object.ClassName .. "." end
			local ValueType = typeof(Value)
			if ValueType == "Instance" then Value = Value and GetObjectFullName(Value) or "nil" end
			return GetObjectFullName(Object) .. "." .. Property .. " = " .. tostring(Value) .. " (" .. ValueType .. ")"
		end)
		AddFinMCPTool("dex_search_instances", "Search client-visible instance names, class names and full paths. Results are capped.", {type = "object", properties = {query = {type = "string", description = "Text to search for"}, classFilter = {type = "string", description = "Optional Roblox class filter"}, limit = {type = "integer", description = "Maximum results from 1 to 60"}}, required = {"query"}, additionalProperties = false}, function(Args)
			local Query = string.lower(tostring(Args.query or "")):gsub("^%s+", ""):gsub("%s+$", "")
			if Query == "" then return "Provide text to search for." end
			local SearchSuccess, Descendants = pcall(function() return game:GetDescendants() end)
			if not SearchSuccess or type(Descendants) ~= "table" then return "The client-visible instance tree couldn't be read." end
			local Limit = math.clamp(math.floor(tonumber(Args.limit) or 30), 1, 60)
			local Matches = {}
			local MatchCount = 0
			for _, Object in ipairs(Descendants) do
				local ClassMatch = true
				if Args.classFilter and tostring(Args.classFilter) ~= "" then
					local ClassSuccess, Result = pcall(MatchesFinClass, Object, tostring(Args.classFilter))
					ClassMatch = ClassSuccess and Result == true
				end
				if ClassMatch then
					local FullName = GetObjectFullName(Object)
					local Haystack = string.lower(Object.Name .. " " .. Object.ClassName .. " " .. FullName)
					if string.find(Haystack, Query, 1, true) then
						MatchCount = MatchCount + 1
					if #Matches < Limit then Matches[#Matches + 1] = FullName .. " [" .. Object.ClassName .. "]" end
					end
				end
			end
			local Lines = {"Found " .. tostring(MatchCount) .. " matching client-visible instance(s):"}
			for Index, Result in ipairs(Matches) do Lines[#Lines + 1] = tostring(Index) .. ". " .. Result end
			if MatchCount > #Matches then Lines[#Lines + 1] = "...and " .. tostring(MatchCount - #Matches) .. " more." end
			return table.concat(Lines, "\n")
		end)
		AddFinMCPTool("dex_list_remotes", "List client-visible RemoteEvents, UnreliableRemoteEvents and RemoteFunctions with their paths.", {type = "object", properties = {limit = {type = "integer", description = "Maximum results from 1 to 80"}}, additionalProperties = false}, function(Args)
			local SearchSuccess, Descendants = pcall(function() return game:GetDescendants() end)
