			local Limit = math.clamp(math.floor(tonumber(Args.limit) or 40), 1, 80)
			local Lines = {}
			local Count = 0
			for _, Object in ipairs(Descendants) do
				if Object:IsA("RemoteEvent") or Object:IsA("UnreliableRemoteEvent") or Object:IsA("RemoteFunction") then
					Count = Count + 1
					if #Lines < Limit then Lines[#Lines + 1] = GetObjectFullName(Object) .. " [" .. Object.ClassName .. "]" end
				end
			end
			local Header = "Client-visible remotes: " .. tostring(Count)
