		AddFinMCPTool("dex_get_decompiler_status", "Read the native Valm Decompiler status and the last decompiler provider used.", {type = "object", properties = {}, additionalProperties = false}, function()
			local Decompiler = (type(env) == "table" and env.ValmDecompiler) or (type(_G) == "table" and _G.ValmDecompiler)
