		AddFinMCPTool("dex_list_players", "List players currently visible to this client, including display name, team and character health.", {type = "object", properties = {Limit = {type = "integer", description = "Maximum players from 1 to 60"}}, additionalProperties = false}, function(Args)
			local PlayersService = service.Players or game:GetService("Players")
			local ReadSuccess, PlayerList = pcall(function() return PlayersService:GetPlayers() end)
			if not ReadSuccess or type(PlayerList) ~= "table" then return "The local client player list couldn't be read." end
			local Limit = math.clamp(math.floor(tonumber(Args.Limit) or 30), 1, 60)
			local Lines = {"Players in this client: " .. tostring(#PlayerList)}
			for Index, Player in ipairs(PlayerList) do
				if Index > Limit then break end
				local TeamName = Player.Team and Player.Team.Name or "No team"
				local Character = Player.Character
				local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
				local HealthText = Humanoid and (string.format("%.1f/%.1f HP", Humanoid.Health, Humanoid.MaxHealth)) or "Character unavailable"
				Lines[#Lines + 1] = tostring(Index) .. ". " .. tostring(Player.DisplayName or Player.Name) .. " (" .. tostring(Player.Name) .. ") | " .. tostring(TeamName) .. " | " .. HealthText
			end
			if #PlayerList > Limit then Lines[#Lines + 1] = "...and " .. tostring(#PlayerList - Limit) .. " more." end
			return table.concat(Lines, "\n")
		end)
		AddFinMCPTool("dex_get_local_player_status", "Read the local player's team, account age, character availability and current humanoid status.", {type = "object", properties = {}, additionalProperties = false}, function()
			if not plr then return "The local player is unavailable." end
			local Lines = {"Name: " .. tostring(plr.Name), "Display name: " .. tostring(plr.DisplayName), "Account age: " .. tostring(plr.AccountAge) .. " days", "Team: " .. tostring(plr.Team and plr.Team.Name or "No team")}
