		AddFinMCPTool("dex_get_character_status", "Inspect the local character's humanoid, root position, movement, health and physics state.", {type = "object", properties = {}, additionalProperties = false}, function()
			local Character = plr and plr.Character
			if not Character then return "The local character isn't currently spawned." end
			local Humanoid = Character:FindFirstChildOfClass("Humanoid")
			local RootPart = Character:FindFirstChild("HumanoidRootPart") or Character.PrimaryPart
