		AddFinMCPTool("dex_list_player_gui", "List top-level ScreenGui, BillboardGui and SurfaceGui objects under the local player's PlayerGui.", {type = "object", properties = {Limit = {type = "integer", description = "Maximum GUI roots from 1 to 80"}}, additionalProperties = false}, function(Args)
			local PlayerGui = plr and plr:FindFirstChildOfClass("PlayerGui")
			if not PlayerGui then return "The local PlayerGui isn't available." end
			local Limit = math.clamp(math.floor(tonumber(Args.Limit) or 50), 1, 80)
			local Lines = {"Top-level PlayerGui children: " .. tostring(#PlayerGui:GetChildren())}
			local Count = 0
			for _, Object in ipairs(PlayerGui:GetChildren()) do
				if Object:IsA("ScreenGui") or Object:IsA("BillboardGui") or Object:IsA("SurfaceGui") then
					Count = Count + 1
					if Count <= Limit then
						local EnabledValue = Object.Enabled
						local DisplayValue = Object:IsA("ScreenGui") and (" | DisplayOrder: " .. tostring(Object.DisplayOrder)) or ""
						Lines[#Lines + 1] = GetObjectFullName(Object) .. " | " .. Object.ClassName .. " | Enabled: " .. tostring(EnabledValue) .. DisplayValue
					end
				end
			end
			if Count == 0 then Lines[#Lines + 1] = "No top-level ScreenGui, BillboardGui or SurfaceGui objects were found." end
			if Count > Limit then Lines[#Lines + 1] = "...and " .. tostring(Count - Limit) .. " more." end
			return table.concat(Lines, "\n")
		end)
		AddFinMCPTool("dex_search_player_gui", "Search PlayerGui descendants by name, class or displayed text and return matching paths.", {type = "object", properties = {Query = {type = "string", description = "Text to search for"}, Limit = {type = "integer", description = "Maximum results from 1 to 60"}}, required = {"Query"}, additionalProperties = false}, function(Args)
			local PlayerGui = plr and plr:FindFirstChildOfClass("PlayerGui")
			if not PlayerGui then return "The local PlayerGui isn't available." end
			local Query = string.lower(tostring(Args.Query or "")):gsub("^%s+", ""):gsub("%s+$", "")
			if Query == "" then return "Provide text to search for." end
			local Limit = math.clamp(math.floor(tonumber(Args.Limit) or 30), 1, 60)
			local SearchSuccess, Descendants = pcall(function() return PlayerGui:GetDescendants() end)
			if not SearchSuccess then return "PlayerGui descendants couldn't be read." end
			local Matches = {}
			local Total = 0
			for _, Object in ipairs(Descendants) do
				local SearchText = Object.Name .. " " .. Object.ClassName
				local TextSuccess, TextValue = pcall(function()
					if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then return Object.Text end
					return ""
				end)
				if TextSuccess then SearchText = SearchText .. " " .. tostring(TextValue or "") end
				if string.find(string.lower(SearchText), Query, 1, true) then
					Total = Total + 1
					if #Matches < Limit then Matches[#Matches + 1] = GetObjectFullName(Object) .. " [" .. Object.ClassName .. "]" end
				end
			end
			local Lines = {"PlayerGui matches: " .. tostring(Total)}
			for Index, Match in ipairs(Matches) do Lines[#Lines + 1] = tostring(Index) .. ". " .. Match end
			if Total > #Matches then Lines[#Lines + 1] = "...and " .. tostring(Total - #Matches) .. " more." end
			return table.concat(Lines, "\n")
		end)
