		end)
		Main.FinMCPServer = FinMCP

		RequestFinAI = function(SystemPrompt, Source, Callback)
			local HttpService = service.HttpService
			local ListResponse = FinMCP.Handle({jsonrpc = "2.0", id = 1, method = "tools/list", params = {}})
			local ToolText = "[]"
			local ToolEncodeSuccess, ToolEncodeResult = pcall(HttpService.JSONEncode, HttpService, ListResponse and ListResponse.result and ListResponse.result.tools or {})
			if ToolEncodeSuccess then ToolText = ToolEncodeResult end
			local MCPPrompt = tostring(SystemPrompt or "") .. "\n\nYou have access to Valm Dex's embedded Model Context Protocol (MCP) server. Its tools are listed here as JSON schemas:\n" .. ToolText .. "\n\nWhen live Dex data or a Dex app action is needed, invoke exactly one tool by replying only with <MCP_CALL>{\"name\":\"tool_name\",\"arguments\":{}}</MCP_CALL>. The name and arguments must match one of the listed tools. Fin will dispatch it through the MCP JSON-RPC tools/call method and return the result to you. You may make up to eight tool calls for one user request. After receiving a tool result, answer naturally and only claim an action succeeded when its result confirms it. If no tool is needed, answer normally. Never invent objects, scripts, properties, app windows, or tool results. The MCP server can only access client-visible Roblox instances and Valm Dex features."
			local function RunFinTurn(CurrentSource, CallDepth)
				local Started, StartError = SendFinAIRequest(MCPPrompt, CurrentSource, function(Answer, AnswerError)
					if not Answer then
						pcall(Callback, nil, AnswerError)
						return
					end
					local CallJson = Answer:match("<MCP_CALL>%s*(.-)%s*</MCP_CALL>")
					if not CallJson then
						pcall(Callback, Answer)
						return
					end
					if CallDepth >= 8 then
						pcall(Callback, "I reached the MCP tool-call limit for this message. Please narrow the request and try again.")
						return
					end
					local DecodeSuccess, CallData = pcall(HttpService.JSONDecode, HttpService, CallJson)
					if not DecodeSuccess or type(CallData) ~= "table" then
						pcall(Callback, nil, "Fin returned an invalid MCP tool-call payload.")
						return
					end
					local ToolName = tostring(CallData.name or CallData.tool or "")
					local ToolArguments = type(CallData.arguments) == "table" and CallData.arguments or {}
					FinMCP.NextId = FinMCP.NextId + 1
					local ToolResponse = FinMCP.Handle({jsonrpc = "2.0", id = FinMCP.NextId, method = "tools/call", params = {name = ToolName, arguments = ToolArguments}})
					local ToolResult = ToolResponse and ToolResponse.result or ToolResponse and ToolResponse.error or {content = {{type = "text", text = "The MCP tool returned no response."}}, isError = true}
					local ResultParts = {}
					for _, Part in ipairs(ToolResult.content or {}) do
						if type(Part) == "table" and type(Part.text) == "string" then ResultParts[#ResultParts + 1] = Part.text end
					end
					local ResultText = table.concat(ResultParts, "\n")
					if ToolResult.isError then ResultText = "Tool error: " .. ResultText end
					local FollowUp = tostring(CurrentSource or "") .. "\n\nMCP tools/call result for " .. ToolName .. ":\n" .. ResultText .. "\n\nUse this verified result to answer the original user request. If another MCP tool is needed, use the same <MCP_CALL> format."
					local FollowStarted, FollowError = RunFinTurn(FollowUp, CallDepth + 1)
					if not FollowStarted and FollowError then pcall(Callback, nil, FollowError) end
				end)
				return Started, StartError
			end
			return RunFinTurn(Source, 0)
		end

		local VisSnap = setmetatable({}, {__mode = "k"})

		local function GetObjTargets(Object)
			local Targets = {Object}
			local DescOK, Descendants = pcall(function()
				return Object:GetDescendants()
			end)
			if DescOK and type(Descendants) == "table" then
				for _, Descendant in ipairs(Descendants) do
					Targets[#Targets + 1] = Descendant
				end
			end
			return Targets
		end

		local function GetFinBaseParts(Object)
			local Parts = {}
			for _, Target in ipairs(GetObjTargets(Object)) do
				local MatchSuccess, IsPart = pcall(function()
					return Target:IsA("BasePart")
				end)
				if MatchSuccess and IsPart then
					Parts[#Parts + 1] = Target
				end
			end
			return Parts
		end

		local function SetObjVisible(Object, IsVisible)
			local ChangedCount = 0
			for _, Target in ipairs(GetObjTargets(Object)) do
				local Properties = {}
				local HiddenValues = {}
				if Target:IsA("BasePart") then
					Properties = {"LocalTransparencyModifier"}
					HiddenValues = {LocalTransparencyModifier = 1}
				elseif Target:IsA("Decal") or Target:IsA("Texture") then
					Properties = {"Transparency"}
					HiddenValues = {Transparency = 1}
				elseif Target:IsA("GuiObject") then
					Properties = {"Visible"}
					HiddenValues = {Visible = false}
				elseif Target:IsA("BillboardGui") or Target:IsA("SurfaceGui") or Target:IsA("ScreenGui") then
					Properties = {"Enabled"}
					HiddenValues = {Enabled = false}
				elseif Target:IsA("ParticleEmitter") or Target:IsA("Trail") or Target:IsA("Beam") or Target:IsA("Fire") or Target:IsA("Smoke") or Target:IsA("Sparkles") or Target:IsA("Highlight") then
					Properties = {"Enabled"}
					HiddenValues = {Enabled = false}
				end
				if #Properties > 0 then
					if IsVisible then
						local Snapshot = VisSnap[Target]
						if Snapshot then
							for PropertyName, OriginalValue in pairs(Snapshot) do
								pcall(function()
									Target[PropertyName] = OriginalValue
								end)
							end
							VisSnap[Target] = nil
							ChangedCount = ChangedCount + 1
						end
					else
						local Snapshot = VisSnap[Target]
						if not Snapshot then
							Snapshot = {}
							for _, PropertyName in ipairs(Properties) do
								local ReadSuccess, OriginalValue = pcall(function()
									return Target[PropertyName]
								end)
								if ReadSuccess then
									Snapshot[PropertyName] = OriginalValue
								end
							end
							VisSnap[Target] = Snapshot
						end
						for PropertyName, HiddenValue in pairs(HiddenValues) do
							pcall(function()
								Target[PropertyName] = HiddenValue
							end)
						end
						ChangedCount = ChangedCount + 1
					end
				end
			end
			return ChangedCount
		end

		local UndoStack = {}

		local function ModifyFinObject(Action, Value, TargetObject)
			local Object = TargetObject or GetSelectedObject()
			if not Object then
				return false, "Select an object in Explorer first."
			end
			if Action == "create_child" then
				local ClassName = tostring(Value and Value.Class or "Folder")
				local AllowedClasses = {Folder = true, Model = true, Part = true, MeshPart = true, Attachment = true, WeldConstraint = true, Weld = true, Motor6D = true, BallSocketConstraint = true, HingeConstraint = true, AlignPosition = true, AlignOrientation = true, StringValue = true, BoolValue = true, IntValue = true, NumberValue = true, ObjectValue = true, Vector3Value = true, Color3Value = true, CFrameValue = true, Highlight = true, ClickDetector = true, ProximityPrompt = true, ParticleEmitter = true, Trail = true, Beam = true, Sound = true, Decal = true, Texture = true, SpecialMesh = true, PointLight = true, SpotLight = true, SurfaceLight = true, ScreenGui = true, BillboardGui = true, SurfaceGui = true, Frame = true, ScrollingFrame = true, TextLabel = true, TextButton = true, TextBox = true, ImageLabel = true, ImageButton = true, UIListLayout = true, UIGridLayout = true, UIPadding = true, UICorner = true, UIStroke = true}
				if not AllowedClasses[ClassName] then
					return false, "That class isn't in the supported child-creation list."
				end
				local CreateSuccess, NewObject = pcall(function()
					return Instance.new(ClassName)
				end)
				if not CreateSuccess or not NewObject then
					return false, "I couldn't create that instance class."
				end
				local NewName = tostring(Value and Value.Name or "")
				if NewName ~= "" then
					NewObject.Name = NewName
				end
				local ParentSuccess, ParentError = pcall(function()
					NewObject.Parent = Object
				end)
				if not ParentSuccess then
					pcall(function() NewObject:Destroy() end)
					return false, "The new object couldn't be parented: " .. tostring(ParentError)
				end
				if NewObject:IsA("BasePart") then
					pcall(function() NewObject.Anchored = true end)
					pcall(function() NewObject.Position = Object:IsA("BasePart") and Object.Position + Vector3.new(0, 3, 0) or Vector3.new(0, 5, 0) end)
				end
				SelectExplorerObject(NewObject)
				return true, "Created " .. NewObject.ClassName .. " '" .. NewObject.Name .. "' under " .. GetObjectFullName(Object) .. " locally and selected it."
			elseif Action == "set_property" then
				local PropertyName = tostring(Value and Value.Name or "")
				local PropertyValue = Value and Value.Value
				local AllowedProperties = {Name = true, Transparency = true, LocalTransparencyModifier = true, Reflectance = true, Anchored = true, CanCollide = true, CanTouch = true, CanQuery = true, Massless = true, CastShadow = true, Locked = true, Archivable = true, Material = true, Shape = true, Color = true, BrickColor = true, BackgroundColor3 = true, ImageColor3 = true, TextColor3 = true, BorderColor3 = true, Size = true, Position = true, CFrame = true, Orientation = true, PivotOffset = true, AnchorPoint = true, CanvasSize = true, Text = true, Visible = true, Enabled = true, Value = true, Volume = true, PlaybackSpeed = true, TimePosition = true, Looped = true, SoundId = true, CollisionGroup = true, WalkSpeed = true, JumpPower = true, JumpHeight = true, HipHeight = true, Health = true, MaxHealth = true, AutoRotate = true, PlatformStand = true, Brightness = true, Range = true, Rate = true, TextSize = true, TextTransparency = true, TextScaled = true, TextWrapped = true, BackgroundTransparency = true, ImageTransparency = true, Rotation = true, DisplayOrder = true, ZIndex = true, LayoutOrder = true, ClipsDescendants = true, Active = true, Selectable = true, Draggable = true, ScrollBarThickness = true, AutoButtonColor = true, TextEditable = true, ClearTextOnFocus = true, PlaceholderText = true, PlaceholderColor3 = true, BorderSizePixel = true, Image = true, Texture = true, MeshId = true, TextureID = true, AssemblyLinearVelocity = true, AssemblyAngularVelocity = true, Velocity = true, RotVelocity = true, RequiresNeck = true, BreakJointsOnDeath = true, UseJumpPower = true, Sit = true, Jump = true, CameraOffset = true, FieldOfView = true, Focus = true, Ambient = true, OutdoorAmbient = true, TimeOfDay = true, ClockTime = true, FogColor = true, FogEnd = true, FogStart = true, GlobalShadows = true, ExposureCompensation = true, EnvironmentDiffuseScale = true, EnvironmentSpecularScale = true}
				if not AllowedProperties[PropertyName] then
					return false, "That property isn't in Fin's supported property-edit list."
				end
				local ReadSuccess, CurrentValue = pcall(function() return Object[PropertyName] end)
				if not ReadSuccess then
					return false, "The selected object doesn't expose a readable " .. PropertyName .. " property."
				end
				local TextValue = tostring(PropertyValue or "")
				local NewValue
				local CurrentType = typeof(CurrentValue)
				if CurrentType == "boolean" then
					local LowerValue = string.lower(TextValue)
					if LowerValue == "true" or LowerValue == "on" or LowerValue == "yes" then
						NewValue = true
					elseif LowerValue == "false" or LowerValue == "off" or LowerValue == "no" then
						NewValue = false
					else
						return false, "Use true or false for " .. PropertyName .. "."
					end
				elseif CurrentType == "number" then
					NewValue = tonumber(TextValue)
					if not NewValue then return false, "Give me a numeric value for " .. PropertyName .. "." end
				elseif CurrentType == "string" then
					NewValue = TextValue
				elseif CurrentType == "Vector3" or CurrentType == "Vector2" or CurrentType == "UDim" or CurrentType == "UDim2" or CurrentType == "NumberRange" or CurrentType == "Rect" or CurrentType == "CFrame" then
					local NumericValues = {}
					for NumericText in TextValue:gmatch("[%-%.%d]+") do
						NumericValues[#NumericValues + 1] = tonumber(NumericText)
					end
					if CurrentType == "Vector3" and #NumericValues == 3 then
						NewValue = Vector3.new(NumericValues[1], NumericValues[2], NumericValues[3])
					elseif CurrentType == "Vector2" and #NumericValues == 2 then
						NewValue = Vector2.new(NumericValues[1], NumericValues[2])
					elseif CurrentType == "UDim" and #NumericValues == 2 then
						NewValue = UDim.new(NumericValues[1], NumericValues[2])
					elseif CurrentType == "UDim2" and #NumericValues == 4 then
						NewValue = UDim2.new(NumericValues[1], NumericValues[2], NumericValues[3], NumericValues[4])
					elseif CurrentType == "NumberRange" and #NumericValues == 2 then
						NewValue = NumberRange.new(NumericValues[1], NumericValues[2])
					elseif CurrentType == "Rect" and #NumericValues == 4 then
						NewValue = Rect.new(NumericValues[1], NumericValues[2], NumericValues[3], NumericValues[4])
					elseif CurrentType == "CFrame" and #NumericValues == 3 then
						NewValue = CFrame.new(NumericValues[1], NumericValues[2], NumericValues[3])
					elseif CurrentType == "CFrame" and #NumericValues == 12 then
						NewValue = CFrame.new(table.unpack(NumericValues))
					else
						return false, "The value format doesn't match the " .. PropertyName .. " property type."
					end
				elseif CurrentType == "BrickColor" then
					local BrickColorSuccess, BrickColorValue = pcall(BrickColor.new, TextValue)
					if not BrickColorSuccess then return false, "That isn't a valid BrickColor name or number." end
					NewValue = BrickColorValue
				elseif CurrentType == "Color3" then
					local RedValue, GreenValue, BlueValue = TextValue:match("(%d+)%s*[, ]%s*(%d+)%s*[, ]%s*(%d+)")
					local ColorNames = {red = Color3.fromRGB(255, 0, 0), orange = Color3.fromRGB(255, 145, 0), yellow = Color3.fromRGB(255, 255, 0), green = Color3.fromRGB(0, 170, 0), lime = Color3.fromRGB(80, 255, 0), blue = Color3.fromRGB(0, 85, 255), cyan = Color3.fromRGB(0, 220, 220), teal = Color3.fromRGB(0, 128, 128), purple = Color3.fromRGB(150, 70, 220), magenta = Color3.fromRGB(255, 0, 255), pink = Color3.fromRGB(255, 105, 180), white = Color3.fromRGB(255, 255, 255), black = Color3.fromRGB(0, 0, 0), gray = Color3.fromRGB(128, 128, 128), grey = Color3.fromRGB(128, 128, 128), brown = Color3.fromRGB(120, 75, 35), gold = Color3.fromRGB(255, 196, 0), silver = Color3.fromRGB(192, 192, 192)}
					NewValue = RedValue and Color3.fromRGB(math.clamp(tonumber(RedValue), 0, 255), math.clamp(tonumber(GreenValue), 0, 255), math.clamp(tonumber(BlueValue), 0, 255)) or ColorNames[string.lower(TextValue)]
					if not NewValue then return false, "Use a color name or three RGB values for " .. PropertyName .. "." end
				elseif CurrentType == "EnumItem" then
					local EnumSuccess, EnumValue = pcall(function() return Enum[CurrentValue.EnumType.Name][TextValue:gsub("%s+", "")] end)
					if not EnumSuccess or not EnumValue then return false, "That isn't a valid " .. CurrentValue.EnumType.Name .. " value." end
					NewValue = EnumValue
				else
					return false, "Fin can't safely convert text into the current " .. PropertyName .. " property type."
				end
				local WriteSuccess, WriteError = pcall(function() Object[PropertyName] = NewValue end)
				return WriteSuccess, WriteSuccess and ("Set " .. PropertyName .. " on " .. GetObjectFullName(Object) .. " locally.") or ("Property update failed: " .. tostring(WriteError))
			elseif Action == "delete" then
				local ObjectName = Object.Name
				local OriginalParent = Object.Parent
				local SnapshotSuccess, SnapshotObject = pcall(function()
					return Object:Clone()
				end)
				if not SnapshotSuccess or not SnapshotObject then
					return false, "I couldn't create an undo snapshot, so I left " .. ObjectName .. " untouched. Check its Archivable setting."
				end
				table.insert(UndoStack, {Snapshot = SnapshotObject, Parent = OriginalParent, Name = ObjectName, ClassName = Object.ClassName})
				while #UndoStack > 20 do
					local OldestRecord = table.remove(UndoStack, 1)
					if OldestRecord and OldestRecord.Snapshot then
						pcall(function() OldestRecord.Snapshot:Destroy() end)
					end
				end
				local DestroySuccess, DestroyError = pcall(function()
					Object:Destroy()
				end)
				if not DestroySuccess then
					local LatestRecord = table.remove(UndoStack)
					if LatestRecord and LatestRecord.Snapshot then pcall(function() LatestRecord.Snapshot:Destroy() end) end
					return false, "Delete failed: " .. tostring(DestroyError)
				end
				return true, "Deleted " .. ObjectName .. " locally. Fin saved an undo snapshot; say undo deletion to restore it. This does not delete the server-owned copy."
			elseif Action == "clone" then
				local CloneSuccess, CloneObject = pcall(function()
					return Object:Clone()
				end)
				if not CloneSuccess or not CloneObject then
					return false, "This object could not be cloned. Check its Archivable setting."
				end
				local ParentSuccess = pcall(function()
					CloneObject.Parent = Object.Parent
				end)
				if not ParentSuccess then
					pcall(function() CloneObject:Destroy() end)
					return false, "The clone could not be placed beside the original object."
				end
				SelectExplorerObject(CloneObject)
				return true, "Cloned " .. Object.Name .. " and selected the new copy."
			elseif Action == "rename" then
				local NewName = tostring(Value or ""):gsub("^%s+", ""):gsub("%s+$", "")
				if NewName == "" then
					return false, "Tell me the new name. Use: rename selected to MyPart."
				end
				local RenameSuccess, RenameError = pcall(function()
					Object.Name = NewName
				end)
				return RenameSuccess, RenameSuccess and ("Renamed the selected object to " .. NewName .. ".") or ("Rename failed: " .. tostring(RenameError))
			elseif Action == "toggle_archivable" or Action == "archivable" then
				local ReadSuccess, CurrentValue = pcall(function() return Object.Archivable end)
				if not ReadSuccess then return false, "The selected object does not expose Archivable." end
				local NewValue = Action == "archivable" and true or not CurrentValue
				local WriteSuccess, WriteError = pcall(function() Object.Archivable = NewValue end)
				return WriteSuccess, WriteSuccess and ("Archivable set to " .. tostring(NewValue) .. ".") or ("Archivable update failed: " .. tostring(WriteError))
			elseif Action == "hide" or Action == "show" then
				local ChangedCount = SetObjVisible(Object, Action == "show")
				if ChangedCount == 0 then
					return false, "I couldn't find supported visual properties on that object or its descendants."
				end
				return true, (Action == "show" and "Restored visibility for " or "Hidden ") .. Object.Name .. " locally across " .. tostring(ChangedCount) .. " visual object(s)."
			elseif Action == "anchor" or Action == "unanchor" or Action == "toggle_anchor" or Action == "collision" or Action == "collision_off" or Action == "toggle_collision" or Action == "touch" or Action == "toggle_touch" or Action == "query" or Action == "toggle_query" or Action == "massless" or Action == "toggle_massless" or Action == "cast_shadow" or Action == "toggle_cast_shadow" or Action == "toggle_locked" or Action == "locked" or Action == "unlock" then
				local Parts = GetFinBaseParts(Object)
				if #Parts == 0 then
					return false, "That object has no BaseParts to modify."
				end
				local PropertyName
				local NewValue
				if Action == "anchor" or Action == "unanchor" or Action == "toggle_anchor" then
					PropertyName = "Anchored"
				elseif Action == "collision" or Action == "collision_off" or Action == "toggle_collision" then
					PropertyName = "CanCollide"
				elseif Action == "touch" or Action == "toggle_touch" then
					PropertyName = "CanTouch"
				elseif Action == "query" or Action == "toggle_query" then
					PropertyName = "CanQuery"
				elseif Action == "massless" or Action == "toggle_massless" then
					PropertyName = "Massless"
				elseif Action == "toggle_locked" or Action == "locked" or Action == "unlock" then
					PropertyName = "Locked"
				else
					PropertyName = "CastShadow"
				end
				if Action == "anchor" or Action == "collision" or Action == "touch" or Action == "query" or Action == "massless" or Action == "cast_shadow" then
					NewValue = true
				elseif Action == "unanchor" or Action == "collision_off" or Action == "unlock" then
					NewValue = false
				elseif Action == "locked" then
					NewValue = true
				else
					NewValue = not Parts[1][PropertyName]
				end
				local ChangedCount = 0
				for _, Part in ipairs(Parts) do
					local WriteSuccess = pcall(function()
						Part[PropertyName] = NewValue
					end)
					if WriteSuccess then ChangedCount = ChangedCount + 1 end
				end
				return ChangedCount > 0, PropertyName .. " set to " .. tostring(NewValue) .. " on " .. tostring(ChangedCount) .. " part(s), locally."
			elseif Action == "transparency" then
				local Transparency = tonumber(Value)
				if not Transparency then return false, "Give me a number from 0 to 1 for transparency." end
				Transparency = math.clamp(Transparency, 0, 1)
				local ChangedCount = 0
				for _, Target in ipairs(GetObjTargets(Object)) do
					if Target:IsA("BasePart") or Target:IsA("Decal") or Target:IsA("Texture") then
						local WriteSuccess = pcall(function() Target.Transparency = Transparency end)
						if WriteSuccess then ChangedCount = ChangedCount + 1 end
					elseif Target:IsA("GuiObject") then
						local WriteSuccess = pcall(function()
							Target.BackgroundTransparency = Transparency
							if Target:IsA("TextLabel") or Target:IsA("TextButton") or Target:IsA("TextBox") then Target.TextTransparency = Transparency end
							if Target:IsA("ImageLabel") or Target:IsA("ImageButton") then Target.ImageTransparency = Transparency end
						end)
						if WriteSuccess then ChangedCount = ChangedCount + 1 end
					end
				end
				return ChangedCount > 0, "Set transparency to " .. tostring(Transparency) .. " on " .. tostring(ChangedCount) .. " visual object(s)."
			elseif Action == "color" then
				if typeof(Value) ~= "Color3" then return false, "I couldn't understand that color. Use a color name or RGB values." end
				local ChangedCount = 0
				for _, Target in ipairs(GetObjTargets(Object)) do
					local WriteSuccess = pcall(function()
						if Target:IsA("BasePart") then
							Target.Color = Value
						elseif Target:IsA("TextLabel") or Target:IsA("TextButton") or Target:IsA("TextBox") then
							Target.TextColor3 = Value
							Target.BackgroundColor3 = Value
						elseif Target:IsA("ImageLabel") or Target:IsA("ImageButton") then
							Target.ImageColor3 = Value
							Target.BackgroundColor3 = Value
						elseif Target:IsA("TextLabel") or Target:IsA("TextButton") or Target:IsA("TextBox") then
							Target.TextColor3 = Value
							Target.BackgroundColor3 = Value
						elseif Target:IsA("ImageLabel") or Target:IsA("ImageButton") then
							Target.ImageColor3 = Value
							Target.BackgroundColor3 = Value
						elseif Target:IsA("GuiObject") then
							Target.BackgroundColor3 = Value
						elseif Target:IsA("Decal") or Target:IsA("Texture") then
							Target.Color3 = Value
						elseif Target:IsA("Highlight") then
							Target.FillColor = Value
							Target.OutlineColor = Value
						elseif Target:IsA("Light") then
							Target.Color = Value
						else
							error("This instance has no supported color property")
						end
					end)
					if WriteSuccess then ChangedCount = ChangedCount + 1 end
				end
				return ChangedCount > 0, "Changed the color of " .. tostring(ChangedCount) .. " visual object(s)."
			elseif Action == "size" then
				if typeof(Value) ~= "Vector3" then return false, "Give me three size values. Use: set size to 4, 2, 4." end
				local Parts = GetFinBaseParts(Object)
				local ChangedCount = 0
				local NewSize = Vector3.new(math.clamp(Value.X, 0.05, 2048), math.clamp(Value.Y, 0.05, 2048), math.clamp(Value.Z, 0.05, 2048))
				for _, Part in ipairs(Parts) do
					local WriteSuccess = pcall(function() Part.Size = NewSize end)
					if WriteSuccess then ChangedCount = ChangedCount + 1 end
				end
				return ChangedCount > 0, "Set the size to " .. tostring(NewSize) .. " on " .. tostring(ChangedCount) .. " part(s), locally."
			elseif Action == "scale" then
				local ScaleFactor = tonumber(Value)
				if not ScaleFactor or ScaleFactor <= 0 then return false, "Give me a positive scale factor, such as 1.25 or 0.8." end
				ScaleFactor = math.clamp(ScaleFactor, 0.05, 20)
				local Parts = GetFinBaseParts(Object)
				local GuiObjects = {}
				for _, Target in ipairs(GetObjTargets(Object)) do
					if Target:IsA("GuiObject") then GuiObjects[#GuiObjects + 1] = Target end
				end
				if #Parts == 0 and #GuiObjects == 0 then return false, "That object has no resizable BaseParts or GUI objects." end
				local ChangedCount = 0
				if #Parts > 0 then
					local Pivot
					local PivotSuccess = pcall(function()
						if Object:IsA("Model") then
							Pivot = Object:GetPivot()
						elseif Object:IsA("BasePart") then
							Pivot = Object.CFrame
						else
							Pivot = Parts[1].CFrame
						end
					end)
					if not PivotSuccess or not Pivot then return false, "I couldn't calculate a safe resize pivot for that object." end
					for _, Part in ipairs(Parts) do
						local WriteSuccess = pcall(function()
							local RelativeFrame = Pivot:ToObjectSpace(Part.CFrame)
							local RelativeRotation = RelativeFrame - RelativeFrame.Position
							local RelativePosition = RelativeFrame.Position * ScaleFactor
							local ScaledSize = Part.Size * ScaleFactor
							Part.Size = Vector3.new(math.clamp(ScaledSize.X, 0.05, 2048), math.clamp(ScaledSize.Y, 0.05, 2048), math.clamp(ScaledSize.Z, 0.05, 2048))
							Part.CFrame = Pivot * CFrame.new(RelativePosition) * RelativeRotation
						end)
						if WriteSuccess then ChangedCount = ChangedCount + 1 end
					end
				end
				for _, GuiObject in ipairs(GuiObjects) do
					local WriteSuccess = pcall(function()
						local CurrentSize = GuiObject.Size
						GuiObject.Size = UDim2.new(CurrentSize.X.Scale * ScaleFactor, math.floor(CurrentSize.X.Offset * ScaleFactor), CurrentSize.Y.Scale * ScaleFactor, math.floor(CurrentSize.Y.Offset * ScaleFactor))
					end)
					if WriteSuccess then ChangedCount = ChangedCount + 1 end
				end
				return ChangedCount > 0, "Scaled " .. tostring(ChangedCount) .. " part or GUI object(s) by " .. tostring(ScaleFactor) .. "x locally."
			elseif Action == "rotate" then
				if typeof(Value) ~= "Vector3" then return false, "Give me three rotation values in degrees. Use: rotate selected by 0, 90, 0." end
				local Rotation = CFrame.Angles(math.rad(Value.X), math.rad(Value.Y), math.rad(Value.Z))
				local RotateSuccess, RotateError = pcall(function()
					if Object:IsA("Model") then
						Object:PivotTo(Object:GetPivot() * Rotation)
					elseif Object:IsA("BasePart") then
						Object.CFrame = Object.CFrame * Rotation
					else
						error("Select a Model or BasePart to rotate")
					end
				end)
				return RotateSuccess, RotateSuccess and "Rotated the selected object locally." or ("Rotation failed: " .. tostring(RotateError))
			elseif Action == "reparent" then
				if typeof(Value) ~= "Instance" then return false, "Choose a valid parent instance." end
				if Value == Object or Value:IsDescendantOf(Object) then return false, "An object cannot be parented to itself or one of its descendants." end
				local ParentSuccess, ParentError = pcall(function() Object.Parent = Value end)
				return ParentSuccess, ParentSuccess and ("Moved " .. Object.Name .. " under " .. Value:GetFullName() .. " locally.") or ("Reparent failed: " .. tostring(ParentError))
			elseif Action == "material" then
				local MaterialName = tostring(Value or ""):gsub("%s+", "")
				local Material = Enum.Material[MaterialName]
				if not Material then return false, "That isn't a recognized Enum.Material name." end
				local Parts = GetFinBaseParts(Object)
				local ChangedCount = 0
				for _, Part in ipairs(Parts) do
					local WriteSuccess = pcall(function() Part.Material = Material end)
					if WriteSuccess then ChangedCount = ChangedCount + 1 end
				end
				return ChangedCount > 0, "Set material to " .. Material.Name .. " on " .. tostring(ChangedCount) .. " part(s)."
			elseif Action == "move_to_me" or Action == "position" then
				local Destination
				if Action == "move_to_me" then
					local LocalPlayer = service.Players.LocalPlayer
					local Character = LocalPlayer and LocalPlayer.Character
					local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
					if not RootPart then return false, "Your character's HumanoidRootPart isn't available." end
					Destination = RootPart.CFrame * CFrame.new(0, 0, -5)
				else
					if typeof(Value) ~= "Vector3" then return false, "Use three coordinates. Format: set position to 0, 10, 0." end
					Destination = CFrame.new(Value)
				end
				local MoveSuccess, MoveError = pcall(function()
					if Object:IsA("Model") then
						Object:PivotTo(Destination)
					elseif Object:IsA("BasePart") then
						Object.CFrame = Destination
					else
						error("Select a Model or BasePart to move")
					end
				end)
				return MoveSuccess, MoveSuccess and ("Moved " .. Object.Name .. " locally.") or ("Move failed: " .. tostring(MoveError))
			elseif Action == "break_joints" then
				local BreakSuccess, BreakError = pcall(function() Object:BreakJoints() end)
				return BreakSuccess, BreakSuccess and ("Broke joints for " .. Object.Name .. " locally.") or ("Break joints failed: " .. tostring(BreakError))
			elseif Action == "value" then
				if not Object:IsA("ValueBase") then return false, "Select a ValueBase object such as a StringValue, NumberValue or BoolValue." end
				local NewValue = Value
				if Object:IsA("BoolValue") then
					local LowerValue = string.lower(tostring(Value))
					if LowerValue ~= "true" and LowerValue ~= "false" then return false, "BoolValue accepts true or false." end
					NewValue = LowerValue == "true"
				elseif Object:IsA("NumberValue") or Object:IsA("IntValue") then
					NewValue = tonumber(Value)
					if not NewValue then return false, "That Value object needs a number." end
				else
					NewValue = tostring(Value or "")
				end
				local WriteSuccess, WriteError = pcall(function() Object.Value = NewValue end)
				return WriteSuccess, WriteSuccess and "Updated the selected Value object locally." or ("Value update failed: " .. tostring(WriteError))
			elseif Action == "text" then
				local TextSuccess, TextError = pcall(function() Object.Text = tostring(Value or "") end)
				return TextSuccess, TextSuccess and "Updated the selected object's Text property locally." or ("Text update failed: " .. tostring(TextError))
			elseif Action == "select_parent" then
				if not Object.Parent then return false, "The selected object has no parent." end
				SelectExplorerObject(Object.Parent)
				return true, "Selected the parent of " .. Object.Name .. "."
			elseif Action == "set_attribute" then
				local AttributeName = Value and Value.Name
				local AttributeValue = Value and Value.Value
				if type(AttributeName) ~= "string" or AttributeName == "" then return false, "Give me an attribute name and value." end
				local ConvertedValue = AttributeValue
				if type(AttributeValue) == "string" then
					local LowerValue = string.lower(AttributeValue)
					if LowerValue == "true" then ConvertedValue = true
					elseif LowerValue == "false" then ConvertedValue = false
					elseif tonumber(AttributeValue) then ConvertedValue = tonumber(AttributeValue) end
				end
				local AttributeSuccess, AttributeError = pcall(function() Object:SetAttribute(AttributeName, ConvertedValue) end)
				return AttributeSuccess, AttributeSuccess and ("Set attribute " .. AttributeName .. " locally.") or ("Attribute update failed: " .. tostring(AttributeError))
			elseif Action == "remove_attribute" then
				local AttributeName = tostring(Value or "")
				if AttributeName == "" then return false, "Tell me the attribute name to remove." end
				local AttributeSuccess, AttributeError = pcall(function() Object:SetAttribute(AttributeName, nil) end)
				return AttributeSuccess, AttributeSuccess and ("Removed attribute " .. AttributeName .. " locally.") or ("Attribute removal failed: " .. tostring(AttributeError))
			elseif Action == "clear_attributes" then
				local AttributeSuccess, Attributes = pcall(function() return Object:GetAttributes() end)
				if not AttributeSuccess then return false, "I couldn't read this object's attributes." end
				local RemovedCount = 0
				for AttributeName in pairs(Attributes) do
					if pcall(function() Object:SetAttribute(AttributeName, nil) end) then RemovedCount = RemovedCount + 1 end
				end
				return true, "Cleared " .. tostring(RemovedCount) .. " attribute(s) from " .. Object.Name .. " locally."
			elseif Action == "add_tag" or Action == "remove_tag" then
				local TagName = tostring(Value or ""):gsub("^%s+", ""):gsub("%s+$", "")
				if TagName == "" then return false, "Give me a non-empty CollectionService tag name." end
				local TagServiceSuccess, TagService = pcall(function() return game:GetService("CollectionService") end)
				if not TagServiceSuccess then return false, "CollectionService is unavailable." end
				local TagSuccess, TagError = pcall(function()
					if Action == "add_tag" then TagService:AddTag(Object, TagName) else TagService:RemoveTag(Object, TagName) end
				end)
				return TagSuccess, TagSuccess and ((Action == "add_tag" and "Added tag " or "Removed tag ") .. TagName .. " locally.") or ("Tag update failed: " .. tostring(TagError))
			elseif Action == "weld_to" then
				local TargetObject = Value
				if typeof(TargetObject) ~= "Instance" or TargetObject == Object or TargetObject:IsDescendantOf(Object) or Object:IsDescendantOf(TargetObject) then
					return false, "Choose a different target object outside the source hierarchy."
				end
				local SourceParts = GetFinBaseParts(Object)
				local TargetParts = GetFinBaseParts(TargetObject)
				local SourcePart = Object:IsA("BasePart") and Object or SourceParts[1]
				local TargetPart = TargetObject:IsA("BasePart") and TargetObject or TargetParts[1]
				if not SourcePart or not TargetPart then return false, "Both objects need at least one BasePart." end
				local WeldSuccess, WeldOrError = pcall(function()
					local NewWeld = Instance.new("WeldConstraint")
					NewWeld.Name = "FinWeld"
					NewWeld.Part0 = SourcePart
					NewWeld.Part1 = TargetPart
					NewWeld.Parent = SourcePart
					return NewWeld
				end)
				return WeldSuccess, WeldSuccess and ("Created a local WeldConstraint between " .. GetObjectFullName(SourcePart) .. " and " .. GetObjectFullName(TargetPart) .. ".") or ("Weld failed: " .. tostring(WeldOrError))
			elseif Action == "unweld" then
				local RemovedCount = 0
				for _, Target in ipairs(GetObjTargets(Object)) do
					if Target:IsA("WeldConstraint") or Target:IsA("Weld") then
						if pcall(function() Target:Destroy() end) then RemovedCount = RemovedCount + 1 end
					end
				end
				return RemovedCount > 0, "Removed " .. tostring(RemovedCount) .. " WeldConstraint/Weld object(s) locally."
			elseif Action == "set_primary_part" then
				if not Object:IsA("Model") then return false, "The source object must be a Model." end
				if typeof(Value) ~= "Instance" or not Value:IsA("BasePart") or not Value:IsDescendantOf(Object) then return false, "The PrimaryPart must be a BasePart inside that Model." end
				local PrimarySuccess, PrimaryError = pcall(function() Object.PrimaryPart = Value end)
				return PrimarySuccess, PrimarySuccess and ("Set " .. Value.Name .. " as the PrimaryPart of " .. Object.Name .. ".") or ("PrimaryPart update failed: " .. tostring(PrimaryError))
			elseif Action == "physical_property" then
				local PropertyName = tostring(Value and Value.Name or "")
				local PropertyValue = tonumber(Value and Value.Value)
				local Limits = {Density = {0.01, 100}, Friction = {0, 2}, Elasticity = {0, 1}, FrictionWeight = {0, 100}, ElasticityWeight = {0, 100}}
				local Limit = Limits[PropertyName]
				if not Limit or not PropertyValue then return false, "Use density, friction, elasticity, friction weight, or elasticity weight with a numeric value." end
				PropertyValue = math.clamp(PropertyValue, Limit[1], Limit[2])
				local ChangedCount = 0
				for _, Part in ipairs(GetFinBaseParts(Object)) do
					local WriteSuccess = pcall(function()
						local Current = Part.CurrentPhysicalProperties
						local Density = PropertyName == "Density" and PropertyValue or Current.Density
						local Friction = PropertyName == "Friction" and PropertyValue or Current.Friction
						local Elasticity = PropertyName == "Elasticity" and PropertyValue or Current.Elasticity
						local FrictionWeight = PropertyName == "FrictionWeight" and PropertyValue or Current.FrictionWeight
						local ElasticityWeight = PropertyName == "ElasticityWeight" and PropertyValue or Current.ElasticityWeight
						Part.CustomPhysicalProperties = PhysicalProperties.new(Density, Friction, Elasticity, FrictionWeight, ElasticityWeight)
					end)
					if WriteSuccess then ChangedCount = ChangedCount + 1 end
				end
				return ChangedCount > 0, "Updated " .. PropertyName .. " on " .. tostring(ChangedCount) .. " BasePart(s) locally."
			end
			return false, "I don't recognize that object modification yet."
		end

		local function ModifySelection(Action, Value)
			local SelectedObjects = GetPicked()
			if #SelectedObjects == 0 and Action == "create_child" then
				return ModifyFinObject(Action, Value, workspace)
			end
			if #SelectedObjects == 0 then
				return false, "Select an object in Explorer first."
			end
			if Action == "select_parent" then
				local ParentObjects = {}
				local SeenParents = {}
				for _, Object in ipairs(SelectedObjects) do
					local ParentObject = Object.Parent
					if ParentObject and not SeenParents[ParentObject] then
						SeenParents[ParentObject] = true
						table.insert(ParentObjects, ParentObject)
					end
				end
				local SelectSuccess, SelectCount = SetExpSelection(ParentObjects)
				return SelectSuccess, SelectSuccess and ("Selected " .. tostring(SelectCount) .. " parent object(s).") or tostring(SelectCount)
			end
			local SelectedSet = {}
			for _, Object in ipairs(SelectedObjects) do
				SelectedSet[Object] = true
			end
			local TopLevelObjects = {}
			for _, Object in ipairs(SelectedObjects) do
				local ParentObject = Object.Parent
				local HasPickedAncestor = false
				while ParentObject do
					if SelectedSet[ParentObject] then
						HasPickedAncestor = true
						break
					end
					ParentObject = ParentObject.Parent
				end
				if not HasPickedAncestor then
					table.insert(TopLevelObjects, Object)
				end
			end
			local ChangedCount = 0
			local FailedCount = 0
			local FirstFailure
			for _, Object in ipairs(TopLevelObjects) do
				local ActionSuccess, ActionMessage = ModifyFinObject(Action, Value, Object)
				if ActionSuccess then
					ChangedCount = ChangedCount + 1
				else
					FailedCount = FailedCount + 1
					FirstFailure = FirstFailure or tostring(ActionMessage)
				end
			end
			if ChangedCount == 0 then
				return false, FirstFailure or "No selected objects could be modified."
			end
			local ResultMessage = "Applied " .. Action .. " to " .. tostring(ChangedCount) .. " selected object group(s)."
			if FailedCount > 0 then
				ResultMessage = ResultMessage .. " " .. tostring(FailedCount) .. " group(s) failed: " .. tostring(FirstFailure)
			end
			return true, ResultMessage
		end

			local function UndoFinDeletion()
				local Record = table.remove(UndoStack)
				if not Record then
					return false, "There is no recent Fin deletion to undo."
				end
				if not Record.Snapshot or not Record.Parent then
					table.insert(UndoStack, Record)
					return false, "The original parent is no longer available, so that deletion cannot be restored."
				end
				local RestoreSuccess, RestoreError = pcall(function()
					Record.Snapshot.Name = Record.Name
					Record.Snapshot.Parent = Record.Parent
				end)
				if not RestoreSuccess then
					table.insert(UndoStack, Record)
					return false, "Undo failed: " .. tostring(RestoreError)
				end
				pcall(SelectExplorerObject, Record.Snapshot)
				return true, "Restored " .. Record.Name .. " (" .. tostring(Record.ClassName) .. ") locally and selected it."
			end

			Main.UndoFinDeletion = UndoFinDeletion

			local function BuildCodeOutline(Source)
			local Lines = string.split(Source, "\n")
			local _, FunctionCount = Source:gsub("function%s*[%w_%.:]*%s*%(", "")
			local _, EventCount = Source:gsub(":Connect%s*%(", "")
			local _, LoopCount = Source:gsub("for%s+", "")
			local _, ServiceCount = Source:gsub("GetService%s*%(", "")
			local _, RemoteEventCount = Source:gsub("FireServer%s*%(", "")
			local _, RemoteFunctionCount = Source:gsub("InvokeServer%s*%(", "")
			local FunctionNames = {}
			for _, Line in ipairs(Lines) do
				local FunctionName = Line:match("^%s*local%s+function%s+([%w_%.:]+)")
					or Line:match("^%s*function%s+([%w_%.:]+)")
					or Line:match("^%s*([%w_%.:]+)%s*=%s*function%s*%(")
				if FunctionName and not table.find(FunctionNames, FunctionName) and #FunctionNames < 6 then
					table.insert(FunctionNames, FunctionName)
				end
			end
			local Outline = "Code overview: " .. tostring(#Lines) .. " line(s), " .. tostring(#Source) .. " characters, " .. tostring(FunctionCount) .. " function(s), " .. tostring(EventCount) .. " event connection(s), " .. tostring(LoopCount) .. " loop(s), and " .. tostring(ServiceCount) .. " service lookup(s)."
			if #FunctionNames > 0 then
				Outline = Outline .. " Functions include: " .. table.concat(FunctionNames, ", ") .. "."
			end
			if RemoteEventCount + RemoteFunctionCount > 0 then
				Outline = Outline .. " Remote calls: " .. tostring(RemoteEventCount) .. " FireServer and " .. tostring(RemoteFunctionCount) .. " InvokeServer."
			end
			return Outline
		end

		local function BuildLocalAudit(Source)
			local Findings = {}
			local HasYield = Source:find("task.wait", 1, true) ~= nil or Source:find("wait(", 1, true) ~= nil or Source:find("Heartbeat", 1, true) ~= nil or Source:find("RenderStepped", 1, true) ~= nil
			local HasHttpFetch = Source:find("HttpGet", 1, true) ~= nil or Source:find("request(", 1, true) ~= nil
			local HasLoadstring = Source:find("loadstring", 1, true) ~= nil
			local function AddFinding(Message)
				if #Findings < 5 and not table.find(Findings, Message) then
					table.insert(Findings, Message)
				end
			end
			local LineNumber = 0
			for Line in Source:gmatch("[^\n]*\n?") do
				if Line == "" then
					break
				end
				LineNumber = LineNumber + 1
				local LowerLine = string.lower(Line)
				if Line:match("%f[%w]wait%s*%(") and not Line:match("task%s*%.%s*wait%s*%(") then
					AddFinding("Line " .. tostring(LineNumber) .. ": legacy wait() found; consider task.wait().")
				end
				if Line:match("%f[%w]spawn%s*%(") and not Line:match("task%s*%.%s*spawn%s*%(") then
					AddFinding("Line " .. tostring(LineNumber) .. ": legacy spawn() found; consider task.spawn().")
				end
				local KeyName, KeyValue = LowerLine:match("([%w_]*key[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				if not KeyName then
					KeyName, KeyValue = LowerLine:match("([%w_]*token[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				end
				if not KeyName then
					KeyName, KeyValue = LowerLine:match("([%w_]*secret[%w_]*)%s*=%s*['\"]([^'\"]+)['\"]")
				end
				if KeyName and KeyValue and #KeyValue >= 12 then
					AddFinding("Line " .. tostring(LineNumber) .. ": possible hard-coded credential in " .. tostring(KeyName) .. "; review and rotate it if genuine.")
				end
				if LowerLine:find("while true do", 1, true) and not HasYield then
					AddFinding("Line " .. tostring(LineNumber) .. ": possible infinite loop without an obvious yield.")
				end
			end
			if HasHttpFetch and HasLoadstring then
				AddFinding("The script combines remote fetching and dynamic code execution; verify the downloaded source before running it.")
			end
			local _, FireServerCount = Source:gsub("FireServer%s*%(", "")
			local _, InvokeServerCount = Source:gsub("InvokeServer%s*%(", "")
			if FireServerCount + InvokeServerCount > 0 then
				AddFinding("Remote requests detected: " .. tostring(FireServerCount) .. " FireServer and " .. tostring(InvokeServerCount) .. " InvokeServer call(s); confirm the server validates every argument.")
			end
			if #Findings == 0 then
				return "The lightweight scan found no common issues. This is a pattern check, not a full Luau parser or security guarantee."
			end
			return "I found " .. tostring(#Findings) .. " item(s) to review: " .. table.concat(Findings, " ") .. " This is a lightweight scan, not a full parser."
		end

		local function AfterPhrase(Query, Phrases)
			local LowerQuery = string.lower(Query)
			for _, Phrase in ipairs(Phrases) do
				local _, PhraseEnd = LowerQuery:find(Phrase, 1, true)
				if PhraseEnd then
					local Value = Query:sub(PhraseEnd + 1)
					Value = Value:gsub("^%s+", ""):gsub("[%s%.%!%?]+$", "")
					for _, Suffix in ipairs({" please", " pls", " for me", " right now", " thanks"}) do
						if string.lower(Value):sub(-#Suffix) == Suffix then
							Value = Value:sub(1, -#Suffix - 1):gsub("%s+$", "")
						end
					end
					if Value ~= "" then
						return Value
					end
				end
			end
			return nil
		end

		local function NormalizeFinQuery(Value)
			local Result = tostring(Value or ""):gsub("[%c]", " ")
			Result = Result:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
			Result = Result:gsub("[Dd][Ee][Ss][Cc][Ee][Nn][Dd][Ee][Nn][Tt][Ss]", "descendants")
			Result = Result:gsub("[Dd][Ee][Ss][Cc][Ee][Nn][Dd][Ee][Nn][Tt]", "descendant")
			Result = Result:gsub("[Cc][Hh][Ii][Ll][Dd][Rr][Ee][Nn][Ss]", "children")
			Result = Result:gsub("[Cc][Hh][Ii][Ll][Dd][Ss]", "children")
			local LowerResult = string.lower(Result)
			local PolitePrefixes = {"hey fin, ", "hey fin ", "yo fin, ", "yo fin ", "fin, ", "please can you ", "please could you ", "please would you ", "can you please ", "could you please ", "would you please ", "can u please ", "could u please ", "would u please ", "can you help me ", "could you help me ", "would you help me ", "could you possibly ", "would you possibly ", "can you just ", "could you just ", "would you just ", "i would like you to ", "i'd like you to ", "id like you to ", "i want you to ", "i need you to ", "i want you ", "i need you ", "please go ahead and ", "go ahead and ", "can you do me a favor and ", "could you do me a favor and ", "do me a favor and ", "would you mind ", "please just ", "just please ", "please ", "pls ", "plz ", "i want to ", "i need to "}
			local PrefixRemoved = true
			while PrefixRemoved do
				PrefixRemoved = false
				for _, Prefix in ipairs(PolitePrefixes) do
					if LowerResult:sub(1, #Prefix) == Prefix then
						Result = Result:sub(#Prefix + 1)
						LowerResult = string.lower(Result)
						PrefixRemoved = true
						break
					end
				end
			end
			local CommandStarts = {"select ", "find ", "help me find ", "help me select ", "help me grab ", "help me change ", "help me make ", "make ", "turn ", "set ", "change ", "modify ", "edit ", "resize ", "scale ", "shrink ", "enlarge ", "grow ", "reduce ", "widen ", "narrow ", "shorten ", "lengthen ", "paint ", "color ", "colour ", "grab ", "get ", "pick ", "choose ", "copy ", "delete ", "destroy ", "remove ", "clone ", "duplicate ", "hide ", "show ", "rename ", "anchor ", "unanchor ", "move ", "bring ", "search ", "locate ", "highlight ", "inspect ", "create ", "add ", "toggle ", "reset ", "increase ", "decrease ", "lower ", "raise ", "check ", "open ", "scan ", "troubleshoot ", "diagnose "}
			for _, Prefix in ipairs({"can you ", "could you ", "would you ", "will you ", "can u ", "could u ", "would u ", "will u ", "can ya ", "could ya ", "would ya ", "can we ", "could we ", "is there a way to ", "would it be possible to ", "any chance you can ", "i was wondering if you could ", "how can i ", "how do i ", "can you help me ", "could you help me ", "would you help me "}) do
				if LowerResult:sub(1, #Prefix) == Prefix then
					local Remainder = LowerResult:sub(#Prefix + 1)
					for _, CommandStart in ipairs(CommandStarts) do
						if Remainder:sub(1, #CommandStart) == CommandStart then
							Result = Result:sub(#Prefix + 1)
							LowerResult = string.lower(Result)
							break
						end
					end
					break
				end
			end
			local InfinitiveMap = {{"selecting ", "select "}, {"finding ", "find "}, {"making ", "make "}, {"changing ", "change "}, {"setting ", "set "}, {"grabbing ", "grab "}, {"getting ", "get "}, {"highlighting ", "highlight "}, {"resizing ", "resize "}, {"shrinking ", "shrink "}, {"enlarging ", "enlarge "}, {"growing ", "grow "}, {"reducing ", "reduce "}, {"widening ", "widen "}, {"narrowing ", "narrow "}, {"shortening ", "shorten "}, {"lengthening ", "lengthen "}, {"moving ", "move "}, {"copying ", "copy "}, {"deleting ", "delete "}}
			for _, Mapping in ipairs(InfinitiveMap) do
				if LowerResult:sub(1, #Mapping[1]) == Mapping[1] then
					Result = Mapping[2] .. Result:sub(#Mapping[1] + 1)
					break
				end
			end
			Result = Result:gsub("[%s%.%!%?]+$", "")
			for _, Suffix in ipairs({" please", " pls", " for me", " right now", " thanks"}) do
				if string.lower(Result):sub(-#Suffix) == Suffix then
					Result = Result:sub(1, -#Suffix - 1):gsub("%s+$", "")
				end
			end
			return Result
		end

			local function GetFinStorage(FunctionName)
				local Candidate = type(env) == "table" and env[FunctionName] or nil
				if type(Candidate) ~= "function" then
					local GlobalSuccess, GlobalCandidate = pcall(function() return _G[FunctionName] end)
					Candidate = GlobalSuccess and GlobalCandidate or nil
				end
				return type(Candidate) == "function" and Candidate or nil
			end

			local function EnsureFinFolders()
				local IsFolderFunction = GetFinStorage("isfolder")
				local MakeFolderFn = GetFinStorage("makefolder")
				for _, FolderPath in ipairs({"ValmD", "ValmD/saved"}) do
					local FolderExists = false
					if IsFolderFunction then
						local CheckSuccess, CheckResult = pcall(IsFolderFunction, FolderPath)
						FolderExists = CheckSuccess and CheckResult == true
					end
					if not FolderExists and MakeFolderFn then
						pcall(MakeFolderFn, FolderPath)
					end
				end
			end

			
			local function GetHumanoid()
				for _, SelectedObject in ipairs(GetPicked()) do
					if SelectedObject:IsA("Humanoid") then return SelectedObject end
				end
				local LocalPlayer = service.Players and service.Players.LocalPlayer
				local Character = LocalPlayer and LocalPlayer.Character
				return Character and Character:FindFirstChildOfClass("Humanoid") or nil
			end

			local function SetCharStat(PropertyName, NumericValue)
				local Humanoid = GetHumanoid()
				if not Humanoid then return false, "I couldn't find your character's Humanoid. Respawn and try again." end
				if type(NumericValue) ~= "number" then return false, "Give me a numeric value for " .. PropertyName .. "." end
				local Limits = {WalkSpeed = {0, 500}, JumpPower = {0, 500}, JumpHeight = {0, 500}, HipHeight = {-20, 100}, Health = {0, 5000}, MaxHealth = {1, 5000}}
				local Range = Limits[PropertyName]
				if not Range then return false, "That character setting isn't supported by Fin." end
				NumericValue = math.clamp(NumericValue, Range[1], Range[2])
				if PropertyName == "JumpPower" then
					pcall(function() Humanoid.UseJumpPower = true end)
				elseif PropertyName == "JumpHeight" then
					pcall(function() Humanoid.UseJumpPower = false end)
				end
				local WriteSuccess, WriteError = pcall(function() Humanoid[PropertyName] = NumericValue end)
				if not WriteSuccess then return false, "I couldn't change " .. PropertyName .. ": " .. tostring(WriteError) end
				if PropertyName == "MaxHealth" and Humanoid.Health > NumericValue then pcall(function() Humanoid.Health = NumericValue end) end
				return true, PropertyName .. " is now " .. tostring(NumericValue) .. " on the selected or local character. This is a client-side change and the server may override it."
			end

			local function GetStat(Query, Phrases)
				local RawValue = AfterPhrase(Query, Phrases) or tostring(Query or "")
				RawValue = RawValue:gsub("%s*studs per second%s*$", "")
				RawValue = RawValue:gsub("%s*studs/sec%s*$", "")
				RawValue = RawValue:gsub("%s*studs%s*$", "")
				local NumberText = RawValue:match("to%s+([%-+]?%d+%.?%d*)") or RawValue:match("by%s+([%-+]?%d+%.?%d*)") or RawValue:match("([%-+]?%d+%.?%d*)")
				return tonumber(NumberText)
			end

			local function SetStat(PropertyName, NumericValue)
				if type(NumericValue) ~= "number" then return false, "Give me a numeric value for " .. PropertyName .. "." end
				local Targets = {
					Gravity = {Object = workspace, Minimum = 0, Maximum = 1000},
					FieldOfView = {Object = workspace.CurrentCamera, Minimum = 1, Maximum = 120}
				}
				local Target = Targets[PropertyName]
				if not Target or not Target.Object then return false, "That environment setting isn't available right now." end
				NumericValue = math.clamp(NumericValue, Target.Minimum, Target.Maximum)
				local WriteSuccess, WriteError = pcall(function() Target.Object[PropertyName] = NumericValue end)
				if not WriteSuccess then return false, "I couldn't change " .. PropertyName .. ": " .. tostring(WriteError) end
				return true, PropertyName .. " is now " .. tostring(NumericValue) .. " locally. The game may override this setting."
			end
			local function ScanKickScripts(CommandToken, Callback)
				task.spawn(function()
					local Decompiler = GetFinStorage("decompile")
					if type(Decompiler) ~= "function" then
						local UnavailableReport = "Kick/Ban script scan\nNo compatible decompiler is available in this executor. No scripts were inspected."
						if type(Main.AppendNotepadText) == "function" then pcall(Main.AppendNotepadText, UnavailableReport) end
						if type(Callback) == "function" then pcall(Callback, false, UnavailableReport, 0, 0) end
						return
					end
					local Patterns = {":kick", ":ban", ".kick", ".ban", "kickasync", "banasync", "kickplayer", "banuser"}
					local MaximumDecompile = 2000
					local YieldEvery = 10
					local SeenObjects = {}
					local NameMatches = {}
					local DetachedObjects = {}
					local TreeObjects = {}
					local Counts = {tree = 0, nilinst = 0, loaded = 0}
					local function AddScript(InstanceObject, SourceKind)
						if typeof(InstanceObject) ~= "Instance" or SeenObjects[InstanceObject] then return end
						local ClassSuccess, IsScript = pcall(function()
							return InstanceObject:IsA("LocalScript") or InstanceObject:IsA("ModuleScript")
						end)
						if not ClassSuccess or not IsScript then return end
						SeenObjects[InstanceObject] = true
						local RootSuccess, IsRooted = pcall(function() return InstanceObject:IsDescendantOf(game) end)
						local Entry = {Instance = InstanceObject, SourceKind = SourceKind, Rooted = RootSuccess and IsRooted or false}
						local LowerName = string.lower(InstanceObject.Name)
						if LowerName:find("kick", 1, true) or LowerName:find("ban", 1, true) then
							NameMatches[#NameMatches + 1] = Entry
						elseif not Entry.Rooted then
							DetachedObjects[#DetachedObjects + 1] = Entry
						else
							TreeObjects[#TreeObjects + 1] = Entry
						end
						Counts[SourceKind] = (Counts[SourceKind] or 0) + 1
					end
					local TreeSuccess, Descendants = pcall(function() return game:GetDescendants() end)
					if TreeSuccess and type(Descendants) == "table" then
						for _, InstanceObject in ipairs(Descendants) do AddScript(InstanceObject, "tree") end
					end
					local GetNil = GetFinStorage("getnilinstances")
					if GetNil then
						local NilSuccess, NilInstances = pcall(GetNil)
						if NilSuccess and type(NilInstances) == "table" then
							for _, InstanceObject in ipairs(NilInstances) do AddScript(InstanceObject, "nilinst") end
						end
					end
					local GetModules = GetFinStorage("getloadedmodules")
					if GetModules then
						local LoadedSuccess, LoadedModules = pcall(GetModules)
						if LoadedSuccess and type(LoadedModules) == "table" then
							for _, InstanceObject in ipairs(LoadedModules) do AddScript(InstanceObject, "loaded") end
						end
					end
					local Queue = {}
					local QueuedObjects = {}
					local function Enqueue(Entries)
						for _, Entry in ipairs(Entries) do
							if not QueuedObjects[Entry.Instance] then
								QueuedObjects[Entry.Instance] = true
								Queue[#Queue + 1] = Entry
							end
						end
					end
					Enqueue(NameMatches)
					Enqueue(DetachedObjects)
					Enqueue(TreeObjects)
					local Hits = {}
					local Attempted = 0
					local Unreadable = 0
					for Index, Entry in ipairs(Queue) do
						if Attempted >= MaximumDecompile then break end
						if CommandToken ~= Helper.CommandToken then
							local CancelledReport = "Kick/Ban script scan cancelled because a newer Fin command was received."
							if type(Callback) == "function" then pcall(Callback, false, CancelledReport, Attempted, #Hits) end
							return
						end
						Attempted = Attempted + 1
						local DecompileSuccess, DecompiledSource = pcall(Decompiler, Entry.Instance)
						if not DecompileSuccess or type(DecompiledSource) ~= "string" or DecompiledSource == "" then
							Unreadable = Unreadable + 1
						else
							local Context = {}
							for LineNumber, Line in ipairs(string.split(DecompiledSource, "\n")) do
								local LowerLine = string.lower(Line)
								for _, Pattern in ipairs(Patterns) do
									if LowerLine:find(Pattern, 1, true) then
										Context[#Context + 1] = {Pattern = Pattern, LineNumber = LineNumber, Text = Line:sub(1, 180)}
										break
									end
								end
								if #Context >= 8 then break end
							end
							if #Context > 0 then
								local PathSuccess, FullPath = pcall(function() return Entry.Instance:GetFullName() end)
								Hits[#Hits + 1] = {Instance = Entry.Instance, ClassName = Entry.Instance.ClassName, Path = PathSuccess and FullPath or "?", Rooted = Entry.Rooted, SourceKind = Entry.SourceKind, Context = Context}
							end
						end
						if Index % YieldEvery == 0 then task.wait(0.05) end
					end
					local ReportLines = {"VALMD KICK/BAN SCRIPT SCAN", "Generated: " .. os.date("%Y-%m-%d %H:%M:%S"), "Attempted: " .. tostring(Attempted) .. " | Unreadable: " .. tostring(Unreadable) .. " | Matches: " .. tostring(#Hits), "Collected: tree=" .. tostring(Counts.tree) .. " | detached=" .. tostring(Counts.nilinst) .. " | loaded=" .. tostring(Counts.loaded), "Patterns: " .. table.concat(Patterns, ", "), ""}
					if #Hits == 0 then
						ReportLines[#ReportLines + 1] = "No readable Kick/Ban source matches were found. This does not prove that the game has no moderation code."
					else
						for HitIndex, Hit in ipairs(Hits) do
							ReportLines[#ReportLines + 1] = "[" .. tostring(HitIndex) .. "] [" .. (Hit.Rooted and "ROOTED" or "DETACHED") .. "] " .. Hit.Path .. " [" .. Hit.ClassName .. "] (source=" .. Hit.SourceKind .. ")"
							for _, Match in ipairs(Hit.Context) do
								ReportLines[#ReportLines + 1] = "    Line " .. tostring(Match.LineNumber) .. " [" .. Match.Pattern .. "] " .. Match.Text
							end
							ReportLines[#ReportLines + 1] = ""
						end
					end
					ReportLines[#ReportLines + 1] = "Scan scope is limited to script instances and source the current client executor could enumerate and decompile. No Kick/Ban code was changed or executed."
					local ReportText = table.concat(ReportLines, "\n")
					EnsureFinFolders()
					local WriteFunction = GetFinStorage("writefile")
					local SaveSuccess = false
					if WriteFunction then SaveSuccess = pcall(WriteFunction, "ValmD/saved/kickban_scripts.txt", ReportText) end
					if type(Main.AppendNotepadText) == "function" then pcall(Main.AppendNotepadText, "KICK/BAN SCAN REPORT\n" .. ReportText) end
					if type(Callback) == "function" then pcall(Callback, SaveSuccess, ReportText, Attempted, #Hits) end
				end)
			end

			local function SearchScripts(SearchTerm, CommandToken, Callback)
			local Decompiler = env.decompile
			if type(Decompiler) ~= "function" then
				pcall(Callback, 0, {}, 0, "No compatible decompiler is available.")
				return
			end
			task.spawn(function()
				local SearchSuccess, Descendants = pcall(function()
					return game:GetDescendants()
				end)
				if not SearchSuccess or type(Descendants) ~= "table" then
					pcall(Callback, 0, {}, 0, "I couldn't read the client instance tree.")
					return
				end
				local CheckedCount = 0
				local Results = {}
				local SearchValue = string.lower(SearchTerm)
				for _, Object in ipairs(Descendants) do
					if not Helper.IsOpen or CommandToken ~= Helper.CommandToken then
						return
					end
					if Object:IsA("LocalScript") or Object:IsA("ModuleScript") then
						local IsViable = true
						if type(env.isViableDecompileScript) == "function" then
							local ViableSuccess, ViableResult = pcall(env.isViableDecompileScript, Object)
							IsViable = ViableSuccess and ViableResult == true
						end
						if IsViable then
							CheckedCount = CheckedCount + 1
							local DecompileSuccess, DecompiledSource = pcall(Decompiler, Object)
							if DecompileSuccess and type(DecompiledSource) == "string" and string.lower(DecompiledSource):find(SearchValue, 1, true) then
								table.insert(Results, Object.Name .. " — " .. GetObjectFullName(Object))
								if #Results >= 5 then
									break
								end
							end
							if CheckedCount >= 60 then
								break
							end
							if CheckedCount % 4 == 0 then
								task.wait()
							end
						end
					end
				end
				pcall(Callback, #Results, Results, CheckedCount)
			end)
		end

		local LastCrashout = ""

		local function CleanText(Value)
			local NormalizedValue = string.lower(tostring(Value or ""))
