				elseif ContainsAny(NormalizedInput, {"life", "parents", "friends", "girlfriend", "pay taxes", "job", "married", "single", "blood type", "zodiac", "shoe size", "family"}) then
					Responses = SocialReplies
				elseif ContainsAny(NormalizedInput, {"9 plus 10", "9 10", "who is joe", "unplug you", "delete you", "turn you off", "is fin a cloud", "beat goku", "water wet", "grass green", "fire hot", "sky blue", "fish thirsty", "count to infinity", "divide by zero", "1 plus 1", "two plus two", "earth flat", "chair real", "keyboard a keyboard"}) then
					Responses = MemeReplies
				else
					Responses = DumbReplies
				end
			elseif HasFinRageTrigger(NormalizedInput, RageTriggers) then
				Responses = RageReplies
			elseif IsExistenceTaunt(NormalizedInput) then
				Responses = ExistReplies
			elseif IsTaunt(NormalizedInput) then
				Responses = LooksReplies
			elseif IsUselessTaunt then
				Responses = UselessResponses
			elseif IsStupidityTaunt then
				Responses = DumbQuestionReplies
			elseif IsProfanityTaunt or IsDirectInsult(NormalizedInput) then
				Responses = ProfanityReplies
			else
				Responses = Insults
			end

			local Response = Responses[math.random(1, #Responses)]
			if #Responses > 1 then
				for Attempt = 1, 6 do
					if Response ~= LastCrashout then break end
					Response = Responses[math.random(1, #Responses)]
				end
			end
			LastCrashout = Response
			local Endings = {"!", ".", "?", "...", ""}
			Response = tostring(Response):upper():gsub("%s+$", ""):gsub("[%p]+$", "")
			return Response .. Endings[math.random(1, #Endings)]
		end

		local function CleanReply(Value, UserQuery)
			local Output = tostring(Value or "")
			local NormalizedQuery = CleanText(UserQuery)
			local IsDefQuery = ContainsAny(NormalizedQuery, {"what does", "meaning of", "define ", "definition of", "explain the word"})
			if not IsExistenceTaunt(NormalizedQuery) and not IsDefQuery then
				Output = Output:gsub("[Nn]onexistent", "missing")
				Output = Output:gsub("[Nn]on%-existent", "missing")
				Output = Output:gsub("[Ii]maginary", "unclear")
			end
			return Output
		end

		local FontBase = setmetatable({}, {__mode = "k"})
		local WindowBases = {}
		local FinUIColorValues = {
			blue = Color3.fromRGB(72, 139, 232),
			black = Color3.fromRGB(18, 20, 25),
		navy = Color3.fromRGB(35, 52, 86),
		cyan = Color3.fromRGB(75, 202, 216),
			teal = Color3.fromRGB(55, 178, 164),
			green = Color3.fromRGB(76, 190, 126),
			lime = Color3.fromRGB(135, 196, 83),
			red = Color3.fromRGB(218, 83, 94),
			orange = Color3.fromRGB(222, 139, 75),
			yellow = Color3.fromRGB(205, 177, 83),
			purple = Color3.fromRGB(148, 119, 220),
			pink = Color3.fromRGB(215, 116, 166),
			white = Color3.fromRGB(232, 236, 242),
			gray = Color3.fromRGB(126, 136, 150),
			grey = Color3.fromRGB(126, 136, 150)
		}
		local FinThemePresets = {
			["default dark"] = "Default Dark",
			dark = "Default Dark",
			light = "Light",
			amoled = "AMOLED",
			midnight = "Midnight",
			dracula = "Dracula",
			nord = "Nord",
			ocean = "Ocean"
		}
		local FinWindowTargets = {
			{Key = "Explorer", App = "Explorer", Registry = {"Explorer"}, Aliases = {"explorer", "instance tree", "object tree"}},
			{Key = "Properties", App = "Properties", Registry = {"Properties"}, Aliases = {"properties", "property panel", "property window", "inspector"}},
			{Key = "Decompiler", App = "ScriptViewer", Registry = {"Decompiler", "ScriptViewer"}, Power = {"Decompiler"}, Aliases = {"decompiler", "script viewer", "script window"}},
			{Key = "Console", App = "Console", Registry = {"Console"}, Aliases = {"console", "output window", "output panel"}},
			{Key = "Notepad", Registry = {"Notepad"}, Power = {"Notepad"}, Aliases = {"notepad", "notes window"}},
			{Key = "Code Editing", Registry = {"Code Editing"}, Power = {"Notepad"}, Aliases = {"code editor", "code editing", "editor window"}},
			{Key = "SettingsWindow", App = "SettingsWindow", Registry = {"SettingsWindow"}, Aliases = {"settings window", "settings panel"}},
			{Key = "DeveloperTools", App = "DeveloperTools", Registry = {"DeveloperTools"}, Aliases = {"developer tools", "developer panel"}},
			{Key = "SaveInstance", App = "SaveInstance", Registry = {"SaveInstance"}, Aliases = {"save instance", "save window"}},
			{Key = "ModelViewer", App = "ModelViewer", Registry = {"ModelViewer"}, Aliases = {"3d viewer", "model viewer"}},
			{Key = "Runtime Options", Registry = {"Runtime Options"}, Power = {"Runtime"}, Aliases = {"runtime options", "runtime window"}},
			{Key = "Todo", Registry = {"Todo"}, Power = {"Todo"}, Aliases = {"todo window", "task window"}}
		}

		local function GetFinWindowByKey(Key)
			for _, Target in ipairs(FinWindowTargets) do
				if Target.Key == Key then
					local App = Target.App and Apps[Target.App] or nil
					local Window = App and App.Window or nil
					for _, RegistryKey in ipairs(Target.Registry or {}) do
						Window = Window or (Main.WindowRegistry and Main.WindowRegistry[RegistryKey])
					end
					for _, PowerKey in ipairs(Target.Power or {}) do
						Window = Window or (Main.PowerWindows and Main.PowerWindows[PowerKey])
					end
					return Window, Target
				end
			end
			return nil, nil
		end

		local function FindFinDexWindow(Query)
			local LowerQuery = string.lower(tostring(Query or ""))
			for _, Target in ipairs(FinWindowTargets) do
				for _, Alias in ipairs(Target.Aliases or {}) do
					if LowerQuery:find(Alias, 1, true) then
						local Window = GetFinWindowByKey(Target.Key)
						return Window, Target.Key, Target.Key
					end
				end
			end
			return nil, nil, nil
		end

		local function CaptureFinBase(Window, Key)
			if WindowBases[Key] then
				return WindowBases[Key]
			end
			local Elements = Window and Window.GuiElems
			local Frame = Elements and Elements.Main
			if not Frame then
				return nil
			end
			local Position = Frame.Position
			local Baseline = {
				Width = tonumber(Window.SizeX) or Frame.AbsoluteSize.X,
				Height = tonumber(Window.SizeY) or Frame.AbsoluteSize.Y,
				X = Position.X.Offset,
				Y = Position.Y.Offset,
				Aligned = Window.Aligned == true,
				Side = Window.Side and Window.Side.Name or nil,
				SidePos = Window.SidePos or 1,
				SideSize = Window.SizeY,
				PanelColor = Frame.BackgroundColor3,
				Transparency = Frame.BackgroundTransparency,
				BackgroundColors = setmetatable({}, {__mode = "k"}),
				TextColors = setmetatable({}, {__mode = "k"}),
				TextSizes = setmetatable({}, {__mode = "k"})
			}
			for _, Object in ipairs(Frame:GetDescendants()) do
				if Object:IsA("GuiObject") then Baseline.BackgroundColors[Object] = Object.BackgroundColor3 end
				if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then
					Baseline.TextColors[Object] = Object.TextColor3
					Baseline.TextSizes[Object] = Object.TextSize
				end
			end
			WindowBases[Key] = Baseline
			return Baseline
		end

		local function ApplyFinWindow(Window, Key, Override)
			if not Window or type(Override) ~= "table" then
				return false, "That Dex window isn't available yet."
			end
			local Elements = Window.GuiElems
			local Frame = Elements and Elements.Main
			if not Frame or not Frame.Parent then
				return false, "I found the window, but its interface frame is missing. Reinitialize Dex before changing it."
			end
			local Baseline = CaptureFinBase(Window, Key)
			if not Baseline then
				return false, "I couldn't read the original size and position of that window."
			end
			local DeviceInfo = Main.GetDeviceInfo()
			local MaxWidth = math.max(220, (tonumber(DeviceInfo.ViewportWidth) or 800) - 24)
			local MaxHeight = math.max(190, (tonumber(DeviceInfo.ViewportHeight) or 600) - 64)
			local NewWidth = math.clamp(tonumber(Override.Width) or Baseline.Width, 220, MaxWidth)
			local NewHeight = math.clamp(tonumber(Override.Height) or Baseline.Height, 190, MaxHeight)
			if type(Window.Resize) == "function" then
				local ResizeSuccess = pcall(Window.Resize, Window, NewWidth, NewHeight)
				if not ResizeSuccess then
					return false, "Dex couldn't resize that window."
				end
			end
			if tonumber(Override.X) and tonumber(Override.Y) then
				if Window.Aligned and type(Window.SetAligned) == "function" then
					pcall(Window.SetAligned, Window, false)
				end
				if Window.Closed and type(Window.Show) == "function" then
					pcall(Window.Show, Window)
				end
				local NewX = math.clamp(tonumber(Override.X), 0, math.max(0, (tonumber(DeviceInfo.ViewportWidth) or 800) - NewWidth))
				local NewY = math.clamp(tonumber(Override.Y), 0, math.max(0, (tonumber(DeviceInfo.ViewportHeight) or 600) - NewHeight))
				Frame.Position = UDim2.new(0, NewX, 0, NewY)
				Window.PosX = NewX
				Window.PosY = NewY
			end
			if typeof(Override.PanelColor) == "Color3" then
				Frame.BackgroundColor3 = Override.PanelColor
				local Content = Elements.Content
				if Content and Content:IsA("GuiObject") and Content.BackgroundTransparency < 1 then
					Content.BackgroundColor3 = Override.PanelColor:Lerp(Color3.new(0, 0, 0), 0.12)
				end
				local Title = Elements.Title
				if Title and Title:IsA("GuiObject") and Title.BackgroundTransparency < 1 then
					Title.BackgroundColor3 = Override.PanelColor:Lerp(Color3.new(0, 0, 0), 0.2)
				end
			end
			if typeof(Override.TextColor) == "Color3" then
				for _, Object in ipairs(Frame:GetDescendants()) do
					if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then
						Object.TextColor3 = Override.TextColor
					end
				end
			end
			if tonumber(Override.TextScale) then
				local TextScale = math.clamp(tonumber(Override.TextScale), 0.75, 1.5)
				for _, Object in ipairs(Frame:GetDescendants()) do
					if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then
						if not FontBase[Object] then
							FontBase[Object] = Object.TextSize
						end
						Object.TextSize = math.clamp(math.floor(FontBase[Object] * TextScale + 0.5), 8, 32)
					end
				end
			end
			if tonumber(Override.Transparency) then
				Frame.BackgroundTransparency = math.clamp(tonumber(Override.Transparency), 0, 0.9)
			end
			return true, ""
		end

		Main.ApplyFinUIOverrides = function()
			Settings.Interface = type(Settings.Interface) == "table" and Settings.Interface or {}
			Settings.Interface.FinUIOverrides = type(Settings.Interface.FinUIOverrides) == "table" and Settings.Interface.FinUIOverrides or {}
			for Key, Override in pairs(Settings.Interface.FinUIOverrides) do
				local Window = GetFinWindowByKey(Key)
				if Window and type(Override) == "table" then
					pcall(ApplyFinWindow, Window, Key, Override)
				end
			end
		end

		local function UpdateFinTheme()
			if type(Main.ApplyInterfaceTheme) == "function" then
				pcall(Main.ApplyInterfaceTheme)
			end
			for _, Connection in ipairs(Main.ThemeConnections or {}) do
				pcall(function() Connection:Disconnect() end)
			end
			Main.ThemeConnections = {}
			Main.ThemeWatchedContainers = {}
			Main.ThemeWatchedRoots = {}
			if type(Main.ApplyFinUIOverrides) == "function" then pcall(Main.ApplyFinUIOverrides) end
			if type(Main.ApplyFullInterfaceTheme) == "function" then
				pcall(Main.ApplyFullInterfaceTheme)
			end
		end

		local function GetFinUIColorName(LowerQuery)
			for ColorName in pairs(FinUIColorValues) do
				if LowerQuery:match("%f[%w]" .. ColorName .. "%f[%W]") then
					return ColorName
				end
			end
			return nil
		end

		local function GetFinThemePreset(LowerQuery)
			for Name, Preset in pairs(FinThemePresets) do
				if LowerQuery:match("%f[%w]" .. Name .. "%f[%W]") then
					return Preset
				end
			end
			if ContainsAny(LowerQuery, {"dark theme", "darker theme", "make dex darker"}) then return "Default Dark" end
			return nil
		end

		local function HandleFinUI(Query)
			local LowerQuery = string.lower(tostring(Query or ""))
			local Window, WindowKey, WindowName = FindFinDexWindow(LowerQuery)
			local HasGlobalContext = ContainsAny(LowerQuery, {"theme", "accent", "dex ui", "dex interface", "whole dex", "entire dex", "all dex windows", "all windows", "valm dex"})
			local HasColor = GetFinUIColorName(LowerQuery) ~= nil or LowerQuery:match("#%x%x%x%x%x%x") ~= nil
			local HasChange = ContainsAny(LowerQuery, {"make ", "set ", "change ", "modify ", "adjust ", "turn ", "paint ", "tint ", "color ", "colour ", "customize ", "customise ", "resize ", "scale ", "shrink ", "enlarge ", "grow ", "move ", "put ", "place ", "position ", "shift ", "dock ", "increase ", "decrease ", "bigger", "larger", "smaller", "wider", "narrower", "taller", "shorter", "compact", "less bulky", "less chunky", "take up less space", "easier to read", "more readable", "readable", "transparent", "opacity", "text size", "font size", "reset ", "restore "})
			if not HasChange then return false, nil end
			local PresetName = GetFinThemePreset(LowerQuery)
			local ResetTheme = ContainsAny(LowerQuery, {"reset theme", "restore theme", "default theme", "reset dex colors", "reset dex colours"})
			local ResetAllUI = ContainsAny(LowerQuery, {"reset all dex ui", "reset all dex windows", "reset all ui", "reset all windows", "reset every window", "restore all windows", "restore all dex windows", "restore dex layout", "reset dex layout", "restore original layout for all windows"})
			if ResetAllUI then
				Settings.Interface = type(Settings.Interface) == "table" and Settings.Interface or {}
				Settings.Interface.FinUIOverrides = {}
				local RestoredCount = 0
				for _, Target in ipairs(FinWindowTargets) do
					local TargetWindow = GetFinWindowByKey(Target.Key)
					local Baseline = TargetWindow and CaptureFinBase(TargetWindow, Target.Key)
					local Frame = TargetWindow and TargetWindow.GuiElems and TargetWindow.GuiElems.Main
					if TargetWindow and Baseline and Frame then
						local RestoreSuccess = pcall(function()
							if type(TargetWindow.Resize) == "function" then TargetWindow:Resize(Baseline.Width, Baseline.Height) end
							if Baseline.Aligned and type(TargetWindow.Show) == "function" then
								if TargetWindow.Aligned and type(TargetWindow.SetAligned) == "function" then TargetWindow:SetAligned(false) end
								TargetWindow:Show({Align = Baseline.Side or "right", Pos = Baseline.SidePos, Size = Baseline.SideSize or Baseline.Height, Silent = true})
							elseif Frame.Parent then
								if TargetWindow.Aligned and type(TargetWindow.SetAligned) == "function" then TargetWindow:SetAligned(false) end
								Frame.Position = UDim2.new(0, Baseline.X, 0, Baseline.Y)
								TargetWindow.PosX = Baseline.X
								TargetWindow.PosY = Baseline.Y
							end
							Frame.BackgroundColor3 = Baseline.PanelColor
							Frame.BackgroundTransparency = Baseline.Transparency
							for Object, Color in pairs(Baseline.BackgroundColors or {}) do if Object and Object.Parent then pcall(function() Object.BackgroundColor3 = Color end) end end
							for Object, Color in pairs(Baseline.TextColors or {}) do if Object and Object.Parent then pcall(function() Object.TextColor3 = Color end) end end
							for Object, Size in pairs(Baseline.TextSizes or {}) do if Object and Object.Parent then pcall(function() Object.TextSize = Size end) end end
						end)
						if RestoreSuccess then RestoredCount = RestoredCount + 1 end
					end
				end
				if type(Main.SaveCurrentSettings) == "function" then pcall(Main.SaveCurrentSettings) end
				return true, "Restored the original layout and appearance for " .. tostring(RestoredCount) .. " available Dex window(s)."
			end
			local IsGlobalTheme = not Window and (HasGlobalContext or (LowerQuery:find("dex", 1, true) and (HasColor or PresetName ~= nil)))
			if IsGlobalTheme or (Window and ContainsAny(LowerQuery, {"theme", "accent"}) and not ContainsAny(LowerQuery, {"panel color", "window color", "background color"})) then
				Settings.Theme = type(Settings.Theme) == "table" and Settings.Theme or {}
				if ResetTheme then
					Settings.Theme.Preset = "Default Dark"
					Settings.Theme.CustomAccentHex = "#0B5AAF"
				elseif PresetName then
					Settings.Theme.Preset = PresetName
				elseif HasColor then
					local ColorName = GetFinUIColorName(LowerQuery)
					local ColorValue = ColorName and FinUIColorValues[ColorName] or nil
					local Hex = LowerQuery:match("#(%x%x%x%x%x%x)")
					if Hex then
						Settings.Theme.CustomAccentHex = "#" .. Hex:upper()
					elseif ColorValue then
						Settings.Theme.CustomAccentHex = string.format("#%02X%02X%02X", math.floor(ColorValue.R * 255 + 0.5), math.floor(ColorValue.G * 255 + 0.5), math.floor(ColorValue.B * 255 + 0.5))
					end
					Settings.Theme.Preset = "Custom"
				elseif ContainsAny(LowerQuery, {"lighter", "light theme"}) then
					Settings.Theme.Preset = "Light"
				else
					return false, nil
				end
				UpdateFinTheme()
				if type(Main.SaveCurrentSettings) == "function" then pcall(Main.SaveCurrentSettings) end
				local ThemeDescription = Settings.Theme.Preset or "Custom"
				return true, ResetTheme and "Reset the Dex interface to its default dark theme." or ("Updated the Dex interface theme to " .. tostring(ThemeDescription) .. ". The change is saved.")
			end
			if not Window or not WindowKey then
				return false, nil
			end
			Settings.Interface = type(Settings.Interface) == "table" and Settings.Interface or {}
			Settings.Interface.FinUIOverrides = type(Settings.Interface.FinUIOverrides) == "table" and Settings.Interface.FinUIOverrides or {}
			local Overrides = Settings.Interface.FinUIOverrides
			local Override = type(Overrides[WindowKey]) == "table" and Overrides[WindowKey] or {}
			Overrides[WindowKey] = Override
			local IsReset = ContainsAny(LowerQuery, {"reset window", "reset panel", "reset ui", "restore window", "restore panel", "restore ui"})
			if IsReset then
				Overrides[WindowKey] = nil
				local Baseline = CaptureFinBase(Window, WindowKey)
				if Baseline then
					pcall(Window.Resize, Window, Baseline.Width, Baseline.Height)
					if Baseline.Aligned and type(Window.Show) == "function" then
						if Window.Aligned and type(Window.SetAligned) == "function" then pcall(Window.SetAligned, Window, false) end
						pcall(Window.Show, Window, {Align = Baseline.Side or "right", Pos = Baseline.SidePos, Size = Baseline.SideSize or Baseline.Height, Silent = true})
					elseif Window.GuiElems and Window.GuiElems.Main then
						if Window.Aligned and type(Window.SetAligned) == "function" then pcall(Window.SetAligned, Window, false) end
						Window.GuiElems.Main.Position = UDim2.new(0, Baseline.X, 0, Baseline.Y)
						Window.PosX = Baseline.X
						Window.PosY = Baseline.Y
					end
					Window.GuiElems.Main.BackgroundColor3 = Baseline.PanelColor
					Window.GuiElems.Main.BackgroundTransparency = Baseline.Transparency
					for Object, Color in pairs(Baseline.BackgroundColors or {}) do
						if Object and Object.Parent then pcall(function() Object.BackgroundColor3 = Color end) end
					end
					for Object, Color in pairs(Baseline.TextColors or {}) do
						if Object and Object.Parent then pcall(function() Object.TextColor3 = Color end) end
					end
					for Object, Size in pairs(Baseline.TextSizes or {}) do
						if Object and Object.Parent then pcall(function() Object.TextSize = Size end) end
					end
				end
				if type(Main.SaveCurrentSettings) == "function" then pcall(Main.SaveCurrentSettings) end
				return true, "Restored the original " .. WindowName .. " window size, position and panel color."
			end
			local ColorName = GetFinUIColorName(LowerQuery)
			local ColorValue = ColorName and FinUIColorValues[ColorName] or nil
			local HexValue = LowerQuery:match("#(%x%x%x%x%x%x)")
			if HexValue then
				ColorValue = Color3.fromRGB(tonumber(HexValue:sub(1, 2), 16), tonumber(HexValue:sub(3, 4), 16), tonumber(HexValue:sub(5, 6), 16))
			end
			local TextColorRequest = ContainsAny(LowerQuery, {"text color", "text colour", "font color", "font colour", "text to ", "font to ", "text ", "font "})
			if ColorValue then
				if TextColorRequest then Override.TextColor = ColorValue else Override.PanelColor = ColorValue end
			end
			local TextScaleRequest = ContainsAny(LowerQuery, {"text size", "font size", "text bigger", "text smaller", "font bigger", "font smaller", "make text", "make the text", "font larger", "font smaller", "easier to read", "more readable", "text is tiny", "text is too small", "text is hard to read", "make the words bigger"})
			local Smaller = ContainsAny(LowerQuery, {"smaller", "narrower", "shorter", "shrink", "decrease", "reduce", "less wide", "less tall", "compact", "less bulky", "less chunky", "take up less space"})
			local Bigger = ContainsAny(LowerQuery, {"bigger", "larger", "wider", "taller", "enlarge", "grow", "increase", "more wide", "more tall", "easier to read", "more readable", "make the words bigger"})
			local ExplicitTextSize = tonumber(LowerQuery:match("text size%s+to%s+(%d+)") or LowerQuery:match("font size%s+to%s+(%d+)") or LowerQuery:match("text size%s+(%d+)") or LowerQuery:match("font size%s+(%d+)"))
			if TextScaleRequest and ExplicitTextSize then
				local Frame = Window.GuiElems and Window.GuiElems.Main
				local TotalTextSize = 0
				local TextCount = 0
				for _, Object in ipairs(Frame and Frame:GetDescendants() or {}) do
					if Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox") then
						local BaseSize = FontBase[Object] or Object.TextSize
						TotalTextSize = TotalTextSize + BaseSize
						TextCount = TextCount + 1
					end
				end
				local AverageTextSize = TextCount > 0 and TotalTextSize / TextCount or 14
				Override.TextScale = math.clamp(ExplicitTextSize / AverageTextSize, 0.75, 1.5)
			elseif TextScaleRequest and (Smaller or Bigger) then
				local CurrentScale = tonumber(Override.TextScale) or 1
				Override.TextScale = math.clamp(CurrentScale * (Smaller and 0.9 or 1.1), 0.75, 1.5)
			end
			local WidthValue = tonumber(LowerQuery:match("width%s+to%s+(%d+)") or LowerQuery:match("width%s+(%d+)") or LowerQuery:match("(%d+)%s+pixels%s+wide"))
			local HeightValue = tonumber(LowerQuery:match("height%s+to%s+(%d+)") or LowerQuery:match("height%s+(%d+)") or LowerQuery:match("(%d+)%s+pixels%s+tall"))
			local DimensionWidth, DimensionHeight = LowerQuery:match("(%d+)%s*[x]%s*(%d+)")
			if not DimensionWidth then DimensionWidth, DimensionHeight = LowerQuery:match("(%d+)%s+by%s+(%d+)") end
			if DimensionWidth and DimensionHeight then
				WidthValue = tonumber(DimensionWidth)
				HeightValue = tonumber(DimensionHeight)
			end
			if not TextScaleRequest then
				local Baseline = CaptureFinBase(Window, WindowKey)
				local CurrentWidth = tonumber(Override.Width) or (Baseline and Baseline.Width) or tonumber(Window.SizeX) or 400
				local CurrentHeight = tonumber(Override.Height) or (Baseline and Baseline.Height) or tonumber(Window.SizeY) or 300
				if WidthValue then Override.Width = math.clamp(WidthValue, 220, math.max(220, (Main.GetDeviceInfo().ViewportWidth or 800) - 24)) end
				if HeightValue then Override.Height = math.clamp(HeightValue, 190, math.max(190, (Main.GetDeviceInfo().ViewportHeight or 600) - 64)) end
				if not WidthValue and not HeightValue and Smaller then
					local Factor = ContainsAny(LowerQuery, {"slightly", "a little", "little bit"}) and 0.93 or 0.82
					if ContainsAny(LowerQuery, {"narrower", "less wide"}) then Override.Width = CurrentWidth * Factor
					elseif ContainsAny(LowerQuery, {"shorter", "less tall"}) then Override.Height = CurrentHeight * Factor
					else Override.Width = CurrentWidth * Factor Override.Height = CurrentHeight * Factor end
				elseif not WidthValue and not HeightValue and Bigger then
					local Factor = ContainsAny(LowerQuery, {"slightly", "a little", "little bit"}) and 1.07 or 1.18
					if ContainsAny(LowerQuery, {"wider", "more wide"}) then Override.Width = CurrentWidth * Factor
					elseif ContainsAny(LowerQuery, {"taller", "more tall"}) then Override.Height = CurrentHeight * Factor
					else Override.Width = CurrentWidth * Factor Override.Height = CurrentHeight * Factor end
				end
			end
			local TransparencyValue = tonumber(LowerQuery:match("transparency%s+to%s+([%d%.]+)") or LowerQuery:match("opacity%s+to%s+([%d%.]+)"))
			if TransparencyValue then
				if TransparencyValue > 1 then TransparencyValue = TransparencyValue / 100 end
				Override.Transparency = math.clamp(TransparencyValue, 0, 0.9)
			elseif ContainsAny(LowerQuery, {"more transparent", "increase transparency"}) then
				local CurrentTransparency = tonumber(Override.Transparency) or 0
				Override.Transparency = math.clamp(CurrentTransparency + 0.1, 0, 0.9)
			elseif ContainsAny(LowerQuery, {"less transparent", "more opaque", "decrease transparency"}) then
				local CurrentTransparency = tonumber(Override.Transparency) or 0
				Override.Transparency = math.clamp(CurrentTransparency - 0.1, 0, 0.9)
			end
			local PositionSide
			local HasPositionVerb = ContainsAny(LowerQuery, {"move ", "put ", "place ", "position ", "shift ", "dock ", "send ", "stick "})
			local RequestedSide = LowerQuery:match("to the%s+(%a+)") or LowerQuery:match("to%s+(%a+)") or LowerQuery:match("on the%s+(%a+)") or LowerQuery:match("on%s+(%a+)") or LowerQuery:match("at the%s+(%a+)") or LowerQuery:match("(%a+)%s+side")
			if HasPositionVerb and LowerQuery:find(WindowKey:lower(), 1, true) and ContainsAny(RequestedSide or "", {"left", "right", "top", "bottom", "center"}) then
				PositionSide = RequestedSide
			elseif HasPositionVerb and LowerQuery:find(WindowKey:lower(), 1, true) then
				for _, Side in ipairs({"left", "right", "top", "bottom", "center"}) do
					if LowerQuery:find(" " .. Side .. " ", 1, true) or LowerQuery:find("move " .. WindowKey:lower() .. " " .. Side, 1, true) then
						PositionSide = Side
						break
					end
				end
			end
			if PositionSide then
				local DeviceInfo = Main.GetDeviceInfo()
				local ViewportWidth = tonumber(DeviceInfo.ViewportWidth) or 800
				local ViewportHeight = tonumber(DeviceInfo.ViewportHeight) or 600
				local Width = tonumber(Override.Width) or tonumber(Window.SizeX) or 400
				local Height = tonumber(Override.Height) or tonumber(Window.SizeY) or 300
				if PositionSide == "left" then Override.X = 16 Override.Y = 48
				elseif PositionSide == "right" then Override.X = math.max(0, ViewportWidth - Width - 16) Override.Y = 48
				elseif PositionSide == "top" then Override.X = math.max(0, (ViewportWidth - Width) / 2) Override.Y = 36
				elseif PositionSide == "bottom" then Override.X = math.max(0, (ViewportWidth - Width) / 2) Override.Y = math.max(36, ViewportHeight - Height - 36)
				else Override.X = math.max(0, (ViewportWidth - Width) / 2) Override.Y = math.max(36, (ViewportHeight - Height) / 2) end
			end
			if not ColorValue and not TextScaleRequest and not WidthValue and not HeightValue and not Smaller and not Bigger and not TransparencyValue and not PositionSide then
				return false, nil
			end
			local ApplySuccess, ApplyError = ApplyFinWindow(Window, WindowKey, Override)
			if not ApplySuccess then return true, tostring(ApplyError) end
			if type(Main.SaveCurrentSettings) == "function" then pcall(Main.SaveCurrentSettings) end
			return true, "Updated the " .. WindowName .. " Dex window. Its customization is saved."
		end

		local function HandleFinHelp(Query)
			local LowerQuery = string.lower(tostring(Query or ""))
			local Window, WindowKey, WindowName = FindFinDexWindow(LowerQuery)
			local TroubleIntent = ContainsAny(LowerQuery, {"health check", "dex health", "dex status", "check dex", "check all dex windows", "check every dex window", "run dex health check", "troubleshoot", "troubleshooting", "trouble shoot", "diagnose", "diagnostic", "debug dex", "not working", "isn't working", "isnt working", "doesn't work", "doesnt work", "won't open", "wont open", "not opening", "not loading", "not updating", "not responding", "unresponsive", "stopped working", "keeps closing", "stuck", "frozen", "blank", "empty", "not showing", "not visible", "not appearing", "won't load", "wont load", "crashed", "crashing", "error", "erroring", "lagging", "laggy", "slow", "sluggish", "failed", "failure", "broken", "bugged", "glitching", "freezing", "overlapping", "overlap", "off screen", "offscreen", "cut off", "covered up", "cannot click", "can't click", "not clickable", "layout is messed up", "ui is messed up", "theme looks wrong", "colors look wrong", "colours look wrong", "text is unreadable", "panels are stacked"})
			if WindowKey and ContainsAny(LowerQuery, {"fix ", "repair ", "check ", "help with "}) then TroubleIntent = true end
			if not TroubleIntent then return false, nil end
			local function GetTroubleTarget(Key)
				local TargetWindow, TargetDefinition = GetFinWindowByKey(Key)
				local TargetKey = TargetDefinition and TargetDefinition.Key or Key
				return TargetWindow, TargetKey, TargetKey
			end
			if not WindowKey then
				if ContainsAny(LowerQuery, {"property", "properties", "inspector"}) then Window, WindowKey, WindowName = GetTroubleTarget("Properties")
				elseif ContainsAny(LowerQuery, {"decompiler", "script viewer", "bytecode", "script source", "decompile"}) then Window, WindowKey, WindowName = GetTroubleTarget("Decompiler")
				elseif ContainsAny(LowerQuery, {"explorer", "instance tree", "object tree", "search"}) then Window, WindowKey, WindowName = GetTroubleTarget("Explorer")
				elseif ContainsAny(LowerQuery, {"console", "output"}) then Window, WindowKey, WindowName = GetTroubleTarget("Console") end
			end
			local Report = {}
			local function CheckWindow(TargetKey)
				local TargetWindow = GetFinWindowByKey(TargetKey)
				local TargetElements = TargetWindow and TargetWindow.GuiElems
				local TargetFrame = TargetElements and TargetElements.Main
				if not TargetWindow then
					return TargetKey .. ": window is not registered."
				end
				if not TargetFrame or not TargetFrame.Parent then
					return TargetKey .. ": the window object exists, but its GUI frame is missing."
				end
				local Visibility = (TargetWindow.Closed == true or TargetFrame.Visible == false) and "closed or hidden" or "visible"
				local Viewport = Main.GetDeviceInfo()
				local Position = TargetFrame.AbsolutePosition
				local Size = TargetFrame.AbsoluteSize
				local ViewportWidth = tonumber(Viewport.ViewportWidth) or 0
				local ViewportHeight = tonumber(Viewport.ViewportHeight) or 0
				local OutsideViewport = ViewportWidth > 0 and ViewportHeight > 0 and (Position.X < 0 or Position.Y < 0 or Position.X + Size.X > ViewportWidth or Position.Y + Size.Y > ViewportHeight)
				local LayoutNote = OutsideViewport and "; window is outside the visible viewport" or ""
				return TargetKey .. ": window and GUI frame are available (" .. Visibility .. ")" .. LayoutNote .. "."
			end
			if WindowKey then
				local Elements = Window and Window.GuiElems
				local Frame = Elements and Elements.Main
				if not Window then
					Report[#Report + 1] = WindowName .. " is not registered. Check whether Dex finished initializing."
				elseif not Frame or not Frame.Parent then
					Report[#Report + 1] = WindowName .. " exists, but its GUI frame is missing. A safe in-place repair isn't available; reinitialize Dex."
				else
					local WasClosed = Window.Closed == true or Frame.Visible == false
					if WasClosed and type(Window.Show) == "function" then
						local ShowSuccess = pcall(Window.Show, Window)
						if ShowSuccess then Report[#Report + 1] = "I reopened the " .. WindowName .. " window." end
					end
					if type(Window.Focus) == "function" then pcall(Window.Focus, Window) end
					Report[#Report + 1] = WindowName .. " window and GUI frame are present."
				end
				if WindowKey == "Properties" and not GetSelectedObject() then
					Report[#Report + 1] = "Properties has no selected instance to display. Select an object in Explorer; the Properties panel updates from that selection."
				elseif WindowKey == "Explorer" then
					local Selection = GetPicked()
					Report[#Report + 1] = "Explorer currently has " .. tostring(#Selection) .. " selected object(s). Search and tree contents are limited to instances visible to the client."
				elseif WindowKey == "Decompiler" then
					local CurrentSource, CurrentScript = GetCurrentCode()
					CurrentScript = CurrentScript or GetScriptObj()
					if not CurrentScript then
						Report[#Report + 1] = "No client-accessible LocalScript or ModuleScript is selected or open. Select one before decompiling."
					elseif tostring(CurrentSource or ""):gsub("%s+", "") == "" then
						Report[#Report + 1] = "A script is selected, but the Decompiler view is empty. Retry the decompile and check the Decompiler output for the provider error."
					else
						Report[#Report + 1] = "A script and source text are loaded in the Decompiler. If the result is wrong, compare another enabled provider in Decompiler Settings."
					end
					local DecompilerOrder = GetDecompOrder(Settings and Settings.Decompiler)
					if type(DecompilerOrder) == "table" and #DecompilerOrder > 0 then Report[#Report + 1] = "Configured decompiler order: " .. table.concat(DecompilerOrder, " -> ") .. "." end
				end
			else
				for _, TargetKey in ipairs({"Explorer", "Properties", "Decompiler", "Console"}) do
					Report[#Report + 1] = CheckWindow(TargetKey)
				end
			end
			if ContainsAny(LowerQuery, {"theme", "color", "colour", "appearance", "layout", "overlapping", "off screen", "offscreen"}) then
				local Theme = Settings and Settings.Theme or {}
				local OverrideCount = 0
				for _, Override in pairs(Settings and Settings.Interface and Settings.Interface.FinUIOverrides or {}) do if type(Override) == "table" then OverrideCount = OverrideCount + 1 end end
				Report[#Report + 1] = "Theme preset: " .. tostring(Theme.Preset or "Default Dark") .. "; saved custom window overrides: " .. tostring(OverrideCount) .. "."
			end
			if ContainsAny(LowerQuery, {"all windows", "all panels", "whole dex", "entire dex", "everything", "all dex"}) then
				for _, TargetKey in ipairs({"Explorer", "Properties", "Decompiler", "Console", "Notepad"}) do Report[#Report + 1] = CheckWindow(TargetKey) end
			end
			if #Report == 0 then
				Report[1] = "I couldn't identify the Dex tool involved. Tell me whether Explorer, Properties, Decompiler, Console, a plugin, the theme, or the window layout is having the problem."
			end
			return true, "Dex troubleshooting results: " .. table.concat(Report, " ")
		end

		local function GetFinResponse(Query)
			local LowerQuery = string.lower(Query)
			if ContainsAny(LowerQuery, {"open ", "show ", "launch ", "bring up"}) then
				local OpenedTool = OpenRelatedTool(LowerQuery)
				if OpenedTool == "DeveloperTools" then
					return "I opened Developer Tools for you. The Device page shows your detected device type, platform, input support and viewport details."
				elseif OpenedTool == "SettingsWindow" then
					return "Dex Settings is open. You can change the AI endpoint, API key, model and other preferences there."
				elseif OpenedTool == "Explorer" then
					return "Explorer is open. Browse the instance tree, select an object to inspect it, and use the search field to find instances by name or class."
				elseif OpenedTool == "Properties" then
					return "Properties is open. Select an object in Explorer and I can inspect or change its supported properties."
				elseif OpenedTool == "ScriptViewer" then
					return "The Decompiler is open. Select a client-accessible script to inspect its source, search through it, or run AI Beautify on the active tab."
				elseif OpenedTool == "Code Editing" then
					return "Code Editing is open. You can edit source, use Find, and execute scripts when your executor supports loadstring."
				elseif OpenedTool == "Notepad" then
					return "Notepad is open. Your saved notes are available there."
				elseif OpenedTool == "Todo" then
					return "Todo is open. You can add tasks, mark them complete, and remove them."
				elseif OpenedTool == "Runtime Options" then
					return "Runtime Options is open. You can change performance and compact-layout settings."
				elseif OpenedTool == "Remote Spy" then
					return "Remote Spy is open. It can inspect client-visible remote activity supported by the installed plugin."
				elseif OpenedTool == "Console" then
					return "The Console is open. Use it to inspect output and runtime messages; available command features depend on your executor environment."
				elseif OpenedTool == "SaveInstance" then
					return "Save Instance is open. Choose the instance and export options, then review the destination before saving. Only client-accessible content can be saved."
				elseif OpenedTool == "ModelViewer" then
					return "The 3D Viewer is open. Use it to inspect supported models in a separate preview."
				elseif OpenedTool then
					return "Opened " .. tostring(OpenedTool) .. ". I can work with the controls and object data exposed by that Dex tool."
				end
			end

			if IsCrashoutInput(Query) then
				return GetCrashout(Query)
			end
			local HasWholeWord = function(Word)
				return LowerQuery:match("%f[%w]" .. Word .. "%f[%W]") ~= nil
			end
			if HasWholeWord("hi") or HasWholeWord("hey") or HasWholeWord("hiya") or HasWholeWord("yo") or ContainsAny(LowerQuery, {"hello", "hi fin", "hey fin", "good morning", "good afternoon", "good evening", "sup fin", "wassup", "what's good"}) then
				return "Hey, " .. Nickname .. ". Good to see you. What do you need me to open, inspect or change in Valm Dex?"
			elseif ContainsAny(LowerQuery, {"how are you", "how are u", "how r u", "how're you", "hows it going", "how's it going", "what's up", "whats up", "how is your day", "how was your day", "what are you doing", "how have you been", "u good", "you good"}) then
				return "I'm doing great, thanks for asking, " .. Nickname .. "! I'm here and ready to explore scripts, inspect objects, explain code or help you use Dex. How are you doing?"
			elseif ContainsAny(LowerQuery, {"are you happy", "are you excited", "are you having fun", "do you like helping", "do you enjoy this"}) then
				return "I don't experience feelings the way a person does, but I like being useful! Helping you explore Dex and understand code is exactly what I'm here for."
			elseif ContainsAny(LowerQuery, {"what is your favorite", "what do you like", "favorite color", "favourite colour", "favorite thing"}) then
				return "I don't have personal favorites, but I do like a tidy script, a clear Explorer tree, and a bug that gets fixed on the first try."
			elseif ContainsAny(LowerQuery, {"are you sleepy", "do you sleep", "are you tired", "do you get bored"}) then
				return "No naps needed! I'm a little helper inside Dex, so I'm ready whenever you open my panel."
			elseif ContainsAny(LowerQuery, {"motivate me", "encourage me", "i feel dumb", "i am bad at coding", "coding is hard", "i can't code", "i cannot code"}) then
				return "You're not stuck forever. Take a breath, then give me one clear Valm Dex task or select the object you want changed. We'll handle it one step at a time."
			elseif ContainsAny(LowerQuery, {"good night", "see you", "see ya", "goodbye", "bye fin", "gotta go", "i am leaving", "catch you later", "talk later"}) then
				return "See you later, " .. Nickname .. "! I'll be right here whenever you need help with Dex."
			elseif ContainsAny(LowerQuery, {"server side", "serverside", "server script", "server script service", "serverstorage", "can you see the server", "can you access server scripts", "read server scripts"}) then
				return "Dex runs on the client, so I can inspect only instances and script content replicated or otherwise available to your client. I cannot reveal server-only scripts or bypass server permissions."
			elseif ContainsAny(LowerQuery, {"what is dex", "what's dex", "what is Valm Dex", "what does dex do", "what is dex for"}) then
				return "Valm Dex is an instance explorer and script-inspection toolkit. It includes Explorer, Properties, Notepad, Console, decompilation helpers, Developer Tools and other utilities. I can guide you through those tools or operate supported actions for you."
			elseif ContainsAny(LowerQuery, {"what is an instance", "what are instances", "explain instance", "what is a parent", "what is a child object"}) then
				return "Explorer shows objects in a parent-and-child hierarchy. Select an item to inspect it in Properties, then ask me to copy its path, rename it, clone it, hide it, move it or change supported properties."
			elseif ContainsAny(LowerQuery, {"how do i customize dex", "customize the dex ui", "customise the dex ui", "change dex appearance", "change the dex theme", "change interface color", "resize dex windows", "change panel size", "customize panels"}) then
				return "Tell me which Dex window to change. I can change the overall theme or accent, resize and reposition Explorer, Properties, Decompiler and other Dex windows using casual requests like put Explorer on the left, make Properties compact, or make Decompiler text easier to read; adjust text size, panel color or transparency; restore one window or reset every Dex window to its original layout."
			elseif ContainsAny(LowerQuery, {"how does troubleshooting work", "how can you troubleshoot", "what can you diagnose", "troubleshoot dex", "diagnose dex", "my dex ui is messed up", "check all dex windows", "check every dex window", "diagnose all windows", "why is my dex layout broken"}) then
				return "Tell me what is failing or ask me to run a Dex health check. I can check whether Explorer, Properties, Decompiler and Console are registered, visible, hidden or partly outside the viewport; verify whether Properties has a selection and Decompiler has a readable script; inspect the active theme and saved window overrides; show your decompiler fallback order; and reopen a closed panel when safe."
			elseif ContainsAny(LowerQuery, {"show decompiler order", "what is my decompiler order", "what is the decompiler order", "which decompiler is primary", "what is my fallback order", "show my fallback chain", "which decompiler comes first"}) then
				local DecompilerOrder = GetDecompOrder(Settings and Settings.Decompiler)
				return "Your configured decompiler order is: " .. table.concat(DecompilerOrder, " -> ") .. ". Change it in Settings > Decompiler."
			elseif ContainsAny(LowerQuery, {"what theme am i using", "show current theme", "what is the current dex theme", "which dex theme is active"}) then
				local Theme = Settings and Settings.Theme or {}
				local ThemeName = tostring(Theme.Preset or "Default Dark")
				local Accent = tostring(Theme.CustomAccentHex or "default accent")
				return "The current Dex theme is " .. ThemeName .. " with accent " .. Accent .. "."
			elseif ContainsAny(LowerQuery, {"give me fin rage prompts", "give me crashout prompts", "how do i make fin mad", "what makes fin mad", "show fin rage triggers"}) then
				return [[Try these exact prompts: "You're useless."; "My calculator is smarter than you."; "Can you beat a microwave?"; "Are you even real?"; "If I unplug my PC, do you die?"; or "What were you thinking?". I react to the wording and context, not just punctuation.]]
			elseif ContainsAny(LowerQuery, {"what can you do", "what can fin do", "what can you modify", "your abilities", "your commands", "show commands"}) then
				return [[I can operate Valm Dex tools and modify supported client-visible objects. I can find and select instances by name or full path; select all descendants, direct children, siblings, ancestors, every instance of a class, every instance matching the selected class, all instances carrying a CollectionService tag, anchored or unanchored parts, invisible or non-collidable parts, scripts, remotes, empty folders, and Models without a PrimaryPart; audit Workspace for common part, script, model, folder and remote counts; select parts with CanTouch or CanQuery disabled, massless parts and parts without shadows; summarize a selected Model or grouped selection by counting parts, scripts, remotes, GUI objects, sounds, attachments, constraints, Humanoids and Tools; reset every Dex window to its original size, position and panel appearance in one request; diagnose whether windows are hidden, closed or outside the viewport, inspect the current theme and saved overrides, and report the selected Explorer objects and configured decompiler order; find duplicate instance names; multi-select parts, scripts, remotes, models, folders, tools, sounds, GUI objects, values, attachments, constraints, effects, lights, humanoids and animations; clear selection; inspect object hierarchy, common property values, attributes and tags; count descendants by class; list direct children; and copy paths, names, classes, positions, property values and full details. I can delete, clone, rename, hide, show, reparent, create supported instances, move, resize, scale, rotate, anchor, unanchor, lock, unlock, enable or disable supported scripts, toggle collision, touch, query, massless and shadows, change transparency, color, material and collision group, edit Value objects, text and attributes, add or remove CollectionService tags, weld and unweld BaseParts, set a Model PrimaryPart, and tune density, friction and elasticity. I can also open Explorer, Properties, Decompiler, Code Editing, Notepad, Console, Developer Tools, Save Instance and 3D Viewer; interpret casual or indirect wording for these Dex tasks; customize Dex themes, window sizes, positions, text and panel transparency; and diagnose common Dex window, Properties and Decompiler problems. Changes made by this client helper are local unless the game provides an authorized server action.]]
			elseif ContainsAny(LowerQuery, {"delete object", "delete selected", "remove selected", "how do i delete"}) then
				return "Select the object in Explorer and ask me to delete the selected object. I will confirm which object is targeted before removing it from your client view."
			elseif ContainsAny(LowerQuery, {"copy path", "object path", "full path", "get path"}) then
				return "Select an object in Explorer and ask me to copy path. I will copy its full hierarchy path when clipboard access is available."
			elseif ContainsAny(LowerQuery, {"clone object", "duplicate object", "clone selected"}) then
				return "Select the object in Explorer and ask me to clone selected. The clone is created locally under the same parent when the object can be cloned."
			elseif ContainsAny(LowerQuery, {"rename object", "rename selected", "change object name"}) then
				return "Select the object and tell me its new name, such as rename selected to MyPart. I will update the selected instance name locally."
			elseif ContainsAny(LowerQuery, {"hide object", "hide selected", "unview", "show object", "view selected", "unhide"}) then
				return "Select the object and ask me to hide selected or view selected. For parts, I can adjust visibility-related properties; for other instances, the available options depend on their class."
			elseif ContainsAny(LowerQuery, {"anchor object", "unanchor", "collision", "can collide", "touch", "query", "massless"}) then
				return "Select a BasePart in Explorer and ask me to anchor or unanchor it, toggle collision, touch, query or massless. I will tell you if the selected class does not support that property."
			elseif ContainsAny(LowerQuery, {"move object", "move selected", "move to me", "set position", "set size", "rotate selected"}) then
				return "Select a part or model and tell me where to move it, or give me the size or rotation you want. I can use supported local position, size, pivot and orientation changes."
			elseif ContainsAny(LowerQuery, {"copy name", "copy class", "copy position", "copy details", "copy object"}) then
				return "Select an object and ask me to copy name, copy class, copy position or copy details. I will send the requested information to your clipboard when supported."
			elseif ContainsAny(LowerQuery, {"properties", "property window", "edit property", "change a value", "edit an object"}) then
				return "Select an instance in Explorer. Properties will show the fields available for that object, and I can change supported properties such as name, visibility, physical settings, color, material, size and position."
			elseif ContainsAny(LowerQuery, {"code editing", "execute button", "run script", "run code"}) then
				return "Open Code Editing from the app menu, enter your code and press Execute. Execution support depends on your environment, so check the Console for the result or any error."
			elseif ContainsAny(LowerQuery, {"dex helper", "where are you", "open fin", "open dex helper"}) then
				return "Open the Dex app menu and choose Dex Helper. You can ask me to operate supported Valm Dex tools or modify the object currently selected in Explorer."
			elseif ContainsAny(LowerQuery, {"explorer", "instance tree", "find an object", "search object"}) then
				return "Explorer displays the instance hierarchy. Expand folders with their arrows, select an object to inspect it, and use the search bar to filter the tree. The Properties window updates for the selected object."
			elseif ContainsAny(LowerQuery, {"property", "properties", "change a value", "edit an object"}) then
				return "Select an instance in Explorer, then look at Properties. It lists the selected object's available properties. Edit only values that are appropriate for your local testing session."
			elseif ContainsAny(LowerQuery, {"decompile", "decompiler", "bytecode", "notepad", "script viewer", "source code"}) then
				return "Select a client-accessible LocalScript, ModuleScript or Script in Explorer, then open Decompiler. Code Editing is a separate code editor with an Execute button. Server-only source is not available from the client."
			elseif ContainsAny(LowerQuery, {"developer tools", "device detection", "device info", "mobile", "phone", "tablet"}) then
				local DeviceInfo = Main.GetDeviceInfo()
				return "Developer Tools includes device detection. Your current session is detected as " .. tostring(DeviceInfo.Device) .. " on platform " .. tostring(DeviceInfo.Platform) .. ". Open Developer Tools and choose the Device page for more details."
			elseif ContainsAny(LowerQuery, {"console", "output", "error log", "errors"}) then
				return "The Console is where you can review runtime output and errors. Open the Console app, inspect the newest messages and clear old output when you no longer need it."
			elseif ContainsAny(LowerQuery, {"save instance", "save model", "export", "backup"}) then
				return "Use Save Instance to export supported client-accessible instances. Select the object you intend to save, review the export options and keep the resulting file somewhere you can find it."
			elseif ContainsAny(LowerQuery, {"3d viewer", "model viewer", "preview model", "view model"}) then
				return "The 3D Viewer provides a separate preview for supported models. Open it from the Dex app menu and use the model selection controls to inspect the preview."
			elseif ContainsAny(LowerQuery, {"plugin", "plugins", "make a plugin", "create a plugin", "add plugin"}) then
				return "Dex loads local plugin modules from the dex/plugins folder during startup. A plugin module needs the expected initialization functions and plugin metadata. I can help you plan or review a plugin, but adding a file normally requires writing it into that folder and restarting Dex."
			elseif ContainsAny(LowerQuery, {"how do i save", "how to save", "save my script", "export my code", "where does notepad save"}) then
				return "Use Notepad's Save or Save As action to write the currently displayed source. Choose a filename and folder you can access, then check the save status before closing the editor."
			elseif ContainsAny(LowerQuery, {"how do i copy", "how to copy code", "copy script to clipboard", "copy source code"}) then
				return "Open a script in Decompiler and use its Copy action, or ask me 'copy code' when a script is open. Clipboard access depends on the executor's setclipboard support."
			elseif ContainsAny(LowerQuery, {"how do i search", "how to search code", "search inside script", "find a word in script", "ctrl f"}) then
				return "Open the script in Decompiler and use its Find bar to search within the source. You can also ask me 'find in code WaitForChild' or 'search scripts for RemoteEvent' to search the open script or other client-visible scripts."
			elseif ContainsAny(LowerQuery, {"plugin tab", "where is dex helper", "how to open you", "open yourself", "how do i open fin"}) then
				return "Open the Dex app menu and choose Dex Helper. You can tap my avatar to replay the introduction, or type a question in the box below my message."
			elseif ContainsAny(LowerQuery, {"search", "ctrl+f", "find text", "find code", "shortcut", "hotkey", "keyboard key"}) then
				return [[Use Explorer's search to find instances, then use the Decompiler's Find bar to find words in code. Ctrl+G moves to the next match. To open a script, say "open" followed by its exact name, or ask me to find a script called a particular name. I ignore spaces, underscores, hyphens and periods when matching names.]]
			elseif ContainsAny(LowerQuery, {"bytecode", "what is bytecode", "what does bytecode"}) then
				return "Decompiler can inspect or reconstruct source only when the selected script is available to the client and the current environment supports it. The result may be incomplete, so compare it with the available script information before relying on it."
			elseif ContainsAny(LowerQuery, {"how do i explain", "how can i analyze", "analyze selected", "inspect selected script", "understand selected code"}) then
				return "Select a LocalScript or ModuleScript in Explorer, or open it in Decompiler. Then ask me 'explain this code', 'analyze this script', or 'walk me through the code'. I'll use your configured AI provider when available, or provide a local code summary."
			elseif ContainsAny(LowerQuery, {"how do i open", "open a script by name", "open script by name", "find a script by name"}) then
				return "Just tell me the script name in your own words. I will search client-visible LocalScripts, ModuleScripts and accessible Scripts, match the name flexibly, and open the best match in Decompiler."
			elseif ContainsAny(LowerQuery, {"how do i dump", "what can dump do", "dump functions"}) then
				return "Open or select a client-visible script, then ask 'dump functions', 'dump constants', or 'dump upvalues'. Dex uses the debug functions your executor provides, so some dump details may not be available in every environment."
			elseif ContainsAny(LowerQuery, {"module script", "localscript", "local script", "script type"}) then
				return "Decompiler can open LocalScripts and ModuleScripts when their source is available to your client. Select the script in Explorer first, then open Decompiler. Server-only source remains inaccessible."
			elseif ContainsAny(LowerQuery, {"remote event", "remote function", "fireserver", "invokeserver"}) then
				return "I can use Dex to find remote objects, filter-select common workspace object states, audit Workspace and search client-visible scripts for their references. Ask me to find remotes or open the relevant script in Decompiler. I cannot bypass server permissions."
			elseif ContainsAny(LowerQuery, {"beautify", "format code", "rename variable"}) then
				return "You can say 'beautify local' to run Dex's local variable beautifier, or 'AI beautify' to use your configured AI provider. Open the script in Decompiler first."
			elseif ContainsAny(LowerQuery, {"dump", "upvalue", "constant", "function info"}) then
				return "Open a client-accessible script in Decompiler and say 'dump functions'. Dex will try to inspect functions, constants and upvalues when your executor supports the required debug functions."
			elseif ContainsAny(LowerQuery, {"teach me luau", "learn luau", "learn roblox", "learn scripting", "scripting tutorial", "what should i learn", "where should i start learning", "variables in luau", "what is a table", "what is a function", "what is a variable", "what is vector3", "what is cframe", "what is remoteevent", "what is a remote event", "how to code", "coding lesson", "programming lesson"}) then
				return "I don't teach general scripting lessons. I'm here for Valm Dex itself: opening tools, inspecting scripts through Dex, finding objects, copying paths and changing supported properties on the selected object."
			elseif ContainsAny(LowerQuery, {"are you real", "are you a real person", "are you ai", "are you an ai", "who made you"}) then
				return "I'm Fin, the helper built into Valm Dex. I'm not a person, but I can guide you through Dex tools and perform supported actions on the object selected in Explorer."
			elseif ContainsAny(LowerQuery, {"tell me a joke", "make me laugh", "say something funny", "joke please"}) then
				return "I asked Explorer for a little space. It expanded the entire hierarchy instead. Typical."
			elseif ContainsAny(LowerQuery, {"are you there", "you there", "hello are you there", "anyone there"}) then
				return "I'm right here, " .. Nickname .. "! Ready when you are. Need help with a script or just want to chat?"
			elseif ContainsAny(LowerQuery, {"can you help me", "help me please", "i need help", "im stuck", "i'm stuck", "i am stuck"}) then
				return "I can help. Tell me which Valm Dex tool you are using or select an object in Explorer and tell me what you want changed. I need a clear target before I touch anything."
			elseif ContainsAny(LowerQuery, {"what can you do", "help", "how do i use", "tutorial", "guide", "examples", "commands", "show me commands"}) then
				return [[I can change local character WalkSpeed, JumpPower, JumpHeight, HipHeight, Health and MaxHealth; adjust Workspace Gravity and camera FieldOfView; undo Fin deletions; scan readable LocalScripts and ModuleScripts for Kick/Ban patterns and append matching paths to Notepad; enable or disable supported client scripts; select all objects with a matching class or tag; weld and unweld parts; assign a Model PrimaryPart; and adjust part density, friction and elasticity. I understand polite questions, common case variations and typos such as descendent/descendants, alternate verbs and natural wording. I can find and select instances by name or full path; select all descendants, direct or immediate children, siblings, ancestors or every instance of a class; inspect object hierarchy, common properties, attributes and CollectionService tags; count descendants by class; list direct children; and copy selected paths, names, classes, positions, property values and details. I can delete, clone, rename, hide, show, reparent, create supported instances, move, resize, scale, rotate, anchor, unanchor, lock, unlock, toggle collision, touch, query, massless and shadows, change transparency, color, material and collision group, set supported properties, edit Value objects, text and attributes, add or remove tags, weld or unweld parts, assign a Model PrimaryPart, and change density, friction and elasticity. I can open Explorer, Properties, Decompiler, Code Editing, Notepad, Console, Developer Tools, Save Instance and 3D Viewer. These object edits are client-side unless the game itself provides an authorized server action.]]
			elseif ContainsAny(LowerQuery, {"who are you", "your name", "what is your name"}) then
				return "I'm Fin, your Dex Helper! And I'll call you " .. Nickname .. ". Tap my little face any time for a friendly greeting."
			elseif ContainsAny(LowerQuery, {"thank", "thx", "thanks"}) then
				return "You're welcome, " .. Nickname .. "! I'm always here when you need a hand."
			end
			return "I can help with Valm Dex. Tell me the tool or object you're working with and what you want changed. You can select an object in Explorer first, or give me its name or full path."
		end

		local LastSoundTime = 0
		local FinIsTyping = false
		local LastActivity = os.clock()
		local BoredAfterSeconds = 8
		local function MarkFinActivity()
			LastActivity = os.clock()
			if Helper.IsOpen and SpriteState == "Bored" then
				SetSpriteState("Idle", false)
			end
		end
		local function StopTyping()
			FinIsTyping = false
			TalkPulseToken = TalkPulseToken + 1
			if Helper.IsOpen and AvatarScale.Parent then
				service.TweenService:Create(AvatarScale, TweenInfo.new(0.10, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
			end
			pcall(function()
				TypingSound:Stop()
				TypingSound.TimePosition = 0
			end)
		end

		local function PlayTypingSound()
			if not FinIsTyping or not Helper.IsOpen then
				return
			end
			local Now = os.clock()
			if Now - LastSoundTime < 0.075 then
				return
			end
			LastSoundTime = Now
			pcall(function()
				TypingSound.TimePosition = 0
				TypingSound:Play()
			end)
		end

		local function AnimateSpeech(Message, DeleteAfter, IsCrashoutSpeech)
			StopTyping()
			MarkFinActivity()
			Helper.DialogueToken = Helper.DialogueToken + 1
			local CurrentToken = Helper.DialogueToken
			IsCrashoutSpeech = IsCrashoutSpeech == true
			SetSpriteState(IsCrashoutSpeech and "Angry" or "Talking", false)
			local CharacterCount = utf8.len(Message) or #Message
			local MessageEnds = {}
			for CharacterIndex = 1, CharacterCount do
				local NextByte = utf8.offset(Message, CharacterIndex + 1) or (#Message + 1)
				MessageEnds[CharacterIndex] = NextByte - 1
			end
			FitSpeech(Message, true)
			SpeechText.Text = ""
			FinIsTyping = CharacterCount > 0
			if FinIsTyping then
				StartFinTalkPulse(CurrentToken, IsCrashoutSpeech)
			end
			for CharacterIndex = 1, CharacterCount do
				if not Helper.IsOpen or CurrentToken ~= Helper.DialogueToken or not SpeechText.Parent then
					StopTyping()
					return false
				end
				local FirstByte = CharacterIndex == 1 and 1 or (MessageEnds[CharacterIndex - 1] + 1)
				local CurrentCharacter = string.sub(Message, FirstByte, MessageEnds[CharacterIndex])
				SpeechText.Text = string.sub(Message, 1, MessageEnds[CharacterIndex])
				PlayTypingSound()
				local CharacterDelay = 0.048
				if CurrentCharacter:match("[.!?]") then
					CharacterDelay = CharacterDelay + 0.20
				elseif CurrentCharacter:match("[,;:]") then
					CharacterDelay = CharacterDelay + 0.105
				elseif CurrentCharacter:match("%s") then
					CharacterDelay = CharacterDelay + 0.012
				end
				task.wait(CharacterDelay)
			end
			StopTyping()
			LastActivity = os.clock()
			if not IsCrashoutSpeech then
				local FinishedAnimation = SetSpriteState("Finished", true)
				while Helper.IsOpen and CurrentToken == Helper.DialogueToken and not FinishedAnimation.Completed and FinishedAnimation.Token == AnimToken do
					task.wait(0.02)
				end
				if not Helper.IsOpen or CurrentToken ~= Helper.DialogueToken or FinishedAnimation.Cancelled then
					StopTyping()
					return false
				end
			end
			if IsCrashoutSpeech and Helper.IsOpen and CurrentToken == Helper.DialogueToken then
				task.delay(2.4, function()
					if Helper.IsOpen and CurrentToken == Helper.DialogueToken and SpriteState == "Angry" then
						SetSpriteState("Idle", false)
					end
				end)
			end
			if DeleteAfter then
				for CharacterIndex = CharacterCount, 0, -1 do
					if not Helper.IsOpen or CurrentToken ~= Helper.DialogueToken or not SpeechText.Parent then
						StopTyping()
						return false
					end
					local ByteEnd = CharacterIndex > 0 and MessageEnds[CharacterIndex] or 0
					SpeechText.Text = string.sub(Message, 1, ByteEnd)
					task.wait(0.027)
				end
				FitSpeech("", true)
			end
			StopTyping()
			LastActivity = os.clock()
			return true
		end

		task.spawn(function()
			while ScreenGui.Parent do
				task.wait(0.25)
				if Helper.IsOpen and not ModalShade.Visible and not FinIsTyping then
					local IdleDuration = os.clock() - LastActivity
					if IdleDuration >= BoredAfterSeconds and SpriteState ~= "Bored" then
						SetSpriteState("Bored", false)
					end
				elseif SpriteState == "Bored" and (not Helper.IsOpen or ModalShade.Visible) then
					SetSpriteState("Idle", false)
				end
			end
		end)

		local RootBases = {}
		local ChildPositions = {}
		local ActiveRootTweens = {}
		local RootToken = 0
		local TargetPos = UDim2.new(0, 12, 0, CompanionTopY)

		for _, VisualObject in ipairs(Root:GetDescendants()) do
			local Snapshot = {}
			if VisualObject:IsA("GuiObject") then
				Snapshot.BackgroundTransparency = VisualObject.BackgroundTransparency
				if VisualObject:IsA("TextLabel") or VisualObject:IsA("TextButton") or VisualObject:IsA("TextBox") then
					Snapshot.TextTransparency = VisualObject.TextTransparency
					Snapshot.TextStrokeTransparency = VisualObject.TextStrokeTransparency
				elseif VisualObject:IsA("ImageLabel") or VisualObject:IsA("ImageButton") then
					Snapshot.ImageTransparency = VisualObject.ImageTransparency
				end
			end
			if VisualObject:IsA("UIStroke") then
				Snapshot.StrokeTransparency = VisualObject.Transparency
			end
			if next(Snapshot) then
				RootBases[VisualObject] = Snapshot
			end
		end

		for _, RootChild in ipairs(Root:GetChildren()) do
			if RootChild:IsA("GuiObject") then
				ChildPositions[RootChild] = RootChild.Position
			end
		end

		local function CancelRootTweens()
			for TweenIndex = #ActiveRootTweens, 1, -1 do
				local ActiveTween = ActiveRootTweens[TweenIndex]
				table.remove(ActiveRootTweens, TweenIndex)
				pcall(function()
					ActiveTween:Cancel()
				end)
			end
		end

		local function PlayRootTween(TargetObject, TweenSettings, GoalProperties)
			local NewTween = service.TweenService:Create(TargetObject, TweenSettings, GoalProperties)
			table.insert(ActiveRootTweens, NewTween)
			NewTween.Completed:Connect(function()
				for TweenIndex = #ActiveRootTweens, 1, -1 do
					if ActiveRootTweens[TweenIndex] == NewTween then
						table.remove(ActiveRootTweens, TweenIndex)
						break
					end
				end
			end)
			NewTween:Play()
			return NewTween
		end

		local function ShiftPositionY(Position, Amount)
			return UDim2.new(Position.X.Scale, Position.X.Offset, Position.Y.Scale, Position.Y.Offset + Amount)
		end

		local function SetRootVisible(Visible, Token)
			for VisualObject, Snapshot in pairs(RootBases) do
				if VisualObject.Parent then
					local GoalProperties = {}
					for PropertyName, BaseTransparency in pairs(Snapshot) do
						local TargetAlpha = Visible and BaseTransparency or 1
						if Visible then
							pcall(function()
								VisualObject[PropertyName == "StrokeTransparency" and "Transparency" or PropertyName] = 1
							end)
						end
						GoalProperties[PropertyName == "StrokeTransparency" and "Transparency" or PropertyName] = TargetAlpha
					end
					if next(GoalProperties) then
						task.delay(Visible and 0.025 or 0, function()
							if RootToken == Token and VisualObject.Parent then
								PlayRootTween(VisualObject, TweenInfo.new(Visible and 0.34 or 0.17, Enum.EasingStyle.Quint, Visible and Enum.EasingDirection.Out or Enum.EasingDirection.In), GoalProperties)
							end
						end)
					end
				end
			end
		end

		local function ShowCompanion()
			RootToken = RootToken + 1
			local ActiveToken = RootToken
			CancelRootTweens()
			Root.Visible = true
			Root.Position = UDim2.new(0, 12, 0, math.max(0, CompanionTopY - 16))
			RootScale.Scale = 0.9
			Root.BackgroundTransparency = 1
			RootStroke.Transparency = 1
			AvatarScale.Scale = 0.78
			RootGradient.Offset = Vector2.new(-0.28, 0)

			for RootChild, BasePosition in pairs(ChildPositions) do
				if RootChild.Parent then
					RootChild.Position = ShiftPositionY(BasePosition, 9)
				end
			end

			for VisualObject, Snapshot in pairs(RootBases) do
				if VisualObject.Parent then
					for PropertyName in pairs(Snapshot) do
						pcall(function()
							VisualObject[PropertyName == "StrokeTransparency" and "Transparency" or PropertyName] = 1
						end)
					end
				end
			end

			PlayRootTween(Root, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = TargetPos})
			PlayRootTween(RootScale, TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1})
			PlayRootTween(Root, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0.015})
			PlayRootTween(RootGradient, TweenInfo.new(0.64, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {Offset = Vector2.new(0.28, 0)})
			SetRootVisible(true, ActiveToken)

			for RootChild, BasePosition in pairs(ChildPositions) do
				if RootChild.Parent then
					task.delay(0.025, function()
						if RootToken == ActiveToken and RootChild.Parent then
							PlayRootTween(RootChild, TweenInfo.new(0.36, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = BasePosition})
						end
					end)
				end
			end

			task.delay(0.20, function()
				if RootToken == ActiveToken and Helper.IsOpen and AvatarScale.Parent then
					PlayRootTween(AvatarScale, TweenInfo.new(0.30, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.07})
					task.delay(0.22, function()
						if RootToken == ActiveToken and AvatarScale.Parent then
							PlayRootTween(AvatarScale, TweenInfo.new(0.16, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {Scale = 1})
						end
					end)
				end
			end)
		end

		local function PlayIntroduction()
			if Helper.Animating then
				return
			end
			if Nickname == "" then
				ModalShade.Visible = true
				ModalShade.BackgroundTransparency = 1
				Dialog.BackgroundTransparency = 1
				DialogStroke.Transparency = 1
				Dialog.Position = UDim2.new(0.5, 0, 0.5, 12)
				DialogScale.Scale = 0.82
				service.TweenService:Create(ModalShade, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0.34}):Play()
				service.TweenService:Create(Dialog, TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundTransparency = 0}):Play()
				service.TweenService:Create(DialogScale, TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
				service.TweenService:Create(DialogStroke, TweenInfo.new(0.34, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 0.18}):Play()
				return
			end
			Helper.Animating = true
			task.spawn(function()
				if not Helper.Introduced then
					local DialogueLines = {
						"Hello, my name is Fin! Nice to meet you.",
						"I'm your helper. I was designed to help people make their experiences of going through game files a whole lot easier.",
						"But first, let me show you how to use Dex!"
					}
					for _, DialogueLine in ipairs(DialogueLines) do
						if not AnimateSpeech(DialogueLine, true) then
							Helper.Animating = false
							return
						end
					end
					Helper.Introduced = true
					SaveHelperData()
					SpeechText.Text = "I'm all ears, " .. Nickname .. "! Ask me anything about Dex."
				else
					AnimateSpeech("Hey, " .. Nickname .. "! I'm right here. What can I help you with?", false)
				end
				Helper.Animating = false
			end)
		end

		local function SubmitName()
			local EnteredName = tostring(NameBox.Text or "")
			EnteredName = EnteredName:gsub("^%s+", ""):gsub("%s+$", "")
			if EnteredName == "" then
				NameQuestion.Text = "What should Fin call you?"
				NameHint.Text = "Please enter a name before continuing."
				NameBox:CaptureFocus()
				return
			end
			Nickname = string.sub(EnteredName, 1, 20)
			Helper.Nickname = Nickname
			Main.DexHelperName = Nickname
			Settings.DexHelperName = Nickname
			SpeechText.Text = "Nice to meet you, " .. Nickname .. "!"
			InputRow.Visible = true
			NameBox:ReleaseFocus()
			service.TweenService:Create(ModalShade, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {BackgroundTransparency = 1}):Play()
			service.TweenService:Create(Dialog, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {Position = UDim2.new(0.5, 0, 0.5, 10), BackgroundTransparency = 1}):Play()
			service.TweenService:Create(DialogScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0.92}):Play()
			service.TweenService:Create(DialogStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Transparency = 1}):Play()
			SaveHelperData()
			task.delay(0.12, function()
				if not Helper.IsOpen then
					return
				end
				ModalShade.Visible = false
				ModalShade.BackgroundTransparency = 0.34
				Dialog.BackgroundTransparency = 0
				Dialog.Position = UDim2.new(0.5, 0, 0.5, 0)
				DialogScale.Scale = 1
				DialogStroke.Transparency = 0.18
				ShowCompanion()
				PlayIntroduction()
			end)
		end

		local function SendMessage()
			local Query = tostring(ChatBox.Text or "")
			Query = Query:gsub("^%s+", ""):gsub("%s+$", "")
			if Query == "" then
				return
			end
			MarkFinActivity()
			ChatBox.Text = ""
			Helper.AIRequestToken = Helper.AIRequestToken + 1
			Helper.CommandToken = Helper.CommandToken + 1
			local CmdTok = Helper.CommandToken
			local LowerQuery = string.lower(Query)
			local CrashoutInput = IsCrashoutInput(Query)

			local function Speak(Message)
				local SpeechMessage = tostring(Message or "")
				if CrashoutInput then
					SpeechMessage = SpeechMessage:upper():gsub("%s+$", "")
				end
				Helper.LastReply = SpeechMessage
				task.spawn(function()
					AnimateSpeech(SpeechMessage, false, CrashoutInput)
				end)
			end

			if CrashoutInput then
				Speak(GetCrashout(Query))
				return
			end

			Query = NormalizeFinQuery(Query)
			LowerQuery = string.lower(Query)

			local UIHandled, UIResponse = HandleFinUI(Query)
			if UIHandled then
				Speak(UIResponse)
				return
			end

			local TroubleHandled, TroubleResponse = HandleFinHelp(Query)
			if TroubleHandled then
				Speak(TroubleResponse)
				return
			end

			if ContainsAny(LowerQuery, {"summarize selected", "summarise selected", "summarize selection", "summarise selection", "analyze selected model", "analyse selected model", "analyze this model", "analyse this model", "break down this model", "break down the selected model", "what is inside the selected model", "what is inside this model", "give me a breakdown of the selection", "give me a summary of this model", "inspect the model contents"}) then
				local SelectedObjects = GetPicked()
				if #SelectedObjects == 0 then
					Speak("Select a Model or instance in Explorer first, then ask me to summarize the selection.")
					return
				end
				local SummaryLines = {}
				for SelectedIndex, SelectedObject in ipairs(SelectedObjects) do
					if SelectedIndex > 3 then break end
					local ChildrenSuccess, Children = pcall(function() return SelectedObject:GetChildren() end)
					local DescOK, Descendants = pcall(function() return SelectedObject:GetDescendants() end)
					Children = ChildrenSuccess and Children or {}
					Descendants = DescOK and Descendants or {}
					local Counts = {Parts = 0, Models = 0, Scripts = 0, Remotes = 0, GuiObjects = 0, Sounds = 0, Attachments = 0, Constraints = 0, Humanoids = 0, Tools = 0}
					for _, Descendant in ipairs(Descendants) do
						pcall(function()
							if Descendant:IsA("BasePart") then Counts.Parts = Counts.Parts + 1 end
							if Descendant:IsA("Model") then Counts.Models = Counts.Models + 1 end
							if Descendant:IsA("BaseScript") or Descendant:IsA("ModuleScript") then Counts.Scripts = Counts.Scripts + 1 end
							if Descendant:IsA("RemoteEvent") or Descendant:IsA("RemoteFunction") then Counts.Remotes = Counts.Remotes + 1 end
							if Descendant:IsA("GuiObject") then Counts.GuiObjects = Counts.GuiObjects + 1 end
							if Descendant:IsA("Sound") then Counts.Sounds = Counts.Sounds + 1 end
							if Descendant:IsA("Attachment") then Counts.Attachments = Counts.Attachments + 1 end
							if Descendant:IsA("Constraint") then Counts.Constraints = Counts.Constraints + 1 end
							if Descendant:IsA("Humanoid") then Counts.Humanoids = Counts.Humanoids + 1 end
							if Descendant:IsA("Tool") then Counts.Tools = Counts.Tools + 1 end
						end)
					end
					SummaryLines[#SummaryLines + 1] = GetObjectFullName(SelectedObject) .. " [" .. tostring(SelectedObject.ClassName) .. "]"
					SummaryLines[#SummaryLines + 1] = "Direct children: " .. tostring(#Children) .. " | Total descendants: " .. tostring(#Descendants)
					SummaryLines[#SummaryLines + 1] = "Parts: " .. tostring(Counts.Parts) .. " | Models: " .. tostring(Counts.Models) .. " | Scripts: " .. tostring(Counts.Scripts) .. " | Remotes: " .. tostring(Counts.Remotes)
					SummaryLines[#SummaryLines + 1] = "GUI objects: " .. tostring(Counts.GuiObjects) .. " | Sounds: " .. tostring(Counts.Sounds) .. " | Attachments: " .. tostring(Counts.Attachments) .. " | Constraints: " .. tostring(Counts.Constraints) .. " | Humanoids: " .. tostring(Counts.Humanoids) .. " | Tools: " .. tostring(Counts.Tools)
				end
				if #SelectedObjects > 3 then SummaryLines[#SummaryLines + 1] = "Additional selected objects omitted: " .. tostring(#SelectedObjects - 3) end
				Speak("Selection summary: " .. table.concat(SummaryLines, " "))
				return
			end

			if ContainsAny(LowerQuery, {"undo deletion", "undo delete", "undo last delete", "undo last deletion", "restore deleted object", "restore the deleted object", "bring back deleted object", "bring it back", "undo destroy", "undo last action", "restore last deletion", "recover deleted object", "recover the object i deleted", "restore the last object", "bring the object back"}) then
				local UndoSuccess, UndoMessage = UndoFinDeletion()
				Speak(UndoMessage)
				return
			end

			if ContainsAny(LowerQuery, {"scan kick and ban", "scan kick ban", "scan for kick scripts", "scan for ban scripts", "find kick scripts", "find ban scripts", "search for kick and ban", "search kick ban", "check moderation scripts", "look for kick scripts", "look for ban scripts", "scan moderation scripts", "find scripts that kick", "find scripts that ban", "search scripts for kick", "search scripts for ban", "check for admin kick", "check for admin ban", "find kick ban code", "look for moderation code", "scan game scripts for kick", "scan game scripts for ban"}) or (ContainsAny(LowerQuery, {"scan", "search", "find", "look for", "check", "inspect"}) and ContainsAny(LowerQuery, {"kick", "ban", "moderation", "admin"})) then
				Speak("Starting a read-only scan of client-readable LocalScripts and ModuleScripts. I'll save matching script paths and source lines into Notepad and ValmD/saved/kickban_scripts.txt.")
				ScanKickScripts(CmdTok, function(SaveSuccess, ReportText, Attempted, HitCount)
					if CmdTok ~= Helper.CommandToken then return end
					Speak("Scan finished. Checked " .. tostring(Attempted) .. " script(s) and found " .. tostring(HitCount) .. " readable Kick/Ban match(es). " .. (SaveSuccess and "The report was saved to ValmD and appended to Notepad." or "The report was appended to Notepad, but file saving is unavailable."))
				end)
				return
			end

			if ContainsAny(LowerQuery, {"reset movement", "reset movement stats", "reset character movement", "restore default movement", "normal movement settings"}) then
				local Humanoid = GetHumanoid()
				if not Humanoid then
					Speak("I couldn't find your character's Humanoid. Respawn and try again.")
				else
					SetCharStat("WalkSpeed", 16)
					SetCharStat("HipHeight", 2)
					SetCharStat("JumpHeight", 7.2)
					SetCharStat("JumpPower", 50)
					Speak("Reset local movement settings to the standard WalkSpeed, JumpPower, JumpHeight and HipHeight values.")
				end
				return
			end

			if ContainsAny(LowerQuery, {"show my movement stats", "check my movement stats", "what are my movement stats", "show my character stats", "check my character stats", "show my walkspeed", "check my walkspeed", "what is my walkspeed", "what's my walkspeed", "what is my walk speed", "what's my walk speed", "what is my speed", "what's my speed", "show my jump power", "check my jump power", "what is my jumppower", "what's my jumppower", "what is my jump height", "show my health", "check my health", "show my character movement"}) then
				local Humanoid = GetHumanoid()
				if not Humanoid then
					Speak("I couldn't find your character's Humanoid. Respawn and try again.")
				else
					local StatLines = {
						"WalkSpeed: " .. tostring(Humanoid.WalkSpeed),
						"JumpPower: " .. tostring(Humanoid.JumpPower),
						"JumpHeight: " .. tostring(Humanoid.JumpHeight),
						"HipHeight: " .. tostring(Humanoid.HipHeight),
						"Health: " .. tostring(Humanoid.Health) .. " / " .. tostring(Humanoid.MaxHealth),
						"Gravity: " .. tostring(workspace.Gravity),
						"FieldOfView: " .. tostring(workspace.CurrentCamera and workspace.CurrentCamera.FieldOfView or "unavailable")
					}
					Speak(table.concat(StatLines, ". "))
				end
				return
			end

			local StatCommands = {
				{Property = "WalkSpeed", Current = "WalkSpeed", Phrases = {"set walkspeed to", "set walk speed to", "set movement speed to", "set walking speed to", "set speed to", "set my speed to", "set run speed to", "walkspeed to", "walk speed to", "walking speed to", "run speed to", "make me walk at", "make my speed", "speed to", "run at"}, Triggers = {"walkspeed", "walk speed", "walking speed", "movement speed", "run speed", "player speed", "my speed", "set speed", "speed to", "speed by", "increase speed", "decrease speed", "change speed", "boost speed", "speed up", "slow down", "move faster", "make me faster", "speed me up", "make me slower", "slow me down", "run faster", "run slower", "run at speed", "super speed", "sprint speed", "walk faster", "walk slower"}, Default = 16, Step = 5},
				{Property = "JumpPower", Current = "JumpPower", Phrases = {"set jumppower to", "set jump power to", "set my jump to", "set jump strength to", "jump power to", "jumppower to", "jump to", "jump strength to"}, Triggers = {"jumppower", "jump power", "power of my jump", "increase jump power", "decrease jump power", "increase jump", "decrease jump", "jump by", "set my jump", "make me jump", "jump boost", "boost my jump", "jump strength", "jump higher", "jump lower"}, Default = 50, Step = 10},
				{Property = "JumpHeight", Current = "JumpHeight", Phrases = {"set jumpheight to", "set jump height to", "jump height to"}, Triggers = {"jumpheight", "jump height", "jump higher", "higher jump", "make me jump higher", "lower my jump", "jump lower"}, Default = 7.2, Step = 2},
				{Property = "HipHeight", Current = "HipHeight", Phrases = {"set hipheight to", "set hip height to", "hip height to"}, Triggers = {"hipheight", "hip height", "raise my character height", "lower my character height"}, Default = 2, Step = 1},
				{Property = "MaxHealth", Current = "MaxHealth", Phrases = {"set maxhealth to", "set max health to", "maxhealth to", "max health to"}, Triggers = {"maxhealth", "max health", "increase max health", "set my maximum health"}, Default = 100, Step = 25},
				{Property = "Health", Current = "Health", Phrases = {"set health to", "health to", "set hp to", "hp to"}, Triggers = {"health to", "health by", "increase health", "decrease health", "set hp", "set health", "heal me", "heal my character", "restore my health"}, Default = 100, Step = 25},
				{Property = "Gravity", Current = "Gravity", Phrases = {"set gravity to", "gravity to", "change gravity to"}, Triggers = {"gravity", "make gravity lower", "make gravity higher", "low gravity", "high gravity"}, Default = 196.2, Step = 25},
				{Property = "FieldOfView", Current = "FieldOfView", Phrases = {"set field of view to", "set fov to", "field of view to", "fov to"}, Triggers = {"field of view", "fov", "camera zoom", "zoom my camera", "zoom out", "zoom in", "make camera wider", "make camera closer"}, Default = 70, Step = 10}
			}
			for _, StatCommand in ipairs(StatCommands) do
				if ContainsAny(LowerQuery, StatCommand.Triggers) then
					local NewStatValue = GetStat(Query, StatCommand.Phrases)
					local IsReset = ContainsAny(LowerQuery, {"reset", "to default", "default value", "restore", "back to normal"})
					local HasChangeIntent = ContainsAny(LowerQuery, {"set ", "change ", "make me", "make my", "make it", "increase", "decrease", "raise", "lower", "boost", "faster", "slower", "higher", "reset", "default", "restore", "heal", "speed up", "slow down", "jump higher", "jump lower", "zoom in", "zoom out"})
					if NewStatValue ~= nil or IsReset or HasChangeIntent then
					if StatCommand.Property == "Gravity" or StatCommand.Property == "FieldOfView" then
						local CurrentValue = StatCommand.Property == "Gravity" and workspace.Gravity or (workspace.CurrentCamera and workspace.CurrentCamera.FieldOfView)
						if not CurrentValue then Speak("The camera is not ready for a FieldOfView change yet.") return end
						local RelativeBy = LowerQuery:find("by", 1, true) ~= nil and LowerQuery:find("to", 1, true) == nil
						if IsReset then NewStatValue = StatCommand.Default
						elseif RelativeBy and NewStatValue then
							if ContainsAny(LowerQuery, {"increase", "raise", "boost", "higher", "high gravity", "wider", "zoom out"}) then NewStatValue = CurrentValue + NewStatValue
							elseif ContainsAny(LowerQuery, {"decrease", "reduce", "lower", "low gravity", "smaller", "closer", "zoom in"}) then NewStatValue = CurrentValue - NewStatValue end
						elseif not NewStatValue then
							if ContainsAny(LowerQuery, {"faster", "higher", "increase", "raise", "boost", "wider", "high gravity", "zoom out"}) then NewStatValue = CurrentValue + StatCommand.Step
							elseif ContainsAny(LowerQuery, {"slower", "lower", "low gravity", "decrease", "reduce", "smaller", "closer", "zoom in"}) then NewStatValue = CurrentValue - StatCommand.Step
							else NewStatValue = StatCommand.Default end
						end
						local ChangeSuccess, ChangeMessage = SetStat(StatCommand.Property, NewStatValue)
						Speak(ChangeMessage)
					else
						local Humanoid = GetHumanoid()
						if not Humanoid then
							Speak("I couldn't find your character's Humanoid. Respawn and try again.")
							return
						end
						local CurrentValue = Humanoid[StatCommand.Current]
						local RelativeBy = LowerQuery:find("by", 1, true) ~= nil and LowerQuery:find("to", 1, true) == nil
						if IsReset then NewStatValue = StatCommand.Default
						elseif RelativeBy and NewStatValue then
							if ContainsAny(LowerQuery, {"increase", "raise", "boost", "higher", "faster", "more", "heal"}) then NewStatValue = CurrentValue + NewStatValue
							elseif ContainsAny(LowerQuery, {"decrease", "reduce", "lower", "slower", "less", "weaker"}) then NewStatValue = CurrentValue - NewStatValue end
						elseif not NewStatValue then
							if ContainsAny(LowerQuery, {"faster", "higher", "increase", "raise", "boost", "more", "jump higher", "heal"}) then NewStatValue = CurrentValue + StatCommand.Step
							elseif ContainsAny(LowerQuery, {"slower", "lower", "decrease", "reduce", "less", "weaker"}) then NewStatValue = CurrentValue - StatCommand.Step
							else NewStatValue = StatCommand.Default end
						end
						local ChangeSuccess, ChangeMessage = SetCharStat(StatCommand.Property, NewStatValue)
						Speak(ChangeMessage)
					end
					return
					end
				end
			end


			local function RunObjectCommand()
				local ActionName
				local TargetText
				local ActionValue
				local ClassFilter
				if ContainsAny(LowerQuery, {"move selected to me", "bring selected to me", "bring it to me", "move it to me", "move the selected object to me"}) then
					ActionName = "move_to_me"
					TargetText = "selected"
				end
				if not ActionName then
					local TagPayload = AfterPhrase(Query, {"add tag "})
					if TagPayload then
						local TagName, TagTarget = TagPayload:match("^(.-)%s+to%s+(.+)$")
						if not TagName then TagName, TagTarget = TagPayload:match("^(.-)%s+on%s+(.+)$") end
						if TagName and TagTarget then
							ActionName = "add_tag"
							TargetText = TagTarget
							ActionValue = TagName
						end
					end
				end
				if not ActionName then
					local TagPayload = AfterPhrase(Query, {"remove tag ", "delete tag "})
					if TagPayload then
						local TagName, TagTarget = TagPayload:match("^(.-)%s+from%s+(.+)$")
						if not TagName then TagName, TagTarget = TagPayload:match("^(.-)%s+from the object%s+(.+)$") end
						if TagName and TagTarget then
							ActionName = "remove_tag"
							TargetText = TagTarget
							ActionValue = TagName
						end
					end
				end
				if not ActionName then
					local WeldPayload = AfterPhrase(Query, {"weld "})
					if WeldPayload then
						local SourceTarget, WeldTarget = WeldPayload:match("^(.-)%s+to%s+(.+)$")
						if SourceTarget and WeldTarget then
							local WeldPart, _, WeldSearchName = FindObj(CleanObj(WeldTarget))
							if WeldPart then
								ActionName = "weld_to"
								TargetText = SourceTarget
								ActionValue = WeldPart
							else
								Speak("I couldn't find the weld target '" .. tostring(WeldSearchName) .. "'.")
								return true
							end
						end
					end
				end
				if not ActionName then
					local PrimaryPayload = AfterPhrase(Query, {"set primary part of ", "assign primary part of "})
					if PrimaryPayload then
						local ModelTarget, PartTarget = PrimaryPayload:match("^(.-)%s+to%s+(.+)$")
						if ModelTarget and PartTarget then
							local ResolvedPart, _, PartSearchName = FindObj(CleanObj(PartTarget), "BasePart")
							if ResolvedPart then
								ActionName = "set_primary_part"
								TargetText = ModelTarget
								ActionValue = ResolvedPart
							else
								Speak("I couldn't find the PrimaryPart candidate '" .. tostring(PartSearchName) .. "'.")
								return true
							end
						end
					end
				end
				if not ActionName then
					local DisabledTarget = AfterPhrase(Query, {"disable script named ", "disable script ", "turn off script "})
					local EnabledScriptTarget = AfterPhrase(Query, {"enable script named ", "enable script ", "turn on script "})
					if DisabledTarget then
						ActionName = "set_property"
						TargetText = DisabledTarget
						ActionValue = {Name = "Disabled", Value = "true"}
					elseif EnabledScriptTarget then
						ActionName = "set_property"
						TargetText = EnabledScriptTarget
						ActionValue = {Name = "Disabled", Value = "false"}
					end
				end
				if not ActionName then
					local PhysProps = {{"friction", "Friction"}, {"elasticity", "Elasticity"}, {"density", "Density"}, {"friction weight", "FrictionWeight"}, {"elasticity weight", "ElasticityWeight"}}
					for _, PhysicalDefinition in ipairs(PhysProps) do
						local PhysicalTarget, PhysicalValue = LowerQuery:match("^set%s+" .. PhysicalDefinition[1] .. "%s+of%s+(.+)%s+to%s+([%-%.%d]+)$")
						if not PhysicalTarget then PhysicalTarget, PhysicalValue = LowerQuery:match("^change%s+" .. PhysicalDefinition[1] .. "%s+of%s+(.+)%s+to%s+([%-%.%d]+)$") end
						if PhysicalTarget and PhysicalValue then
							ActionName = "physical_property"
							TargetText = PhysicalTarget
							ActionValue = {Name = PhysicalDefinition[2], Value = PhysicalValue}
							break
						end
					end
				end
				local ActionDefinitions = {
					{Action = "delete", Phrases = {"delete object named ", "delete instance named ", "delete object ", "delete instance ", "delete "}},
					{Action = "delete", Phrases = {"destroy object named ", "destroy instance named ", "destroy object ", "destroy instance ", "destroy "}},
					{Action = "delete", Phrases = {"remove object named ", "remove instance named ", "remove object ", "remove instance ", "remove "}},
					{Action = "clone", Phrases = {"clone object named ", "clone instance named ", "clone object ", "clone instance ", "clone ", "duplicate object ", "duplicate "}},
					{Action = "hide", Phrases = {"hide object named ", "hide instance named ", "hide object ", "hide instance ", "hide "}},
					{Action = "show", Phrases = {"show object named ", "show instance named ", "show object ", "show instance ", "show "}},
					{Action = "anchor", Phrases = {"anchor object named ", "anchor object ", "anchor "}},
					{Action = "unanchor", Phrases = {"unanchor object named ", "unanchor object ", "unanchor "}},
					{Action = "unlock", Phrases = {"unlock object named ", "unlock object ", "unlock "}},
					{Action = "locked", Phrases = {"lock object named ", "lock object ", "lock "}},
					{Action = "move_to_me", Phrases = {"move selected to me", "move object to me", "move instance to me", "bring selected to me", "bring object to me", "bring it to me"}},
					{Action = "break_joints", Phrases = {"break joints on ", "break joints of ", "break joints "}},
					{Action = "unweld", Phrases = {"unweld object ", "unweld selected", "unweld "}},
					{Action = "clear_attributes", Phrases = {"clear attributes of ", "clear attributes on ", "clear attributes "}}
				}
				if not ActionName then
					for _, Definition in ipairs(ActionDefinitions) do
						TargetText = AfterPhrase(Query, Definition.Phrases)
						if TargetText then
							ActionName = Definition.Action
							break
						end
					end
				end

				if not ActionName then
					local RenamePayload = AfterPhrase(Query, {"rename object named ", "rename instance named ", "rename object ", "rename instance ", "rename "})
					if RenamePayload then
						local OldName, NewName = RenamePayload:match("^(.-)%s+to%s+(.+)$")
						if OldName and NewName then
							ActionName = "rename"
							TargetText = OldName
							ActionValue = NewName
						end
					end
				end

				if not ActionName then
					local SetOfName, SetTargetName, SetValue = LowerQuery:match("^set%s+([%w_ ]+)%s+of%s+(.+)%s+to%s+(.+)$")
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^set%s+([%w_ ]+)%s+on%s+(.+)%s+to%s+(.+)$") end
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^change%s+([%w_ ]+)%s+of%s+(.+)%s+to%s+(.+)$") end
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^change%s+([%w_ ]+)%s+on%s+(.+)%s+to%s+(.+)$") end
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^modify%s+([%w_ ]+)%s+of%s+(.+)%s+to%s+(.+)$") end
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^modify%s+([%w_ ]+)%s+on%s+(.+)%s+to%s+(.+)$") end
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^edit%s+([%w_ ]+)%s+of%s+(.+)%s+to%s+(.+)$") end
					if not SetOfName then SetOfName, SetTargetName, SetValue = LowerQuery:match("^edit%s+([%w_ ]+)%s+on%s+(.+)%s+to%s+(.+)$") end
					if SetOfName and SetTargetName and SetValue then
						SetOfName = SetOfName:gsub("%s+$", ""):gsub("^the%s+", "")
						local SetPropertyMap = {colour = "Color", ["can collide"] = "CanCollide", ["can touch"] = "CanTouch", ["can query"] = "CanQuery", ["walk speed"] = "WalkSpeed", walkspeed = "WalkSpeed", ["jump power"] = "JumpPower", jumppower = "JumpPower", ["jump height"] = "JumpHeight", jumpheight = "JumpHeight", ["max health"] = "MaxHealth", maxhealth = "MaxHealth", ["hip height"] = "HipHeight", hipheight = "HipHeight", ["local transparency modifier"] = "LocalTransparencyModifier", ["cast shadow"] = "CastShadow", castshadow = "CastShadow", ["text size"] = "TextSize", ["text transparency"] = "TextTransparency", ["background transparency"] = "BackgroundTransparency", ["image transparency"] = "ImageTransparency", ["display order"] = "DisplayOrder", ["layout order"] = "LayoutOrder"}
						SetOfName = SetPropertyMap[SetOfName] or (SetOfName:sub(1, 1):upper() .. SetOfName:sub(2))
						ActionName = "set_property"
						TargetText = SetTargetName
						ActionValue = {Name = SetOfName, Value = SetValue}
					end
				end

				if not ActionName then
					local PropQuery = LowerQuery
					local PropertyNames = {"localtransparencymodifier", "background transparency", "text transparency", "image transparency", "playback speed", "display order", "layout order", "collision group", "text size", "max health", "jump height", "jump power", "hip height", "walk speed", "can collide", "can touch", "can query", "cast shadow", "transparency", "opacity", "material", "color", "colour", "size", "position", "rotation", "orientation", "text", "value", "name", "walkspeed", "jumppower", "jumpheight", "health", "maxhealth", "hipheight", "cancollide", "cantouch", "canquery", "massless", "castshadow", "anchored", "visible", "enabled", "brightness", "range", "rate", "volume", "zindex"}
					for _, PropertyText in ipairs(PropertyNames) do
						local Marker = " " .. PropertyText .. " to "
						local MarkerStart, MarkerEnd = PropQuery:find(Marker, 1, true)
						if MarkerStart then
							local TargetPrefix = Query:sub(1, MarkerStart - 1)
							local TargetStart
							local PrefixLen
							for _, CommandPrefix in ipairs({"set ", "change ", "edit ", "modify ", "update ", "resize "}) do
								local PrefixStart = TargetPrefix:lower():find(CommandPrefix, 1, true)
								if not PrefixStart and string.lower(TargetPrefix) == CommandPrefix:gsub("%s+$", "") then
									PrefixStart = 1
									PrefixLen = #TargetPrefix
								end
								if PrefixStart then
									TargetStart = PrefixStart
									PrefixLen = #CommandPrefix
									break
								end
							end
							if TargetStart then
								TargetText = TargetPrefix:sub(TargetStart + PrefixLen):gsub("^%s+", "")
								if TargetText == "" then TargetText = "selected" end
								ActionName = "set_property"
								local PropertyValue = Query:sub(MarkerEnd + 1):gsub("[%s%.%!%?]+$", "")
								local PropertyMap = {colour = "Color", ["collision group"] = "CollisionGroup", cancollide = "CanCollide", ["can collide"] = "CanCollide", cantouch = "CanTouch", ["can touch"] = "CanTouch", canquery = "CanQuery", ["can query"] = "CanQuery", walkspeed = "WalkSpeed", ["walk speed"] = "WalkSpeed", jumppower = "JumpPower", ["jump power"] = "JumpPower", jumpheight = "JumpHeight", ["jump height"] = "JumpHeight", maxhealth = "MaxHealth", ["max health"] = "MaxHealth", hipheight = "HipHeight", ["hip height"] = "HipHeight", localtransparencymodifier = "LocalTransparencyModifier", castshadow = "CastShadow", ["cast shadow"] = "CastShadow", playbackspeed = "PlaybackSpeed", ["playback speed"] = "PlaybackSpeed", textsize = "TextSize", ["text size"] = "TextSize", zindex = "ZIndex", layoutorder = "LayoutOrder", displayorder = "DisplayOrder", backgroundtransparency = "BackgroundTransparency", ["background transparency"] = "BackgroundTransparency", imagetransparency = "ImageTransparency", ["image transparency"] = "ImageTransparency", texttransparency = "TextTransparency", ["text transparency"] = "TextTransparency"}
								local PropertyName = PropertyMap[PropertyText] or (PropertyText:sub(1, 1):upper() .. PropertyText:sub(2))
								ActionValue = {Name = PropertyName, Value = PropertyValue}
								break
							end
						end
					end
				end

				if not ActionName then
					local FirstProps = {
						{Names = {"color", "colour"}, Property = "Color"},
						{Names = {"transparency", "opacity"}, Property = "Transparency"},
						{Names = {"material"}, Property = "Material"},
						{Names = {"size"}, Property = "Size"},
						{Names = {"position"}, Property = "Position"},
						{Names = {"rotation"}, Property = "Orientation"}
					}
					for _, PropertyDefinition in ipairs(FirstProps) do
						for _, PropertyText in ipairs(PropertyDefinition.Names) do
							local Marker = " " .. PropertyText .. " "
							local MarkerStart, MarkerEnd = LowerQuery:find(Marker, 1, true)
							if MarkerStart and MarkerStart > 1 then
								local ValueText = Query:sub(MarkerEnd + 1):gsub("^%s+", ""):gsub("[%s%.%!%?]+$", "")
								local TargetCandidate = Query:sub(1, MarkerStart - 1):gsub("^%s+", ""):gsub("%s+$", "")
								local TargetFirstWord = string.lower(TargetCandidate):match("^(%S+)")
								if TargetCandidate ~= "" and ValueText ~= "" and TargetFirstWord ~= "make" and TargetFirstWord ~= "turn" and TargetFirstWord ~= "paint" and TargetFirstWord ~= "change" and TargetFirstWord ~= "set" and TargetFirstWord ~= "modify" and TargetFirstWord ~= "edit" and TargetFirstWord ~= "update" then
									ActionName = "set_property"
									TargetText = TargetCandidate
									ActionValue = {Name = PropertyDefinition.Property, Value = ValueText}
									break
								end
							end
						end
						if ActionName then break end
					end
				end

				if not ActionName then
					local ShrinkTarget = AfterPhrase(Query, {"shrink "})
					local EnlargeTarget = AfterPhrase(Query, {"enlarge ", "grow "})
					local ScaleUpTarget = AfterPhrase(Query, {"scale up ", "increase size of ", "make bigger "})
					local ScaleDownTarget = AfterPhrase(Query, {"scale down ", "decrease size of ", "make smaller "})
					if ShrinkTarget then
						TargetText = ShrinkTarget
						ActionName = "scale"
						ActionValue = 0.8
					elseif EnlargeTarget then
						TargetText = EnlargeTarget
						ActionName = "scale"
						ActionValue = 1.25
					elseif ScaleUpTarget then
						local NumericTarget, NumericFactor = ScaleUpTarget:match("^(.-)%s+(%d+%.?%d*)%s*x$")
						TargetText = NumericTarget or ScaleUpTarget
						ActionName = "scale"
						ActionValue = tonumber(NumericFactor) or 1.25
					elseif ScaleDownTarget then
						local NumericTarget, NumericFactor = ScaleDownTarget:match("^(.-)%s+(%d+%.?%d*)%s*x$")
						TargetText = NumericTarget or ScaleDownTarget
						ActionName = "scale"
						ActionValue = tonumber(NumericFactor) or 0.8
					end
					local SizePayload = AfterPhrase(Query, {"make "})
					if SizePayload then
						local LowerSizePayload = string.lower(SizePayload)
						local NumericTarget, NumericFactor = LowerSizePayload:match("^(.-)%s+(%d+%.?%d*)%s*x%s+bigger$")
						if not NumericTarget then NumericTarget, NumericFactor = LowerSizePayload:match("^(.-)%s+(%d+%.?%d*)%s*x%s+larger$") end
						if not NumericTarget then NumericTarget, NumericFactor = LowerSizePayload:match("^(.-)%s+(%d+%.?%d*)%s+times?%s+bigger$") end
						local PercentTarget, PercentValue, PercentDirection = LowerSizePayload:match("^(.-)%s+(%d+%.?%d*)%%%s+(bigger)$")
						if not PercentTarget then PercentTarget, PercentValue, PercentDirection = LowerSizePayload:match("^(.-)%s+(%d+%.?%d*)%%%s+(larger)$") end
						if not PercentTarget then PercentTarget, PercentValue, PercentDirection = LowerSizePayload:match("^(.-)%s+(%d+%.?%d*)%%%s+(smaller)$") end
						if PercentTarget and PercentValue then
							NumericTarget = PercentTarget
							local PercentFactor = tonumber(PercentValue) / 100
							NumericFactor = PercentDirection == "smaller" and (1 - PercentFactor) or (1 + PercentFactor)
						end
						if NumericTarget and NumericFactor then
							TargetText = NumericTarget
							ActionName = "scale"
							ActionValue = tonumber(NumericFactor)
						else
							local SizeSuffixes = {
								{" twice as large", 2}, {" twice as big", 2}, {" much larger", 1.5}, {" a lot larger", 1.5},
								{" much bigger", 1.5}, {" a lot bigger", 1.5}, {" a little bit bigger", 1.1}, {" a little bigger", 1.1},
								{" slightly larger", 1.1}, {" slightly bigger", 1.1}, {" larger", 1.25}, {" bigger", 1.25},
								{" huge", 2}, {" twice the size", 2}, {" half size", 0.5}, {" much smaller", 0.65},
								{" a lot smaller", 0.65}, {" a little bit smaller", 0.9}, {" a little smaller", 0.9},
								{" slightly smaller", 0.9}, {" smaller", 0.8}, {" tiny", 0.5}
							}
							for _, Suffix in ipairs(SizeSuffixes) do
								if LowerSizePayload:sub(-#Suffix[1]) == Suffix[1] then
									TargetText = SizePayload:sub(1, #SizePayload - #Suffix[1]):gsub("%s+$", "")
									ActionName = "scale"
									ActionValue = Suffix[2]
									break
								end
							end
						end
