			if ContainsAny(LowerQuery, {"scan code", "scan this script", "check this code", "check this script", "security scan", "performance scan", "audit code", "review for issues", "find risky patterns"}) then
				local Source = GetCurrentCode()
				if Source == "" then
					Speak("Open a script in Decompiler first, then ask me to scan it.")
				else
					Speak(BuildLocalAudit(Source))
				end
				return
			end

			if ContainsAny(LowerQuery, {"copy code", "copy source", "copy this script", "copy open script"}) then
				local Source = GetCurrentCode()
				local ClipboardFunction = env.setclipboard or setclipboard or toclipboard
				if Source == "" then
					Speak("Open a script in Decompiler first, then ask me to copy its code.")
				elseif type(ClipboardFunction) ~= "function" then
					Speak("Your executor doesn't expose a clipboard function, so I can't copy the code automatically.")
				else
					local CopySuccess, CopyError = pcall(ClipboardFunction, Source)
					Speak(CopySuccess and "Copied the open code to your clipboard." or ("I couldn't copy it: " .. tostring(CopyError)))
				end
				return
			end

			if ContainsAny(LowerQuery, {"save code", "save source", "export open code", "save this script as"}) then
				local Source = GetCurrentCode()
				if Source == "" then
					Speak("Open a script in Decompiler first, then ask me to save its code.")
				else
					local SaveSuccess, SaveError = pcall(Lib.SaveAsPrompt, "Place_" .. tostring(game.PlaceId) .. "_Code_" .. tostring(os.time()) .. ".txt", Source)
					Speak(SaveSuccess and "I opened the Save As dialog for the current code." or ("I couldn't open Save As: " .. tostring(SaveError)))
				end
				return
			end

			if ContainsAny(LowerQuery, {"find in code", "search in code", "find text in code", "search current script for", "find text in this script", "search open script for"}) then
				local SearchTerm = AfterPhrase(Query, {"search current script for", "search open script for", "find text in this script", "find text in code for", "search in code for", "find in code for", "find text in code", "search in code", "find in code"})
				local Viewer = Apps.ScriptViewer
				if not SearchTerm or SearchTerm == "" then
					Speak("Tell me the text to find. You can say: find in code WaitForChild.")
				elseif not Viewer or type(Viewer.FocusSearch) ~= "function" then
					Speak("Decompiler search isn't ready yet.")
				elseif GetCurrentCode() == "" then
					Speak("Open a script in Decompiler first, then ask me to search inside it.")
				else
					ShowDecompiler()
					pcall(Viewer.FocusSearch, SearchTerm)
					Speak("I entered '" .. SearchTerm .. "' into the Decompiler search. Use Enter or Ctrl+G to move through matches.")
				end
				return
			end

			if ContainsAny(LowerQuery, {"search scripts for", "search all scripts for", "find code across scripts for", "find text across scripts for"}) then
				local SearchTerm = AfterPhrase(Query, {"search all scripts for", "search scripts for", "find code across scripts for", "find text across scripts for"})
				if not SearchTerm then
					Speak("Tell me the text to search for. You can say: search scripts for WaitForChild.")
				else
					Speak("I'll search up to 60 client-visible scripts for '" .. SearchTerm .. "'. This can take a moment.")
					SearchScripts(SearchTerm, CmdTok, function(ResultCount, Results, CheckedCount, SearchError)
						if not Helper.IsOpen or CmdTok ~= Helper.CommandToken then
							return
						end
						if SearchError then
							Speak(SearchError)
						elseif ResultCount == 0 then
							Speak("I didn't find '" .. SearchTerm .. "' in the " .. tostring(CheckedCount) .. " client-visible scripts I could inspect.")
						else
							Speak("I found '" .. SearchTerm .. "' in " .. tostring(ResultCount) .. " script(s): " .. table.concat(Results, " | ") .. ". Ask me to open one by name.")
						end
					end)
				end
				return
			end

			local ClassFilter, ItemName = LowerQuery:match("find%s+(remote%s+event)%s+named%s+(.+)$")
			if not ItemName then
				ClassFilter, ItemName = LowerQuery:match("find%s+(remote%s+function)%s+named%s+(.+)$")
			end
			if not ItemName then
				ClassFilter, ItemName = LowerQuery:match("find%s+(%w+)%s+named%s+(.+)$")
			end
			if not ItemName then
				ItemName = AfterPhrase(Query, {"find instance named", "find object named", "locate instance named", "locate object named", "find instance", "find object", "locate instance", "locate object"})
			end
			if ItemName and not IsOpenIntent(LowerQuery) and not ContainsAny(LowerQuery, {"script", "code"}) then
				local FoundObject, MatchCount = FindInstanceByName(ItemName, ClassFilter)
				if not FoundObject then
					Speak("I couldn't find an instance named '" .. ItemName .. "' in the client-visible tree.")
				else
					local SelectSuccess, ObjectPath = SelectExplorerObject(FoundObject)
					Speak(SelectSuccess and ("Found " .. ObjectPath .. " and selected it in Explorer. " .. (MatchCount > 1 and "There may be similar partial matches." or "")) or tostring(ObjectPath))
				end
				return
			end

			if ContainsAny(LowerQuery, {"open parent", "select parent", "go to parent", "show parent of selected"}) then
				local SelectedObject = GetSelectedObject()
				local ParentObject = SelectedObject and SelectedObject.Parent
				if ParentObject then
					local SelectSuccess, ObjectPath = SelectExplorerObject(ParentObject)
					Speak(SelectSuccess and ("Selected the parent: " .. ObjectPath) or tostring(ObjectPath))
				else
					Speak("Select an instance with a parent in Explorer first.")
				end
				return
			end

			if ContainsAny(LowerQuery, {"open selected script", "view selected script", "open the selected code"}) then
				local SelectedScript = GetScriptObj()
				if not SelectedScript then
					Speak("Select a LocalScript or ModuleScript in Explorer first.")
				else
					local OpenSuccess, OpenResult = OpenScriptObject(SelectedScript)
					Speak(OpenSuccess and ("Opened " .. OpenResult .. " in the Decompiler.") or tostring(OpenResult))
				end
				return
			end

			if ContainsAny(LowerQuery, {"show current script path", "where is this script", "what script is open", "current script path"}) then
				local Viewer = Apps.ScriptViewer
				local CurrentScript = Viewer and type(Viewer.GetCurrentScript) == "function" and Viewer.GetCurrentScript()
				Speak(CurrentScript and ("The open script is " .. GetObjectFullName(CurrentScript) .. ".") or "No script is currently open in the Decompiler.")
				return
			end

			if ContainsAny(LowerQuery, {"explain this code", "explain the code", "explain code", "what does this code", "what does this do", "what is this code for", "what is it doing", "tell me what this does", "analyze this code", "analyse this code", "analyze this script", "analyse this script", "analyze this", "analyse this", "review this script", "review this code", "what is this script doing", "walk me through this code", "break this code down", "code breakdown", "summarize this code", "summary of this script", "help me understand this code", "debug this code", "debug this script", "find bugs in this code", "find bugs in this script", "what is wrong with this code", "why does this code error", "explain selected script"}) then
				Helper.AIRequestToken = Helper.AIRequestToken + 1
				local ActiveAIRequest = Helper.AIRequestToken
				local Source, CurrentScript = GetCurrentCode()
				if Source == "" then
					Speak("Open a script in the Decompiler or select a LocalScript or ModuleScript in Explorer first. Then ask me to explain this code.")
					return
				end
				ShowDecompiler()
				local SystemPrompt = "You are Fin, the Dex Helper built into Valm Dex. Stay focused on Valm Dex features, navigation, decompiler and editor workflows, Explorer, Properties, supported selected-object modifications, natural-language request interpretation, Dex interface customization, and Dex troubleshooting. Understand informal or indirect wording, but ask when the target is unclear. Only customize Valm Dex interface windows, themes, sizes, positions, text and transparency when a UI target is clear; do not confuse Dex UI changes with changes to game instances. Diagnose the actual available window and script state before suggesting a repair, and never claim a fix that was not applied. Do not provide general coding lessons, learning roadmaps, or answers to unrelated programming questions. If asked outside your scope, politely redirect the user to a Valm Dex task. When describing supplied code as part of a Dex feature, only summarize what the code shows and do not turn it into a general lesson. Use continuous plain text with no headings, bullet lists, markdown example labels, or emojis. Be warm and patient when the user is respectful or genuinely confused. Only switch into a strong crashout voice when the user directly insults, mocks or taunts Fin, or asks intentionally demeaning questions about his existence or appearance. Match the comeback category to the insult: do not mention nonexistent, imaginary or fake existence unless the user actually insults Fin's existence. Never repeat slurs; treat them as censored rage triggers only. Ordinary questions and every Dex command must be handled normally. The crashout voice should be sarcastic, blunt, visibly annoyed, witty, and occasionally profane. Handle vague but non-insulting requests calmly by asking for the target or missing detail. Crashout replies should be entirely uppercase, use varied natural punctuation, and must not all end with the same punctuation. Do not sound corporate, apologetic, timid, or artificially cheerful during a crashout. Roast the behavior and the ridiculous request, not protected traits or personal circumstances. Escalate naturally when the user keeps doing it, then cool down when they communicate clearly. Stay focused on Valm Dex."
				local RequestStarted, RequestError = RequestFinAI(SystemPrompt, Source, function(Explanation, ExplainError)
					if not Helper.IsOpen or ActiveAIRequest ~= Helper.AIRequestToken then
						return
					end
				if Explanation then
					Speak(Explanation)
				else
					Speak(GetCodeInfo(Source) .. " " .. tostring(ExplainError or ""))
				end
				end)
				if RequestStarted then
				Speak("I'm reading the code now, " .. Nickname .. ". Give me a moment to understand what it does.")
				else
					Speak(GetCodeInfo(Source) .. " " .. tostring(RequestError or ""))
				end
				return
			end

			if ContainsAny(LowerQuery, {"beautify local", "local beautify", "beautify locally", "local format", "format locally", "format this code", "clean up this code", "clean this code locally", "rename local variables", "beautify this script locally"}) and not ContainsAny(LowerQuery, {"what is", "what does", "how does", "explain"}) then
				local Viewer = Apps.ScriptViewer
				local Source = GetCurrentCode()
				if not Viewer or type(Viewer.BeautifyLocal) ~= "function" then
					Speak("The Decompiler isn't ready yet. Open it and load a script first.")
				elseif Source == "" then
					Speak("The active Decompiler tab is empty. Open a script before asking me to beautify it.")
				else
					ShowDecompiler()
					local BeautifySuccess, BeautifyError = pcall(Viewer.BeautifyLocal)
					Speak(BeautifySuccess and "Done. I formatted the source in the active Decompiler tab." or ("Local beautify failed: " .. tostring(BeautifyError)))
				end
				return
			end

			if ContainsAny(LowerQuery, {"ai beautify", "beautify with ai", "beautify using ai", "use ai to beautify", "ai format", "ai beautify this script", "format this script with ai", "beautify this for me", "make this code cleaner with ai", "beautify it with ai", "clean up this script with ai"}) and not ContainsAny(LowerQuery, {"what is", "what does", "how does", "explain"}) then
				local Viewer = Apps.ScriptViewer
				local Source = GetCurrentCode()
				local AIConfig = type(Main.ResolveAIBeautifierPluginConfig) == "function" and Main.ResolveAIBeautifierPluginConfig() or {Enabled = false, ApiKey = "", Endpoint = "", Model = ""}
				if not Viewer or type(Viewer.BeautifyAI) ~= "function" then
					Speak("The Decompiler isn't ready yet. Open it and load a script first.")
				elseif Source:gsub("%s+", "") == "" then
					Speak("There is no source in the active Decompiler tab. Open a script first.")
				elseif not AIConfig.Enabled then
					Speak("AI Beautifier Plugin is disabled. Enable it in Dex Settings.")
				elseif tostring(AIConfig.ApiKey or ""):gsub("%s+", "") == "" then
					Speak("No API key is saved for the AI Beautifier provider. Add that provider key in Dex Settings → AI Configuration.")
				elseif tostring(AIConfig.Endpoint or ""):gsub("%s+", "") == "" or tostring(AIConfig.Model or ""):gsub("%s+", "") == "" then
					Speak("The AI Beautifier provider endpoint or model is missing. Check its own settings in Dex Settings.")
				else
					ShowDecompiler()
					local BeautifyOK, BeautifyStarted, BeautifyStartError = pcall(Viewer.BeautifyAI, function(BeautifyFinished, BeautifyDetail)
						if not Helper.IsOpen then return end
						if BeautifyFinished then
							Speak("AI Beautify finished. I updated the active Decompiler tab.")
						else
							Speak("AI Beautify failed: " .. tostring(BeautifyDetail or "Unknown AI error"))
						end
					end)
					if not BeautifyOK then
						Speak("AI Beautify couldn't start: " .. tostring(BeautifyStarted))
					elseif BeautifyStarted == true then
						Speak("I'm sending the active Decompiler source to your AI provider now.")
					elseif BeautifyStarted ~= false then
						Speak("AI Beautify couldn't start: " .. tostring(BeautifyStartError or "Unknown start error"))
					end
				end
				return
			end

			if LowerQuery == "dump" or (ContainsAny(LowerQuery, {"dump functions", "dump this script", "dump upvalues", "dump constants", "dump function info", "run dump"}) and not ContainsAny(LowerQuery, {"what is", "what does", "how does", "explain"})) then
				local Viewer = Apps.ScriptViewer
				local Source, CurrentScript = GetCurrentCode()
				CurrentScript = CurrentScript or (Viewer and type(Viewer.GetCurrentScript) == "function" and Viewer.GetCurrentScript()) or GetScriptObj()
				if not Viewer or type(Viewer.DumpFunctions) ~= "function" then
					Speak("Decompiler isn't ready yet. Try again after Dex finishes loading.")
				elseif not CurrentScript then
					Speak("Select or open a LocalScript or ModuleScript first. Then say 'dump functions'.")
				else
					ShowDecompiler()
					local DumpSuccess, DumpError = pcall(Viewer.DumpFunctions, CurrentScript)
					Speak(DumpSuccess and "Function dump finished. I've added the available function details to the Decompiler code view." or ("The dump failed: " .. tostring(DumpError)))
				end
				return
			end

			if ContainsAny(LowerQuery, {"find duplicate object names", "find duplicate instance names", "scan duplicate object names", "scan duplicate instance names", "show duplicate object names", "show duplicate instance names", "objects with the same name", "instances with the same name"}) then
				local DuplicateCount, DuplicateNames = FindDupInstances()
				Speak(DuplicateCount > 0 and ("Found " .. tostring(DuplicateCount) .. " instance(s) belonging to duplicate-name groups. " .. table.concat(DuplicateNames, " | ")) or "I couldn't find duplicate instance names in the client-visible tree.")
				return
			end

			if ContainsAny(LowerQuery, {"find duplicate scripts", "duplicate script names", "scripts with same name", "show duplicate scripts", "scan duplicate scripts"}) then
				local DuplicateCount, DuplicateNames = FindDupScripts()
				if DuplicateCount == 0 then
					Speak("I didn't find duplicate names among the client-visible LocalScripts and ModuleScripts.")
				else
					Speak("I found " .. tostring(DuplicateCount) .. " duplicated script name(s): " .. table.concat(DuplicateNames, " | ") .. ". These are name matches, not proof that the scripts contain identical code.")
				end
				return
			end

			if ContainsAny(LowerQuery, {"list scripts", "show scripts", "show me scripts", "list localscripts", "list local scripts", "list module scripts", "scan client scripts", "what scripts are available", "show available scripts"}) then
				local TotalCount, ScriptNames = ListClientScripts()
				if TotalCount == 0 then
					Speak("I couldn't find any client-visible LocalScripts or ModuleScripts in the current instance tree.")
				else
					Speak("I found " .. tostring(TotalCount) .. " client-visible script(s). Here are a few: " .. table.concat(ScriptNames, ", ") .. ". Ask me to open one by name.")
				end
				return
			end

			if IsOpenIntent(LowerQuery) then
				local ScriptName = ExtractScriptName(Query)
				if not ScriptName then
					Speak("Tell me the exact or partial script name. You can say: open the script named MyScript.")
					return
				end
				local FoundScript = FindScriptByName(ScriptName)
				if not FoundScript then
					Speak("I couldn't find a client-visible LocalScript or ModuleScript named '" .. ScriptName .. "'. Check its spelling or make sure it exists in the client Explorer.")
					return
				end
				local OpenSuccess, OpenResult = OpenScriptObject(FoundScript)
				Speak(OpenSuccess and ("Found " .. OpenResult .. " and opened it in the Decompiler for you.") or tostring(OpenResult))
				return
			end

			local Response = GetFinResponse(Query)
			local AIConfig = ResolveAIConfig()
			UpdateFinMode()
			if AIConfig.Enabled and tostring(AIConfig.ApiKey or ""):gsub("%s+", "") ~= "" and AIConfig.Endpoint ~= "" and AIConfig.Model ~= "" then
				Helper.AIRequestToken = Helper.AIRequestToken + 1
				local ActiveAIRequest = Helper.AIRequestToken
				local SystemPrompt = "You are Fin, the Dex Helper built into Valm Dex. Only help with Valm Dex itself: its tools, navigation, plugin features, script inspection workflows, supported actions for modifying the selected client-side object, natural-language request interpretation, Dex UI customization, and Dex troubleshooting. Understand casual, indirect and imperfectly phrased Dex requests. Change only Dex interface windows, themes and supported UI properties when the user clearly targets the interface; do not confuse these requests with game-object edits. Diagnose current Dex window and script state before recommending a safe fix, and never claim an action succeeded unless it actually did. Do not provide general coding lessons or answer unrelated topics. If a request is outside this scope, gently redirect the user to something you can do in Valm Dex. Never claim to have opened a tool, copied data, or changed an object unless the local helper action explicitly did so. State clearly when the client cannot access or modify something. Reply in continuous plain text, without headings, markdown example labels, bullet lists, or emojis. Be warm when the user is respectful. When they directly insult, mock or taunt Fin, or ask intentionally demeaning questions about his existence or appearance, be sharply sarcastic, openly irritated, blunt, witty, and occasionally profane. Match your comeback to the actual insult and never mention nonexistent or imaginary unless that is what the user said. Never repeat slurs; treat them as censored rage triggers only. Keep every normal Dex command calm and useful. Handle vague but non-insulting requests normally and ask for the missing target or detail. Crashout replies should be entirely uppercase, use varied natural punctuation, and must not all end with the same punctuation. Do not soften every comeback with politeness or generic reassurance. Roast the behavior and unclear request rather than protected traits or personal circumstances. Let the irritation escalate across repeated nonsense, then cool down when the user gives a clear Valm Dex task."
				local RequestStarted, RequestError = RequestFinAI(SystemPrompt, CleanFinInput(Query), function(Answer, AnswerError)
					if not Helper.IsOpen or ActiveAIRequest ~= Helper.AIRequestToken then
						return
					end
					if Answer then
						Speak(CleanReply(Answer, Query))
					else
						Speak(Response .. " " .. tostring(AnswerError or "I couldn't reach the configured AI provider just now."))
					end
				end)
				if RequestStarted then
					Speak("Let me check that against the Valm Dex features I can access, " .. Nickname .. ".")
				else
					Speak(Response .. " " .. tostring(RequestError or ""))
				end
			else
				Speak(Response)
			end
		end

		local function OpenHelper()
			if Helper.IsOpen then
				return
			end
			UpdateFinMode()
			Helper.IsOpen = true
			MarkFinActivity()
			Helper.DialogueToken = Helper.DialogueToken + 1
			Helper.AIRequestToken = Helper.AIRequestToken + 1
			SetSpriteState("Idle", false)
			if Nickname == "" then
				Root.Visible = false
				ModalShade.Visible = true
				ModalShade.BackgroundTransparency = 1
				Dialog.BackgroundTransparency = 1
				DialogStroke.Transparency = 1
				Dialog.Position = UDim2.new(0.5, 0, 0.5, 12)
				DialogScale.Scale = 0.82
				service.TweenService:Create(ModalShade, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0.34}):Play()
				service.TweenService:Create(Dialog, TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundTransparency = 0}):Play()
				service.TweenService:Create(DialogScale, TweenInfo.new(0.38, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
				service.TweenService:Create(DialogStroke, TweenInfo.new(0.34, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Transparency = 0.18}):Play()
				NameBox.Text = ""
				task.defer(function()
					if ModalShade.Visible then
						NameBox:CaptureFocus()
					end
				end)
			else
				ModalShade.Visible = false
				ShowCompanion()
				if Helper.Introduced then
					SpeechText.Text = "Welcome back, " .. Nickname .. "! Ask me anything about Dex."
				else
					SpeechText.Text = "Nice to see you again, " .. Nickname .. "!"
					PlayIntroduction()
				end
			end
		end

		local function CloseHelper()
			if not Helper.IsOpen then
				return
			end
			Helper.IsOpen = false
			Helper.Animating = false
			StopTyping()
			Helper.DialogueToken = Helper.DialogueToken + 1
			Helper.AIRequestToken = Helper.AIRequestToken + 1
			AnimToken = AnimToken + 1
			RootToken = RootToken + 1
			local ActiveToken = RootToken
			CancelRootTweens()
			ModalShade.Visible = false

			local ExitTween = PlayRootTween(Root, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
				Position = UDim2.new(0, -18, 0, 91),
				BackgroundTransparency = 1
			})
			PlayRootTween(RootScale, TweenInfo.new(0.27, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0.88})
			PlayRootTween(AvatarScale, TweenInfo.new(0.20, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.82})
			PlayRootTween(RootGradient, TweenInfo.new(0.22, Enum.EasingStyle.Sine, Enum.EasingDirection.In), {Offset = Vector2.new(-0.28, 0)})
			SetRootVisible(false, ActiveToken)

			for RootChild, BasePosition in pairs(ChildPositions) do
				if RootChild.Parent then
					PlayRootTween(RootChild, TweenInfo.new(0.20, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {Position = ShiftPositionY(BasePosition, -5)})
				end
			end

			ExitTween.Completed:Connect(function()
				if RootToken == ActiveToken and not Helper.IsOpen and Root.Parent then
					Root.Visible = false
				end
			end)
		end

		SubmitButton.Activated:Connect(SubmitName)
		NameBox.FocusLost:Connect(function(EnterPressed)
			if EnterPressed then
				SubmitName()
			end
		end)
		AvatarButton.Activated:Connect(function()
			service.TweenService:Create(AvatarScale, TweenInfo.new(0.12, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1.08}):Play()
			task.delay(0.13, function()
				if AvatarScale.Parent then
					service.TweenService:Create(AvatarScale, TweenInfo.new(0.16, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
				end
			end)
			PlayIntroduction()
		end)
		SendButton.Activated:Connect(SendMessage)
		ChatBox.Focused:Connect(MarkFinActivity)
		ChatBox:GetPropertyChangedSignal("Text"):Connect(function()
			if Helper.IsOpen then MarkFinActivity() end
		end)
		ChatBox.FocusLost:Connect(function(EnterPressed)
			if EnterPressed then
				SendMessage()
			end
		end)

		Lib.ShowGui(ScreenGui)
		Main.CreateApp({
			Name = "Dex Helper",
			Open = false,
			Icon = "rbxassetid://123131180250816",
			IconSize = 36,
			OnClick = function(IsOpen)
				if IsOpen then
					OpenHelper()
				else
					CloseHelper()
				end
			end
		})

		Helper.Open = OpenHelper
		Helper.Close = CloseHelper
		Helper.PlayIntroduction = PlayIntroduction
		Helper.Save = SaveHelperData
		Main.DexHelper = Helper
		return Helper
	end

	Main.SetMainGuiOpen = function(val)
		Main.MainGuiOpen = val

		Main.MainGui.OpenButton.Text = val and "Close" or "Dex++"
		if val then Main.MainGui.OpenButton.MainFrame.Visible = true end
		Main.MainGui.OpenButton.MainFrame:TweenSize(val and UDim2.new(0,224,0,200) or UDim2.new(0,0,0,0),Enum.EasingDirection.Out,Enum.EasingStyle.Quad,0.2,true)
		--Main.MainGui.OpenButton.BackgroundTransparency = val and 0 or (Lib.CheckMouseInGui(Main.MainGui.OpenButton) and 0 or 0.2)
		service.TweenService:Create(Main.MainGui.OpenButton,TweenInfo.new(0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundTransparency = val and 0 or (Lib.CheckMouseInGui(Main.MainGui.OpenButton) and 0 or 0.2)}):Play()

		if Main.MainGuiMouseEvent then Main.MainGuiMouseEvent:Disconnect() end

		if not val then
			local startTime = tick()
			Main.MainGuiCloseTime = startTime
			coroutine.wrap(function()
				Lib.FastWait(0.2)
				if not Main.MainGuiOpen and startTime == Main.MainGuiCloseTime then Main.MainGui.OpenButton.MainFrame.Visible = false end
			end)()
		else
			Main.MainGuiMouseEvent = service.UserInputService.InputBegan:Connect(function(input)
				if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) and not Lib.CheckMouseInGui(Main.MainGui.OpenButton) and not Lib.CheckMouseInGui(Main.MainGui.OpenButton.MainFrame) then

					Main.SetMainGuiOpen(false)
				end
			end)
		end
	end

	Main.CreatePowerTools = function()
		if Main.PowerToolsCreated then return end
		Main.PowerToolsCreated = true
		Settings.Interface = type(Settings.Interface) == "table" and Settings.Interface or {}
		Settings.Interface.PerformanceMode = Settings.Interface.PerformanceMode == true
		Settings.Interface.ForceMobileLayout = Settings.Interface.ForceMobileLayout == true
		Settings.Interface.Favorites = type(Settings.Interface.Favorites) == "table" and Settings.Interface.Favorites or {}
		Settings.Shortcuts = nil
		local Theme = Settings.Theme
