			Main1 = Color3.fromRGB(43, 43, 43),
			Main2 = Color3.fromRGB(34, 34, 34),
			Outline1 = Color3.fromRGB(22, 22, 22),
			Outline2 = Color3.fromRGB(64, 64, 64),
			Outline3 = Color3.fromRGB(25, 25, 25),
			TextBox = Color3.fromRGB(29, 29, 29),
			Menu = Color3.fromRGB(27, 27, 27),
			ListSelection = Color3.fromRGB(83, 83, 83),
			Button = Color3.fromRGB(52, 52, 52),
			ButtonHover = Color3.fromRGB(69, 69, 69),
			ButtonPress = Color3.fromRGB(35, 35, 35),
			Highlight = Color3.fromRGB(94, 94, 94),
