			PlaceholderText = Color3.fromRGB(145, 145, 145),
			Important = Color3.fromRGB(190, 190, 190)
		}
		local function ColorValue(Name, Fallback)
			return PluginPalette[Name] or (Theme and Theme[Name]) or Fallback
		end
		local function IsNeutralColor(Color)
			local Maximum = math.max(Color.R, Color.G, Color.B)
			local Minimum = math.min(Color.R, Color.G, Color.B)
			return Maximum - Minimum <= 0.16
		end
		local function SetPluginTheme(Window)
			local Elements = Window and Window.GuiElems
			local MainFrame = Elements and Elements.Main
			if not MainFrame or not MainFrame:IsA("GuiObject") then return end
			MainFrame.BackgroundColor3 = PluginPalette.Main1
			MainFrame.BorderColor3 = PluginPalette.Outline1
			MainFrame.BorderSizePixel = 1
			local Content = Elements.Content
			if Content and Content:IsA("GuiObject") then
				Content.BackgroundColor3 = PluginPalette.Main1
				Content.BorderColor3 = PluginPalette.Outline1
				Content.ClipsDescendants = true
			end
			local Title = Elements.Title
			if Title and Title:IsA("TextLabel") then
				Title.TextColor3 = PluginPalette.Text
				Title.Font = Enum.Font.SourceSansSemibold
				Title.TextSize = 15
			end
			for _, Descendant in ipairs(MainFrame:GetDescendants()) do
				if Descendant:IsA("TextButton") then
					Descendant.AutoButtonColor = false
					Descendant.BackgroundColor3 = PluginPalette.Button
					Descendant.BorderColor3 = PluginPalette.Outline2
					Descendant.TextColor3 = PluginPalette.Text
					Descendant.Font = Enum.Font.SourceSansSemibold
					Descendant.TextSize = math.clamp(Descendant.TextSize, 12, 15)
				elseif Descendant:IsA("TextBox") then
					Descendant.BackgroundColor3 = PluginPalette.TextBox
					Descendant.BorderColor3 = PluginPalette.Outline3
					Descendant.TextColor3 = PluginPalette.Text
					Descendant.PlaceholderColor3 = PluginPalette.PlaceholderText
					Descendant.Font = Descendant.MultiLine and Enum.Font.Code or Enum.Font.SourceSans
				elseif Descendant:IsA("TextLabel") then
					if IsNeutralColor(Descendant.TextColor3) then
						Descendant.TextColor3 = Descendant.TextSize <= 12 and PluginPalette.PlaceholderText or PluginPalette.Text
					end
					if Descendant.TextSize >= 16 then Descendant.Font = Enum.Font.SourceSansSemibold end
				elseif Descendant:IsA("ScrollingFrame") then
					Descendant.BackgroundColor3 = PluginPalette.Main2
					Descendant.BorderColor3 = PluginPalette.Outline1
					Descendant.ScrollBarImageColor3 = PluginPalette.Highlight
					Descendant.ScrollBarThickness = math.clamp(Descendant.ScrollBarThickness, 4, 6)
				elseif Descendant:IsA("Frame") and Descendant.BackgroundTransparency < 1 and IsNeutralColor(Descendant.BackgroundColor3) then
					local LowerName = string.lower(Descendant.Name)
					if string.find(LowerName, "header", 1, true) or string.find(LowerName, "toolbar", 1, true) or string.find(LowerName, "titlebar", 1, true) then
						Descendant.BackgroundColor3 = PluginPalette.Main2
					else
						Descendant.BackgroundColor3 = PluginPalette.Main1
					end
					if Descendant.BorderSizePixel > 0 then Descendant.BorderColor3 = PluginPalette.Outline1 end
				elseif Descendant:IsA("UIStroke") then
					Descendant.Color = PluginPalette.Outline2
				end
			end
		end
		local function RegisterPluginWindow(Window, ApplyTheme)
			if not Window or not Window.GuiElems or not Window.GuiElems.Main then return false end
			Window.ValmPluginPanel = true
			if not PluginWindowSet[Window] then
				PluginWindowSet[Window] = true
				PluginWindows[#PluginWindows + 1] = Window
			end
			if ApplyTheme ~= false then SetPluginTheme(Window) end
			return true
		end
		local function ArrangePluginWindow(Window)
			if not Window or not Window.GuiElems or not Window.GuiElems.Main then return false end
			local MainFrame = Window.GuiElems.Main
			local DeviceInfo = Main.GetDeviceInfo()
			local ViewportWidth = math.max(260, tonumber(DeviceInfo.ViewportWidth) or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.X) or 800)
			local ViewportHeight = math.max(240, tonumber(DeviceInfo.ViewportHeight) or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize.Y) or 600)
			local Margin = 12
			local TopInset = 42
			local Width = tonumber(Window.SizeX) or MainFrame.AbsoluteSize.X
			local Height = tonumber(Window.SizeY) or MainFrame.AbsoluteSize.Y
			if Width <= 0 then Width = 500 end
			if Height <= 0 then Height = 360 end
			local MaxWidth = math.max(220, ViewportWidth - Margin * 2)
			local MaxHeight = math.max(190, ViewportHeight - TopInset - Margin)
			Width = math.min(Width, MaxWidth)
			Height = math.min(Height, MaxHeight)
			if math.abs((tonumber(Window.SizeX) or 0) - Width) > 1 or math.abs((tonumber(Window.SizeY) or 0) - Height) > 1 then
				pcall(function() Window:Resize(Width, Height) end)
			end
			local MaxX = math.max(Margin, ViewportWidth - Width - Margin)
			local MaxY = math.max(TopInset, ViewportHeight - Height - Margin)
			local StepX = math.max(24, math.floor(math.min(Width, 420) * 0.34))
			local StepY = math.max(24, math.floor(math.min(Height, 320) * 0.34))
			local Candidates = {}
			local function AddCandidate(X, Y)
				X = math.clamp(math.floor(X), Margin, MaxX)
				Y = math.clamp(math.floor(Y), TopInset, MaxY)
				for _, Candidate in ipairs(Candidates) do
					if Candidate.X == X and Candidate.Y == Y then return end
				end
				Candidates[#Candidates + 1] = {X = X, Y = Y}
			end
			AddCandidate((ViewportWidth - Width) / 2, (ViewportHeight - Height + TopInset) / 2)
			AddCandidate(Margin, TopInset)
			AddCandidate(MaxX, TopInset)
			AddCandidate(Margin, MaxY)
			AddCandidate(MaxX, MaxY)
			AddCandidate((ViewportWidth - Width) / 2, TopInset)
			AddCandidate((ViewportWidth - Width) / 2, MaxY)
			AddCandidate(Margin, (TopInset + MaxY) / 2)
			AddCandidate(MaxX, (TopInset + MaxY) / 2)
			for Y = TopInset, MaxY, StepY do
				for X = Margin, MaxX, StepX do
					AddCandidate(X, Y)
				end
			end
			local BestCandidate = Candidates[1]
			local BestScore = math.huge
			for _, Candidate in ipairs(Candidates) do
				local OverlapArea = 0
				local CandidateRight = Candidate.X + Width
				local CandidateBottom = Candidate.Y + Height
				for _, OtherWindow in ipairs(PluginWindows) do
					local OtherMain = OtherWindow.GuiElems and OtherWindow.GuiElems.Main
					local OtherIsOpen = OtherWindow.Closed == false or (OtherWindow.Closed == nil and OtherMain and OtherMain.Visible)
					if OtherWindow ~= Window and OtherMain and OtherIsOpen then
						local OtherPosition = OtherMain.AbsolutePosition
						local OtherSize = OtherMain.AbsoluteSize
						if OtherSize.X > 0 and OtherSize.Y > 0 then
							local OverlapWidth = math.max(0, math.min(CandidateRight, OtherPosition.X + OtherSize.X) - math.max(Candidate.X, OtherPosition.X))
							local OverlapHeight = math.max(0, math.min(CandidateBottom, OtherPosition.Y + OtherSize.Y) - math.max(Candidate.Y, OtherPosition.Y))
							OverlapArea += OverlapWidth * OverlapHeight
						end
					end
				end
				local CenterX = Candidate.X + Width / 2
				local CenterY = Candidate.Y + Height / 2
				local Distance = math.abs(CenterX - ViewportWidth / 2) + math.abs(CenterY - (TopInset + ViewportHeight) / 2)
				local Score = OverlapArea * 100 + Distance
				if Score < BestScore then
					BestScore = Score
					BestCandidate = Candidate
				end
			end
			MainFrame.Position = UDim2.new(0, BestCandidate.X, 0, BestCandidate.Y)
			Window.PosX = BestCandidate.X
			Window.PosY = BestCandidate.Y
			return true
		end
