		local function MakeWindow(Name, Width, Height)
			local Window = Lib.Window.new()
			Window:SetTitle(Name)
			local DeviceInfo = Main.GetDeviceInfo()
			local MaxWidth = math.max(220, (tonumber(DeviceInfo.ViewportWidth) or 800) - 24)
			local MaxHeight = math.max(190, (tonumber(DeviceInfo.ViewportHeight) or 600) - 64)
			Width = math.clamp(Width, 220, MaxWidth)
			Height = math.clamp(Height, 190, MaxHeight)
			Window:Resize(Width, Height)
			Windows[Name] = Window
			RegisterPluginWindow(Window)
			return Window
		end
		local function TintColor(Color, Amount)
			return Color3.new(
				math.clamp(Color.R + Amount, 0, 1),
				math.clamp(Color.G + Amount, 0, 1),
				math.clamp(Color.B + Amount, 0, 1)
			)
		end
		local function MakeButton(Parent, Text, Position, Size, Callback)
			local Button = Instance.new("TextButton")
			local BaseColor = ColorValue("Button", Color3.fromRGB(60, 60, 60))
			local HoverColor = ColorValue("ButtonHover", Color3.fromRGB(68, 68, 68))
			local PressColor = ColorValue("ButtonPress", Color3.fromRGB(40, 40, 40))
			local OutlineColor = ColorValue("Outline2", Color3.fromRGB(55, 55, 55))
			Button.AutoButtonColor = false
			Button.BackgroundColor3 = BaseColor
			Button.BorderColor3 = OutlineColor
			Button.BorderSizePixel = 1
			Button.Font = Enum.Font.SourceSans
			Button.TextSize = 14
			Button.TextColor3 = ColorValue("Text", Color3.fromRGB(255, 255, 255))
			Button.TextTransparency = 0.1
			Button.Text = Text
			Button.TextWrapped = true
			Button.Position = Position
			Button.Size = Size
			Button.Parent = Parent
			Lib.ButtonAnim(Button, {
				Mode = 2,
				StartColor = BaseColor,
				HoverColor = HoverColor,
				PressColor = PressColor,
				OutlineColor = OutlineColor
			})
			if Callback then Button.Activated:Connect(Callback) end
			return Button
		end
