		local function GetSelectedObjects()
			local Result = {}
			if Explorer and Explorer.Selection then
				for _, Node in ipairs(Explorer.Selection.List) do
					if Node and Node.Obj and Node.Obj.Parent then Result[#Result + 1] = Node.Obj end
				end
			end
			return Result
		end
		Main.SelectInstance = function(Object)
			if not Object or typeof(Object) ~= "Instance" then return false end
			local Node = nodes[Object]
			if Node and Explorer and Explorer.Selection then
				Explorer.Selection:Set(Node)
				Explorer.ViewNode(Node)
				if Explorer.Window then Explorer.Window:Show() end
				if Properties and Properties.Window then Properties.Window:Show() end
				return true
			end
			return false
		end
		Main.SearchInstances = function(Query, ClassQuery, Limit, IncludeAll)
			local Results = {}
			Query = string.lower(tostring(Query or ""))
			ClassQuery = string.lower(tostring(ClassQuery or ""))
			if Query == "" and ClassQuery == "" and not IncludeAll then return Results, 0 end
			local MaxScan = Limit or (Main.PerformanceMode and 1200 or 8000)
			local Objects = game:GetDescendants()
			local Scanned = math.min(#Objects, MaxScan)
			for Index = 1, Scanned do
				local Object = Objects[Index]
				local LowerName = string.lower(Object.Name)
				local NameMatch = Query == "" or string.find(LowerName, Query, 1, true) ~= nil
				if not NameMatch and Query ~= "" and Explorer and type(Explorer.GetInstancePath) == "function" then
					local PathSuccess, ObjectPath = pcall(Explorer.GetInstancePath, Object)
					NameMatch = PathSuccess and string.find(string.lower(tostring(ObjectPath)), Query, 1, true) ~= nil
				end
				local ClassMatch = ClassQuery == "" or string.find(string.lower(Object.ClassName), ClassQuery, 1, true) ~= nil
				if NameMatch and ClassMatch then
					Results[#Results + 1] = Object
				end
				if #Results >= 250 then break end
			end
			return Results, Scanned
		end


