		local function UpdateProblems()
			NotepadProblemsPanel.Visible = NotepadProblemsOpen
			NotepadEditor.Frame.Size = NotepadProblemsOpen and UDim2.new(1, 0, 1, -178) or UDim2.new(1, 0, 1, -56)
