		local function FocusProblem(Diagnostic)
			local Line = math.max(1, tonumber(Diagnostic.Line) or 1)
			local Column = math.max(1, tonumber(Diagnostic.Column) or 1)
			NotepadEditor.ScrollV:ScrollTo(math.max(0, Line - 2))
			NotepadEditor.ScrollH:ScrollTo(math.max(0, Column - 8))
			NotepadEditor.CursorX = Column - 1
			NotepadEditor.CursorY = Line - 1
			NotepadEditor.FloatCursorX = NotepadEditor.CursorX
			NotepadEditor.SelectionRange = {{Column - 1, Line - 1}, {math.max(Column, Diagnostic.EndColumn or Column), Line - 1}}
			NotepadEditor:Refresh()
			UpdateNotepad(Diagnostic.Severity .. " " .. Line .. ":" .. Column .. " — " .. Diagnostic.Message)
		end
		local function ShowProblems(Diagnostics, ParserMode)
			NotepadEditor.Diagnostics = Diagnostics
			table.clear(NotepadEditor.ColoredLines)
			NotepadEditor:Refresh()
			local ErrorCount = 0
			local WarningCount = 0
			for _, Diagnostic in ipairs(Diagnostics) do
				if Diagnostic.Severity == "Error" then ErrorCount += 1 else WarningCount += 1 end
			end
			NotepadProblemsButton.Text = "Problems " .. tostring(#Diagnostics)
			ProblemCount.Text = tostring(ErrorCount) .. " errors    " .. tostring(WarningCount) .. " warnings    " .. tostring(ParserMode or "Analyzer")
			for _, Child in ipairs(NotepadProblemsList:GetChildren()) do
				if Child ~= NotepadProblemsLayout and Child ~= NotepadProblemsEmpty then Child:Destroy() end
			end
			NotepadProblemsEmpty.Visible = #Diagnostics == 0
			NotepadProblemsEmpty.Text = #Diagnostics == 0 and "No problems detected." or ""
			for Index, Diagnostic in ipairs(Diagnostics) do
				local Row = Instance.new("TextButton")
				Row.Name = "Problem_" .. tostring(Index)
				Row.LayoutOrder = Index
				Row.AutoButtonColor = true
				Row.BackgroundColor3 = Index % 2 == 0 and ColorValue("Main2", Settings.Theme.Main2) or ColorValue("Main1", Settings.Theme.Main1)
				Row.BorderColor3 = ColorValue("Outline2", Color3.fromRGB(62, 62, 62))
				Row.BorderSizePixel = 1
				Row.Size = UDim2.new(1, -5, 0, 25)
				Row.Font = Enum.Font.SourceSans
