				local Marker = Diagnostic.Severity == "Error" and "●  " or "▲  "
				Row.Text = Marker .. tostring(Diagnostic.Line) .. ":" .. tostring(Diagnostic.Column) .. "  " .. tostring(Diagnostic.Message) .. (Diagnostic.Suggestion ~= "" and "  |  " .. Diagnostic.Suggestion or "")
				Row.Parent = NotepadProblemsList
				Row.Activated:Connect(function() FocusProblem(Diagnostic) end)
