		local function QueueNotepadCheck()
			NoteSerial += 1
			local RequestSerial = NoteSerial
			ProblemCount.Text = "Checking Luau source..."
			NotepadProblemsButton.Text = "Problems ..."
			task.delay(0.3, function()
				if RequestSerial ~= NoteSerial or not NotepadEditor.Frame or not NotepadEditor.Frame.Parent then return end
				local SourceText = NotepadEditor:GetText() or ""
				if #SourceText > 500000 then
					ShowProblems({})
					ProblemCount.Text = "Diagnostics paused: source exceeds 500 KB"
					NotepadProblemsEmpty.Text = "Diagnostics paused: source exceeds 500 KB."
					return
				end
				local Diagnostics, ParserMode = {}, "Diagnostics unavailable"
				local Analyzer = ScriptViewer and ScriptViewer.AnalyzeCodeDiagnostics
				if type(Analyzer) ~= "function" and type(Main) == "table" then Analyzer = Main.AnalyzeCodeDiagnostics end
				if type(Analyzer) == "function" then
					local AnalysisSuccess, AnalysisResult, AnalysisMode = pcall(Analyzer, SourceText)
					if AnalysisSuccess and type(AnalysisResult) == "table" then
						Diagnostics = AnalysisResult
						ParserMode = AnalysisMode or "Luau diagnostics"
					else
						ParserMode = "Diagnostics failed: " .. tostring(AnalysisResult)
					end
				end
				ShowProblems(Diagnostics, ParserMode)
			end)
		end
