			local SourceText = NotepadEditor:GetText() or ""
			if SourceText:gsub("%s", "") == "" then
				UpdateNotepad("Nothing to execute")
				return
			end
			local LoadFunction = env.loadstring or loadstring
			if type(LoadFunction) ~= "function" then
				UpdateNotepad("loadstring is unavailable in this executor")
				return
			end
			local CompileSuccess, Executable, CompileError = pcall(LoadFunction, SourceText)
			if not CompileSuccess then
				UpdateNotepad("Compile error: " .. tostring(Executable))
				return
			end
			if type(Executable) ~= "function" then
				UpdateNotepad("Compile error: " .. tostring(CompileError or "No executable function was returned"))
				return
			end
			UpdateNotepad("Executing...")
			task.spawn(function()
				local ExecutionSuccess, ExecutionResult = pcall(Executable)
				UpdateNotepad(ExecutionSuccess and "Executed successfully" or ("Runtime error: " .. tostring(ExecutionResult)))
			end)
		end)
