		local function GetStorageFunc(FunctionName)
			local Candidate = type(env) == "table" and env[FunctionName] or nil
			if type(Candidate) ~= "function" and type(getgenv) == "function" then
				local EnvTest, GlobalEnvironment = pcall(getgenv)
				if EnvTest and type(GlobalEnvironment) == "table" then Candidate = GlobalEnvironment[FunctionName] end
			end
			if type(Candidate) ~= "function" and type(_G) == "table" then
				local GlobalSuccess, GlobalCandidate = pcall(function() return _G[FunctionName] end)
				if GlobalSuccess then Candidate = GlobalCandidate end
			end
			return type(Candidate) == "function" and Candidate or nil
		end
		local function EnsureDataFolders()
			local IsFolderFunction = GetStorageFunc("isfolder")
			local MakeFolderFn = GetStorageFunc("makefolder")
			for _, FolderPath in ipairs({"ValmD", "ValmD/saved"}) do
				local FolderExists = false
				if IsFolderFunction then
					local CheckSuccess, CheckResult = pcall(IsFolderFunction, FolderPath)
					FolderExists = CheckSuccess and CheckResult == true
				end
				if not FolderExists and MakeFolderFn then pcall(MakeFolderFn, FolderPath) end
			end
		end
		local function ReadSavedText(Path)
			EnsureDataFolders()
			local ReadFunction = GetStorageFunc("readfile")
			if not ReadFunction then return nil end
			local ReadSuccess, StoredText = pcall(ReadFunction, Path)
			if ReadSuccess and type(StoredText) == "string" then return StoredText end
			return nil
		end
		local function WritePersistentText(Path, Content)
			EnsureDataFolders()
			local WriteFunction = GetStorageFunc("writefile")
			if not WriteFunction then return false end
			local WriteSuccess, WriteResult = pcall(WriteFunction, Path, Content)
			return WriteSuccess and WriteResult ~= false
		end

