					service.TweenService:Create(TodoRow, TweenInfo.new(0.13, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = TintColor(RowBaseColor, 0.035)}):Play()
				end)
				TodoRow.MouseLeave:Connect(function()
					service.TweenService:Create(TodoRow, TweenInfo.new(0.13, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = RowBaseColor}):Play()
