		local function AddTodoTask()
			local NewTaskText = tostring(TodoTaskInput.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
			if NewTaskText == "" then return end
			TodoTasks[#TodoTasks + 1] = {Text = NewTaskText, Done = false}
