			if DecodeSuccess and type(StoredTodoEntries) == "table" then
				for _, StoredTodoEntry in ipairs(StoredTodoEntries) do
					if type(StoredTodoEntry) == "table" and type(StoredTodoEntry.Text) == "string" and StoredTodoEntry.Text ~= "" then
						TodoTasks[#TodoTasks + 1] = {Text = StoredTodoEntry.Text, Done = StoredTodoEntry.Done == true}
					end
				end
			end
		end
