		local function OpenWindow(Name)
			local Window = Main.WindowRegistry[Name] or Windows[Name]
			if Window then
				if Window.ValmPluginPanel then ArrangePluginWindow(Window) end
				Window:Show()
				Window:Focus()
				return true
			end
			local App = Apps[Name]
			if App and App.Window then
				if App.Window.ValmPluginPanel then ArrangePluginWindow(App.Window) end
				App.Window:Show()
				return true
			end
			return false
		end
