				if Main.ActiveCreditsIntro == CreditsIntro then Main.ActiveCreditsIntro = nil end
				CreditsIntro.Close()
			end
			CloseButton.MouseButton1Click:Connect(CloseCreditsIntro)

			local CreditsAnimationToken = 0
			local function AnimateCredits()
				CreditsAnimationToken += 1
				local AnimationToken = CreditsAnimationToken
				for Index, Entry in ipairs(CreditsLabels) do
					Entry.Object.TextTransparency = 1
					Entry.Object.Position = UDim2.new(Entry.Position.X.Scale, Entry.Position.X.Offset, Entry.Position.Y.Scale, Entry.Position.Y.Offset + 10)
					task.delay((Index - 1) * 0.065, function()
						if AnimationToken ~= CreditsAnimationToken or not Entry.Object.Parent then return end
						service.TweenService:Create(Entry.Object, TweenInfo.new(0.32, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
							TextTransparency = 0,
							Position = Entry.Position
						}):Play()
					end)
				end
			end
			AnimateCredits()
		end

