	Main.SetupFilesystem = function()
		if not env.writefile or not env.makefolder then return end

		local writefile,makefolder = env.writefile,env.makefolder

		makefolder("dex")
		makefolder("dex/assets")
		makefolder("dex/saved")
		makefolder("dex/plugins")
		makefolder("dex/plugin_sources")
		makefolder("dex/ModuleCache")
	end

	Main.SaveCurrentSettings = function()
		local SaveFunction = type(env.writefile) == "function" and env.writefile or writefile
		if type(SaveFunction) == "function" then
			local Success, Data = pcall(Main.ExportSettings)
			if Success and type(Data) == "string" then pcall(SaveFunction, "DexPlusPlusSettings.json", Data) end
		end
	end

	Main.LocalDepsUpToDate = function()
		return Main.DepsVersionData and Main.ClientVersion == Main.DepsVersionData[1]
	end

	Main.PreloadUIAssets = function(Intro)
		local ContentProvider = service.ContentProvider
		if not ContentProvider then
			local ProviderSuccess, ProviderResult = pcall(function() return game:GetService("ContentProvider") end)
			if ProviderSuccess then ContentProvider = ProviderResult end
		end
		if not ContentProvider or type(ContentProvider.PreloadAsync) ~= "function" then
			return 0, 0
		end
		local Targets = {}
		local SeenTargets = {}
		local function AddTarget(Object)
			if typeof(Object) ~= "Instance" or SeenTargets[Object] then return end
			local IsContent = Object:IsA("ImageLabel") or Object:IsA("ImageButton") or Object:IsA("Decal") or Object:IsA("Texture") or Object:IsA("ParticleEmitter") or Object:IsA("Beam") or Object:IsA("Trail") or Object:IsA("SurfaceAppearance") or Object:IsA("SpecialMesh") or Object:IsA("MeshPart") or Object:IsA("Sky")
			if not IsContent then return end
			local HasAsset = false
			pcall(function()
				if Object:IsA("ImageLabel") or Object:IsA("ImageButton") then
					HasAsset = Object.Image ~= ""
				elseif Object:IsA("Decal") or Object:IsA("Texture") then
					HasAsset = Object.Texture ~= ""
				elseif Object:IsA("ParticleEmitter") or Object:IsA("Beam") or Object:IsA("Trail") then
					HasAsset = Object.Texture ~= ""
				elseif Object:IsA("SpecialMesh") then
					HasAsset = Object.MeshId ~= "" or Object.TextureId ~= ""
				elseif Object:IsA("MeshPart") then
					HasAsset = Object.MeshId ~= ""
				elseif Object:IsA("SurfaceAppearance") then
					HasAsset = Object.ColorMap ~= "" or Object.MetalnessMap ~= "" or Object.NormalMap ~= "" or Object.RoughnessMap ~= ""
				elseif Object:IsA("Sky") then
					HasAsset = Object.SkyboxBk ~= "" or Object.SkyboxDn ~= "" or Object.SkyboxFt ~= "" or Object.SkyboxLf ~= "" or Object.SkyboxRt ~= "" or Object.SkyboxUp ~= ""
				end
			end)
			if HasAsset then
				SeenTargets[Object] = true
				Targets[#Targets + 1] = Object
			end
		end
		local function AddTree(Root)
			if typeof(Root) ~= "Instance" then return end
			AddTarget(Root)
			local Success, Descendants = pcall(function() return Root:GetDescendants() end)
			if Success then
				for _, Object in ipairs(Descendants) do AddTarget(Object) end
			end
		end
		AddTree(Main.MainGui)
		local Containers = {}
		local SeenContainers = {}
		local function AddContainer(Container)
			if typeof(Container) == "Instance" and not SeenContainers[Container] then
				SeenContainers[Container] = true
				Containers[#Containers + 1] = Container
			end
		end
		AddContainer(Main.GuiHolder)
		local SecureSuccess, SecureContainer = pcall(Main.GetSecureContainer)
		if SecureSuccess then AddContainer(SecureContainer) end
		if type(gethui) == "function" then
			local HUISuccess, HUIContainer = pcall(gethui)
			if HUISuccess then AddContainer(HUIContainer) end
		end
		for _, Container in ipairs(Containers) do
			local Children = {}
			pcall(function() Children = Container:GetChildren() end)
			for _, Child in ipairs(Children) do
				if Child:IsA("ScreenGui") and (Child == Main.MainGui or Child.Name:sub(1, 5) == "_DPP_") then
					AddTree(Child)
				end
			end
		end
		local Total = #Targets
		local Done = 0
		local Failed = 0
		local BatchSize = 24
		for StartIndex = 1, Total, BatchSize do
			local Batch = {}
			for Index = StartIndex, math.min(Total, StartIndex + BatchSize - 1) do
				Batch[#Batch + 1] = Targets[Index]
			end
			local BatchSuccess = pcall(function()
				ContentProvider:PreloadAsync(Batch, function(_, FetchStatus)
					if FetchStatus ~= Enum.AssetFetchStatus.Success then Failed = Failed + 1 end
				end)
			end)
			if not BatchSuccess then Failed = Failed + #Batch end
			Done = math.min(Total, StartIndex + #Batch - 1)
			if Intro and type(Intro.SetProgress) == "function" then
				local Ratio = Total > 0 and Done / Total or 1
				pcall(Intro.SetProgress, "Loading textures " .. tostring(Done) .. "/" .. tostring(Total), 0.9 + Ratio * 0.08)
			end
			if task and type(task.wait) == "function" then task.wait() end
		end
		return Done, Failed
	end

	Main.WaitForUISettle = function(Intro)
		local RunService = service.RunService
		if not RunService then
			local RunSuccess, RunResult = pcall(function() return game:GetService("RunService") end)
			if RunSuccess then RunService = RunResult end
		end
		local ContentProvider = service.ContentProvider
		local StepSignal = RunService and RunService.RenderStepped
		local StartTime = tick()
		local LastSignature = nil
		local StableFrames = 0
		local QueueStableFrames = 0
		local MaxWait = 8
		local function GetSignature()
			local Root = Main.MainGui
			if typeof(Root) ~= "Instance" then return nil end
			local Success, Descendants = pcall(function() return Root:GetDescendants() end)
			if not Success then return nil end
			local Parts = {tostring(#Descendants)}
			for Index, Object in ipairs(Descendants) do
				if Object:IsA("GuiObject") then
					local Position = Object.AbsolutePosition
					local Size = Object.AbsoluteSize
					Parts[#Parts + 1] = tostring(Index) .. ":" .. Object.ClassName .. ":" .. Object.Name .. ":" .. tostring(math.floor(Position.X + 0.5)) .. "," .. tostring(math.floor(Position.Y + 0.5)) .. "," .. tostring(math.floor(Size.X + 0.5)) .. "," .. tostring(math.floor(Size.Y + 0.5))
				end
			end
			return table.concat(Parts, "|")
		end
		while tick() - StartTime < MaxWait do
			local Signature = GetSignature()
			if Signature and Signature == LastSignature then
				StableFrames = StableFrames + 1
			else
				StableFrames = 0
			end
			LastSignature = Signature
			local QueueReady = true
			if ContentProvider then
				local QueueSuccess, QueueSize = pcall(function() return ContentProvider.RequestQueueSize end)
				if QueueSuccess and tonumber(QueueSize) then QueueReady = tonumber(QueueSize) <= 0 end
			end
			if QueueReady then
				QueueStableFrames = QueueStableFrames + 1
			else
				QueueStableFrames = 0
			end
			if Intro and type(Intro.SetProgress) == "function" then
				pcall(Intro.SetProgress, "Settling interface", 0.985)
			end
			if StableFrames >= 3 and QueueStableFrames >= 2 then break end
			if StableFrames >= 7 and tick() - StartTime >= 3 then break end
			if StepSignal then
				local WaitSuccess = pcall(function() StepSignal:Wait() end)
				if not WaitSuccess then task.wait(0.05) end
			else
				task.wait(0.05)
			end
		end
		for _ = 1, 2 do
			if StepSignal then
				local WaitSuccess = pcall(function() StepSignal:Wait() end)
				if not WaitSuccess then task.wait(0.05) end
			else
				task.wait(0.05)
			end
		end
		return StableFrames >= 3, StableFrames, QueueStableFrames
	end

	Main.Init = function()
		Main.Elevated = pcall(function() local a = game:GetService("CoreGui"):GetFullName() end)
		
		-- saves new settings if does not exist
