						moduleData.PluginData = moduleData.PluginData or {}
						local PluginIdentity = (tostring(pluginDir) .. tostring(moduleData.PluginData.Name or "") .. tostring(moduleData.PluginData.FriendlyName or "")):lower():gsub("%W", "")
						if PluginIdentity:find("aibeautifier", 1, true) or PluginIdentity:find("aibeautify", 1, true) then
							moduleData.IsAIBeautifierPlugin = true
							moduleData.PluginPath = tostring(pluginDir)
							moduleData.AIBeautifierPluginSettings = Settings.AIBeautifierPlugin
							local GetPluginConfig = type(Main.ResolveAIBeautifierPluginConfig) == "function" and Main.ResolveAIBeautifierPluginConfig or function() return {} end
							local ConfigSuccess, PluginAIConfig = pcall(GetPluginConfig)
							if not ConfigSuccess or type(PluginAIConfig) ~= "table" then PluginAIConfig = {} end
							moduleData.ResolveAIConfig = GetPluginConfig
							moduleData.GetAIConfig = GetPluginConfig
							moduleData.AIConfig = PluginAIConfig
							moduleData.PluginData.AIBeautifierPluginSettings = Settings.AIBeautifierPlugin
							moduleData.PluginData.ResolveAIConfig = GetPluginConfig
							moduleData.PluginData.AIConfig = PluginAIConfig
							if type(moduleData.SetAIConfigResolver) == "function" then
								pcall(moduleData.SetAIConfigResolver, GetPluginConfig)
							end
						end
						local InitSuccess, InitError = pcall(function()
							if type(moduleData.Init) ~= "function" then error("Plugin module is missing Init()") end
							moduleData.Init()
						end)
						if InitSuccess then
							local PluginTitle = moduleData.PluginData.FriendlyName or (moduleData.Window and moduleData.Window.GuiElems and moduleData.Window.GuiElems.Title and moduleData.Window.GuiElems.Title.Text) or "Unnamed Plugin"
							local PluginName = moduleData.PluginData.Name or tostring(PluginTitle):gsub("%s+", "")
							intro.SetProgress("Initializing Plugin: " .. tostring(PluginTitle), 0.9)
							moduleData.PluginData.Name = PluginName
							moduleData.PluginData.FriendlyName = PluginTitle
							table.insert(Main.Plugins, moduleData)
							if type(Main.SyncAIBeautifierPluginConfig) == "function" then
								pcall(Main.SyncAIBeautifierPluginConfig)
							end
						else
							warn("[Valm Plugin] Failed to initialize " .. tostring(pluginDir) .. ": " .. tostring(InitError))
						end
					else
						warn("[Valm Plugin] Failed to load " .. tostring(pluginDir) .. ": " .. tostring(moduleData))
					end
				end
			end
		end
		
		
		Lib.FastWait()

