		coroutine.wrap(function()
			local ReadyStart = tick()
			while not Main.UIReady and tick() - ReadyStart < 30 do
				Lib.FastWait(0.1)
			end
			if Main.UIReady and type(Main.PreloadUIAssets) == "function" then
				local PreloadSuccess, LoadedCount, FailedCount = pcall(Main.PreloadUIAssets, intro)
				if not PreloadSuccess then
					warn("[Valm Dex] Texture preload failed: " .. tostring(LoadedCount))
				elseif FailedCount and FailedCount > 0 then
					warn("[Valm Dex] Some textures could not be preloaded: " .. tostring(FailedCount))
				end
				if type(Main.WaitForUISettle) == "function" then
					local SettleSuccess, IsSettled = pcall(Main.WaitForUISettle, intro)
					if not SettleSuccess then warn("[Valm Dex] Initial UI settle failed: " .. tostring(IsSettled)) end
