					pcall(Main.RefreshInterfaceTheme)
				elseif type(Main.ApplyFullInterfaceTheme) == "function" then
					pcall(Main.ApplyFullInterfaceTheme)
				end
				local PreloadOK, LateLoadedCount, LateFailedCount = pcall(Main.PreloadUIAssets, intro)
				if PreloadOK then
					if LateFailedCount and LateFailedCount > 0 then warn("[Valm Dex] Some late UI textures could not be preloaded: " .. tostring(LateFailedCount)) end
				else
					warn("[Valm Dex] Late texture preload failed: " .. tostring(LateLoadedCount))
				end
				if type(Main.WaitForUISettle) == "function" then
					local FinalSettleSuccess, IsFinalSettled = pcall(Main.WaitForUISettle, intro)
					if not FinalSettleSuccess then warn("[Valm Dex] Final UI settle failed: " .. tostring(IsFinalSettled)) end
				end
			end
			intro.SetProgress("Complete",1)
			Lib.FastWait(0.8)
			intro.Close()
			while not Main.MainGui do
				Lib.FastWait(0.1)
			end
			if type(Notices) == "table" then
				if type(Notices.Queue) == "function" then
					pcall(Notices.Queue, "Welcome to Valm Dex++!", "da best vex version omagadz??", 4, 4729263385)
				end
				if type(Notices.StartBackdoorScan) == "function" then
					pcall(Notices.StartBackdoorScan)
				end
			end
		end)()

		-- Init window system, create main menu, show explorer and properties
		Lib.Window.Init()
		Main.CreateMainGui()
		Main.ApplyFullInterfaceTheme()
		Explorer.Window:Show({Align = "right", Pos = 1, Size = 0.5, Silent = true})
		Properties.Window:Show({Align = "right", Pos = 2, Size = 0.5, Silent = true})
