				gui:Destroy()
			end
		end
		Main.DexHelper = nil
		Main.DexHelperGui = nil
	end

	Main.Reinit = function()
		Main.Uninit()
		task.wait()
		Main.Init()
	end

	return Main
end)()

-- Start
local function GetSharedEnv()
	local SharedEnvironment = _G
	if type(getgenv) == "function" then
		local Success, Result = pcall(getgenv)
		if Success and type(Result) == "table" then
			SharedEnvironment = Result
		end
	end
	return SharedEnvironment
end

local function VFC()
	local SharedEnvironment = GetSharedEnv()
	if SharedEnvironment.ValmDexFirstRunCompleted == true then
		return true
	end
	local ReadFileFunction = SharedEnvironment.readfile or readfile
	if type(ReadFileFunction) == "function" then
		local Success, Contents = pcall(ReadFileFunction, "ValmDexFirstRun.dat")
		if Success and tostring(Contents) == "Completed" then
			SharedEnvironment.ValmDexFirstRunCompleted = true
			return true
		end
	end
	return false
end

local function SetVFC()
	local SharedEnvironment = GetSharedEnv()
	SharedEnvironment.ValmDexFirstRunCompleted = true
	local WriteFileFunction = SharedEnvironment.writefile or writefile
	if type(WriteFileFunction) == "function" then
		pcall(WriteFileFunction, "ValmDexFirstRun.dat", "Completed")
	end
end

local function IsLoadDexNowwwEnabled()
	local SharedEnvironment = GetSharedEnv()
	local ReadFileFunction = SharedEnvironment.readfile or readfile
	if type(ReadFileFunction) ~= "function" then
		return true
	end
	local ReadSuccess, SettingsData = pcall(ReadFileFunction, "DexPlusPlusSettings.json")
	if not ReadSuccess or type(SettingsData) ~= "string" or SettingsData == "" then
		return true
	end
	local DecodeSuccess, StoredSettings = pcall(function()
		return game:GetService("HttpService"):JSONDecode(SettingsData)
	end)
	if DecodeSuccess and type(StoredSettings) == "table" and type(StoredSettings.ToggleDaLoadDexNowww) == "boolean" then
		return StoredSettings.ToggleDaLoadDexNowww
	end
	return true
end

