		Volume = Level
		Music.Volume = Level
	end
	task.spawn(function()
		local MusicFile = "music.mp3"
		local MusicUrl = "https://raw.githubusercontent.com/9faces/gang-maxwell/main/maxwell.mp3"
		local GetAsset = getsynasset or getcustomasset
		local WriteFile = writefile
		if type(GetAsset) ~= "function" or type(WriteFile) ~= "function" then
			return
		end
		local HasFile = false
		if type(isfile) == "function" then
			local CheckOk, FileExists = pcall(isfile, MusicFile)
			HasFile = CheckOk and FileExists == true
		end
		if not HasFile then
			local Downloaded, Data = pcall(function()
				return game:HttpGet(MusicUrl)
			end)
			if not Downloaded or type(Data) ~= "string" or #Data == 0 then
				return
			end
			local Saved = pcall(WriteFile, MusicFile, Data)
			if not Saved then
				return
			end
		end
		local AssetOk, Asset = pcall(GetAsset, MusicFile)
		if not AssetOk or type(Asset) ~= "string" or Asset == "" or not ScreenGui.Parent then
			return
		end
		Music.SoundId = Asset
		Music.Volume = Volume
		local ContentProvider = game:GetService("ContentProvider")
		pcall(function()
			ContentProvider:PreloadAsync({Music})
		end)
		if ScreenGui.Parent then
			Music.Volume = Volume
			pcall(function()
