	local SpriteColumns = 4
	local SpriteRows = 4
	local SpriteFrameSize = 147
	local FrameTime = 1 / 15
	local function SetSpriteFrame(FrameNumber)
		SpriteFrame = ((FrameNumber - 1) % SpriteFrameCount) + 1
		local FrameOffset = SpriteFrame - 1
		local Column = FrameOffset % SpriteColumns
		local Row = math.floor(FrameOffset / SpriteColumns)
		MaxwelledSprite.Position = UDim2.fromOffset(-Column * SpriteFrameSize, -Row * SpriteFrameSize)
